;WITH raw AS (
    SELECT * FROM (VALUES
        (N'AE-01-P01', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 1, N'Ask what the certified business data says', N'Analyze aggregate pipeline position and gap drivers', N'Featured', N'Prompt', N'For the current quarter, where is pipeline most materially behind plan? Break the gap down by stage, solution area, expected close timing, and account. Identify the largest contributors, distinguish pipeline-volume issues from progression or timing issues, and show the metrics supporting each conclusion. Flag anything the available report cannot answer.', NULL, N'Enabled certified MSXI report; relevant report filters; current quarter scope', N'Pipeline gap analysis by stage, solution area, timing, and account, with metrics and report limitations visible.', N'AE confirms report, filters, KPI definitions, and interpretation before using the output in a forecast or management conversation.', N'Workflow execution', N'Certified data creates a shared starting point for the judgment conversation.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'AE-01-P02', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 2, N'Find the right report and configure a useful view', N'Report discovery, KPI clarification, filters, and bookmarks', N'Featured', N'Both', N'I need the best MSXI report for inspecting current-quarter pipeline gaps by account, stage, and solution area. Provide the report link, explain the relevant KPIs, and help me apply filters for [scope]. If supported, save a bookmark for this view.', N'1. Ask MSXI Assist for the best report for the question.
2. Confirm the KPI definitions match what you meant.
3. Apply filters for your scope.
4. Save a bookmark so the next inspection starts here.', N'Business question; role; scope; desired dimensions', N'Report recommendation, KPI explanation, filtered view guidance, and bookmark or repeatable navigation path where supported.', N'AE confirms report scope, definitions, and filters match the business question.', N'Problem identification', N'The right question in the wrong report creates confident noise.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'AE-01-P04', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 3, N'Review pipeline-hygiene corrections', N'Review eligible automated or assisted pipeline-hygiene changes', N'Featured', N'Activity', NULL, N'1. Open the Auto-Fix Pipeline Agent review queue in MSX.
2. Filter to your opportunities.
3. Review each suggested change against the real customer and deal timeline.
4. Confirm, adjust, revert or opt out on each item.
