        (N'AE-01-P05B', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 5, N'Schedule account or opportunity checks', N'Run a recurring MSX and interaction-grounded check', N'Extended', N'Both', N'Schedule this prompt for [cadence]: Review [scope] for opportunities with material changes, missing next steps, stale customer engagement, or newly surfaced risk. Show the source signal and one seller action for each item.', N'1. Open Sales Agent.
2. Enter the prompt.
3. Set the recurring cadence.
4. Confirm the MSX scope it runs against.
5. Review the first scheduled result before relying on it.', N'Connected MSX scope; cadence; seller access', N'Scheduled MSX-grounded opportunity check with scope, cadence, source signals, and recommended seller actions.', N'AE reviews the first scheduled result, validates source signals, and narrows scope if output is too broad.', N'Monitoring and signal', N'Recurring checks should reduce review burden, not create another inbox.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-02-ALT-01', N'WF-X-PIPE-01', N'AE-PIPE-2', N'PH-AE-PIPE-2-EXPL', 3, N'Pressure-test the forecast narrative', N'Find the movement, risk or commitment in your forecast narrative that you cannot yet evidence.', N'Extended', N'Prompt', N'Review the forecast narrative. For each claim about movement, risk or commitment, state the certified source behind it and whether the judgment is yours or the data''s. Identify the two claims most likely to be challenged in inspection and what evidence would settle them.', NULL, N'The forecast narrative; the certified data behind each claim; the commitments you have made to your manager.', N'A forecast challenge list separating sourced movement from seller judgment, with the evidence needed for the two weakest claims.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Build a Decision-Ready Forecast Narrative is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-02-ALT-02', N'WF-X-PIPE-01', N'AE-PIPE-2', N'PH-AE-PIPE-2-EXPL', 4, N'Create the forecast follow-through plan', N'Turn the forecast inspection into the specific actions and dates that change the position before the next review.', N'Extended', N'Prompt', N'Turn the forecast narrative into a follow-through plan. For each at-risk commit and gap driver, define the action that would change it, the owner, the date it must move by, and the evidence you will check. Set the rhythm you will use to inspect it before the next forecast call.', NULL, N'The reviewed forecast narrative; the at-risk commits and their owners; the date of your next inspection.', N'A forecast follow-through plan with actions, owners, dates, evidence checks, and an inspection rhythm.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Build a Decision-Ready Forecast Narrative rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-02-P01', N'WF-X-PIPE-01', N'AE-PIPE-2', N'PH-AE-PIPE-2-EXPL', 1, N'Analyze certified forecast movement', N'Analyze certified business metrics and drivers.', N'Featured', N'Prompt', N'Give me my weekly forecast narrative for [scope]: qualified versus committed change since last week, the five biggest movers up and down with one-line reasons, committed deals at risk in the next 30 days, and three inspection questions. Use only the enabled certified report and show supporting metrics.', NULL, N'Your forecast scope; access to certified pipeline data; last week''s position for comparison.', N'Forecast narrative with qualified versus committed movement, biggest movers, at-risk deals, inspection questions, and supporting metrics.', N'AE validates source metrics, customer context, and whether the narrative reflects seller judgment.', N'Analysis and assessment', N'A forecast narrative should make risk inspectable, not make uncertainty sound certain.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'AE-02-P02', N'WF-X-PIPE-01', N'AE-PIPE-2', N'PH-AE-PIPE-2-EXPL', 2, N'Create the inspection brief', N'Synthesize approved analysis and work context into an artifact.', N'Featured', N'Prompt', N'Using the approved forecast analysis and my meeting notes, draft a concise forecast-call brief that separates sourced facts, seller judgment, risks, decisions needed, and follow-up actions.', NULL, N'The approved forecast analysis; your own meeting notes; the risks you judge to be real but cannot yet evidence.', N'Forecast-call brief separating sourced facts, seller judgment, risks, decisions needed, and follow-up actions.', N'AE reviews every claim, adds judgment, and decides what is shared with manager or leadership.', N'Synthesis and drafting', N'The brief turns analysis into a review-ready conversation.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-03-ALT-01', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 3, N'Pressure-test the account priority list', N'Challenge whether your account priorities are driven by evidence or by habit and familiarity.', N'Extended', N'Prompt', N'Review my account priority list. For each of the top accounts, state the evidence behind the priority and whether it reflects a current signal or a standing assumption. Identify the account most likely to be wrongly prioritized, the account most likely to be wrongly ignored, and what would confirm either.', NULL, N'The prioritized account list; the source signal behind each priority; the accounts you have not touched recently.', N'A priority challenge showing evidence per account, plus the most likely over-prioritized and under-prioritized account.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Prioritize Accounts and Build an Actionable Account Plan is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-03-ALT-02', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 4, N'Create the account follow-through plan', N'Convert the account priorities into named next actions and the rhythm that keeps them from decaying into a list.', N'Extended', N'Prompt', N'Turn the account priority list into a follow-through plan. For each top account, define the next action, the owner, the date, the signal you will check to know it worked, and the point at which you would drop the account down the list. Set a weekly rhythm for reviewing it.', NULL, N'The prioritized account list; the next action for each top account; your weekly planning rhythm.', N'An account follow-through plan with next actions, owners, dates, verification signals, and a weekly review rhythm.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Prioritize Accounts and Build an Actionable Account Plan rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-03-ECIF-01', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 5, N'Assess ECIF fit and investment momentum', N'Explore eligible investment options for an approved opportunity and identify request or delivery risks to momentum.', N'Featured', N'Prompt', N'Using the approved opportunity ID or TPID, explore eligible investment offers, summarize customer investments, and identify request or delivery risks that could affect opportunity momentum. Separate retrieved facts from assumptions.', NULL, N'Approved opportunity ID or TPID and current opportunity context.', N'Investment-fit summary with supported options, active-request status, risks, evidence gaps, and next human decision.', N'AE confirms opportunity context and does not determine eligibility, approval, or funding. Route to the accountable ECIF owner.', N'Analysis and assessment', N'Investment is useful only when it removes a real account or opportunity barrier.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-03-P01', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 1, N'Prioritize account action for this week', N'Use Sales Agent and available sales context to rank accounts and name one next action for each.', N'Featured', N'Prompt', N'Rank my top 10 accounts for this week. For each, show the priority driver, active opportunity stage, renewal or whitespace signal, partner context, and the single highest-impact seller action. Show the source signal and flag missing context.', NULL, N'Your account list; access to opportunity, renewal and whitespace signals; partner coverage for those accounts.', N'Prioritized account list with priority driver, source signal, active stage, role gaps, and highest-impact action.', N'AE validates the priority logic, relationship nuance, and whether the action is realistic this week.', N'Prioritization', N'Prioritization is a decision about what will not get attention.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-03-P02', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 2, N'Build or assess the account plan with approval gates', N'Use a reusable planning skill to propose account-plan updates while keeping every write or commitment AE-approved.', N'Featured', N'Both', N'For [Account] and [TPID], assess the current account plan, research evidence gaps, propose additive updates to priorities, stakeholders, opportunities, and next actions, and require approval before any MSX write.', N'1. Open Scout and start the account plan skill.
2. Supply the account and TPID.
3. Review the proposed additions against your own knowledge.
4. Approve or reject each proposed MSX write.
5. Confirm nothing was written without your approval.', N'The account and its TPID; the current account plan; your authority to approve or reject an MSX write.', N'Account-plan assessment with proposed updates, evidence gaps, and explicit approval/rejection decisions.', N'AE approves or rejects each proposed change and confirms nothing is written or committed without review.', N'Synthesis and drafting', N'Account planning becomes usable when it creates next actions, not just more content.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'AE-04-ALT-01', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 3, N'Pressure-test the opportunity hypotheses', N'Separate the opportunity signals that are genuinely evidenced from the ones that reflect optimism.', N'Extended', N'Prompt', N'Review my opportunity hypotheses. For each, state the trigger event, the evidence it rests on, and whether a customer has actually indicated intent or the intent is inferred. Identify which would create duplicate or unsupported pipeline, and what one piece of evidence would qualify or kill each.', NULL, N'The opportunity hypotheses; the trigger and evidence behind each; your existing pipeline so you can spot duplication.', N'A qualification challenge per hypothesis, with evidence status, duplication risk, and the single test that would qualify or kill it.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Create and Qualify New Opportunities is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-04-ALT-02', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 4, N'Create the opportunity follow-through plan', N'Turn qualified opportunity hypotheses into the first customer action and the date you will know whether it is real.', N'Extended', N'Prompt', N'Turn the qualified opportunity hypotheses into a follow-through plan. For each, define the first customer action, the stakeholder, the date, the response that would confirm it is real, and the point at which you would stop pursuing it. Rank by which is most likely to convert.', NULL, N'The qualified hypotheses; the stakeholder you would approach for each; your outreach capacity this week.', N'A ranked opportunity follow-through plan with first actions, stakeholders, dates, confirming signals, and stop conditions.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Create and Qualify New Opportunities rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-04-P01', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 1, N'Qualify buying signals into opportunity hypotheses', N'Use Sales Agent and available customer context to separate real buying signals from noise or optimism.', N'Featured', N'Prompt', N'Review [Account] across MSX, recent meetings, email, and available content. Summarize buying signals, risks, existing opportunity overlap, and the top three actions to create or progress a qualified opportunity. Flag signals that lack evidence.', NULL, N'The account you are working; access to MSX, recent meetings and email for it; your open opportunities so you can spot overlap.', N'Buying-signal summary with evidence, risks, existing opportunity overlap, top actions, and unsupported signals flagged.', N'AE verifies source access, customer intent, duplication risk, and whether the signal warrants outreach or opportunity creation.', N'Opportunity qualification', N'A qualified opportunity starts with a trigger and evidence, not the need to fill coverage.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-04-P02', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 2, N'Develop whitespace outreach from evidence', N'Turn whitespace and account signals into testable outreach and first-meeting structure.', N'Featured', N'Prompt', N'Analyze whitespace for [scope]. Identify accounts with low solution penetration relative to known priorities, propose the top three opportunity hypotheses, and create an initial outreach plan with a first-meeting agenda. Separate evidence from assumptions.', NULL, N'The territory or account scope; solution penetration data; the customer priorities you already know.', N'Whitespace opportunity hypotheses with evidence, assumptions, first outreach, partner consideration, and meeting agenda.', N'AE validates account fit, customer relevance, partner appropriateness, and whether assumptions are acceptable for outreach.', N'Synthesis and drafting', N'Whitespace only matters when it becomes a customer problem worth testing.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-04-P03', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 5, N'Inspect opportunity-level context before action', N'Review connected MSX opportunities and available customer-conversation context', N'Featured', N'Prompt', N'Review open opportunities closing this quarter for [seller or account scope]. Identify opportunities that need seller attention because the close date, next step, forecast evidence, or recent customer engagement appears incomplete or inconsistent. For each flagged opportunity, show the source signal, explain why attention may be needed, and suggest one seller action. Flag cases where recent customer context is missing.', NULL, N'Connected MSX scope; user access; seller or account scope', N'Flagged opportunity list with close-date, next-step, engagement, and risk signals plus one seller action each.', N'AE verifies the underlying records, customer context, and whether the proposed action is still current.', N'Inspection and review', N'Opportunity inspection is where pipeline noise either becomes action or gets removed.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-ALT-01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 6, N'Pressure-test the deal inspection', N'Find the blocker, approval or stakeholder gap that the deal plan assumes is handled but nobody owns.', N'Extended', N'Prompt', N'Review this deal inspection. Identify the next decision the customer must make, whether the evidence to support it exists, and which blocker has no named owner. Name the assumption that, if wrong, would move the close date most, and what would confirm it.', NULL, N'The deal inspection brief; the exit criteria for the current stage; the account-team roles involved.', N'A deal challenge naming the next customer decision, unowned blockers, and the assumption with the largest close-date impact.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Accelerate a Strategic Deal is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-05-ALT-02', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 7, N'Create the deal follow-through plan', N'Convert the deal inspection into owned actions and checkpoints that move the next customer decision.', N'Extended', N'Prompt', N'Turn the deal inspection into a follow-through plan. For each blocker and open decision, define the action, the owner, the date, the customer-facing step if there is one, and the checkpoint where you will verify movement. Separate what you own from what the account team owns.', NULL, N'The reviewed deal inspection; the account-team owners; the customer decision date you are working toward.', N'A deal follow-through plan separating seller-owned from team-owned actions, with dates and verification checkpoints.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Accelerate a Strategic Deal rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-DEAL-01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 1, N'Inspect deal context before customer action', N'Use the deal making features in Sales Agent to assemble agreement, enrollment, renewal, discount, and consumption context, then shape the deal from real data rather than recollection.', N'Featured', N'Prompt', N'Show me the list of enrollments for [Account name or TPID], then list all agreements with type and status. For the agreement I name, provide license estate details grouped by SKU, list the SKUs whose discount is between 40 and 60 percent, and show the upcoming renewals with expiry dates. Lead with the identifier I give you. Tell me which figures you could not retrieve rather than estimating them, and flag anything that needs licensing or entitlement validation before I use it with the customer.', NULL, N'Approved account, TPID, enrollment, or agreement identifier and current deal context.', N'A deal context brief covering enrollments, agreements, license estate by SKU, discount posture, and upcoming renewals, with retrieval gaps named.', N'AE verifies the figures came from the source systems rather than inference, and routes pricing approval, policy exceptions, and final commercial authority to the accountable owner.', N'Inspection and review', N'Deal making answers depend on the identifier. A named enrollment or agreement returns real deal data; a vague account reference returns a generic summary.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-P01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 2, N'Generate the Deal Book for a renewal and choose your scenario', N'Compile the renewal summary for one agreement, then decide which pricing scenario to lead with and why.', N'Featured', N'Both', N'Create Deal Book for agreement number [agreement number]. If the agreement number does not resolve, try the enrollment number instead. When it returns, summarize the pricing scenarios it produced, what each assumes about the customer, and what evidence in the purchase history and current licensing footprint supports each one. Tell me which scenario you would lead with for [customer context] and what would have to be true for that to be wrong. Flag any upsell or cross-sell recommendation that is not supported by the consumption data. Do not present a scenario as approved or as a commitment.', N'1. Have the agreement number ready; the enrollment number also works.
2. Run the prompt.
3. Review the Agreement Details sheet, including year-over-year revenue, before the scenario tabs.
4. Check the Reason to Believe tooltips on the List Price column for SKUs marked discontinued, new, or replaced.
5. Treat the first output as a draft; re-run if the data looks stale.
6. Decide which scenario to lead with and why.', N'An agreement number or enrollment number for a real renewal. Customer context that would make one scenario more appropriate than another. Sales Agent access with your CRM scope connected.', N'A Deal Book with purchase history, current licensing footprint, pricing scenarios, and upsell or cross-sell recommendations, plus your reasoned choice of which scenario to lead with.', N'AE validates the deal facts against the source data, decides which scenario fits this customer, and routes pricing approval, exceptions, and material amendments to the accountable owner and approval chain rather than acting on the recommendation alone.', N'Synthesis and drafting', N'The Deal Book assembles in minutes what used to take weeks across seven or eight portals. The judgment that matters is which scenario fits this customer.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-P02', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 3, N'Prepare grounded customer follow-up', N'Translate an approved inspection into grounded follow-up.', N'Featured', N'Prompt', N'Using the reviewed deal inspection and latest customer interaction, draft a follow-up that confirms customer outcomes, open decisions, commitments, and the next agreed action. Do not invent commitments.', NULL, N'The reviewed deal inspection; notes from the latest customer interaction; the commitments already made to the customer.', N'Customer follow-up draft confirming outcomes, decisions, commitments, next action, and any open questions.', N'AE validates tone, relationship context, commitments, and whether follow-up should be sent or revised.', N'Conversation preparation', N'A good follow-up turns inspection into customer momentum.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-QUOTE-01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 4, N'Turn the chosen scenario into a quote and start the approval', N'Create the EA quote from the scenario you selected, check the pricing fields, and request the approval you know it will need, rather than discovering the approval requirement later.', N'Extended', N'Both', N'Create an EA Quote for [enrollment number] based on the scenario I selected from the Deal Book. Then show me the price settings so I can check them, and tell me which fields you populated from the Deal Book versus which need my input. Identify any discount level in this quote that will require approval, and what the approval path would be. Do not submit anything or represent any discount as approved. If a guardrail or validation issue applies to this deal, including anything multi-year or multi-tenant, surface it now rather than at submission.', N'1. Bring the enrollment number and the scenario you chose from the Deal Book.
2. Run the prompt.
3. Review the price settings and correct anything that came across wrong.
4. Note the approval that will be needed and who owns it.
5. If a discount needs approval, request it: Request approval for a [X percent] discount on this renewal.
6. Keep this in the same chat thread as the rest of this deal.', N'The enrollment number and the Deal Book scenario you selected. Knowledge of your own empowerment level and who owns approval beyond it. Sales Agent access with your CRM scope connected.', N'A draft EA quote with price settings visible, a clear split between populated and required fields, and the approval requirement and path named before submission.', N'AE verifies every pricing field before submission, treats the draft as a draft rather than a final quote, and routes discount approval, exceptions, and any material amendment through the accountable owner and the legal approval chain rather than around it.', N'Execution and drafting', N'Deals stall between a good scenario and a submitted quote. Knowing the approval requirement before you build the quote is what keeps that gap short.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-06-ALT-01', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 4, N'Pressure-test the executive conversation plan', N'Test the conversation plan against the objections and stakeholder dynamics most likely to derail it.', N'Extended', N'Prompt', N'Review my plan for this executive conversation. Identify the claim most likely to be challenged, the stakeholder most likely to resist, the evidence I am missing for my primary ask, and whether my fallback ask is genuinely different or just a smaller version of the same one.', NULL, N'The conversation brief; the stakeholder history and dynamics; the ask you intend to make.', N'A conversation challenge naming the weakest claim, the likely resistor, missing evidence, and fallback-ask quality.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Prepare for a Customer Conversation is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-06-P-AE01', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 1, N'Build the account and conversation brief', N'Use MSX and available customer-interaction context to prepare the AE.', N'Featured', N'Prompt', N'Prepare me for my next conversation with [Account]. Summarize priorities from the last 60 days, sentiment shifts, open commitments, active MSX opportunities, competitive mentions, engaged account-team roles, and missing context. Recommend three talking points and the single ask that best advances the customer decision. Show the source signal for each major claim.', NULL, N'Account; meeting type; desired decision; user access to MSX and available customer context.', N'Grounded AE conversation brief with source signals, gaps, talking points, likely objections, primary ask, and fallback ask.', N'AE verifies customer facts, relationship nuance, opportunity strategy, claims, commitments, and the ask before use.', N'Synthesis and drafting', N'Preparation is the highest-leverage place to improve the customer conversation.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-06-P-AE02', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 5, N'Create the executive value narrative', N'Create a customer-ready narrative from approved evidence and work content.', N'Featured', N'Prompt', N'Using the approved account brief and these source materials, create an executive value narrative for [solution/workload]. Map the solution to the customer’s stated priorities, use only sourced outcomes or quantified evidence, flag claims requiring review, and end with three CXO talking points, one primary ask, and one realistic fallback ask.', NULL, N'Approved account brief; selected files, meetings, or content; solution/workload; desired decision.', N'Executive value narrative with sourced claims, customer priorities, CXO talking points, primary ask, fallback ask, and review flags.', N'AE and relevant technical or commercial roles validate all claims, ROI, customer commitments, and tone before use.', N'Synthesis and drafting', N'Value that is not evidenced is opinion; value that is not connected to an ask does not move the decision.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-06-P-AE03', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 2, N'Research the customer and competitive position with citations', N'Build the sourced research base for the executive conversation, so claims can be traced back to something.', N'Featured', N'Prompt', N'Act as my research analyst for an upcoming executive conversation with [Customer]. Produce a sourced brief covering their stated business priorities, recent public announcements and results, the industry pressures they are under, their current technology direction, and any competitor positioning that is likely to come up. Cite every claim. Separate what you found in published sources from what you found in our own work content, and state clearly where you found nothing rather than filling the gap.', NULL, N'Customer name; the executive and their remit; approved access to work content and public sources.', N'Sourced research brief with citations, separating published sources from internal work content, and naming the gaps.', N'AE verifies each citation actually supports the claim, discards anything unsourced, and decides what is appropriate to reference in front of the customer.', N'Evidence gathering', N'An executive notices the difference between a seller who did the research and one who read the account record. Researcher is also available inside Sales Agent, which draws on it to answer research questions; using it directly gives you the full sourced report and the citations.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'AE-07-ALT-01', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 4, N'Pressure-test the renewal assessment', N'Test whether your renewal risk read is supported by usage and engagement evidence or by the absence of bad news.', N'Extended', N'Prompt', N'Review my renewal assessment. For each at-risk renewal, state the evidence behind the risk rating, when the customer was last genuinely engaged, and whether the value delivered has been demonstrated or assumed. Identify the renewal where I am most likely to be wrong and why.', NULL, N'The renewal view with risk evidence; consumption and usage trends; recency of real customer engagement.', N'A renewal challenge with risk evidence, engagement recency, value-proof status, and the renewal most likely misjudged.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Manage Renewal Risk and Expansion Readiness is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-07-ALT-02', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 5, N'Create the renewal follow-through plan', N'Turn the renewal read into the actions and dates that change the outcome while there is still runway.', N'Extended', N'Prompt', N'Turn the renewal assessment into a follow-through plan. For each at-risk renewal, define the action, the owner, the date it must happen by given the renewal date, the value evidence to assemble, and the point at which CE or commercial support must be engaged.', NULL, N'The reviewed renewal view; the renewal dates and their lead times; the account-team and CE owners.', N'A renewal follow-through plan with actions, owners, deadline-aware dates, value evidence, and CE engagement triggers.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Manage Renewal Risk and Expansion Readiness rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-07-P01', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 1, N'Assess renewal risk and expansion readiness', N'Use Sales Agent and available customer context to prioritize upcoming renewals by risk and supported expansion signals.', N'Featured', N'Prompt', N'Show my accounts with renewals in the next six months. For each, summarize ARR, licensing, consumption trend, usage gaps, recent customer engagement, expansion signals, and risk evidence. Prioritize by potential impact and flag missing data.', NULL, N'Your renewal portfolio for the next six months; licensing, consumption and usage data; recent customer engagement history.', N'Renewal risk view with ARR, licensing, consumption or usage trend, engagement recency, expansion signal, impact priority, and missing data.', N'AE validates renewal facts, customer intent, value evidence, and owner alignment with CSAM, CSA, CE, and SSP.', N'Analysis and assessment', N'Renewal risk found early is still actionable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-07-P02', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 2, N'Draft a renewal outreach package', N'Synthesize reviewed evidence into customer communication.', N'Featured', N'Prompt', N'For [Account] renewing in [Month], use the reviewed renewal assessment and source materials to draft outreach tied to stated goals, value delivered, unresolved consumption gaps, and expansion options. Flag pricing or commercial claims for CE review.', NULL, N'The reviewed renewal assessment; the customer''s stated goals; the value evidence you can support, and your CE contact for pricing claims.', N'Renewal outreach draft with customer goals, value delivered, consumption gaps, expansion options, and CE-review flags.', N'AE validates customer claims, tone, commercial statements, and whether expansion is supported by evidence.', N'Synthesis and drafting', N'Renewal outreach should connect value and next action, not just announce a date.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-07-P03', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 3, N'Assemble the renewal and expansion package', N'Pull the renewal position, consumption evidence, value story and expansion options into one package the customer and the account team can both work from.', N'Featured', N'Both', N'Build a renewal and expansion package for [Customer]. Work across the agreement and renewal position, consumption and usage evidence, the value delivered so far, open risks, and the expansion options we believe are supported. Produce a short customer-facing summary, an internal account-team view with the risks stated plainly, and a one-page value story. Show me the plan before you build it, and check in before each document so I can redirect you.', N'1. Bring the customer, the renewal date, and the value evidence you can actually support.
2. Run the prompt.
3. Separate what the package claims as delivered value from what is projected.
4. Flag every pricing or commercial statement for CE review before the package goes near the customer.
5. Confirm the expansion options are grounded in usage evidence rather than aspiration.', N'Approved renewal, consumption, usage and value evidence for the account; the expansion hypotheses already tested.', N'Renewal package with a customer-facing summary, an internal risk view, and a one-page value story.', N'AE validates every claim in the customer-facing material, confirms commercial statements with the Commercial Executive, and decides what is shared externally.', N'Synthesis and drafting', N'The renewal conversation needs a package, not a chat answer. This is multistep work across several sources, with checkpoints, which is what Cowork is for.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'AE-INVEST-01-P01', N'WF-INVEST-01', N'AE-INVEST', N'PH-AE-INVEST-EXPL', 1, N'Identify where customer investment could unlock the next decision', N'Identify where a customer investment could remove a decision, deployment or adoption barrier, without judging eligibility.', N'Featured', N'Prompt', N'Using approved account, opportunity, customer-priority, and adoption context, identify where a customer investment could remove a decision, deployment, or adoption barrier. Separate evidence from assumptions and do not determine eligibility or approval.', NULL, N'Customer priorities, opportunity context, adoption or deployment barrier', N'Investment hypothesis with customer outcome, opportunity linkage, barrier evidence, assumptions, and next human decision.', N'AE confirms the barrier is real, investment is a plausible lever, and eligibility or approval is not implied.', N'Problem identification', N'Naming where customer investment could unlock the next decision is most of the work. Unnamed problems never get an owner.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'AE-INVEST-01-P02', N'WF-INVEST-01', N'AE-INVEST', N'PH-AE-INVEST-EXPL', 2, N'Connect proposed investment to account strategy and outcomes', N'Connect a proposed investment to account priorities and opportunity milestones, naming unsupported claims and dependencies.', N'Featured', N'Prompt', N'Explain how the proposed investment supports account priorities, opportunity milestones, and intended customer outcomes. Identify unsupported claims, dependencies, and the owner of the next decision.', NULL, N'Proposed engagement, scope inputs, intended outcomes', N'Account-level investment rationale with customer outcomes, opportunity milestones, dependencies, unsupported claims, and owner.', N'AE validates account strategy fit, source evidence, and accountable decision owner before routing.', N'Value translation', N'Making proposed investment to account strategy and outcomes explicit is the part almost nobody does, and the part that travels.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'AE-INVEST-01-P03', N'WF-INVEST-01', N'AE-INVEST', N'PH-AE-INVEST-EXPL', 3, N'Confirm account-team sponsorship and handoff', N'Create the handoff showing investment purpose, contributors, unresolved questions and who is accountable next.', N'Featured', N'Prompt', N'Create a concise handoff showing the investment purpose, approved customer context, contributors, unresolved questions, and the person accountable for progressing the request.', NULL, N'Approved context and current investment status', N'Account sponsorship and handoff brief with purpose, contributors, unresolved questions, owner, and next governed action.', N'AE confirms role ownership and does not bypass governed ECIF or investment process steps.', N'Validation and evidence', N'Confirming account-team sponsorship and handoff now costs a conversation. Discovering it late costs a decision.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'AE-INVEST-01-P04', N'WF-INVEST-01', N'AE-INVEST', N'PH-AE-INVEST-EXPL', 4, N'Qualify the investment before anyone builds a request', N'Test whether the investment idea is worth the effort of a request, and decide who owns the next step, before work starts.', N'Featured', N'Both', N'Here is the investment hypothesis for [account and opportunity]: [paste]. Test it. What customer outcome would it unlock that will not happen otherwise? What evidence supports that, and what is assumption? What would need to be true for this to be declined, and is any of that already true? If this is Azure-specific, note that Azure Offer Navigator is the front door rather than a general ECIF request. Recommend proceed, reshape, or stop, and say who owns the next step. Do not assess eligibility or approval likelihood.', N'1. Bring the investment hypothesis from the previous activity.
2. Run the prompt.
3. Be honest about which supporting points are assumption.
4. Decide proceed, reshape, or stop.
5. If proceeding, name who builds the request and who owns the workscope.', N'The investment hypothesis and its account linkage. What the customer has actually said. Who on the account team would build and own the request.', N'A proceed, reshape, or stop decision with the evidence and assumptions separated, and the owner of the next step named.', N'AE owns the judgment about whether the customer outcome is real, and routes eligibility, policy, and funding questions to the accountable owners rather than answering them.', N'Assumption testing', N'The cheapest investment request is the one you decide not to build. Qualifying early costs an hour; qualifying late costs the team weeks.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'AE-INVLINK-01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 5, N'Test whether customer investment would unblock this deal', N'Check the deal for a barrier that customer investment could remove.', N'Extended', N'Prompt', N'Using the approved opportunity, account priorities and current blockers, identify whether a customer investment could remove a decision, deployment or adoption barrier on this deal. Separate evidence from assumption. Do not determine eligibility, funding or approval.', NULL, N'Approved opportunity context, current blockers, account priorities', N'Deal-linked investment hypothesis with barrier, evidence, assumptions, owner, and next human decision.', N'AE confirms the barrier is real, investment is appropriate, and funding or eligibility remains a governed decision.', N'Check the deal for a barrier that customer investment could remove.', N'Investment belongs in the deal conversation only when it changes a real blocker.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-OPP-SCOUT-01', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 6, N'Watch your accounts for buying signals worth acting on', N'Set up a standing watch across your account list so external and internal signals reach you while they are still actionable.', N'Extended', N'Both', N'Set up a recurring watch across my named accounts. Each week, surface publicly reported changes - leadership moves, earnings commentary, announced initiatives, regulatory or funding events - alongside internal signals such as new support volume, usage shifts, or newly opened engagements. For each signal, state what it plausibly implies for a Microsoft opportunity and what would have to be true for that to hold. Separate what is evidenced from what is inference, and cite the source for every external claim.', N'1. Bring your named account list and confirm which of those accounts you can see internal activity for.
2. Run the prompt.
3. Check the first digest against one account you know well, and confirm every external claim carries a source.
4. Set the cadence you will actually read; weekly is usually enough.
5. Discard any signal you cannot trace to a source before acting on it.', N'Your named account list; access to internal account activity; the priority solution areas for your territory.', N'A recurring signal digest per account with sourced external events, internal activity changes, and an explicit evidence-versus-inference split.', N'AE validates each signal against what they know about the account before acting, and never repeats an unsourced claim to a customer.', N'Monitoring and signal', N'Opportunity creation is mostly a timing problem. The trigger events that make an account ready are public or visible internally - the constraint is noticing them while there is still time to act.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'AE-ORCH-01-P01', N'WF-X-ORCH-01', N'AE-ORCH', N'PH-AE-ORCH-EXPL', 1, N'Build the account-team role and handoff map', N'Clarify who needs to be involved, what input they owe, and which customer decision the team is supporting.', N'Featured', N'Prompt', N'For [Account or Opportunity], build an account-team role and handoff map. Include customer outcome, current stage, required Microsoft roles, partner role if relevant, missing coverage, owner for each action, input needed, due date, and the next customer decision. Flag unsupported assumptions and stale context.', NULL, N'Account or opportunity context; current stage; known team members; desired customer decision.', N'Account-team role and handoff map with missing roles, owners, inputs, dates, and next customer decision.', N'AE validates role need, relationship nuance, owner accountability, partner fit, and customer commitments before sharing.', N'Coordination and handoff', N'Most account-team friction is hidden until the handoff fails. Naming it early makes it manageable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-ORCH-01-P02', N'WF-X-ORCH-01', N'AE-ORCH', N'PH-AE-ORCH-EXPL', 2, N'Prepare partner co-sell engagement', N'Identify where partner involvement could improve scale, specialization, credibility, or deal velocity.', N'Featured', N'Prompt', N'Recommend whether partner engagement is useful for [Opportunity]. Identify candidate partner roles, evidence of fit from approved sources, dependencies, risks, proposed two-week ask, and a draft internal introduction. Do not imply partner acceptance or incentive eligibility unless confirmed by approved sources.', NULL, N'Opportunity; solution area; customer context; approved partner evidence or criteria.', N'Partner engagement recommendation with role, evidence, risks, dependencies, draft intro, and next ask.', N'AE validates partner evidence, conflicts, ownership, customer fit, and any incentive or co-sell claims before outreach.', N'Workflow execution', N'Partner engagement helps only when the partner role is specific enough to move the customer decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-ORCH-01-P03', N'WF-X-ORCH-01', N'AE-ORCH', N'PH-AE-ORCH-EXPL', 3, N'Create the account-team briefing and follow-through rhythm', N'Turn context, role asks, and open decisions into a reusable team brief and follow-up rhythm.', N'Featured', N'Both', N'Create a briefing for my extended account team ahead of [event or decision]. Include objective, customer context, open commitments, each role’s expected contribution, prep required, questions I need answered, and follow-up cadence. Keep it concise and flag claims needing validation.', N'1. Choose the account or opportunity.
2. Identify the decision or event.
3. Generate the brief.
4. Validate role asks and sensitive claims.
5. Send or store the brief and create follow-up owners.', N'Account context; event or decision; role list; open commitments; approved source materials.', N'Account-team briefing with role-specific asks, prep, open questions, and follow-through owners.', N'AE confirms role asks, relationship sensitivities, source accuracy, and whether the brief should be shared.', N'Synthesis and drafting', N'A team brief reduces repeated context-setting and makes follow-through inspectable.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-PIPE-SCOUT-01', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 6, N'Keep pipeline hygiene current between reviews', N'Stand up a recurring sweep of your owned pipeline so hygiene problems surface on a schedule instead of the night before a review.', N'Extended', N'Both', N'Check my owned pipeline on a recurring basis and report only what has changed since the last run. Flag opportunities with a close date in the past, no activity in the last 30 days, a missing or generic next step, or a stage that has not moved while the close date has. For each one, draft the specific update or question I would need to resolve it. Rank by revenue at risk within the current period. Do not change any record - produce a review list for me to action.', N'1. Confirm your team''s definition of a healthy next step so the check flags the right things.
2. Run the prompt against your owned pipeline.
3. Review the first list and confirm each flagged opportunity is genuinely stale rather than deliberately paused.
4. Set the cadence to land before your pipeline review, not after it.
5. Make every record change yourself; do not let the check write to MSX.', N'Access to your owned pipeline; your current period close dates; your team''s definition of a healthy next step.', N'A recurring change-only hygiene list ranked by revenue at risk, with a drafted resolution for each flagged opportunity.', N'AE confirms each flagged item is genuinely stale before updating, and makes every record change themselves rather than delegating the write.', N'Monitoring and signal', N'Pipeline hygiene fails because it is a periodic scramble rather than a standing habit. A recurring check that reports only what changed turns a two-hour clean-up into a five-minute review.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'AE-VALUE-01-P01', N'WF-X-VALUE-01', N'AE-VALUE', N'PH-AE-VALUE-EXPL', 1, N'Build the QBR and value evidence brief', N'Assemble outcomes, commitments, usage or consumption signals, risks, investments, and expansion plays into a reviewable evidence base.', N'Featured', N'Prompt', N'For [Account] and [period], build a QBR evidence brief. Include outcomes delivered, supporting evidence, open customer and Microsoft commitments, usage or consumption signals, active investments, risks, expansion plays, and missing evidence. Separate sourced facts from interpretation.', NULL, N'Account; period; approved usage, consumption, meeting, opportunity, investment, and commitment sources.', N'QBR evidence brief with supported outcomes, commitments, risks, expansion plays, and evidence gaps.', N'AE validates source evidence, customer-recognized value, unsupported claims, and which roles must review.', N'Synthesis and drafting', N'A QBR should start with evidence the customer would recognize, not slides that sound good internally.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-VALUE-01-P02', N'WF-X-VALUE-01', N'AE-VALUE', N'PH-AE-VALUE-EXPL', 2, N'Create the executive QBR narrative and strategic asks', N'Convert the reviewed evidence brief into an executive-ready narrative with decisions and asks.', N'Featured', N'Both', N'Using the reviewed QBR evidence brief, create an executive QBR narrative for [Account]. Include a concise executive summary, value delivered, commitments, risks, top expansion plays, investment status if relevant, three strategic asks, and claims requiring final review.', N'1. Review the evidence brief.
2. Generate the QBR narrative or deck outline.
3. Remove unsupported claims.
4. Validate with account-team owners.
5. Decide what becomes customer-facing.', N'Reviewed QBR evidence brief; customer audience; desired decisions; approved branding or format constraints.', N'Executive QBR narrative or deck outline with value story, risks, expansion plays, and strategic asks.', N'AE validates tone, customer relevance, commitments, claims, and whether technical or commercial owners must review.', N'Synthesis and drafting', N'The QBR should create the next decision, not just summarize the last quarter.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'AE-VALUE-01-P03', N'WF-X-VALUE-01', N'AE-VALUE', N'PH-AE-VALUE-EXPL', 3, N'Draft the executive value follow-up', N'Turn reviewed value evidence and strategic asks into a concise customer-ready message.', N'Featured', N'Prompt', N'Draft a follow-up email to [Customer Exec] using the reviewed QBR or value brief. Summarize the value supported by evidence, acknowledge open commitments, propose next steps aligned to strategic priorities, and include three talk-track bullets for my follow-up call. Flag any commercial or technical claims for review.', NULL, N'Reviewed value brief; customer executive; desired next step; approved source evidence.', N'Executive follow-up email and talk-track bullets with review flags.', N'AE validates relationship tone, customer facts, commitments, and claims before sending.', N'Conversation preparation', N'Value is only useful if it reaches the right executive with a clear next step.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ALL-DEAL-01', N'WF-X-DEAL-01', N'ALL-DEAL', N'PH-ALL-DEAL-EXPL', 1, N'Find out what this customer actually owns', N'Retrieve the agreements, enrollments, and license estate for one of your own accounts, so you know what the customer already has before you talk to them.', N'Featured', N'Both', N'List all agreements for [Account name or TPID] with type and status, and show me the list of enrollments. For the agreement I name next, provide the license estate details grouped by SKU. Lead with the identifier I gave you. If you cannot retrieve something, say so rather than estimating it, and do not infer entitlements that are not in the data.', N'1. Bring one account you actually work on.
2. Run the prompt with the account name or TPID.
3. Pick one agreement from what comes back and ask for the license estate grouped by SKU.
4. Note anything you did not know.
5. Note anything you had assumed that turned out to be different.', N'An account you work on, and ideally an agreement number, enrollment number, or TPID. Access to Sales Agent with your CRM scope connected.', N'A list of agreements and enrollments for the account, plus license estate grouped by SKU for one agreement.', N'You confirm the retrieved data matches the account you meant, and treat entitlement and licensing detail as information to verify with the deal owner before making any customer-facing commitment.', N'Inspection and review', N'Most roles walk into customer conversations without knowing what the customer already bought. The answer takes about ninety seconds to retrieve.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ALL-DEAL-02', N'WF-X-DEAL-01', N'ALL-DEAL', N'PH-ALL-DEAL-EXPL', 2, N'See what is expiring and what that means for your work', N'Surface upcoming renewals and consumption trend for your account, then work out what it changes for your own role rather than for the deal owner''s.', N'Featured', N'Both', N'What are the upcoming renewals for [Account name or TPID]? Show expiry dates and current agreement details, then give me the ACR trend month over month for this account. Do not recommend a renewal strategy. I want the facts and the timing so I can work out what my own role needs to do before that date.', N'1. Run the prompt for your account.
2. Note the nearest expiry date.
3. Work backwards: what does your role need to have done before that date?
4. Name the one thing you would otherwise have found out too late.', N'The account and identifier from the previous activity. Your own role''s commitments on that account.', N'Upcoming renewals with expiry dates, agreement detail, and consumption trend, plus one action your own role owns ahead of that date.', N'You decide what the timing means for your own work, and leave renewal strategy, pricing, and commercial approach to the account owner and Commercial Executive.', N'Analysis and assessment', N'A renewal date is a deadline for every role touching the account, not only for the person who owns the deal.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ALL-DEAL-03', N'WF-X-DEAL-01', N'ALL-DEAL', N'PH-ALL-DEAL-EXPL', 3, N'Draw the line between what you can answer and what you should hand off', N'Sort the deal questions you get asked into ones you can now answer yourself and ones that belong to the deal owner, so you stop escalating retrievable facts and stop answering commercial questions you should not.', N'Featured', N'Both', N'Here are deal-related questions I have been asked recently by customers or colleagues: [paste the questions]. For each one, tell me whether it can be answered by retrieving facts from agreements, enrollments, licensing, or consumption data, or whether it requires a commercial, pricing, policy, or approval decision. For the retrievable ones, give me the prompt I would use. For the rest, say what kind of decision it is. Do not answer the commercial ones yourself.', N'1. List the deal questions you have been asked in the last month.
2. Run the prompt.
3. Check the split against your own judgment.
4. Pick one question you used to escalate and commit to answering it yourself next time.
5. Pick one you should always route, and confirm who owns it.', N'Real questions you have been asked. Knowledge of who owns commercial decisions on your accounts.', N'Your questions sorted into retrievable and decision-requiring, with a prompt for the first group and an owner for the second.', N'You own the judgment about where the line sits on your accounts, and confirm that anything commercial, pricing, policy, or approval related routes to the accountable owner rather than being answered from retrieved data.', N'Problem identification', N'Two failures cost time: escalating a question you could have answered, and answering one you should have escalated.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ALL-USECASE-01', N'WF-X-USECASE-01', N'ALL-USECASE', N'PH-ALL-USECASE-EXPL', 1, N'Map the workflow the team chose and find where it leaks', N'Make the chosen workflow visible end to end, then locate the specific steps where time, confidence, or quality is lost.', N'Featured', N'Both', N'I run this recurring workflow: [describe the workflow, what triggers it, how often, and who depends on the output]. Here is a recent example of it going badly: [describe what happened]. Break the workflow into its actual steps. For each step, identify what input it needs, what decision it requires, and who owns it. Then tell me which two or three steps most likely cost time or quality, and why you think so. Ask me for anything you need rather than assuming it. Do not propose tools yet.', N'1. Describe the workflow and one recent example.
2. Run the prompt.
3. Correct the step map where the model got your work wrong; that correction is where the learning is.
4. Agree as a group which step leaks the most.', N'A recurring workflow you personally run; a recent concrete example; who owns each step; what inputs the workflow depends on.', N'A step-by-step map of the chosen workflow with the two or three highest-friction steps named.', N'The person who owns the workflow confirms the step map matches how the work is really done, not how it is supposed to be done.', N'Problem identification', N'Most workflow friction is invisible to the person living with it, because they have already adapted to it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ALL-USECASE-02', N'WF-X-USECASE-01', N'ALL-USECASE', N'PH-ALL-USECASE-EXPL', 2, N'Design one bounded experiment you can finish this week', N'Turn the highest-friction step into a test small enough to run before the next huddle and specific enough to judge.', N'Featured', N'Both', N'Here is the workflow step I want to test: [paste the step and why it costs time or quality]. Design a one-week experiment. Specify: the exact input I will supply, the action I will take, the output I expect, who reviews it before it is used, what evidence I will bring back, and the stop condition that tells me to abandon it. Keep it small enough to run in under an hour total. If the step as described is too large to test in a week, tell me how to narrow it rather than proposing a bigger plan.', N'1. Take the step your group identified.
2. Run the prompt.
3. Cut the experiment down until it fits in an hour.
4. Name your reviewer and your stop condition out loud.
5. Put it in your calendar before you leave the huddle.', N'The friction step from the previous activity; what data or systems you can actually access this week; who could review the output.', N'A bounded experiment card with input, action, output, reviewer, evidence, and stop condition.', N'You decide whether the experiment is genuinely small enough to finish, and you own the judgment about what output is safe to use in real work.', N'Planning and drafting', N'An experiment that does not fit in a week does not get run, and an experiment without a stop condition never ends.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-03-ALT-01', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'PH-ATS-WORKLOAD-EXPL', 3, N'Stress-test the workload readiness evidence', N'Test each ranked workload for the readiness evidence that exists, what is still unproven, and who would need to confirm it.', N'Extended', N'Prompt', N'Review this workload prioritization. For each ranked workload, identify the readiness evidence that exists, the impact assumption being made, what is still unproven, the dependency most likely to block it, and the person who would need to confirm it.', NULL, N'Draft workload ranking, readiness signals, and approved account context.', N'Workload readiness challenge list with unproven assumptions and named confirmation owners.', N'ATS confirms which assumptions must be validated before the ranking is allowed to influence technical strategy.', N'Assumption testing', N'A ranking built on unproven readiness sends technical effort to the wrong workload.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-03-ALT-02', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'PH-ATS-WORKLOAD-EXPL', 4, N'Package the workload decision brief', N'Assemble the ranked workloads, rationale, blockers and validation steps into a brief the v-team can decide from.', N'Extended', N'Prompt', N'Using the approved workload prioritization, create a decision brief with ranked workloads, rationale, owner, dependency, blocker, next validation step, and team ask.', NULL, N'Approved workload ranking and evidence.', N'Workload decision brief ready for team review.', N'ATS confirms priority, owner, dependency, and whether the team ask is realistic.', N'Synthesis and handoff', N'The priority is not real until the next action and owner are named.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-04-ALT-01', N'WF-X-ARCH-01', N'ATS-TECH', N'PH-ATS-TECH-EXPL', 4, N'Validate technical and business assumptions', N'Find the unsupported assumptions, unresolved risks and readiness gaps in a technical strategy before it is socialized.', N'Extended', N'Prompt', N'Review this technical strategy package. Identify unsupported assumptions, weak evidence, unresolved technical risks, customer readiness gaps, security or compliance dependencies, and decisions that require SME review.', NULL, N'Draft strategy package and source evidence.', N'Assumption and validation gap register.', N'ATS decides what to revise before sharing or acting.', N'Assumption testing', N'If the strategy is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-05-ALT-01', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 3, N'Validate briefing evidence and decisions', N'Check that the briefing is designed to move a specific customer decision and that its claims and participants support that.', N'Extended', N'Prompt', N'Review this EBC plan. Identify the customer decision it is designed to move, evidence gaps, unsupported technical or business claims, missing participants, and follow-through risks.', NULL, N'Draft EBC plan and approved evidence.', N'Briefing validation checklist and fix list.', N'ATS confirms which fixes are required before the briefing plan is used.', N'Validation and evidence', N'A briefing plan without evidence and follow-through becomes calendar management.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-05-ALT-02', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 4, N'Brief the contributors so they arrive ready', N'Give each contributor their objective, the evidence they own, the questions to expect and the time they have.', N'Extended', N'Prompt', N'Using the validated EBC plan, create a per-contributor brief that states the session objective, what each participant must prepare, the evidence they own, the questions they should expect, and the time they have.', NULL, N'Validated EBC plan and confirmed participant list.', N'Per-contributor briefing pack with owned evidence and time allocation.', N'ATS confirms each ask is realistic and that no contributor is asked to present unvalidated evidence.', N'Coordination and handoff', N'An executive briefing fails quietly when contributors arrive unclear about their part.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-05-ALT-03', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 5, N'Define follow-through and inspection rhythm', N'Turn briefing commitments into owners, checkpoint dates and the escalation triggers that keep them alive afterwards.', N'Extended', N'Prompt', N'Using the approved EBC plan, create a follow-through plan with decisions, commitments, owners, evidence required, checkpoint dates, risks, and escalation triggers.', NULL, N'Approved EBC plan and participant list.', N'Follow-through and inspection plan.', N'ATS validates ownership, timing, and escalation boundaries.', N'Follow-through planning', N'The briefing creates value only if the next decision survives after the session.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-06-ALT-01', N'WF-X-CONV-01', N'ATS-TALK', N'PH-ATS-TALK-EXPL', 3, N'Find the weak claims before the customer does', N'Audit the talk track claim by claim, separating what is evidenced from what rests on assumption or unshipped roadmap.', N'Extended', N'Prompt', N'Audit this talk track claim by claim. For each claim, state the evidence that supports it, whether that evidence is approved for customer use, and what a technically informed customer would ask for. Flag any claim that rests on assumption, marketing language, or a roadmap item rather than something available today.', NULL, N'Draft talk track, current customer signals, and approved evidence.', N'Claim-by-claim audit separating supported claims, unsupported claims, and roadmap-dependent claims.', N'ATS decides which challenges are real and validates any technical claim before it is used with the customer.', N'Validation and evidence', N'Executive credibility is lost on one unsupported claim, and roadmap language is the most common source.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-06-ALT-02', N'WF-X-CONV-01', N'ATS-TALK', N'PH-ATS-TALK-EXPL', 4, N'Package the technical conversation brief', N'Assemble the objective, signals, questions, objections and reviewed responses into one brief you can walk in with.', N'Extended', N'Prompt', N'Package the approved talk track into a conversation brief with objective, audience, customer signals, opening, key questions, likely objections, reviewed responses, roles, and follow-up ownership.', NULL, N'Approved talk track and meeting context.', N'Technical conversation brief.', N'ATS confirms claims, roles, and follow-up before sharing.', N'Synthesis and handoff', N'A talk track becomes useful when the team can align around it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-07-P02', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 2, N'Assess role coverage and handoffs', N'Identify missing role coverage and handoff risk.', N'Featured', N'Prompt', N'Review [Account or Opportunity]. Identify current AE, ATS, SSP, SE, CE, CSA, CSAM, partner, and investment coverage for the technical decision in front of the customer. Flag missing roles, unclear owners, dependency risks, and the next handoff that needs confirmation.', NULL, N'Account or opportunity; current team context; decision to move.', N'Role coverage and handoff map.', N'ATS confirms who owns each input, action, and decision.', N'Coverage inspection', N'You cannot orchestrate a team if the coverage gaps are invisible.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ATS-CBR-P01', N'WF-X-VALUE-01', N'ATS-CBR', N'PH-ATS-CBR-EXPL', 1, N'Create the technical CBR contribution', N'Draft the ATS portion of a customer business review.', N'Featured', N'Prompt', N'Using approved account and technical sources, draft the technical contribution for a CBR. Include customer objectives, roadmap, technical progress, proof, risks, open decisions, asks, and follow-through owners.', NULL, N'Approved account, roadmap, proof, risk, and outcome sources.', N'Technical CBR contribution.', N'ATS validates technical accuracy, claims, proof, and customer relevance.', N'Synthesis and drafting', N'The CBR needs the technical story connected to customer outcomes.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-CBR-P02', N'WF-X-VALUE-01', N'ATS-CBR', N'PH-ATS-CBR-EXPL', 2, N'Review technical claims and evidence', N'Check CBR technical content before sharing.', N'Featured', N'Prompt', N'Review this technical CBR contribution. Flag unsupported claims, missing evidence, unclear decisions, weak linkage to customer priorities, and follow-through gaps.', NULL, N'Draft technical CBR contribution and source evidence.', N'Claim and evidence review list.', N'ATS decides which claims to revise, remove, or route to SME review.', N'Validation and evidence', N'Unsupported technical claims weaken the whole customer review.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-CBR-P03', N'WF-X-VALUE-01', N'ATS-CBR', N'PH-ATS-CBR-EXPL', 3, N'Turn the hardest review questions into a readiness edit', N'Find the three questions the content invites, then change the contribution so it answers them before they are asked.', N'Featured', N'Both', N'Here is our technical contribution for a customer business review: [paste]. Identify the three hardest questions this content invites, including about progress that has been slower than planned and any risk we have named. For each question, state what evidence the content currently offers, whether that evidence is sufficient, and the specific edit to the contribution that would answer the question before it is asked. Return the edits as a numbered change list, not as a rewritten document. Do not treat a statement of intent as evidence.', N'1. Bring the reviewed CBR contribution.
2. Run the prompt.
3. Apply the edits where evidence exists.
4. For any question where evidence does not exist, decide whether to name the gap openly in the review or remove the claim.
5. Bring that decision to the huddle.', N'The technical CBR contribution; known risks and slow areas; who attends from the customer side; commitments made in prior reviews.', N'A numbered change list making the contribution answer its three hardest questions, plus any evidence gap named explicitly.', N'ATS decides whether to strengthen the evidence, name the gap openly, or remove the claim, and owns every technical statement made to the customer.', N'Validation and evidence', N'The credibility of a business review is decided by the answer to the uncomfortable question.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-CBR-P04', N'WF-X-VALUE-01', N'ATS-CBR', N'PH-ATS-CBR-EXPL', 4, N'Convert the review into technical decisions', N'Turn what was discussed into the decisions, owners, and dates that make the next review shorter.', N'Featured', N'Both', N'Here are the notes from the customer business review [paste]. Extract only the technical decisions that were actually made, the decisions that were deferred and why, and the ones that were avoided. For each open decision, state who needs to make it, what they need in order to make it, and by when it must happen to protect the roadmap. Do not record a decision as made if the notes show it was only discussed.', N'1. Capture review notes.
2. Run the prompt.
3. Separate made, deferred, and avoided.
4. Assign the top open decision an owner and date.
5. Confirm it with the customer.', N'Review notes; attendees; the roadmap and its dependencies; commitments made in prior reviews.', N'Separated lists of made, deferred, and avoided decisions, with owners and dates for the open ones.', N'ATS confirms which decisions were genuinely made and owns the follow-up commitments before they are shared.', N'Synthesis and drafting', N'A review that produces no decision guarantees the same conversation next quarter.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-HEALTH-P01', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'PH-ATS-HEALTH-EXPL', 1, N'Prioritize technical health risks', N'Create a ranked technical risk response.', N'Featured', N'Prompt', N'Review available account, usage, deployment, support, and technical context. Identify the top technical health risks, evidence, impact, owner, intervention, and next checkpoint. Flag missing data.', NULL, N'Authorized account, usage, deployment, support, and technical context.', N'Ranked technical risk response.', N'ATS validates risk significance, owner, and intervention.', N'Risk inspection', N'A technical risk only matters when someone decides what to do about it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-HEALTH-P02', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'PH-ATS-HEALTH-EXPL', 2, N'Coordinate the technical risk intervention', N'Turn a reviewed risk into a coordinated action plan.', N'Featured', N'Prompt', N'Using the reviewed technical risk response, create an intervention plan with owners, dependencies, customer communication needs, escalation triggers, and checkpoint dates.', NULL, N'Reviewed technical risk response and role context.', N'Technical risk intervention plan.', N'ATS confirms owners, dependencies, and escalation path.', N'Orchestration', N'Risk response usually fails at the handoff, not the diagnosis.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-HEALTH-P03', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'PH-ATS-HEALTH-EXPL', 3, N'Raise the risk with the customer before it becomes news', N'Draft the message that tells the customer about a technical risk early, in a way that keeps trust rather than spending it.', N'Featured', N'Both', N'We have identified this technical health risk: [paste risk, evidence, impact, and what we are doing]. Draft a short message to the customer technical owner that states the risk plainly, what we know and do not yet know, what we are already doing, what we need from them, and when we will update them next. Do not minimize the risk, do not over-apologize, and do not commit to a resolution date we have not agreed internally. Keep it under 150 words.', N'1. Bring the ranked risk and intervention plan.
2. Confirm internally what can be committed.
3. Run the prompt.
4. Adjust to your relationship with the customer.
5. Send, and diarize the next update.', N'The identified risk and its evidence; the intervention plan; what has been agreed internally; the customer relationship and prior communications.', N'A short, honest customer message with a named next update date.', N'ATS confirms no commitment is made that has not been agreed internally, and owns the decision to communicate and the wording.', N'Synthesis and drafting', N'A risk the customer hears about from us early costs far less than one they discover themselves.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-HEALTH-P04', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'PH-ATS-HEALTH-EXPL', 4, N'Find the risk the data does not show', N'Test the health assessment against what people have said, not only against what the systems report.', N'Featured', N'Both', N'Here is our current technical health assessment based on system data: [paste]. Here are recent notes and conversations with the customer team: [paste]. Identify concerns raised by people that do not appear in the system data, and any system signal that people are not talking about. For each mismatch, say which source is more likely to be right and what would confirm it. Do not treat silence as agreement.', N'1. Bring the data-based assessment.
2. Gather recent conversation notes. If dashboard or transcript access is unavailable, build a lightweight table by hand with source, date, owner, evidence, and your confidence in it, then use that instead.
3. Run the prompt.
4. Pick the mismatch that would hurt most if ignored.
5. Add it to the risk list or record why not.', N'System-derived health assessment, or a hand-built substitute table if system access is unavailable; recent conversation notes with the customer team; who has been quiet and who has been raising concerns.', N'A list of mismatches between reported data and human signals, with what would confirm each.', N'ATS judges which human signal is credible and owns the decision to add or dismiss a risk.', N'Analysis and assessment', N'The risks that damage accounts are usually mentioned in conversation long before they appear in a dashboard.', N'https://m365.cloud.microsoft/chat', N'Open Analyst'),
        (N'ATS-INTEL-SCOUT-01', N'WF-X-PLAN-01', N'ATS-INTEL', N'PH-ATS-INTEL-EXPL', 4, N'Build a standing account intelligence hub the v-team can use', N'Consolidate the scattered sources behind account planning into one maintained hub that refreshes rather than being rebuilt each planning cycle.', N'Extended', N'Both', N'Build me a standing account intelligence hub for this account. Pull together the business context, current opportunities, stakeholder map, installed estate and licensing position, recent engagement history, and open risks into one structured place. Then keep it current on a recurring basis and tell me specifically what changed since the last refresh. Where a source is unavailable to you, list it as a gap rather than filling it with inference.', N'1. Confirm which account planning sources you can reach, and name the ones you cannot.
2. Run the prompt.
3. Review the first hub build against what you already know about the account.
4. Check that nothing customer-confidential has been placed where the wider v-team should not see it.
5. Set the refresh cadence and agree with the v-team who reads the change summary.', N'The account name; access to your account planning sources; the v-team members who need visibility.', N'A maintained account intelligence hub with a change summary each refresh and an explicit list of unavailable sources.', N'ATS reviews the hub for accuracy before sharing with the v-team, and confirms that no customer-confidential material has been placed where it should not sit.', N'Research and synthesis', N'Account planning quality is usually limited by assembly time, not thinking time. When the assembly is standing and self-refreshing, the v-team spends its hour on the judgement instead of the gathering.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'ATS-INVEST-01-P01', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 1, N'Assess strategic and technical investment fit', N'Test whether the investment advances the account technology strategy.', N'Featured', N'Prompt', N'Review this proposed customer investment. Assess fit against account technology strategy, priority workloads, customer readiness, deployment blockers, expected technical outcome, consumption path, dependencies, and risks. Recommend proceed, revise, or pause for review.', NULL, N'Investment idea or request; account technology plan; workload priorities; readiness and blocker context.', N'Strategic and technical investment fit assessment.', N'ATS validates strategy fit, technical feasibility, dependencies, and recommendation. Final funding decisions remain with accountable owners.', N'Investment assessment', N'Testing investment fit early prevents technical time from being spent on low-value work.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ATS-INVEST-01-P02', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 2, N'Validate engagement scope and consumption readiness', N'Assess whether the funded engagement can deliver the intended outcome.', N'Featured', N'Prompt', N'Review the proposed engagement scope, milestones, deliverables, success criteria, deployment path, partner readiness, customer readiness, and consumption drivers. Identify gaps, risks, and fixes needed before request review.', NULL, N'Draft scope; milestones; deliverables; success criteria; readiness context.', N'Scope and consumption-readiness review.', N'ATS confirms technical content and readiness; eligibility, approval, policy, and commercial decisions remain with accountable owners.', N'Validation and evidence', N'Unclear scope becomes rework at approval or delivery.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ATS-INVEST-01-P03', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 3, N'Build the investment review recommendation', N'Package the recommendation for the human decision owner.', N'Featured', N'Prompt', N'Using the reviewed investment assessment, create a concise recommendation package with strategic rationale, technical outcome, scope concerns, dependencies, risks, required reviewers, open questions, and the next governed decision.', NULL, N'Reviewed investment assessment and supporting evidence.', N'Investment review recommendation package.', N'ATS validates claims and routes approval questions to the correct owner before use.', N'Synthesis and drafting', N'The goal is not to approve inside the prompt. The goal is to make the next governed decision easier.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-INVEST-01-P04', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 4, N'Track investment dependencies and realization evidence', N'Create a lightweight evidence and dependency rhythm.', N'Featured', N'Prompt', N'Create an investment follow-through tracker with dependency, owner, milestone, evidence required, risk, decision needed, checkpoint date, and realization signal.', NULL, N'Approved or draft investment plan; owners; milestones; expected outcomes.', N'Investment dependency and evidence tracker.', N'ATS confirms ownership, evidence quality, and escalation path.', N'Monitoring and follow-through', N'Investment value is proven with evidence gathered along the way, not reconstructed at the end.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-INVEST-01-P05', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 5, N'Prove the investment produced the technical outcome', N'Collect the technical evidence that the investment delivered what it was funded to deliver, and name what it did not.', N'Featured', N'Both', N'This investment was funded to achieve [paste the original technical outcome and success measures]. Here is what has happened since: [paste delivery status, milestones from ECIF Central, and any technical results]. Assess each success measure as met, partially met, or not met, with the evidence for each judgment. Where a measure cannot be evidenced, say so rather than inferring it. Identify what would need to be true for this to count as a technical success, and what the customer would say if asked independently.', N'1. Retrieve the original success measures from the approved workscope.
2. Gather delivery status and milestones from ECIF Central.
3. Run the prompt.
4. Be honest about measures that cannot be evidenced.
5. Bring the unmet ones to the account team before the realization review, not during it.', N'The original technical outcome and success measures from the workscope. Delivery status and milestones from ECIF Central. Technical results to date.', N'Each success measure assessed with evidence, and an explicit list of what cannot be evidenced.', N'ATS owns the technical judgment about whether an outcome was genuinely achieved, and does not let an unevidenced measure be reported as met.', N'Validation and evidence', N'Investment that cannot be evidenced makes the next request harder for everyone on the account.', N'https://aka.ms/ECIFCentral', N'Open ECIF Central'),
        (N'ATS-PARTNER-P01', N'WF-X-ORCH-01', N'ATS-PARTNER', N'PH-ATS-PARTNER-EXPL', 1, N'Identify partner and specialist capability gaps', N'Assess what support is needed for the technical priority.', N'Featured', N'Prompt', N'For [Account or Opportunity], summarize the technical priority, current roles involved, missing capability, partner or specialist support needed, timing, risks, and next decision. Recommend the role needed, not a specific partner unless supported by available data.', NULL, N'Account or opportunity context; technical priority; role coverage.', N'Capability gap and support need assessment.', N'ATS validates capability need, timing, and whether partner involvement is appropriate.', N'Coverage inspection', N'Support should be attached to the technical priority, not added by habit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ATS-PARTNER-P02', N'WF-X-ORCH-01', N'ATS-PARTNER', N'PH-ATS-PARTNER-EXPL', 2, N'Prepare the support alignment note', N'Create an internal alignment note for partner or specialist support.', N'Featured', N'Prompt', N'Using the reviewed support need, draft an internal alignment note with customer outcome, technical priority, expected contribution, required preparation, owner, timing, and next decision.', NULL, N'Reviewed support need and approved account context.', N'Support alignment note.', N'ATS validates claims, owners, timing, and sensitivity before sending.', N'Synthesis and handoff', N'Clear asks make it easier for partners and specialists to contribute at the right time.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-PARTNER-P03', N'WF-X-ORCH-01', N'ATS-PARTNER', N'PH-ATS-PARTNER-EXPL', 3, N'Brief the specialist so they arrive useful', N'Build the short briefing that lets a partner or specialist contribute in their first meeting rather than spending it catching up.', N'Featured', N'Both', N'A [role] is joining to support this technical priority. First tell me: are they an internal Microsoft specialist or an external partner? I will answer, and you will adjust what may be included accordingly. Here is the context: [paste priority, customer context, and what has already been tried]. Write the briefing they need before their first customer meeting. Include: the customer''s outcome in their own words, what has already been attempted and why it did not close the gap, the technical constraints that are fixed, who they will meet and what each person cares about, the specific contribution we need from them, and what they should not commit to. If the recipient is external, generalize or remove customer-identifying detail, internal roadmap references, unannounced product information, and named technical risks, and list separately what I removed so I can decide whether to share it another way. Keep it under 300 words and assume they have no history with this account.', N'1. Bring the capability gap assessment and alignment note.
2. Classify the recipient as internal specialist or external partner before writing anything.
3. Run the prompt.
4. Review the removed-items list and decide what, if anything, to share through an approved channel.
5. Send it before the meeting, not during.
6. Ask them what is still unclear.', N'Whether the recipient is an internal Microsoft specialist or an external partner; the technical priority and customer outcome; what has been tried; fixed constraints; the stakeholders they will meet; the sensitivity classification of any account detail.', N'A short standalone briefing appropriate to the recipient type, plus a separate list of anything withheld because the recipient is external.', N'ATS classifies the recipient as internal or external before drafting, then confirms that no customer-identifying detail, roadmap reference, or named technical risk reaches an external partner without approval, and confirms what the recipient may and may not commit to.', N'Coordination and handoff', N'An unbriefed specialist spends their first customer meeting learning what you already knew.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-PARTNER-P04', N'WF-X-ORCH-01', N'ATS-PARTNER', N'PH-ATS-PARTNER-EXPL', 4, N'Check whether the support actually moved the priority', N'Review what changed after partner or specialist involvement, so the next request is based on evidence rather than habit.', N'Featured', N'Both', N'Gather what has happened on this account since [date] from my recent meetings, notes, chats, and files, and summarize it against this original capability gap and ask: [paste original gap and what we asked for]. Then assess whether the gap is now closed, partially closed, or unchanged, and what evidence supports that judgment. If it is unchanged, identify whether the problem was the brief, the fit, the timing, or the gap itself being misdiagnosed. If you cannot find enough recent activity to judge, say so rather than inferring. Be direct.', N'1. Restate the original gap and ask.
2. Let the agent gather recent activity, or supply it manually if the agent cannot reach the sources.
3. Run the prompt.
4. Decide whether to continue, change the ask, or stop.
5. Record the lesson for the next request.', N'The original capability gap and the ask made; the date support began; access to recent meetings, notes, and files, or a manual summary if access is unavailable; the current state of the technical priority.', N'A judgment on whether the gap closed, with evidence, and a diagnosis if it did not.', N'ATS owns the assessment of a colleague''s or partner''s contribution and decides how, or whether, it is shared.', N'Inspection and review', N'Support gets added by habit unless someone checks whether the last one worked.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'ATS-TEAM-P05', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 5, N'Keep the v-team commitments moving between huddles', N'Set up a recurring check that watches the technical v-team commitments and tells you what has slipped, without you having to go looking.', N'Extended', N'Both', N'Set up a recurring check on the technical v-team commitments for [Account or opportunity]. Each week, look across our meetings, mail and the account record for the commitments made, and tell me which ones have no activity since they were made, which have passed their date, and which have gone quiet on the customer side. Give me the specific chase for each one and who should make it. Keep a memory of what you already flagged so you are not repeating the same item back to me every week.', N'1. Bring the current v-team commitments with owners and dates.
2. Run the prompt.
3. Confirm each flagged commitment is genuinely stalled rather than progressing somewhere you cannot see.
4. Set the cadence to run before your v-team call.
5. Raise slipped items with the owner directly rather than in the group thread.', N'The v-team commitments and owners from the alignment brief; approved access to your own mail, meetings and account record.', N'A recurring commitment check that reports slipped, stalled and quiet items with a named chase for each.', N'ATS decides whether silence actually means a stall, and owns the judgment about which chases are appropriate given the relationships involved.', N'Monitoring and follow-through', N'Technical commitments do not fail loudly. They go quiet, and by the time anyone notices the customer has moved on. This is exactly the persistent, between-sessions work that Scout is built for.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CE-01-ALT-01', N'WF-X-HEALTH-01', N'CE-HEALTH', N'PH-CE-HEALTH-EXPL', 3, N'Stress-test assumptions behind the commercial risk view', N'Find the unsupported assumptions, stale sources and missing owners that would change your commercial risk recommendation.', N'Extended', N'Prompt', N'Review the commercial risk view for unsupported assumptions, stale sources, missing owners, policy dependencies, approval needs, and customer constraints. Identify what would change the intervention recommendation.', NULL, N'The prioritized commercial risk view; the source and date behind each item; the customer constraints you know of.', N'Commercial assumption and risk register with evidence gaps, owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the commercial risk view will fail, it should fail in review rather than at approval or with the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-01-ALT-02', N'WF-X-HEALTH-01', N'CE-HEALTH', N'PH-CE-HEALTH-EXPL', 4, N'Create the intervention and escalation plan', N'Turn prioritized commercial risks into owned actions, keeping internal steps separate from anything the customer is asked to do.', N'Extended', N'Prompt', N'Translate the prioritized commercial risks into owners, next actions, approval steps, customer actions, escalation route, and inspection points. Separate internal actions from customer actions.', NULL, N'The validated commercial risk view; the approval owners; the escalation route your team actually uses.', N'Commercial intervention plan with owners, actions, escalation route, and inspection points.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Risk without owner, action, and route is just a warning label.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-02-ALT-01', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 4, N'Stress-test commercial structure assumptions', N'Find the precedent risk, customer constraints and approval dependencies a proposed commercial structure is quietly assuming away.', N'Extended', N'Prompt', N'Review the proposed commercial structure for unsupported assumptions, customer constraints, policy dependencies, approval needs, precedent risk, and unresolved decisions.', NULL, N'The proposed commercial structure; the approval requirements it triggers; known customer constraints and precedent concerns.', N'Commercial structure assumption register with risks, evidence gaps, and decision owners.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the structure will fail, it should fail while options still exist.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-02-ALT-02', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 5, N'Build the commercial structure execution plan', N'Turn the selected commercial direction into owners, approval steps and inspection points that survive contact with the deal timeline.', N'Extended', N'Prompt', N'Translate the selected commercial direction into owners, approval steps, dependencies, customer actions, internal actions, and inspection points.', NULL, N'The selected commercial structure; the approval path and its lead times; internal and customer action owners.', N'Commercial structure execution plan with owners and approval path.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'The structure is not real until the approval path and owners are real.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-02-BYOD-01', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 2, N'Build an MCA-E proposal from a validated product list you already have', N'Bring your own product data into proposal creation for an MCA-E or EA to MCA-E transition, and resolve what does not map before it reaches the customer.', N'Featured', N'Both', N'I have product and quantity data for an MCA-E proposal in a spreadsheet. Walk me through bringing it in: what format you need, how you will validate the SKUs and products against the agreement, and what happens to anything that does not match. Then generate the draft proposal in MSX from the validated inputs. List every unmatched product separately so I can resolve it, and tell me if the upload has to be split across multiple proposals to stay within platform limits. Do not drop unmatched items silently.', N'1. Prepare the product and quantity data as Excel or CSV.
2. Run the prompt and follow the validation guidance.
3. Review the unmatched product list; those are the ones that will cause problems later.
4. Resolve or consciously defer each one.
5. Generate the draft proposal in MSX.
6. Check the proposal against the customer''s actual commercial expectation before it goes anywhere.', N'Product and quantity data in Excel or CSV. The MCA-E agreement or the EA being transitioned. The opportunity the proposal attaches to.', N'A validated input set, a named list of unmatched products for follow-up, and a draft proposal in MSX ready for commercial review.', N'CE confirms the SKU mapping is commercially correct rather than merely valid, resolves unmatched products rather than accepting the gap, and owns the pricing and structure before the proposal reaches the customer.', N'Execution and validation', N'Unmatched products found before proposal creation are a cleanup task. Found after, they are a customer conversation.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-02-DEAL-01', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 1, N'Create and validate the deal path', N'Role-relevant Deal Making capabilities practice within the recommended Role Path.', N'Featured', N'Prompt', N'Using the approved agreement or enrollment context, review deal assumptions and create or revise the appropriate deal-book or proposal path. Include options, dependencies, validation issues, authority boundaries, and required approvals. Do not submit or approve deal artifacts.', NULL, N'Approved agreement or enrollment identifier, deal strategy, pricing context, and approval constraints.', N'Reviewable deal path with options, proposal or deal-book artifact, validation findings, and approval requirements.', N'CE validates commercial accuracy, pricing, exception handling, approval path, and any customer-facing use before progressing the deal.', N'Synthesis and drafting', N'You spend your time editing the deal path rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-03-ALT-01', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 3, N'Stress-test policy and licensing assumptions', N'Identify where a policy or licensing conclusion rests on stale guidance or an assumption no authoritative owner has confirmed.', N'Extended', N'Prompt', N'Review the policy and licensing check for unsupported assumptions, stale guidance, missing evidence, unresolved exceptions, and questions that require authoritative review.', NULL, N'The policy and licensing check; the guidance sources used and their dates; the authoritative owners for each open question.', N'Policy assumption register with evidence gaps, authoritative owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the policy interpretation is uncertain, that uncertainty should be explicit before the deal advances.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-03-ALT-02', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 4, N'Create the policy routing and execution plan', N'Route each open policy question to its authoritative owner with the evidence they need, without implying an approval that has not happened.', N'Extended', N'Prompt', N'Translate the policy and licensing findings into routed questions, owners, evidence needed, approval steps, and execution checkpoints. Do not infer approval or exception status.', NULL, N'The policy and licensing findings; the authoritative owner for each question; the deal timeline the answers must meet.', N'Policy routing and execution plan with owners, evidence, and checkpoints.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Policy work moves when the question, owner, and evidence are explicit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-04-ALT-01', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 5, N'Stress-test negotiation assumptions', N'Test the concession logic and authority boundaries in a negotiation plan before customer pressure exposes them.', N'Extended', N'Prompt', N'Review the negotiation plan for unsupported commercial assumptions, customer constraints, policy dependencies, approval needs, concession risks, and unresolved authority boundaries.', NULL, N'The negotiation plan with its concession logic; your confirmed authority limits; known customer constraints and alternatives.', N'Negotiation assumption register with authority gaps, concession risks, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the negotiation position will fail, it should fail in rehearsal rather than across the table.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-04-ALT-02', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 6, N'Build the negotiation follow-through plan', N'Define who does what after the negotiation, including concession checkpoints and the triggers that force an escalation.', N'Extended', N'Prompt', N'Translate the negotiation position into owners, customer actions, internal approval steps, concession checkpoints, escalation triggers, and follow-through dates.', NULL, N'The agreed negotiation position; the approval owners; the customer commitments and dates already made.', N'Negotiation follow-through plan with owners, checkpoints, and escalation triggers.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Negotiation discipline survives only when follow-through is explicit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-05-ALT-01', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 5, N'Stress-test approval and execution assumptions', N'Find where an approval path assumes an owner, an evidence item or an exception that nobody has actually confirmed.', N'Extended', N'Prompt', N'Review the approval and commercial execution path for unsupported assumptions, missing evidence, unclear owners, policy dependencies, exception triggers, and unresolved decisions.', NULL, N'The commercial execution path; the approval record as it stands; the exception triggers your team must respect.', N'Approval and execution assumption register with evidence gaps, owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If approval will fail, it should fail before the package reaches the approver.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-05-ALT-02', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 3, N'Build the approval and execution plan', N'Turn a commercial direction into a governed execution plan that never represents approval as granted unless the record confirms it.', N'Extended', N'Prompt', N'Translate the commercial direction into owners, approval steps, evidence needed, dependencies, customer actions, internal actions, escalation route, and inspection points. Do not represent approval as granted unless the authoritative record confirms it.', NULL, N'The commercial recommendation; the authoritative approval record; the owners for each approval step and customer action.', N'Governed commercial execution plan with owners, approval path, blockers, and next decision.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Commercial execution stalls when the route, owner, and evidence are implied.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-05-ECIF-01', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 1, N'Clarify ECIF commercial and approval dependencies', N'Role-relevant ECIF practice within the recommended Role Path.', N'Featured', N'Prompt', N'Using approved deal and ECIF context, summarize commercial dependencies, approval touchpoints, communication constraints, evidence needs, and unresolved questions that require ECIF, finance, Deal Desk, or policy-owner review. Do not imply funding, policy, or approval authority without explicit evidence.', NULL, N'Approved deal context, current ECIF status, and authoritative guidance.', N'Commercial dependency and escalation brief with owners, evidence needs, and next decisions.', N'CE confirms whether the scenario is within CE accountability and does not imply funding, policy, or approval authority without explicit evidence.', N'Scoping and design', N'ECIF dependencies move faster when the commercial question, owner, and evidence are visible early.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-05-ORCH-01', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 2, N'Map the approval path and the evidence each approver needs', N'Build the approval sequence for the commercial structure, with owners, evidence, and timing. Assumes policy and licensing questions have already been routed.', N'Featured', N'Prompt', N'Using approved deal context, map the approval path for this commercial structure: each approval required, the accountable owner, the evidence or justification that approver expects, the sequence and dependencies, the rework risk, and a realistic timeline. Do not interpret pricing, discount, or policy rules; route those to the authoritative owner.', NULL, N'Approved deal context, proposed commercial structure, and current approval guidance.', N'Approval path with owners, required evidence, sequence, dependencies, and timeline risk.', N'CE verifies approval requirements against authoritative guidance and routes pricing, discount, and policy interpretation to the accountable owner rather than answering them.', N'Scoping and design', N'Approvals discovered one at a time cost weeks. Approvals mapped up front cost a conversation.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-06-ALT-01', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 4, N'Stress-test renewal strategy assumptions', N'Challenge the value evidence, expansion claims and approval assumptions in a renewal strategy before they reach the customer.', N'Extended', N'Prompt', N'Review the renewal strategy for unsupported commercial assumptions, value evidence gaps, customer constraints, policy dependencies, approval needs, expansion claims, and unresolved decisions.', NULL, N'The renewal strategy; the value evidence behind each claim; the approval requirements and customer constraints.', N'Renewal assumption and risk register with evidence gaps, owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the renewal strategy will fail, it should fail while there is still time to change it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-06-ALT-02', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 5, N'Build the renewal execution plan', N'Convert the renewal strategy into owners, approval steps and timing checkpoints that hold against the renewal date.', N'Extended', N'Prompt', N'Translate the renewal strategy into owners, approval steps, customer actions, internal actions, dependencies, inspection points, and timing checkpoints.', NULL, N'The validated renewal strategy; the renewal date and approval lead times; the internal and customer owners.', N'Renewal execution plan with owners, approval path, actions, and checkpoints.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A renewal strategy becomes executable only when owners and checkpoints are explicit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-06-SCOUT-01', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 3, N'Watch the renewal portfolio for commercial trigger dates', N'Set up a standing check across your renewal portfolio so commercial trigger dates surface with enough runway to act on them.', N'Featured', N'Both', N'Set up a recurring check across my renewal portfolio. Each week, tell me which agreements are approaching a commercial trigger date, which have consumption or usage moving in a direction that changes the commercial position, and which have an approval dependency that has not started yet. Rank by how much runway is left rather than by value. Do not interpret pricing or policy; where a question needs an authoritative answer, name the owner instead.', N'1. Bring your renewal portfolio with dates and the current approval requirements.
2. Run the prompt.
3. Confirm the runway ranking matches your own read on which renewals are genuinely tight.
4. Set the cadence far enough ahead of approval lead times to be useful.
5. Route pricing, discount and policy questions to the accountable owner rather than answering them yourself.', N'Your renewal portfolio with dates; approved consumption and usage data; the current approval requirements.', N'A recurring portfolio check ranked by remaining runway, with approval dependencies and the owner for each open question.', N'CE confirms the commercial reading of every flagged item and routes pricing, discount and policy interpretation to the accountable owner rather than acting on the output.', N'Monitoring and signal', N'Commercial leverage is a function of how early you saw it coming. A renewal found with three weeks left is a different negotiation from the same renewal found with three months.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CE-07-ALT-01', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 4, N'Stress-test agreement transition assumptions', N'Surface the timing risk, customer constraints and policy dependencies hiding in a proposed agreement or commerce transition.', N'Extended', N'Prompt', N'Review the proposed agreement or commerce transition for commercial assumptions, customer constraints, policy dependencies, approval needs, timing risk, and unresolved questions.', NULL, N'The proposed transition; the current agreement terms and dates; the policy dependencies and approval needs.', N'Agreement transition assumption register with risks, owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'Agreement transitions fail when unstated assumptions become customer-facing commitments.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-07-ALT-02', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 6, N'Build the agreement transition execution plan', N'Sequence the agreement transition into owners, approval steps and decision gates tied to the dates that cannot move.', N'Extended', N'Prompt', N'Translate the agreement or commerce transition direction into owners, approval steps, customer actions, internal actions, dependencies, checkpoints, and decision gates.', NULL, N'The validated transition approach; the agreement dates that constrain it; internal and customer owners for each step.', N'Agreement transition execution plan with owners, approval path, dependencies, and checkpoints.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A transition plan holds only when the owners, checkpoints, and decision gates are explicit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-INVEST-01-P01', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 1, N'Identify commercial and policy dependencies for the investment', N'Surface the commercial, agreement, exception and approval questions an investment path will encounter, using authoritative guidance only.', N'Featured', N'Prompt', N'Using current approved guidance, identify commercial, policy, agreement, exception, or approval questions that may affect the investment path. Do not interpret policy beyond authoritative sources or approve exceptions.', NULL, N'Proposed investment, customer and agreement context', N'Commercial and policy dependency brief with authoritative questions and owners.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Problem identification', N'Naming commercial and policy dependencies early prevents investment rework later.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CE-INVEST-01-P02', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 2, N'Clarify approval and exception handoffs', N'Map the approvals, exception triggers and evidence needs for an investment without assigning authority that policy has not confirmed.', N'Featured', N'Prompt', N'Map the known approvals, exception triggers, evidence needs, owners, and escalation questions for the investment without assigning authority not confirmed by policy.', NULL, N'Request stage, known policy constraints, unresolved exceptions', N'Approval and exception handoff map with evidence needs, owners, and open questions.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Scoping and design', N'Approval and exception handoffs hold only when authority and evidence are explicit.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CE-INVEST-01-P03', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 3, N'Assess the commercial shape of the investment', N'Test whether the proposed investment structure holds up commercially before it reaches approval.', N'Featured', N'Prompt', N'Review the proposed investment against the customer agreement, term, commercial structure, exception risk, precedent risk, and current approved guidance. Cite authoritative guidance and flag anything you cannot confirm.', NULL, N'Proposed investment, agreement and term context, current approved guidance', N'Commercial structure assessment with precedent risks, exception questions, and cited guidance.', N'Confirm the grounding sources, separate evidence from assumption, and validate the named owner and next decision before this reaches a customer or an approver.', N'Analysis and assessment', N'Working through the commercial shape of the investment forces a position, and a position is what the decision needs.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-INVEST-01-P04', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 4, N'Track the approval path and unblock the next decision', N'Follow an in-flight investment request through approval and identify what is actually holding it.', N'Featured', N'Both', N'For the in-flight investment request, summarize the approval stage, evidence supplied, outstanding items, known owner, and next decision. Do not represent any approval as granted unless confirmed by the authoritative record.', N'1. Ask ECIF Agent via Sales Agent for the current approval stage and outstanding items.
2. Review against your own record of what was submitted.
3. Open ECIF Central where approval detail is not answerable from the summary.
4. Identify the single blocking item and its owner.
5. Route the missing evidence request.', N'Approved request status, policy constraints, approval stage', N'Approval-path status with blocking item, owner, evidence needed, and next decision.', N'Confirm status and milestone data against the authoritative record before acting or reporting. Do not infer financial yield or approval state from a summary.', N'Monitoring and signal', N'With approval-path tracking, the blocker finds you instead of you remembering to go look.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CE-INVEST-01-P05', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 5, N'Find where the approval is actually stuck', N'Work out which approval a request is waiting on, who holds it, and what would move it, rather than waiting for it to surface.', N'Featured', N'Both', N'For investment request [request ID or opportunity], I need to work out what is blocking approval. Here is the current status from the tracker: [paste]. Identify which approval it is waiting on, what evidence that approver typically needs, what in our submission is likely to be the sticking point, and what the fastest legitimate way to unblock it is. Distinguish between a request that is genuinely progressing and one that has stalled. Do not represent anything as approved, and do not suggest routing around an approver.', N'1. Open the request in MSX Deal Assistance and read the tracker view for stage, owner, and blockers.
2. Run the prompt with that status.
3. Decide whether it is progressing or stalled.
4. If stalled, contact the named owner with the specific evidence gap rather than a status request.
5. If blocked on access or tooling, use MCAPS Help.', N'The request ID and its current tracker status. The submitted package. Knowledge of the approval path for this request type.', N'A clear read on whether the request is progressing or stalled, the specific blocker, its owner, and one action to unblock it.', N'CE owns the judgment about whether a delay is normal or a genuine block, and never routes around an approver or represents an approval that has not been given.', N'Inspection and review', N'Requests rarely get rejected. They go quiet, and quiet looks like progress until the customer asks.', N'https://microsoftsales.crm.dynamics.com/main.aspx?appid=fe0c3504-3700-e911-a849-000d3a10b7cc&forceUCI=1&pagetype=entitylist&etn=opportunity&viewid=00000000-0000-0000-00aa-000010003000&viewType=1039', N'Open MSX Opportunities'),
        (N'CE-INVLINK-01', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 5, N'Check the investment path against policy and approval requirements', N'Surface the commercial and policy dependencies that an investment request will meet.', N'Featured', N'Prompt', N'Using current approved guidance, identify the policy, licensing, agreement, exception, or approval questions that a proposed customer investment would raise, the approval path it would follow, and the authoritative owner of each question. Cite the guidance used and flag anything you cannot confirm. Do not infer eligibility, exception, funding, or approval status.', NULL, N'Proposed investment, customer agreement context, current approved guidance', N'Dependency and approval map for the investment with cited guidance, named owners, and unresolved questions.', N'CE confirms every interpretation against an authoritative source and approves no exception here.', N'Surface the commercial and policy dependencies that an investment request will meet.', N'Clearing the investment path early prevents approval rework without overstating authority.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-POLICY-SCOUT-01', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 6, N'Track commercial policy and licensing changes that affect your accounts', N'Set up a monitored, source-locked watch on the commercial policy and licensing guidance you rely on, so changes reach you before a customer raises them.', N'Extended', N'Both', N'Set up a recurring check against a fixed list of authoritative Microsoft commercial policy and licensing sources that I will confirm with you first. Each time, report only what has changed, quote the change, cite the source, and state plainly which of my accounts it plausibly affects and why. Do not interpret the change into commercial advice and do not draw on any source outside the confirmed list. Where the implication is unclear, say so and name the owner who can rule on it.', N'1. Agree the fixed list of authoritative policy and licensing sources with your team before you enable anything.
2. Run the prompt with that confirmed list.
3. Check the first digest quotes and cites each change rather than paraphrasing it.
4. Set the cadence and confirm the watch is not drawing on sources outside the agreed list.
5. Route every interpretation to the accountable policy owner rather than acting on the summary.', N'The authoritative policy and licensing sources your team treats as canonical; your account list; your escalation owners.', N'A recurring change-only digest quoting and citing each change, with plausible account impact and the named owner for anything requiring a ruling.', N'CE confirms the source list before the watch is enabled, and routes every interpretation to the accountable policy owner rather than acting on the summary.', N'Monitoring and signal', N'Commercial policy changes are only a problem when the customer knows before you do. A locked source list is what separates a reliable watch from confident invention.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSA-01-ALT-01', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 4, N'Validate the technical health evidence', N'Separate what the health signals actually evidence from what the team has been assuming, before a risk is escalated.', N'Extended', N'Prompt', N'Review the technical health assessment. For each risk, state the signal that evidences it, how current that signal is, and what is inference rather than observation. Identify the risks whose evidence would not survive a customer challenge, and name what would be needed to confirm them.', NULL, N'The technical health and risk view; the telemetry and support signals behind it; the customer constraints that limit your options.', N'A technical health evidence map separating observed signal from inference, with the confirmation needed for each weak item.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Assess Customer Technical Health and Prioritize Risk now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-01-ALT-02', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 5, N'Design the technical risk intervention plan', N'Turn the prioritized technical risks into sequenced interventions with owners and checkpoints that show whether they worked.', N'Extended', N'Prompt', N'Turn the prioritized technical risks into a sequenced intervention plan. For each risk, define the specific technical action, the owner, the dependency that could block it, the checkpoint date, and the evidence that will show the intervention worked. Sequence by which risk becomes customer-visible soonest.', NULL, N'The validated technical risk list; the delivery and customer owners available; the checkpoints already in the engagement rhythm.', N'A sequenced technical intervention plan with owners, dependencies, checkpoint dates, and success evidence per risk.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Assess Customer Technical Health and Prioritize Risk before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-02-ALT-01', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 5, N'Validate the architecture evidence before the design is shared', N'Find the unsupported assumptions and unresolved dependencies in a production design before it reaches the customer.', N'Extended', N'Prompt', N'Review the production architecture package. Identify assumptions presented as requirements, dependencies with no named owner, non-functional requirements with no validation step, and any option comparison that does not map to the customer decision criteria. Name what must be proven before this design is committed.', NULL, N'The production architecture package; the constraints and non-functional requirements it assumes; the validation steps already planned.', N'An architecture assumption and dependency review naming what must be proven before commitment.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Design a Production-Ready Customer Architecture now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-02-ALT-02', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 1, N'Design the architecture intervention plan', N'Sequence the work needed to close the gaps a design review exposed, with owners and the evidence that closes each one.', N'Extended', N'Prompt', N'Turn the architecture review findings into a sequenced remediation plan. For each gap, define the action, the owner, the dependency, the date it must be closed by to protect the delivery milestone, and the evidence that will close it. Flag any gap that cannot be closed in time.', NULL, N'The architecture review findings; the delivery owners available; the milestone dates the design must support.', N'A sequenced architecture remediation plan with owners, dates tied to delivery milestones, and closure evidence.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Design a Production-Ready Customer Architecture before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-02-ECIF-01', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 2, N'Review ECIF delivery readiness and technical outcomes', N'Review delivery readiness, milestones and success measures for funded engagement work before execution starts.', N'Featured', N'Prompt', N'Review the funded-engagement context, technical dependencies, delivery milestones, success measures, and evidence needed to support execution and outcome tracking.', NULL, N'Approved case or workscope context, milestones, architecture dependencies, and intended outcomes.', N'Delivery-readiness review with technical risks, checkpoints, and evidence needs.', N'CSA verifies technical and delivery assumptions and confirms ownership boundaries with CSAM, delivery, and the ECIF process owner.', N'Inspection and review', N'Reviewing eCIF delivery readiness and technical outcomes is judgment work. The agent proposes; you stay accountable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSA-03-ALT-01', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 3, N'Validate the evidence behind the technical decision path', N'Check whether the sequence of technical decisions rests on confirmed evidence or on decisions nobody has actually made yet.', N'Extended', N'Prompt', N'Review the technical decision path. For each decision, state whether the evidence to make it exists today, who owns the decision, and what happens to the sequence if that decision slips. Identify decisions that are being assumed rather than scheduled.', NULL, N'The technical decision path; the evidence behind each decision point; the owner who must confirm each one.', N'A decision-path review naming evidence status, decision owner, and slip impact for each point in the sequence.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Build the Technical Decision and Validation Path now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-03-ALT-02', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 4, N'Design the validation-path intervention plan', N'Define how each unproven part of the design gets validated, by whom, and by when.', N'Extended', N'Prompt', N'Turn the open validation items into a proof plan. For each, define the smallest test that would settle it, the environment and data needed, the owner, the date, and what the result changes. Order by which unproven item carries the most delivery risk.', NULL, N'The validation path and its open items; the environments and data available for proof; the owners of each validation step.', N'A validation proof plan ordered by delivery risk, with the smallest settling test, environment needs, owner, and date per item.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Build the Technical Decision and Validation Path before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-04-ALT-01', N'WF-X-CONV-01', N'CSA-CONV', N'PH-CSA-CONV-EXPL', 3, N'Validate the evidence behind the advisory recommendation', N'Check that every claim in your advisory recommendation is backed by evidence the customer will accept before you put it in front of them.', N'Extended', N'Prompt', N'Review the advisory recommendation you intend to give. For each claim, state the supporting evidence, whether that evidence is approved for customer use, and what a technically informed customer would push back on. Flag anything resting on assumption or on a roadmap item that has not shipped.', NULL, N'The draft advisory recommendation; the telemetry, architecture and cost evidence behind it; the customer''s stated constraints.', N'A claim-by-claim evidence review of the advisory recommendation with customer-safe status and likely pushback per claim.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Prepare a Technical Advisory Customer Conversation now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-04-ALT-02', N'WF-X-CONV-01', N'CSA-CONV', N'PH-CSA-CONV-EXPL', 4, N'Design the advisory adoption plan', N'Convert the advisory recommendation into the actions, owners and checkpoints the customer would need to actually adopt it.', N'Extended', N'Prompt', N'Turn the advisory recommendation into an adoption plan the customer can act on. Define the sequenced actions, the customer owner and Microsoft owner for each, the dependency most likely to stall it, the checkpoint dates, and the evidence that will show progress.', NULL, N'The agreed advisory recommendation; the customer roles who would own each step; the delivery dependencies involved.', N'An adoption plan for the advisory recommendation with paired customer and Microsoft owners, dependencies, and checkpoints.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Prepare a Technical Advisory Customer Conversation before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-05-ALT-01', N'WF-X-PIPE-01', N'CSA-PIPE', N'PH-CSA-PIPE-EXPL', 3, N'Validate the consumption gap analysis', N'Test whether the consumption gap has been traced to a real technical cause or to a plausible-sounding assumption.', N'Extended', N'Prompt', N'Review the consumption analysis. For each shortfall, state the technical cause proposed, the signal that evidences that cause, and the alternative explanations that have not been ruled out. Identify which gaps are technically caused, which are commercial or customer-driven, and which are still unexplained.', NULL, N'The consumption position against plan; the telemetry and deployment signals behind it; known customer events that affect usage.', N'A consumption gap analysis separating evidenced technical causes from unruled-out alternatives and non-technical drivers.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Forecast Consumption and Intervene on Shortfall Risk now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-05-ALT-02', N'WF-X-PIPE-01', N'CSA-PIPE', N'PH-CSA-PIPE-EXPL', 4, N'Design the consumption intervention plan', N'Build the intervention that changes the consumption trajectory, with the owner and the checkpoint that will show whether it moved.', N'Extended', N'Prompt', N'Turn the evidenced consumption causes into an intervention plan. For each, define the technical action, who owns it on both sides, the dependency that could block it, the date you would expect to see movement, and the telemetry that would confirm it. Rank by the size of the gap each one closes.', NULL, N'The validated consumption causes; the deployment and architecture levers available; the customer owners for each dependency.', N'A ranked consumption intervention plan with owners, blocking dependencies, expected movement dates, and confirming telemetry.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Forecast Consumption and Intervene on Shortfall Risk before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-05-SCOUT-01', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 3, N'Watch consumption and health signals between reviews', N'Set up a standing check on the accounts you carry, so a health or consumption change reaches you when it happens rather than at the next review.', N'Featured', N'Both', N'Set up a recurring check on technical health across the accounts I carry. Each week, tell me where consumption has moved against plan, where a deployment or adoption blocker has appeared, and where a previously flagged risk has not changed. For each one, state what the data shows, what it does not tell us, and the single technical question I should ask next. Remember what you flagged before so you can tell me what is new and what is unchanged.', N'1. Confirm which telemetry, support and consumption sources the check can reach.
2. Run the prompt.
3. Review the first output and separate genuinely new movement from risk you already knew about.
4. Set the cadence to land before your delivery review.
5. Validate each technical hypothesis yourself before raising it with the customer or the account team.', N'The accounts you carry; approved consumption, usage and support data; the risks currently on your register.', N'A recurring health check separating new movement from unchanged risk, with the next technical question for each.', N'CSA confirms the technical reading of each signal and decides which movement is significant enough to act on.', N'Monitoring and signal', N'Risk found early is a conversation and the same risk found late is an escalation. Between reviews is exactly where that gap opens, and it is where an always-on agent earns its place.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSA-06-ALT-01', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'PH-CSA-VALUE-1-EXPL', 3, N'Validate the cost and optimization evidence', N'Test the cost baseline and savings estimates before an optimization recommendation goes to the customer.', N'Extended', N'Prompt', N'Review the cost and optimization analysis. For each recommendation, state the baseline it is measured against, the assumptions behind the projected saving, whether the saving is modelled or observed, and the customer constraint that could prevent it. Flag any figure that would not survive review by the customer finance function.', NULL, N'The cost and consumption evidence base; the baseline period and its assumptions; the customer commitments that constrain change.', N'A cost evidence review separating modelled from observed savings, with baseline assumptions and blocking constraints per recommendation.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Build a FinOps and Optimization Recommendation now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-06-ALT-02', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'PH-CSA-VALUE-1-EXPL', 4, N'Design the FinOps intervention plan', N'Turn the validated cost findings into changes someone owns, with the measurement that will prove the saving landed.', N'Extended', N'Prompt', N'Turn the validated cost findings into an implementation plan. For each optimization, define the technical change, the owner, the customer approval needed, the date, and the specific billing or telemetry measure that will confirm the saving. Rank by net saving against effort.', NULL, N'The validated optimization recommendations; the technical owners for each change; the billing or telemetry view that will show the effect.', N'A ranked FinOps implementation plan with owners, required approvals, and the measure that will confirm each saving.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Build a FinOps and Optimization Recommendation before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-07-ALT-01', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 3, N'Validate the evidence behind the customer value story', N'Check that the value story is built on measured outcomes rather than activity, before the customer''s finance function does it for you.', N'Extended', N'Prompt', N'Review the technical value narrative. For each claimed outcome, state whether it is measured or projected, the baseline it is compared against, and whether the measurement basis has changed since the commitment was made. Separate delivered value from activity completed, and flag any claim a finance reviewer would reject.', NULL, N'The draft value narrative; the outcomes committed in the business case; the measurement basis and baseline used.', N'A value-claim review separating measured from projected outcomes, with baseline integrity and finance-review risk per claim.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Translate Technical Progress into Customer Value now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-07-ALT-02', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 4, N'Design the value-translation intervention plan', N'Close the gap between the value you have delivered and the value the customer can see, with named owners and evidence.', N'Extended', N'Prompt', N'Where the value story has gaps, define what would close them. For each gap, state the evidence still needed, who can produce it, the date it is needed by, and the customer stakeholder it is intended to convince. Identify which gaps can be closed before the next review and which cannot.', NULL, N'The validated value narrative and its gaps; the customer stakeholders who need to see it; the upcoming review that will carry it.', N'A value evidence plan naming the missing proof, its producer, the date, and the stakeholder it must convince.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Translate Technical Progress into Customer Value before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-INVEST-01-P01', N'WF-INVEST-01', N'CSA-INVEST', N'PH-CSA-INVEST-EXPL', 1, N'Validate delivery readiness and technical dependencies', N'Test whether investment-funded scope can be executed as written, against dependencies, prerequisites and ownership.', N'Featured', N'Prompt', N'Review the approved or proposed investment scope for execution readiness, technical dependencies, customer prerequisites, ownership, and measurable technical outcomes.', NULL, N'Proposed scope, technical evidence, customer prerequisites', N'Delivery-readiness assessment with dependencies, risks, and required actions.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Validation and evidence', N'Confirming delivery readiness and technical dependencies now costs a conversation. Discovering it late costs a decision.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSA-INVEST-01-P02', N'WF-INVEST-01', N'CSA-INVEST', N'PH-CSA-INVEST-EXPL', 2, N'Define technical checkpoints and outcome evidence', N'Define the technical checkpoints and evidence that will support the later value-realization review.', N'Featured', N'Prompt', N'Translate the investment scope into technical checkpoints, evidence requirements, and signals that support later value-realization review.', NULL, N'Scope, milestones, technical success measures', N'Technical checkpoint and evidence plan.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Scoping and design', N'Settling technical checkpoints and outcome evidence before the work starts is the only version of that decision that holds.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSA-INVEST-01-P03', N'WF-INVEST-01', N'CSA-INVEST', N'PH-CSA-INVEST-EXPL', 3, N'Surface delivery risk before it reaches the customer', N'Review in-flight investment delivery for the technical risks that would become customer-visible.', N'Featured', N'Both', N'Using approved delivery status and milestone evidence, identify technical risks, unmet prerequisites and dependency slippage that could become customer-visible. State evidence, owner and the intervention available now.', N'1. Ask ECIF Agent via Sales Agent for delivery status across in-flight engagements.
2. Review for dependency slippage and unmet prerequisites.
3. Open ECIF Central for milestone detail where needed.
4. Name evidence, owner and intervention for each risk.
5. Raise what cannot wait.', N'Approved delivery status, milestone evidence, customer prerequisites', N'Technical delivery-risk brief with evidence, owners and interventions.', N'Confirm status and milestone data against the authoritative record before acting or reporting. Do not infer financial yield or approval state from a summary.', N'Problem identification', N'Naming delivery risk before it reaches the customer is most of the work. Unnamed problems never get an owner.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSA-INVEST-01-P04', N'WF-INVEST-01', N'CSA-INVEST', N'PH-CSA-INVEST-EXPL', 4, N'Translate technical outcomes into the customer value story', N'Connect the technical evidence from the investment to the outcomes the customer agreed to.', N'Featured', N'Prompt', N'Using approved milestone, adoption and consumption evidence, connect what was delivered to the intended customer outcomes. Separate evidenced from expected. Do not claim causality the data does not support.', NULL, N'Approved milestone, adoption and consumption evidence, agreed outcomes', N'Evidence-based technical value story with confirmed outcomes and gaps.', N'Confirm the grounding sources, separate evidence from assumption, and validate the named owner and next decision before this reaches a customer or an approver.', N'Value translation', N'Making technical outcomes into the customer value story explicit is the part almost nobody does, and the part that travels.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSA-INVLINK-01', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 5, N'Validate delivery readiness for investment-funded scope', N'Test whether investment-funded technical scope can actually be delivered as designed.', N'Featured', N'Prompt', N'Review the proposed investment-funded scope for execution readiness, technical dependencies, customer prerequisites, ownership and measurable technical outcomes. Identify what would block delivery and who owns each item.', NULL, N'Proposed scope, technical evidence, customer prerequisites', N'A delivery-readiness view with dependencies, prerequisites and named owners.', N'CSA confirms the prerequisites are real and that the outcome measures are technically observable.', N'Test whether investment-funded technical scope can actually be delivered as designed.', N'Avoid inheriting an undeliverable scope', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSAM-ESCALATE-ALT01', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 3, N'Build the recovery action register', N'Capture each recovery action with owner, customer impact, dependency, due date and escalation threshold.', N'Extended', N'Both', N'Create a recovery action register with action, owner, customer impact, dependency, due date, escalation threshold and evidence source.', N'1. Open the Customer Success Agent app in Teams; there is no published direct link.
2. Start from the validated escalation brief.
6. Extract actions.
6. Confirm owner and date.
6. Add escalation threshold.
6. Track follow-through in the appropriate system.', N'Validated escalation brief and owner context.', N'Recovery action register.', N'CSAM validates owners, dates and where actions should be tracked.', N'Operational governance', N'Escalations repeat when recovery actions do not become governed follow-through.', NULL, N'Open Customer Success Agent'),
        (N'CSAM-ESCALATE-ALT02', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 4, N'Prepare the post-incident value and prevention summary', N'Document impact, completed recovery, prevention actions and how the fix will be reviewed once things stabilize.', N'Extended', N'Prompt', N'After the issue stabilizes, draft a prevention summary. Include root-cause status if approved, customer impact, recovery actions completed, prevention actions, owners, dates and how this will be reviewed in the next CSDR.', NULL, N'Closed or stabilized issue, approved RCA or status, recovery actions and CSDR cadence.', N'Post-incident prevention summary.', N'CSAM validates approved RCA language, customer sensitivity and follow-through ownership.', N'Continuous improvement', N'Trust is repaired when the customer sees what changed after the issue.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSAM-ESCALATE-P01', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 1, N'Create the escalation and recovery brief', N'Consolidate incident, support, delivery and customer communication context into a grounded brief.', N'Featured', N'Prompt', N'Create an escalation and recovery brief for [issue]. Include customer impact, current status, timeline, owners, decisions needed, risks, next action, next update cadence and what is unknown. Use only approved sources and separate facts from assumptions.', NULL, N'Incident or support notes, delivery updates, customer communications, owners, timelines and current risks.', N'Escalation and recovery brief.', N'CSAM validates accuracy, sensitivity, owner commitments and customer-safe language before distribution.', N'Escalation leadership', N'In escalation moments, clarity protects trust and reduces duplicated status chasing.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-ESCALATE-P02', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 2, N'Draft the customer-safe status update', N'Prepare a concise status update that protects trust and avoids unsupported commitments.', N'Featured', N'Prompt', N'Draft a customer-safe status update for [stakeholder] on [issue]. Include what happened, current impact, what Microsoft is doing, what we need from the customer, next update timing and what remains under investigation. Avoid blame and unsupported commitments.', NULL, N'Validated escalation brief, customer stakeholder and approved communication position.', N'Customer-safe escalation update.', N'CSAM confirms accuracy, support alignment and approval path before sending.', N'Stakeholder communication', N'The wrong update can create more risk than the issue itself.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-EXEC-ALT01', N'WF-X-CONV-01', N'CSAM-EXEC', N'PH-CSAM-EXEC-EXPL', 3, N'Rehearse the executive conversation', N'Role-play the executive stakeholder against your approved brief to expose weak evidence, vague asks and unowned risk.', N'Extended', N'Prompt', N'Role-play [executive stakeholder] for the upcoming alignment conversation. Use the approved brief only. Challenge weak evidence, unclear value, vague asks and unowned risks. End with coaching notes and changes to make before the meeting.', NULL, N'Approved executive alignment brief.', N'Role-play output with likely questions, objections and coaching notes.', N'CSAM decides what to change and confirms no unsupported customer facts were introduced.', N'Conversation preparation', N'A ten-minute rehearsal is cheaper than discovering the weak ask in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'CSAM-EXEC-ALT02', N'WF-X-CONV-01', N'CSAM-EXEC', N'PH-CSAM-EXEC-EXPL', 4, N'Draft executive follow-up with decisions and asks', N'Capture the decisions, open asks, owners and next review point in a follow-up the executive can act on.', N'Extended', N'Prompt', N'Draft a concise executive follow-up for [meeting]. Summarize decisions, open asks, owners, dates, risks and next review point. Keep the tone advisory and customer-safe.', NULL, N'Meeting notes, executive brief and confirmed decisions.', N'Executive follow-up draft.', N'CSAM validates decisions, owner commitments and customer-facing language before sending.', N'Stakeholder communication', N'Follow-up is where alignment becomes accountability.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-EXEC-P01', N'WF-X-CONV-01', N'CSAM-EXEC', N'PH-CSAM-EXEC-EXPL', 1, N'Build the stakeholder and influence map', N'Map stakeholders, decision rights, sponsor health, relationship gaps and next engagement actions.', N'Featured', N'Prompt', N'Using approved meetings, emails, CRM notes and account context for [Account], build a stakeholder and influence map. Include executive sponsor, BDMs, workload owners, blockers, champions, relationship health, last interaction, open asks and recommended next engagement action. Flag inferred items separately.', NULL, N'Approved customer relationship context, recent interactions, CRM notes and known account team inputs.', N'Stakeholder and influence map with relationship risks and next actions.', N'CSAM validates relationship interpretation and removes unsupported inferences.', N'Customer intelligence', N'Stakeholder changes can break adoption, value proof and renewal confidence before metrics show it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSAM-EXEC-P02', N'WF-X-CONV-01', N'CSAM-EXEC', N'PH-CSAM-EXEC-EXPL', 2, N'Prepare the executive alignment brief', N'Create a brief with priorities, value evidence, risk, decision needed and the executive ask.', N'Featured', N'Prompt', N'Prepare an executive alignment brief for [stakeholder or meeting]. Include customer priorities, progress since last touch, value evidence, top risk, decision needed, recommended ask and questions to confirm alignment. Use only approved sources and flag gaps.', NULL, N'Stakeholder map, success plan, value evidence, health risks and meeting context.', N'Executive alignment brief and talk track.', N'CSAM validates executive relevance, tone, evidence and the ask.', N'Executive storytelling', N'Executive alignment is where CSAMs convert activity into trust and decisions.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-HEALTH-ALT01', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'PH-CSAM-HEALTH-EXPL', 3, N'Prepare the customer-safe health message', N'Write the health concern in customer language, with the proposed action and the support you need from them.', N'Extended', N'Prompt', N'Draft a customer-safe message for [stakeholder] about this health risk. State the concern, why it matters, the proposed action and the support needed from the customer. Avoid internal terminology and unsupported conclusions.', NULL, N'Validated health risk, customer stakeholder and proposed action.', N'Customer-safe health message.', N'CSAM approves tone, accuracy and whether the message should be sent.', N'Stakeholder communication', N'Risk communication can build trust or create noise. The CSAM owns that judgment.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-HEALTH-ALT02', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'PH-CSAM-HEALTH-EXPL', 4, N'Update RAID and CSDR follow-through', N'Turn a health risk into RAID and review entries with owner, dependency, decision, due date and evidence source.', N'Extended', N'Both', N'Create RAID and CSDR follow-through entries for this health risk. Include risk, action, owner, dependency, decision, due date and evidence source.', N'1. Select the validated health risk.
2. Draft RAID entries.
3. Confirm owners and dates.
4. Prepare the CSDR follow-up line.
5. Update the system only after review.', N'Validated health risk and account governance cadence.', N'RAID-ready and CSDR-ready follow-through entries.', N'CSAM verifies system updates and confirms accountable owners.', N'Operational governance', N'Health work fails when findings do not become tracked actions.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-HEALTH-P01', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'PH-CSAM-HEALTH-EXPL', 1, N'Rank customer health risks and drivers', N'Create a ranked view of health risk across usage, support, sentiment, delivery and stakeholder signals.', N'Featured', N'Prompt', N'Using approved customer health, usage, support, delivery, sentiment and stakeholder signals for [Account or portfolio], rank the top risks. For each risk show driver, evidence, likely customer impact, owner, mitigation, due date and escalation threshold. Flag unavailable data.', NULL, N'Customer health signals, usage or consumption data, support trends, delivery milestones, sentiment and stakeholder notes.', N'Ranked customer health risk view with mitigations.', N'CSAM validates source freshness, customer impact and the intervention before acting.', N'Problem identification', N'Health scores rarely tell you what to do. This turns signals into action.', N'https://msxi.microsoft.com/', N'Open MSX Insights'),
        (N'CSAM-HEALTH-P02', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'PH-CSAM-HEALTH-EXPL', 2, N'Create the proactive intervention plan', N'Translate the top risk into a customer-safe intervention with owner and cadence.', N'Featured', N'Prompt', N'For the top validated health risk, create a proactive intervention plan. Include customer-facing framing, Microsoft owner, customer owner, required evidence, next meeting, mitigation action, escalation condition and follow-up cadence.', NULL, N'Validated top health risk, owner context, customer relationship context and available mitigation options.', N'Proactive intervention plan.', N'CSAM confirms the plan is appropriate for the customer relationship and does not overstate risk.', N'Action planning', N'Early intervention is where customer health work creates trust.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-INVEST-ALT01', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 3, N'Track investment delivery risks and handoffs', N'Find the overdue milestones, unclear owners and delivery dependencies in active investment work.', N'Extended', N'Prompt', N'Review active investment milestones for [Account]. Identify overdue actions, unclear owners, missing evidence, delivery dependencies, customer impact and recommended next action.', NULL, N'Active investment milestones, workscope status, delivery updates and success-plan context.', N'Investment risk and handoff review.', N'CSAM confirms status with ECIF or delivery owners before escalating or updating the customer.', N'Risk tracking', N'Investment value is lost when handoffs drift without visibility.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSAM-INVEST-ALT02', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 4, N'Prepare the investment realization review', N'Assemble objective, work completed, value evidence, remaining gaps and the recommendation for the next review.', N'Extended', N'Prompt', N'Prepare an investment realization review for [Account]. Include original objective, work completed, customer value evidence, remaining gaps, risks, next actions and recommendation for the next CSDR or QBR.', NULL, N'Completed or in-flight investment data, value evidence, success plan and review audience.', N'Investment realization review brief.', N'CSAM validates value claims, approved sources and next-step ownership.', N'Value storytelling', N'Investment only proves value when the evidence is captured and reviewed.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-INVEST-P01', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 1, N'Connect the investment to the success plan', N'Ensure the investment supports a documented customer outcome and success-plan milestone.', N'Featured', N'Prompt', N'Review this customer investment against the success plan for [Account]. Identify the customer outcome it supports, related milestone, owner, dependency, risk, success evidence and next governed action. Flag gaps before execution continues.', NULL, N'Investment request or workscope, success plan, customer priority, milestones and stakeholder context.', N'Investment-to-success-plan alignment view.', N'CSAM validates outcome alignment and confirms policy or approval questions remain with accountable owners.', N'Governance and evidence', N'Investment should accelerate a customer outcome, not become a disconnected activity.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSAM-INVEST-P02', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 2, N'Establish the investment operating rhythm', N'Create the owners, checkpoints and evidence plan for investment execution.', N'Featured', N'Both', N'Create an investment operating rhythm with milestones, owner, checkpoint date, delivery dependency, risk, evidence needed and realization review timing.', N'1. Select the investment.
2. Identify milestones and owners.
3. Add checkpoints.
4. Define value evidence.
5. Review with the v-team before customer use.', N'Investment scope, milestones, delivery plan and success-plan context.', N'Investment operating rhythm with checkpoints and evidence plan.', N'CSAM validates owners, dates, handoffs and customer-facing commitments.', N'Operational governance', N'A governed rhythm is what keeps investment execution from drifting.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-INVEST-P05', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 5, N'Turn investment delivery into evidence the customer recognizes', N'Convert what the investment delivered into value the customer would describe the same way, and identify what is still unproven.', N'Featured', N'Both', N'This investment was intended to deliver [paste the outcome and the success plan linkage]. Here is what was delivered and what the usage and adoption data shows: [paste]. Produce a realization view that separates what we can evidence, what we are inferring, and what has not materialized. For each evidenced outcome, phrase it the way the customer would describe it rather than the way we would. Flag anything a customer stakeholder would dispute if they read it.', N'1. Bring the investment outcome and its success plan linkage.
2. Gather delivery evidence from ECIF Central and adoption data.
3. Run the prompt.
4. Read the evidenced list as if you were the customer.
5. Take the unproven items to the account team before the realization review.', N'The investment outcome and success plan linkage. Delivery evidence and milestones. Adoption and usage data. What the customer has said about value.', N'A realization view separating evidenced, inferred, and unmaterialized outcomes, phrased in the customer''s terms.', N'CSAM confirms the customer would recognize the value as described, and removes any claim the customer would dispute before it reaches a review.', N'Value translation', N'Value the customer would not describe the same way is not realized value, whatever the internal record says.', N'https://aka.ms/ECIFCentral', N'Open ECIF Central'),
        (N'CSAM-ORCH-ALT01', N'WF-X-ORCH-01', N'CSAM-ORCH', N'PH-CSAM-ORCH-EXPL', 3, N'Build the weekly customer-success action plan', N'Rank this week''s top five customer actions by impact, urgency and dependency risk, including what to leave alone.', N'Extended', N'Prompt', N'Create my weekly customer-success action plan for [Account]. Prioritize the top five actions by customer impact, urgency and dependency risk. Include owner, source signal, next step and what not to spend time on this week.', NULL, N'Current account signals, meetings, notes, support, delivery and success-plan context.', N'Weekly customer-success action plan.', N'CSAM confirms priority logic and adjusts based on customer relationship context.', N'Prioritization', N'The highest-value CSAM week starts with deciding what not to chase.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-ORCH-ALT02', N'WF-X-ORCH-01', N'CSAM-ORCH', N'PH-CSAM-ORCH-EXPL', 4, N'Prepare the internal alignment message', N'Give the v-team the customer outcome, current state, open risks and the decisions you need from them.', N'Extended', N'Prompt', N'Draft an internal alignment message for the v-team. Include customer outcome, current state, open risks, needed decisions, owner asks and date. Keep it concise and specific.', NULL, N'V-team orchestration brief and desired decision or action.', N'Internal alignment message.', N'CSAM validates ownership, tone and whether any customer-sensitive content should be removed.', N'Stakeholder communication', N'Internal alignment should reduce meetings, not create more of them.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-ORCH-P01', N'WF-X-ORCH-01', N'CSAM-ORCH', N'PH-CSAM-ORCH-EXPL', 1, N'Create the v-team orchestration brief', N'Synthesize current workstreams, owners, handoffs, decisions and blockers.', N'Featured', N'Prompt', N'Analyze approved customer-success sources for [Account] across meetings, emails, notes, CRM, support and delivery context. List active workstreams, owner, input needed, due date, dependency, blocker, decision needed and recommended next action. Flag missing owners and stale dates.', NULL, N'Approved account context, workstream notes, meetings, delivery updates, support context and CRM records.', N'V-team orchestration brief with workstreams and handoffs.', N'CSAM validates owners, dates, escalation path and whether each action is still relevant.', N'Orchestration', N'CSAMs create leverage by making the system visible instead of carrying every detail personally.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-ORCH-P02', N'WF-X-ORCH-01', N'CSAM-ORCH', N'PH-CSAM-ORCH-EXPL', 2, N'Make one stalled handoff explicit', N'Turn a vague or stalled handoff into an owner, input, date and decision.', N'Featured', N'Both', N'For this stalled handoff, identify the missing input, accountable owner, decision needed, customer impact, due date and escalation route. Draft the internal message that asks for exactly what is needed.', N'1. Pick one stalled handoff.
2. Name the needed input.
3. Confirm owner.
4. Draft the ask.
5. Send or route only after validation.', N'One stalled handoff or vague dependency.', N'Handoff clarification message and action record.', N'CSAM confirms the ask is accurate, respectful and routed to the right owner.', N'Workflow coordination', N'Most stalled work gets unstuck when the missing input and owner are explicit.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-RENEW-ALT01', N'WF-X-RENEW-01', N'CSAM-RENEW', N'PH-CSAM-RENEW-EXPL', 3, N'Stress-test the expansion hypothesis', N'Test an expansion hypothesis against usage, stakeholder and timing evidence, and name the likely objections.', N'Extended', N'Prompt', N'Stress-test this expansion hypothesis. Identify supporting usage, stakeholder, business-outcome and timing evidence. Flag missing evidence, likely objections and the next validation action.', NULL, N'Expansion hypothesis, adoption and usage evidence, customer priorities and stakeholder context.', N'Expansion evidence and objection review.', N'CSAM and AE validate whether this is ready for pursuit or needs more discovery.', N'Assumption testing', N'Expansion tied to realized value is stronger than expansion tied only to whitespace.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'CSAM-RENEW-ALT02', N'WF-X-RENEW-01', N'CSAM-RENEW', N'PH-CSAM-RENEW-EXPL', 4, N'Draft the renewal value narrative', N'Connect realized outcomes, adoption progress and remaining risk into a customer-safe renewal narrative.', N'Extended', N'Prompt', N'Draft a renewal value narrative for [Account] that connects realized outcomes, adoption progress, remaining risks and the next value milestone. Keep it customer-safe and avoid pricing or commercial commitments.', NULL, N'Validated value evidence, renewal readiness view and customer audience.', N'Renewal value narrative draft.', N'CSAM validates with AE or account owner before using in customer-facing renewal context.', N'Value storytelling', N'The strongest renewal support is credible evidence that Microsoft value is ongoing.', N'https://m365.cloud.microsoft/chat', N'Open Analyst'),
        (N'CSAM-RENEW-P01', N'WF-X-RENEW-01', N'CSAM-RENEW', N'PH-CSAM-RENEW-EXPL', 1, N'Build the renewal and growth readiness view', N'Connect health, consumption, adoption, value and stakeholder signals into a renewal readiness view.', N'Featured', N'Prompt', N'Build a renewal and growth readiness view for [Account]. Include renewal context, consumption or usage trajectory, MACC or commitment risk if applicable, adoption gaps, value evidence, support or health risks, stakeholder health, expansion hypothesis and recommended v-team next action. Flag unavailable data.', NULL, N'Renewal context, agreements, consumption or usage signals, adoption data, value proof, health risks and stakeholder context.', N'Renewal and growth readiness view.', N'CSAM aligns with AE and validates which signals are appropriate to share or escalate.', N'Renewal readiness', N'Renewal risk is easier to change when it is seen through health and value before the renewal date.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSAM-RENEW-P02', N'WF-X-RENEW-01', N'CSAM-RENEW', N'PH-CSAM-RENEW-EXPL', 2, N'Prepare the AE and v-team alignment brief', N'Create a brief that helps AE, CSA, SSP and CE align on renewal risk and growth actions.', N'Featured', N'Prompt', N'Prepare a v-team alignment brief for [Account] renewal or growth readiness. Include the customer value proof, top risk, consumption or adoption gap, expansion hypothesis, roles needed, decision owner and 30-day action plan.', NULL, N'Renewal readiness view, v-team roles and next review context.', N'V-team renewal and growth alignment brief.', N'CSAM confirms ownership boundaries and aligns with AE before external use.', N'Cross-role alignment', N'CSAMs influence renewal outcomes by making value, risk and next actions visible to the account team.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-SPLAN-ALT01', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 3, N'Validate the success-plan evidence', N'Label every statement in the success plan as sourced fact, assumption or recommendation, and flag what is not customer-ready.', N'Featured', N'Prompt', N'Review the success-plan update and label each statement as sourced fact, assumption, recommendation or missing evidence. Flag anything that should not be shared with the customer yet.', NULL, N'Draft success-plan update and source material.', N'Evidence validation matrix for the success-plan update.', N'CSAM removes unsupported claims and confirms customer-safe language.', N'Validation and evidence', N'Validation prevents the plan from sounding confident where the evidence is thin.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSAM-SPLAN-ALT02', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 4, N'Create the CSDR-ready success-plan narrative', N'Turn the validated success plan into a short review narrative covering progress, value, risk and the decision needed.', N'Extended', N'Prompt', N'Turn this validated success-plan update into a concise CSDR narrative. Include progress, value, risk, decision needed and next action. Keep it customer-safe and avoid unsupported claims.', NULL, N'Validated success-plan update and CSDR audience context.', N'CSDR-ready success-plan narrative.', N'CSAM validates tone, customer context and decision ask before use.', N'Executive storytelling', N'A plan matters more when the customer can understand the progress and decision needed.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-SPLAN-P01', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 1, N'Draft the outcome-anchored success-plan view', N'Draft or refresh the CSP around customer outcomes, milestones, owners, risks and review points.', N'Featured', N'Prompt', N'Using approved customer priorities, recent meetings, CSP notes and delivery updates for [Account], draft a Customer Success Plan view. Include outcome, success measure, milestone, owner, dependency, risk, next customer review point and evidence source. Separate sourced facts from suggested updates.', NULL, N'Customer priorities, existing CSP or notes, recent customer meetings, delivery milestones and known risks.', N'Outcome-anchored success-plan view with gaps and suggested updates.', N'CSAM validates customer priority, owner, commitment, measure and source before updating any system of record.', N'Synthesis and drafting', N'Most success-plan toil is assembling scattered signals. The CSAM should spend judgment on the outcome and commitment.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSAM-SPLAN-P02', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 2, N'Inspect the plan for drift and missing accountability', N'Find stale milestones, missing owners and risks that are not tied to action.', N'Featured', N'Prompt', N'Review this success plan for drift. Identify stale milestones, missing owners, unsupported outcomes, risks without mitigation, dependencies without dates and actions that no longer map to the customer priority. Recommend the smallest set of updates needed before the next CSDR.', NULL, N'Current success plan, action log, CSDR notes, milestone status and RAID items.', N'Plan-drift inspection with recommended updates.', N'CSAM confirms what should be changed, retired, escalated or kept as-is.', N'Inspection and review', N'A stale plan creates false confidence. Drift detection keeps the plan governable.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-SPLAN-SCOUT-01', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 5, N'Keep success plan commitments visible between check-ins', N'Turn the success plan from a document reviewed monthly into a tracked set of commitments with standing visibility on what is slipping.', N'Extended', N'Both', N'Track the commitments in this account''s success plan on a recurring basis. For each milestone, tell me whether there is recent evidence of progress, whether the named owner has been active on it, and whether the date is still credible given what has happened since it was set. Flag anything with no evidence of movement and draft the specific question I should ask the owner. Report only changes and exceptions - do not restate the whole plan each time.', N'1. Bring the current success plan with milestones, owners and dates.
2. Run the prompt.
3. Review the exceptions list, remembering that no evidence of movement is not proof that nothing moved.
4. Set the cadence to run before your customer check-in.
5. Ask the named owner the drafted question directly rather than escalating first.', N'The current success plan with milestones, owners and dates; access to the engagement activity behind it.', N'A recurring exceptions-only commitment tracker with an evidence check per milestone and a drafted question for each stalled item.', N'CSAM confirms the credibility judgement on each date personally before raising it, since absence of visible evidence is not proof of absence of progress.', N'Follow-through and orchestration', N'Success plans decay quietly. The milestone that slipped is rarely announced - it is simply never mentioned again until the review.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSAM-VALUE-ALT01', N'WF-X-VALUE-01', N'CSAM-VALUE', N'PH-CSAM-VALUE-EXPL', 3, N'Draft the sponsor value update', N'Summarize adoption progress and value evidence for a sponsor in their language, not in internal metrics.', N'Extended', N'Prompt', N'Draft a sponsor update for [stakeholder] that summarizes adoption progress, value evidence, remaining gap and the next action needed. Use customer language and avoid internal metrics unless they support the outcome.', NULL, N'Validated value realization brief and sponsor context.', N'Sponsor value update draft.', N'CSAM validates evidence, tone, sensitivity and next ask before sending.', N'Stakeholder communication', N'Sponsors need a clear value narrative, not a dashboard dump.', N'https://m365.cloud.microsoft/chat', N'Open Analyst'),
        (N'CSAM-VALUE-ALT02', N'WF-X-VALUE-01', N'CSAM-VALUE', N'PH-CSAM-VALUE-EXPL', 4, N'Convert value gaps into next-best actions', N'Turn adoption and value gaps into next-best actions with paired customer and Microsoft owners and a review date.', N'Extended', N'Prompt', N'Review the adoption and value gaps for [Account]. Recommend next-best actions, including customer owner, Microsoft owner, Success Program or delivery resource if relevant, expected outcome and review date.', NULL, N'Adoption gaps, value evidence, success plan and available delivery or program options.', N'Next-best-action list for value acceleration.', N'CSAM validates fit, ownership and whether recommendations should enter the success plan.', N'Action planning', N'The value story should lead to action, not just a better deck.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-VALUE-P01', N'WF-X-VALUE-01', N'CSAM-VALUE', N'PH-CSAM-VALUE-EXPL', 1, N'Identify adoption friction and next activation actions', N'Map usage gaps to customer priorities and build a short activation plan.', N'Featured', N'Prompt', N'For [Account and workload], compare current adoption or usage signals with customer priorities and licensed or committed scope. Identify the top adoption friction points, likely root cause, stakeholder owner and a 4-week activation plan with measurable milestones.', NULL, N'Usage or adoption data, customer priorities, workload scope, stakeholder context and prior adoption actions.', N'Adoption friction analysis and 4-week activation plan.', N'CSAM validates whether the adoption action is relevant to the customer priority and achievable with available owners.', N'Adoption acceleration', N'Adoption work matters when it changes customer behavior tied to a business outcome.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'CSAM-VALUE-P02', N'WF-X-VALUE-01', N'CSAM-VALUE', N'PH-CSAM-VALUE-EXPL', 2, N'Build the value realization brief', N'Translate adoption, usage, delivery and outcome evidence into a customer-recognized value story.', N'Featured', N'Prompt', N'Build a value realization brief for [Account]. Show what changed, what evidence supports it, how it maps to the customer outcome, remaining gaps and the recommended next action. Separate measured evidence from narrative interpretation.', NULL, N'Adoption data, usage signals, customer outcome, delivery milestones, support or health improvements and prior review notes.', N'Value realization brief with evidence and gaps.', N'CSAM validates customer-recognized value, removes unsupported claims and aligns tone to the audience.', N'Value storytelling', N'Value that is not evidenced is an opinion. Value that is not communicated is invisible.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSA-VALUE-SCOUT-01', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 5, N'Track delivered value against what was promised', N'Keep a running comparison between the outcomes committed in the business case and what consumption and usage data actually show.', N'Extended', N'Both', N'Set up a recurring comparison between the outcomes we committed to in this account''s business case and what the consumption and usage data now shows. Report the direction of travel for each committed outcome, flag any where the trend will not reach the commitment on the current trajectory, and state what evidence would be needed to make the value claim defensible to the customer''s finance function. Distinguish measured results from projected results everywhere.', N'1. Bring the agreed business case, its committed outcomes, and the baseline used at commitment.
2. Run the prompt.
3. Confirm the tracker distinguishes measured results from projected ones on every outcome.
4. Check that the measurement basis has not changed since the commitment was made.
5. Verify any figure yourself before it is shown to the customer as delivered value.', N'The agreed business case and its committed outcomes; current consumption and usage data; the baseline used at commitment.', N'A recurring value tracker per committed outcome, showing measured versus projected, trajectory against commitment, and the evidence gap.', N'CSA verifies the measurement basis has not changed and confirms every figure before it is shown to the customer as a delivered result.', N'Analysis and measurement', N'Value claims lose credibility the moment a customer''s finance function finds the number is projected rather than measured. Tracking continuously is what makes the claim survive scrutiny.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SE-01-ALT-01', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 3, N'Map evidence gaps against decision criteria', N'Test each decision criterion in the discovery brief against the evidence you actually hold, so the gaps are visible before the customer finds them.', N'Extended', N'Prompt', N'Using the discovery brief, map each proposed decision criterion to supporting evidence, missing evidence, assumptions, and required reviewer input.', NULL, N'The discovery brief with its proposed decision criteria; the evidence you currently hold for each; the reviewers who could close a gap.', N'Evidence-gap map tied to customer decision criteria.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'The gap map shows what must be proven before architecture, demo, or PoC work proceeds.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-01-ALT-02', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 4, N'Create the discovery handoff package', N'Package the bounded problem, agreed criteria, evidence gaps and owners so the next technical stage starts without repeating discovery.', N'Extended', N'Prompt', N'Package the bounded problem, agreed criteria, evidence gaps, assumptions, owners, and next technical action for the account team.', NULL, N'The completed discovery brief; the agreed decision criteria; the named owner for each open item.', N'Discovery handoff package for the next technical stage.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A clear handoff prevents discovery findings from being lost before design or proof work begins.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-01-ECIF-01', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 5, N'Validate the technical scope for ECIF', N'Review a proposed investment-funded technical scope for missing evidence and corrections before it reaches request review.', N'Featured', N'Prompt', N'Review the proposed ECIF technical scope, milestones, deliverables, dependencies, and acceptance criteria. Identify missing technical evidence and corrections needed before request review.', NULL, N'Draft workscope, architecture context, technical dependencies, and acceptance criteria.', N'Technical-scope review with issues, proposed corrections, and handoff notes.', N'SE validates technical content only and confirms that eligibility, policy, commercial, and approval decisions remain with accountable owners.', N'Validation and evidence', N'Confirming the technical scope for ECIF now costs a conversation. Discovering it late costs a decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-02-ALT-01', N'WF-X-ARCH-01', N'SE-ARCH-1', N'PH-SE-ARCH-1-EXPL', 3, N'Validate architecture evidence and assumptions', N'Find the unsupported claims and open security or operations questions in an architecture decision record before it is shared.', N'Extended', N'Prompt', N'Review the architecture decision record and source evidence. Identify unsupported claims, assumptions, security or operations questions, and reviewer needs.', NULL, N'The architecture decision record; the source evidence behind each option; the security and operations reviewers available to you.', N'Architecture evidence and assumption review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Architecture confidence improves when unsupported claims are visible before customer use.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-02-ALT-02', N'WF-X-ARCH-01', N'SE-ARCH-1', N'PH-SE-ARCH-1-EXPL', 4, N'Package the architecture handoff', N'Assemble the recommendation, criteria, dependencies and unresolved questions so the next technical stage can act on the decision.', N'Extended', N'Prompt', N'Package the architecture recommendation, decision criteria, dependencies, validation steps, risks, owners, and unresolved questions for the next technical stage.', NULL, N'The validated architecture decision record; the named owner for each dependency; the next technical stage and who leads it.', N'Architecture handoff package.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A clean handoff prevents design intent from changing silently during demo, PoC, or delivery.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-03-ALT-01', N'WF-X-ARCH-01', N'SE-ARCH-2', N'PH-SE-ARCH-2-EXPL', 3, N'Validate demo evidence and known limitations', N'Check what the demo actually proves, what it cannot, and which environment or permission constraints could break it on the day.', N'Extended', N'Prompt', N'Review the demo or workshop plan for evidence, known limitations, environment needs, permission constraints, and unsupported claims.', NULL, N'The demo or workshop plan; the environment and tenant it will run in; the claims you intend to make live.', N'Demo evidence and limitation review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'The strongest demo is honest about what it proves and what still needs validation.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-03-ALT-02', N'WF-X-ARCH-01', N'SE-ARCH-2', N'PH-SE-ARCH-2-EXPL', 4, N'Create the demo follow-up and decision package', N'Capture what the customer reacted to, what stayed unresolved, and the technical decision the demo was meant to move.', N'Extended', N'Prompt', N'Package the demo outcome, customer reactions, unresolved questions, evidence shown, follow-up owners, and next technical decision.', NULL, N'The demo plan as delivered; your notes on customer reactions and questions; the decision the demo was designed to advance.', N'Demo follow-up and decision package.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Follow-up turns the demo from an event into a decision step.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-04-ALT-01', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 3, N'Validate PoC success and exit criteria', N'Test whether the PoC has measurable success criteria and a real exit condition, or whether it will quietly become a project.', N'Extended', N'Prompt', N'Review the PoC plan for measurable success criteria, exit conditions, dependencies, security or data assumptions, milestones, and owner clarity.', NULL, N'The PoC plan with its stated criteria; the data and environment assumptions; the owner of the exit decision.', N'PoC criteria and readiness review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Measurable success and exit criteria prevent the PoC from becoming open-ended work.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-04-ALT-02', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 4, N'Create the PoC decision and handoff package', N'Package the hypothesis, criteria, exit decision and dependencies so the PoC result can be acted on rather than debated.', N'Extended', N'Prompt', N'Package the PoC hypothesis, scope, success criteria, exit decision, milestones, dependencies, owners, and handoff requirements.', NULL, N'The reviewed PoC plan; the milestone owners; the team receiving the result if it succeeds.', N'PoC decision and handoff package.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A PoC handoff makes the final decision and next stage inspectable.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-05-ALT-01', N'WF-X-CONV-01', N'SE-CONV', N'PH-SE-CONV-EXPL', 3, N'Route unsupported technical answers for review', N'Separate the answers that are supported from those needing an SME, policy owner or security reviewer, and name who decides each one.', N'Extended', N'Prompt', N'Review the answer matrix and create an exception list for unsupported, low-confidence, policy-sensitive, security-sensitive, or SME-needed items. Assign suggested reviewers and required decisions.', NULL, N'The completed answer matrix with confidence levels; your reviewer and SME contacts; the response deadline.', N'Exception and reviewer-routing list.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Showing uncertainty early is better than discovering it after the response is distributed.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-05-ALT-02', N'WF-X-CONV-01', N'SE-CONV', N'PH-SE-CONV-EXPL', 4, N'Prepare the response quality checklist', N'Build the final pass that catches unsourced claims, unapproved commitments and unresolved items before a technical response leaves the building.', N'Extended', N'Prompt', N'Create a final response quality checklist covering source completeness, claim review, assumptions, approvals, unresolved items, customer commitments, and distribution readiness.', NULL, N'The near-final response package; the approvals already obtained; the customer commitments it implies.', N'Technical response quality checklist.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'The checklist protects the SE from sending a fluent answer that still lacks approval or evidence.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-06-ALT-01', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 3, N'Validate the blocker evidence and mitigation path', N'Check that every blocker in the technical risk plan has evidence, an owner, a mitigation and a next decision rather than just a name.', N'Extended', N'Prompt', N'Review the technical risk plan and identify whether each blocker has evidence, impact, owner, mitigation, checkpoint, and a clear next decision.', NULL, N'The technical risk plan with its listed blockers; the evidence behind each; the owners you can realistically assign.', N'Blocker evidence and mitigation review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'A blocker without evidence and owner remains an observation, not a plan.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-06-ALT-02', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 4, N'Prepare the delivery or account-team handoff for technical risk', N'Package the technical risk, mitigation and re-engagement triggers so the account or delivery team can carry it without you in the room.', N'Extended', N'Prompt', N'Package the technical risk, evidence, mitigation, owners, dependencies, re-engagement triggers, and handoff requirements for the account team or delivery roles.', NULL, N'The reviewed technical risk plan; the mitigation owners; the delivery or account-team roles receiving the handoff.', N'Technical risk handoff package.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A clear handoff prevents technical risk from being rediscovered after the deal progresses.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-07-ALT-01', N'WF-X-ASSET-01', N'SE-ASSET', N'PH-SE-ASSET-EXPL', 3, N'Sanitize and validate the reusable asset', N'Check a technical asset for sensitive content, accuracy and missing prerequisites before anyone else reuses it.', N'Extended', N'Prompt', N'Review the asset for sensitive content, technical accuracy, prerequisites, limitations, permissions, owner, and validation checks before reuse.', NULL, N'The draft asset; the customer context it was built from; your team''s rules on what may be shared internally.', N'Asset readiness and sanitization review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Reusable assets create risk when sensitive content or unvalidated assumptions travel with them.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-07-ALT-02', N'WF-X-ASSET-01', N'SE-ASSET', N'PH-SE-ASSET-EXPL', 4, N'Create the reuse note and repository metadata', N'Write the tags, purpose, prerequisites and limitations another SE needs to find the asset and know whether it fits their situation.', N'Extended', N'Prompt', N'Create the reuse note, tags, owner, purpose, prerequisites, example use, limitations, and repository metadata needed for another SE to find and adapt the asset.', NULL, N'The sanitized asset; where it will be stored; the owner who will maintain it.', N'Reuse note and repository metadata.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Findability and context are what turn a useful file into a reusable asset.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-HEALTH-SCOUT-01', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 5, N'Monitor technical blockers across your accounts between reviews', N'Set up a standing watch on the technical signals that predict a stalled deployment, so intervention happens before the review rather than at it.', N'Extended', N'Both', N'Set up a recurring check across the accounts I support. Surface where deployment or consumption has flattened or declined, where a technical blocker has been open longer than expected, where a support pattern suggests an unresolved architectural issue, and where a planned milestone has slipped without a new date. For each, state the technical hypothesis and the evidence behind it, and name what you would need to confirm it. Do not diagnose root cause with confidence you do not have.', N'1. Confirm which deployment, consumption and support signals you can reach for the accounts you support.
2. Run the prompt.
3. Review each technical hypothesis and check the evidence actually supports it.
4. Set the cadence to land before your account or delivery review.
5. Confirm any blocker technically yourself before raising it with the customer.', N'The accounts you support; access to deployment, consumption and support signals; the committed technical milestones.', N'A recurring technical risk list with a stated hypothesis, supporting evidence, and the confirmation step for each item.', N'SE validates each hypothesis technically before raising it with the customer or the account team, and corrects any signal that reflects a known planned change.', N'Monitoring and signal', N'Technical blockers are cheapest to fix early and most expensive to fix at a review. The signal is usually present weeks before anyone names the problem.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SE-INVEST-01-P01', N'WF-INVEST-01', N'SE-INVEST', N'PH-SE-INVEST-EXPL', 1, N'Define the investment-funded technical scope and decision criteria', N'Bound what the investment is technically meant to prove, including the assumptions, dependencies and explicit out-of-scope items.', N'Featured', N'Prompt', N'Clarify the technical problem, bounded scope, architecture assumptions, decision criteria, dependencies, risks, and out-of-scope items that the proposed investment should address. Do not infer eligibility or approval.', NULL, N'Customer problem, opportunity context, proposed investment', N'Bounded technical scope and decision-criteria brief.', N'SE validates technical content and confirms that eligibility, policy, commercial, funding, and approval decisions remain with accountable owners.', N'Scoping and design', N'Clear technical scope prevents investment-funded work from expanding beyond the proof it was meant to produce.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-INVEST-01-P02', N'WF-INVEST-01', N'SE-INVEST', N'PH-SE-INVEST-EXPL', 2, N'Create the technical evidence and success-measure package', N'Define the proof, milestones and observable success measures that let a reviewer judge whether the funded work delivered.', N'Featured', N'Prompt', N'Identify the technical proof, readiness evidence, milestones, observable success measures, failure indicators, and review gates needed to evaluate the investment-funded work.', NULL, N'Draft scope and technical context', N'Technical evidence and success-measure package.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Synthesis and drafting', N'Observable success measures make the investment reviewable instead of anecdotal.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-INVEST-01-P03', N'WF-INVEST-01', N'SE-INVEST', N'PH-SE-INVEST-EXPL', 3, N'Pressure-test investment scope against failure modes', N'Stress the proposed technical scope for the assumptions and failure modes that would undermine the investment.', N'Featured', N'Prompt', N'Using the draft technical scope and architecture assumptions, identify the assumptions that would most damage the outcome if wrong, the failure modes that would surface during delivery, and the evidence that would confirm or rule out each one.', NULL, N'Draft technical scope, architecture assumptions, known constraints', N'Ranked assumption and failure-mode register with the evidence needed to close each one.', N'Confirm the grounding sources, separate evidence from assumption, and validate the named owner and next decision before this reaches a customer or an approver.', N'Assumption testing', N'Failure modes found during scoping are cheaper than failure modes found during delivery.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-INVEST-01-P04', N'WF-INVEST-01', N'SE-INVEST', N'PH-SE-INVEST-EXPL', 4, N'Prepare the technical handoff to delivery', N'Package the technical scope, evidence and success measures for the roles who will deliver against them.', N'Featured', N'Prompt', N'Using the approved technical scope, evidence package and success measures, prepare a handoff for the delivery roles. State what is decided, what remains open, and which technical decisions must not change without returning to you.', NULL, N'Approved scope, technical evidence package, success measures', N'Delivery handoff with decided items, open questions and re-engagement triggers.', N'Confirm the grounding sources, separate evidence from assumption, and validate the named owner and next decision before this reaches a customer or an approver.', N'Conversation preparation', N'A handoff protects the technical decisions that should not change without re-engaging the SE.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-INVLINK-01', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 5, N'Define what an investment-funded proof must demonstrate', N'Set the success criteria for technical work that customer investment would fund.', N'Featured', N'Prompt', N'For the proposed proof of concept or workshop, define what an investment-funded engagement would need to demonstrate, the observable success measures, the exit criteria and the evidence that would satisfy a reviewer. Do not assume the investment is approved.', NULL, N'Draft proof or workshop scope, customer decision criteria', N'Success and exit criteria specific enough to justify and later evaluate an investment.', N'SE validates that the criteria are observable and that scope is bounded.', N'Set the success criteria for technical work that customer investment would fund.', N'This links PoC scope to investment readiness without implying the investment is approved.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SSP-COMP-SCOUT-01', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 6, N'Build a reusable objection and language library from real calls', N'Mine your own customer conversations for the objections and language that keep recurring, and turn them into something the team can reuse.', N'Featured', N'Both', N'Work across my customer meeting transcripts and mail from the last quarter for [solution area]. Identify the objections that keep recurring, the language customers actually use to describe the problem we solve, the competitor claims that come up, and the points where conversations stall. Group them by how often they appear. For each recurring objection, show me the customer''s own words rather than a paraphrase, and note which conversations it came from so I can go back to the source.', N'1. Confirm you can reach your own meeting transcripts and mail for this solution area.
2. Run the prompt.
3. Check the recurring objections against your own memory of those calls before treating them as a pattern.
4. Keep the customer language the customer actually used rather than rewriting it into product language.
5. Share the library with your solution area only after removing customer-identifying detail.', N'Approved access to your own meeting transcripts and mail; the solution area in scope; a quarter or more of conversations.', N'An objection and customer-language library grouped by frequency, quoted in the customer''s own words, traceable back to source conversations.', N'SSP verifies the quotes against the source conversation, removes anything customer-identifying before sharing, and decides what is safe to circulate beyond the account team.', N'Analysis and assessment', N'The most useful competitive content is already sitting in conversations you have had. Reading a quarter of transcripts by hand is not realistic, which is why this pattern only became available recently.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SSP-INVEST-01-P01', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 1, N'Assess investment fit and request readiness', N'Assemble an investment readiness assessment without determining eligibility or approval.', N'Featured', N'Prompt', N'Using approved customer, opportunity, workload, partner, and engagement context, assemble an investment readiness assessment. Identify confirmed inputs, gaps, dependencies, and questions requiring a process owner. Do not determine final eligibility or approval.', NULL, N'Customer outcome; opportunity context; engagement intent; partner context.', N'Readiness assessment with confirmed inputs, gaps, owners, and next decision.', N'SSP confirms source accuracy, current policy/process boundaries, role ownership, decision authority, and customer context.', N'Analysis and assessment', N'Working through readiness forces a position without overstating authority.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-01-P02', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 2, N'Build the request preparation package', N'Organize approved investment inputs into a preparation package.', N'Featured', N'Prompt', N'Organize approved investment inputs into a preparation package. Separate facts from assumptions, identify role contributions, and show unresolved dependencies. Do not submit, approve, or invent missing information.', NULL, N'Approved account, technical, delivery, partner, and outcome inputs.', N'Request preparation package with confirmed facts, open questions, contributions, and human decisions.', N'SSP confirms source accuracy, current policy/process boundaries, role ownership, decision authority, and customer context.', N'Synthesis and drafting', N'Most request delay is missing inputs and unclear ownership.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-01-P03', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 3, N'Coordinate contributors, suppliers, and handoffs', N'Map contributors, partner/supplier inputs, dependencies, and handoff points.', N'Featured', N'Prompt', N'Map the contributors, partner or supplier inputs, dependencies, and handoff points for the proposed investment. Identify stalled items and owners. Do not imply funding or approval status.', NULL, N'Current request context and contributor information.', N'Contributor and handoff map with inputs, owners, dependencies, and escalation questions.', N'SSP confirms source accuracy, ownership, decision authority, and status before use.', N'Coordination and handoff', N'Contributor handoffs are invisible when they work and obvious when they fail.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-01-P04', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 4, N'Connect investment to the opportunity decision path', N'Explain how investment supports the customer decision, milestones, readiness, and outcomes.', N'Featured', N'Prompt', N'Explain how the proposed investment supports the customer decision, engagement milestones, implementation readiness, and intended outcomes. Separate evidence from assumptions and do not represent funding as approved.', NULL, N'Opportunity strategy; proposed investment; supported outcomes.', N'Investment-to-opportunity rationale with evidence, milestones, dependencies, and next decision.', N'SSP confirms the barrier is real, investment is an appropriate lever, and no approval or funding status is overstated.', N'Value translation', N'Investment should connect to a customer decision, not sit beside the pursuit.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-01-P05', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 5, N'Track request status and identify the next supported action', N'Summarize current request stage, owner, blockers, and next supported action.', N'Featured', N'Prompt', N'Summarize the current investment request stage, known owner, blockers, pending information, and next supported action using approved status sources. Do not claim unsupported editing, automation, eligibility, funding, or approval status.', NULL, N'Approved request status and notifications.', N'Status and next-action brief with owner, blockers, and questions.', N'SSP verifies current status against authoritative records before acting or reporting.', N'Monitoring and signal', N'With request status, the change finds you instead of you remembering to look.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-P06', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 6, N'Submit the request and know where it went', N'Move the prepared request into MSX Deal Assistance, confirm what is required before submission, and know how to check its status afterwards.', N'Featured', N'Both', N'I have a prepared investment request for [opportunity]. Before I submit it in MSX Deal Assistance, check my package against what a complete submission needs: opportunity linkage, business justification, ROI rationale, workscope reference, supplier detail if applicable, and the consumption plan if this is a Global ECIF or ACO request. Tell me what is missing or thin, and what an approver is most likely to send back. Do not tell me it is eligible or approvable; that is not your call.', N'1. Run the prompt against your prepared package.
2. Close whatever it flags as missing.
3. Open the opportunity in MSX, go to the Deal Assistance tab, select New Request, and choose the request type.
4. Attach the workscope from ECIF Central if the request needs one.
5. Submit, then note where the tracker view shows it sitting and who holds it.
6. If you are blocked on access or process rather than a decision, go to MCAPS Help rather than waiting.', N'The prepared request package. The MSX opportunity. The workscope from ECIF Central if applicable. Access to MSX Deal Assistance.', N'A submitted request with a known status, a named current owner, and a completeness check done before submission rather than after a rejection.', N'SSP confirms the business justification is genuine rather than assembled to pass a check, and accepts that eligibility, policy, and funding decisions belong to the accountable owners rather than to the seller or the tool.', N'Execution and validation', N'A request that comes back for missing information costs a cycle. Most of what gets sent back is knowable before submission.', N'https://microsoftsales.crm.dynamics.com/main.aspx?appid=fe0c3504-3700-e911-a849-000d3a10b7cc&forceUCI=1&pagetype=entitylist&etn=opportunity&viewid=00000000-0000-0000-00aa-000010003000&viewType=1039', N'Open MSX Opportunities'),
        (N'SSP-INVLINK-01', N'WF-X-ORCH-01', N'SSP-ORCH', N'PH-SSP-ORCH-EXPL', 2, N'Bring funding into the pursuit orchestration plan', N'Add investment and funding path to the specialist and partner plan.', N'Featured', N'Prompt', N'Using the current pursuit plan, identify where funding or customer investment is a dependency, who owns the request, what inputs are still missing, and the next governed action. Do not represent funding as approved.', NULL, N'Current pursuit plan; contributor list; known funding dependencies.', N'Pursuit plan with funding dependency, owner, and next action made explicit.', N'SSP confirms ownership of the request and that no funding status is overstated.', N'Coordination and handoff', N'Funding is part of orchestration when it changes the pursuit path.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SSP-LEAD-SCOUT-01', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 5, N'Close the loop on outreach that never got an answer', N'Track the outreach you have sent so the follow-ups that matter are surfaced and drafted rather than remembered.', N'Extended', N'Both', N'Review the outreach I have sent over the last 30 days and identify every message where I asked for something - a meeting, an introduction, a decision, or information - and did not receive a substantive reply. For each one, tell me how long it has been waiting, how important it looks based on the opportunity involved, and draft a short follow-up in my own voice that adds a new reason to respond rather than simply repeating the ask. Do not send anything.', N'1. Confirm the check can see your sent messages for the last 30 days.
2. Run the prompt.
3. Review the ranked list and remove any thread where the silence is itself the answer.
4. Edit every drafted follow-up so it adds a new reason to reply rather than repeating the ask.
5. Send them yourself; do not let the check send on your behalf.', N'Access to your sent messages; your current lead and opportunity list; your team''s follow-up cadence norms.', N'A ranked list of unanswered asks with elapsed time and a drafted follow-up for each that adds new value rather than repeating.', N'SSP reviews and edits every draft before sending, and removes any follow-up where the silence is itself the answer.', N'Follow-through and orchestration', N'Most lost specialist opportunities are not rejected - they are dropped. The follow-up that would have converted was never sent because it was never surfaced.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'WF-ARCH-01-P-CSA-01', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 1, N'Compare production architecture options', N'Investigate current architecture patterns and evidence.', N'Featured', N'Prompt', N'Research architecture options for [workload/customer scenario] using approved Microsoft and authoritative public sources. Compare security, resilience, governance, scale, operational complexity, cost considerations, dependencies and maturity. Cite claims, identify conflicting guidance or missing evidence, and do not recommend until decision criteria are explicit.', NULL, N'Outcome; workload; constraints; decision criteria; allowed sources.', N'Sourced option comparison.', N'CSA validates source authority, applicability, security, compliance and recommendation boundaries.', N'Prioritization', N'Comparing production architecture options surfaces the difference that actually changes the decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-ARCH-01-P-CSA-02', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 2, N'Create the production-ready architecture package', N'Produce a bounded architecture decision package.', N'Featured', N'Prompt', N'Create a production-ready architecture decision package for [Customer/workload] using approved context and option analysis. Include desired outcome, current state, recommended architecture, alternative, tradeoffs, controls, governance, dependencies, sequence, readiness criteria, open decisions, and a human-review checklist. Stop and ask when evidence conflicts or a material decision lacks an owner.', NULL, N'Approved architecture context and reviewers.', N'Architecture decision package.', N'CSA owns the recommendation and obtains required reviews.', N'Synthesis and drafting', N'You spend your time editing the production-ready architecture package rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-CE-APPROVAL-01-P-CE-01', N'WF-X-DEAL-01', N'CE-DEAL-1', N'PH-CE-DEAL-1-EXPL', 2, N'Map approvals and fastest governed path', N'Identify approval, policy and escalation dependencies.', N'Featured', N'Prompt', N'Review opportunity [ID] and map all known approvals, policy checks, reviewers, dependencies and escalation paths. Highlight blockers, missing evidence and the next action for each. Draft a Deal Desk justification, but do not submit it.', NULL, N'Opportunity ID and approved materials.', N'Approval map and draft justification.', N'CE validates approval requirements, evidence, routing, precedent and final submission.', N'Problem identification', N'Naming approvals and fastest governed path is most of the work. Unnamed problems never get an owner.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-APPROVAL-01-P-CE-02', N'WF-X-DEAL-01', N'CE-DEAL-1', N'PH-CE-DEAL-1-EXPL', 3, N'Create the commercial execution tracker', N'Coordinate approvals, amendments and close actions.', N'Featured', N'Prompt', N'Using approved deal materials, create an execution tracker with action, owner, evidence, dependency, due checkpoint, status, blocker, escalation and decision required. Separate customer actions from internal actions.', NULL, N'Approved deal materials.', N'Commercial execution tracker.', N'CE confirms owners, dates, approvals, customer commitments and system-of-record updates.', N'Synthesis and drafting', N'You spend your time editing the commercial execution tracker rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-CE-NEG-01-P-CE-01', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 3, N'Build the negotiation strategy and concession plan', N'Prepare positions and value trades before negotiation.', N'Featured', N'Prompt', N'Build a negotiation plan for [deal]. Include customer objectives, Microsoft objectives, opening position, must-have terms, tradable items, concession ladder, give/get logic, likely objections, walk-away or escalation triggers and next decision.', NULL, N'Approved deal and authority context.', N'Negotiation and concession plan.', N'CE validates authority, customer context, policy, value trades and escalation triggers.', N'Synthesis and drafting', N'Most of the effort in the negotiation strategy and concession plan is assembly, and assembly is exactly what AI removes.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-NEG-01-P-CE-02', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 4, N'Rehearse the commercial negotiation', N'Practice objections, value trades and decision control.', N'Featured', N'Prompt', N'Role-play the upcoming commercial negotiation using the approved plan. Simulate realistic customer objections and requests. Pause for my response, then coach clarity, value trading, concession discipline, policy boundaries and the next decision. Do not invent terms or authority.', NULL, N'Approved negotiation plan.', N'Negotiation rehearsal and coaching actions.', N'CE validates all positions, concessions, authority and customer commitments before use.', N'Conversation preparation', N'Ten minutes rehearsing the commercial negotiation is cheaper than improvising it in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-CE-POLICY-01-P-CE-01', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 1, N'Map eligibility, policy, and execution requirements', N'Apply current authoritative guidance to a proposed structure and route open questions.', N'Featured', N'Prompt', N'Using current approved guidance and the proposed segment, products, SKUs, terms, agreement context, and exception questions, identify eligibility considerations, required amendments, execution steps, approval needs, side-agreement risk, and authoritative owners. Cite the exact guidance used and flag uncertainty. Do not approve exceptions.', NULL, N'Current approved guidance and proposed offer.', N'Policy, eligibility, and execution map with cited guidance, open questions, and owners.', N'CE validates source version, interpretation, required legal, finance, policy, or Deal Desk review, and any customer-facing use.', N'Validation and evidence', N'The useful AI output is not a guessed policy answer. It is the right question, evidence, and owner.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-CE-POLICY-01-P-CE-02', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 2, N'Inspect licensing, discount, and compliance risk', N'Review the proposed structure for commercial risk.', N'Featured', N'Prompt', N'Review the proposed licensing, discount, and compliance structure for [account/opportunity]. Identify unused or mismatched licensing, discount exceptions, compliance concerns, policy questions, approval requirements, renewal risk, and evidence gaps. Cite sources where available.', NULL, N'Proposed licensing and discount structure.', N'Licensing, discount, and compliance risk review with evidence gaps and approval questions.', N'CE validates licensing, eligibility, discount authority, policy and recommended action.', N'Inspection and review', N'Reviewing licensing and discount risk is judgment work. The agent proposes; the CE remains accountable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-RENEW-01-P-CE-01', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 1, N'Build the CE-led renewal strategy view', N'Surface renewal economics, risk and expansion early.', N'Featured', N'Prompt', N'For [account name or TPID], show the upcoming renewals with expiry dates and current agreement details, then for the agreement I name provide the license estate grouped by SKU, the SKUs whose discount is between 40 and 60 percent, and ACR trends month over month. Build a CE-led renewal strategy view covering structure, MACC trajectory, consumption signals, current discounts and concessions, risk, expansion potential, and amendments in play. Separate what the source systems returned from what you inferred, and do not represent any concession or discount as approved.', NULL, N'Account and approved renewal context.', N'Renewal strategy brief with commercial structure, risk, expansion potential, approval path, and evidence gaps.', N'CE validates contract, revenue, usage, structure, risk, authority and ownership.', N'Synthesis and drafting', N'Most of the effort in the renewal strategy view is assembly. The strategy decision stays human-led.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-RENEW-01-P-CE-02', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 2, N'Inspect upcoming renewal portfolio for CE intervention', N'Prioritize renewals requiring CE intervention.', N'Featured', N'Prompt', N'Show upcoming renewals in the selected period for my scope. Prioritize by revenue, discount exposure, consumption or MACC risk, execution complexity, expansion potential, approval requirements, and evidence quality. Explain the certified signal behind each priority.', NULL, N'Approved renewal report and scope.', N'Prioritized renewal radar with intervention rationale, evidence quality, and missing data.', N'CE validates report scope, signals, ownership and recommended intervention.', N'Inspection and review', N'Reviewing the renewal portfolio is judgment work. The agent proposes; the CE stays accountable.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-CE-RISK-01-P-CE-01', N'WF-X-HEALTH-01', N'CE-HEALTH', N'PH-CE-HEALTH-EXPL', 1, N'Identify commercial risk and escalation priorities', N'Use approved signals to prioritize commercial risk, source evidence, and escalation needs.', N'Featured', N'Prompt', N'Review the approved commercial, renewal, agreement, and deal signals for [scope]. Identify the top commercial risks, the supporting source signal, likely impact, recommended intervention, owner, escalation need, and any unavailable or stale data. Separate evidence from interpretation.', NULL, N'Approved scope, current commercial signals, renewal or agreement context, and known ownership.', N'Prioritized commercial risk view with evidence, intervention, owner, escalation need, and source gaps.', N'CE validates data scope, source freshness, business context, risk interpretation, mitigation, owner, and escalation route.', N'Problem identification', N'Commercial risk found early is a conversation. The same risk found at approval becomes delay.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-CE-RISK-01-P-CE-02', N'WF-X-HEALTH-01', N'CE-HEALTH', N'PH-CE-HEALTH-EXPL', 2, N'Build the commercial decision brief', N'Prepare commercial talking points, decision needs, and authority boundaries for a live customer or deal review.', N'Featured', N'Prompt', N'Prepare the CE commercial decision brief for [account/opportunity]. Include contract context, proposed structure, concessions or terms requiring review, current approvals, renewal or consumption risk, likely customer questions, authority boundaries, and the next commercial decision. Flag any customer-facing claim requiring review.', NULL, N'Account or opportunity context.', N'Commercial decision brief with authority boundaries, risks, questions, and next decision.', N'CE validates terms, authority, source freshness, customer-facing positions, and required reviewers.', N'Synthesis and drafting', N'Most of the effort in the commercial decision brief is assembly. The judgment stays with the CE.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-STRUCT-01-P-CE-01', N'WF-X-DEAL-01', N'CE-DEAL-1', N'PH-CE-DEAL-1-EXPL', 1, N'Compare viable commercial structures', N'Develop decision-ready commercial options.', N'Featured', N'Prompt', N'For [opportunity], compare three viable commercial structures using available approved context. For each show products or SKUs, term, pricing logic, customer value, Microsoft trade-offs, risks, approvals and assumptions. Do not create or submit an offer.', NULL, N'Approved opportunity context.', N'Commercial options matrix.', N'CE validates pricing, products, licensing, authority, policy and feasibility.', N'Prioritization', N'Comparing viable commercial structures surfaces the difference that actually changes the decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-STRUCT-01-P-CE-02', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 1, N'Create the commercial decision narrative', N'Turn approved context into a concise internal recommendation.', N'Featured', N'Prompt', N'Using the approved deal context and options, draft a commercial decision narrative with customer outcome, options considered, recommended structure, value trades, assumptions, risks, required reviewers and next decision.', NULL, N'Approved deal context and options.', N'Internal commercial recommendation.', N'CE approves the recommendation and routes required review.', N'Synthesis and drafting', N'You spend your time editing the commercial decision narrative rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-CE-TRANS-01-P-CE-01', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 2, N'Research agreement and commerce changes', N'Ground migration advice in current authoritative sources.', N'Featured', N'Prompt', N'Research current differences between [legacy agreement] and [new commerce model] using authoritative Microsoft sources. Summarize commercial, administrative and customer-impact differences, risks, unresolved questions and citations.', NULL, N'Agreement models and authoritative sources.', N'Sourced transition evidence brief.', N'CE and policy, licensing or legal SMEs validate applicability and current guidance.', N'Analysis and assessment', N'Being able to cite agreement and commerce changes beats being able to remember it.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-CE-TRANS-01-P-CE-02', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 3, N'Build the customer migration brief', N'Translate approved guidance into customer-specific decision support.', N'Featured', N'Prompt', N'Using approved customer contract context and validated transition guidance, create a migration brief with current state, contractual differences, administrative shift, amendment needs, red-line risks, choices, timeline, responsibilities and customer talk track.', NULL, N'Approved contract context and validated guidance.', N'Customer-specific migration brief.', N'CE validates contract interpretation, policy, dates, commitments and required reviewers.', N'Synthesis and drafting', N'Most of the effort in the customer migration brief is assembly, and assembly is exactly what AI removes.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-COMP-01-P-SSP-01', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 1, N'Build the competitive differentiation brief', N'Use approved win/loss and market context for a proof-backed competitive position.', N'Featured', N'Prompt', N'Produce a competitive differentiation brief for [solution area] and [customer context]. Include relevant win/loss drivers, three strongest differentiators with proof, common objections with handlers, risks, and a concise talk track. Flag where data or proof is weak.', NULL, N'Solution area; customer context; approved competitive and win/loss sources.', N'Competitive brief with differentiators, proof, objections, and talk track.', N'SSP validates freshness, source grounding, customer applicability, and claims before external use.', N'Synthesis and drafting', N'Competitive conversations are lost by improvisation.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-COMP-01-P-SSP-02', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 2, N'Research competitive and industry context', N'Investigate current evidence before positioning.', N'Featured', N'Prompt', N'Research [competitor], [solution area], and [customer industry]. Compare publicly supportable positions, proof, recent developments, common objections, and uncertainty. Do not infer confidential competitor information.', NULL, N'Competitor; solution area; industry; approved source boundaries.', N'Sourced competitive context brief.', N'SSP validates source quality, timeliness, relevance, and customer-facing claims.', N'Analysis and assessment', N'Being able to cite competitive context beats remembering it.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-COMP-01-P-SSP-03', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 3, N'Test the differentiator against the customer''s real decision criteria', N'Pressure-test each claimed differentiator against what this customer actually said they will decide on, and drop the ones that do not connect.', N'Extended', N'Both', N'You are helping a specialist seller sharpen a competitive position. Here is the customer''s stated decision criteria and evaluation process: [paste criteria, evaluation team, timeline]. Here are the differentiators we plan to lead with: [paste differentiators and proof]. For each differentiator, state which specific decision criterion it addresses, how directly it addresses it, and what proof the customer would need to accept it. Identify any differentiator that does not map to a stated criterion and recommend dropping or reframing it. Flag any criterion we currently have no answer for. Do not add differentiators that are not in my list.', N'1. Gather the customer''s stated decision criteria from meeting notes or MSX.
2. List current differentiators and their proof.
3. Run the prompt.
4. Cut differentiators that do not map to a criterion.
5. Name the gaps you cannot yet answer.', N'Customer decision criteria and evaluation process; current differentiators and supporting proof; who is on the evaluation team.', N'A shortened differentiator list mapped to decision criteria, plus a named list of criteria with no current answer.', N'SSP confirms the decision criteria are what the customer actually said rather than what the team assumes, and owns the decision to drop a differentiator.', N'Analysis and assessment', N'A differentiator the customer is not deciding on is noise, however true it is.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-COMP-01-P-SSP-04', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 4, N'Rehearse the competitive conversation and build the objection handler', N'Practice the response out loud, then convert what broke into a written objection handler tied to approved proof.', N'Extended', N'Both', N'Play the role of a technical evaluator at [customer] who currently favors [competitor]. I will present our competitive position. Challenge me the way that evaluator would, including on price, migration effort, and lock-in. After three exchanges, stop the role-play and produce an objection handler table: each objection you raised, my response, the approved proof that supports it, and a note where no approved proof exists. Do not soften the objections and do not supply proof I have not given you.', N'1. Bring the differentiator list from the previous activity and the approved competitive proof.
2. Run a short rehearsal with the agent as the skeptical evaluator.
3. Have it produce the objection handler table.
4. Fill or remove any row where proof is missing.
5. Bring the table to the huddle.', N'Competitive position and differentiators; the competitor in play; approved competitive proof sources; known evaluator concerns; customer role you will be speaking to.', N'An objection handler table mapping each objection to a response and the approved proof behind it, with proof gaps named.', N'SSP judges whether the rehearsed language is accurate, appropriate for this customer, and consistent with approved competitive guidance before using it externally.', N'Practice and rehearsal', N'Competitive conversations are lost in the moment, not in the brief.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-COMP-01-P-SSP-05', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 5, N'Convert the competitive position into the next customer step', N'Turn the position into a concrete next action in the opportunity rather than a document that stops at the brief.', N'Extended', N'Both', N'Using this competitive position and the customer''s decision criteria [paste], propose the single next step that would most reduce competitive risk in this opportunity. Give me three options ranked by impact, each with: what it is, who from our side needs to be involved, what the customer gets out of it, and what evidence it would generate for the decision. Then draft the short note I would send to the customer to set it up. Keep the note under 120 words and do not overstate what we have proven.', N'1. Bring the tested differentiator list and the open gaps.
2. Run the prompt.
3. Pick one next step.
4. Adjust the draft note in your own voice.
5. Record the next step in the opportunity.', N'Tested differentiators and open gaps; opportunity stage and close plan; who owns the customer relationship.', N'One chosen next step with owner and purpose, and a short customer-ready note to set it up.', N'SSP owns the choice of next step and the customer-facing wording, and confirms it fits the account team''s plan before sending.', N'Planning and drafting', N'A competitive brief that does not change the next customer interaction has not changed the deal.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CONSUME-01-P-CSA-01', N'WF-X-PIPE-01', N'CSA-PIPE', N'PH-CSA-PIPE-EXPL', 1, N'Analyze consumption trajectory and shortfall drivers', N'Ask what certified consumption data says.', N'Featured', N'Prompt', N'For [Customer] and [period], analyze enabled consumption trajectory and compare it with the relevant plan or milestone view. Break down largest changes by available dimension, identify data-supported contributors to potential shortfall, show supporting metrics and state what the report cannot answer.', NULL, N'Enabled certified report; customer; period.', N'Consumption trajectory analysis.', N'CSA confirms scope, KPI definitions, technical significance and credibility.', N'Analysis and assessment', N'Working through consumption trajectory and shortfall drivers forces a position, and a position is what the decision needs.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-CONSUME-01-P-CSA-02', N'WF-X-PIPE-01', N'CSA-PIPE', N'PH-CSA-PIPE-EXPL', 2, N'Design a technical shortfall intervention', N'Connect customer context to intervention planning.', N'Featured', N'Prompt', N'Using approved consumption analysis and available context for [Customer], identify technical blockers, workload milestones, stakeholders, commitments and dependencies relevant to the potential shortfall. Propose intervention options, owner candidates, customer touchpoints and evidence needed. Do not assume cause or make commitments.', NULL, N'Approved analysis and authorized context.', N'Intervention options with evidence, owners and gaps.', N'CSA selects intervention and validates cause, context, ownership and commitments.', N'Scoping and design', N'Settling a technical shortfall intervention before the work starts is the only version of that decision that holds.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CONV-01-P-AE-JAI', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 3, N'Rehearse the executive customer conversation', N'Rehearse the executive customer conversation', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the upcoming [meeting type] with [customer or stakeholder]. Use the approved conversation plan and focus on the AE contribution: executive narrative, customer outcome, primary ask, fallback ask, likely questions, and relationship-sensitive responses. Simulate realistic questions or objections, pause for the team member response, then provide coaching on clarity, evidence, listening, and the proposed next step. Identify claims, commitments, technical guidance, or commercial positions that require human or SME review. Do not invent customer facts or make commitments.', NULL, N'Approved conversation plan; meeting type; customer or stakeholder context; role contribution; desired decision or outcome; known boundaries.', N'Role-play output with likely questions, coaching observations, improvement actions, and claims requiring review.', N'AE validates customer facts, commitments, technical or commercial guidance, and final wording before customer use.', N'Conversation preparation', N'Rehearsal lets weak claims fail safely before the customer hears them.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-CONV-01-P-SSP-01', N'WF-X-CONV-01', N'SSP-CONV', N'PH-SSP-CONV-EXPL', 1, N'Prepare the solution-specific customer conversation', N'Build grounded discovery, proof, objection, role contribution, and ask structure.', N'Featured', N'Prompt', N'Prepare me for the upcoming [meeting] with [account]. Summarize priorities, stakeholders, open risks, competitive mentions, and solution context. Draft five discovery questions, proof points, likely objections with responses, role contributions, primary ask, and fallback ask. Flag uncertainty.', NULL, N'Account; meeting; solution play; current stage; approved sales context.', N'Conversation plan with discovery questions, proof, objections, role contributions, and ask.', N'SSP validates customer facts, evidence, competitive claims, commitments, and the final ask.', N'Conversation preparation', N'Preparation is where the solution conversation is decided.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CONV-01-P-SSP-03', N'WF-X-CONV-01', N'SSP-CONV', N'PH-SSP-CONV-EXPL', 3, N'Find the discovery gap before the meeting, not after', N'Check what you still do not know that would change your recommendation, and build the question that closes it.', N'Extended', N'Both', N'Here is what we currently know about [account] for [solution play]: [paste priorities, environment, stakeholders, constraints, prior conversations]. Identify what we do not know that would materially change our recommendation, ranked by how much it would change it. For the top three unknowns, write one open question each that could be asked naturally in the upcoming conversation without sounding like a survey. Distinguish what we actually know from what we have assumed.', N'1. Assemble what is known about the account.
2. Run the prompt.
3. Separate known from assumed.
4. Choose one question to definitely ask.
5. Add it to the conversation plan.', N'Everything currently known about the account and solution context; prior conversation notes; the recommendation you intend to make.', N'A ranked list of decision-changing unknowns and three natural questions to close the top ones.', N'SSP verifies which items are genuinely known versus assumed by the account team, and chooses which question is worth the meeting time.', N'Problem identification', N'The most expensive assumptions are the ones nobody noticed they were making.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-CONV-01-P-SSP-04', N'WF-X-CONV-01', N'SSP-CONV', N'PH-SSP-CONV-EXPL', 4, N'Turn the conversation into decisions and commitments', N'Convert meeting notes into what changed, what was agreed, and what the customer actually committed to.', N'Extended', N'Both', N'Here are my notes from the customer conversation: [paste notes or transcript summary]. Produce three separate lists: what we learned that changes our understanding, what was explicitly agreed and by whom, and what remains open. Then draft a short follow-up note to the customer confirming only what was actually agreed. Do not record something as agreed if the notes only show it was discussed. Flag anything ambiguous rather than resolving it.', N'1. Capture notes immediately after the meeting.
2. Run the prompt.
3. Check the agreed list against your memory.
4. Send the follow-up note.
5. Update the opportunity with what changed.', N'Meeting notes or transcript summary; who attended; what was asked for; the conversation plan you went in with.', N'Separated lists of learnings, agreements, and open items, plus a short confirming follow-up note.', N'SSP confirms that anything recorded as agreed was actually agreed, and owns the follow-up wording before sending.', N'Synthesis and drafting', N'Deals slip on the gap between what was discussed and what was agreed.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CONV-01-P-SSP-JAI', N'WF-X-CONV-01', N'SSP-CONV', N'PH-SSP-CONV-EXPL', 2, N'Rehearse solution discovery and objection handling', N'Rehearse the solution conversation and receive coaching before customer use.', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the upcoming [meeting type] with [customer or stakeholder]. Use the approved conversation plan and focus on solution discovery, differentiation, proof points, likely objections, next solution decision, and primary ask. Pause for the team member response, then coach clarity, evidence, listening, and next step. Do not invent customer facts or commitments.', NULL, N'Approved conversation plan; meeting type; customer context; desired outcome.', N'Interactive role-play, targeted coaching, objections, and improvement list.', N'SSP validates facts, claims, commitments, guidance, and decides what to change before customer use.', N'Conversation preparation', N'Ten minutes rehearsing is cheaper than improvising in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-DEAL-01-P-SSP-01', N'WF-X-DEAL-01', N'SSP-DEAL', N'PH-SSP-DEAL-EXPL', 1, N'Inspect solution opportunity readiness', N'Identify the decision or blocker preventing progression.', N'Featured', N'Prompt', N'Review opportunity [ID] for [solution play]. Summarize current stage, customer outcome, stakeholder coverage, proof or demo status, technical and commercial dependencies, partner or funding needs, blockers, and the single next decision required. Recommend actions with owners.', NULL, N'Opportunity ID; solution play; current sales context.', N'Readiness view with blockers, next decision, actions, and owners.', N'SSP validates stage, blockers, owners, dependencies, and commitments.', N'Inspection and review', N'Readiness inspection is judgment work. The agent proposes; the SSP stays accountable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-DEAL-01-P-SSP-02', N'WF-X-DEAL-01', N'SSP-DEAL', N'PH-SSP-DEAL-EXPL', 2, N'Create the solution acceleration action plan', N'Turn enabled opportunity data into prioritized actions.', N'Featured', N'Prompt', N'For my active [solution area] opportunities, identify stalled milestones, missing customer evidence, stakeholder gaps, and next actions. Prioritize the opportunities requiring SSP intervention this week.', NULL, N'Enabled MSXI report or opportunity context.', N'Prioritized solution-opportunity action plan.', N'SSP validates report scope, stage, risk, intervention, and ownership.', N'Synthesis and drafting', N'The path advances when blockers, owners, and next decisions are explicit.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-DEAL-01-P-SSP-03', N'WF-X-DEAL-01', N'SSP-DEAL', N'PH-SSP-DEAL-EXPL', 3, N'Prepare the conversation that clears the next decision', N'Design the single conversation that would unblock the opportunity, and decide who needs to be in it.', N'Extended', N'Both', N'For opportunity [ID], the next decision required is [paste decision] and the current blocker is [paste blocker]. Design the one conversation that would most likely clear it: who needs to be in the room from both sides, what each person needs to hear, what we must bring as evidence, what we are asking them to decide by the end, and what we do if they say not yet. Keep it to one conversation; do not propose a sequence of three meetings.', N'1. Bring the readiness view and the named blocker.
2. Run the prompt.
3. Confirm the attendee list is realistic.
4. Prepare the evidence.
5. Schedule it.', N'The readiness view; the next decision required; the current blocker; stakeholder coverage; available evidence and proof.', N'A single conversation design with attendees, evidence needed, the decision being asked for, and a fallback.', N'SSP validates that the named blocker is the real one, confirms attendees with the account team, and owns what is asked of the customer.', N'Conversation preparation', N'Most stalled opportunities need one specific conversation, not more activity.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-DEAL-01-P-SSP-04', N'WF-X-DEAL-01', N'SSP-DEAL', N'PH-SSP-DEAL-EXPL', 4, N'State the close plan in the customer''s terms', N'Rewrite the close plan as the customer''s path to their outcome, so it can be shared with them rather than kept internal.', N'Extended', N'Both', N'Rewrite this internal close plan [paste] as a shared plan from the customer''s point of view. Replace our sales stages with their decision milestones, name what they need from us at each step and what we need from them, and end with the outcome they said they wanted. Remove internal language, forecast terms, and anything we would not want a customer to read. Flag any step that depends on something we have not confirmed with them.', N'1. Bring the internal close plan.
2. Run the prompt.
3. Remove anything still internal.
4. Check every date is one the customer has agreed to.
5. Share it and ask them to correct it.', N'The internal close plan; the customer''s stated outcome and decision process; confirmed dates versus assumed dates.', N'A customer-facing shared plan organized around their decision milestones, with unconfirmed dependencies flagged.', N'SSP verifies no internal forecast language survives, confirms which dates the customer actually agreed to, and approves before sharing externally.', N'Value translation', N'A close plan the customer has never seen is a forecast, not a plan.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-LEAD-01-P-SSP-01', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 1, N'Build a prioritized lead follow-up plan', N'Combine scattered lead, event, account, and interaction signals into a structured SSP follow-up plan.', N'Featured', N'Prompt', N'Using approved lead, attendee, account, email, meeting, and public context, create a prioritized follow-up plan for [solution area]. For each lead include source, account, likely interest, solution relevance, suggested message, owner, and next action. Flag missing evidence and do not send outreach.', NULL, N'Approved lead or attendee lists; account context; solution area; recent interactions.', N'Prioritized lead follow-up plan with source, fit, message, owner, and next action.', N'SSP validates consent, customer context, solution relevance, ownership, and outreach language before use.', N'Synthesis and drafting', N'Most of the effort in lead follow-up is assembly. AI can assemble; the SSP decides where to focus.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-LEAD-01-P-SSP-02', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 2, N'Identify missed solution-area opportunities', N'Use sales signals to identify solution-area opportunities the SSP may be missing.', N'Featured', N'Prompt', N'For [solution area] across my active accounts, identify opportunity signals I may be missing. Show the source signal, likely customer need, relevant solution play, uncertainty, and the next discovery action. Separate facts from recommendations.', NULL, N'SSP scope; solution area; available MSX and approved customer signals.', N'Ranked opportunity hypotheses with next discovery actions.', N'SSP validates signal quality, customer need, ownership, and whether an opportunity should be created or advanced.', N'Problem identification', N'Unnamed solution opportunities never get an owner.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-LEAD-01-P-SSP-03', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 3, N'Draft the first contact for the top-priority lead', N'Turn the top-ranked lead into a specific, short first message that connects the signal to a reason for the customer to respond.', N'Extended', N'Both', N'Here is the top lead from my follow-up plan: [paste source signal, account, role, likely interest, and any prior interaction]. Draft a first contact message under 100 words that references the specific signal, states one reason this is relevant to their business now, and asks for one small next step. Give me two versions: one for a business decision maker and one for a technical decision maker. Do not claim knowledge of their environment we do not have, and do not assert a product feature I have not given you.', N'1. Take the top lead from the prioritized plan.
2. Confirm consent and context are appropriate for outreach.
3. Run the prompt.
4. Edit into your own voice.
5. Send one, and note the date.', N'The prioritized lead plan; the source signal; the contact''s role; prior interaction history; consent and outreach appropriateness.', N'Two short first-contact drafts, one business and one technical, tied to the originating signal.', N'SSP confirms consent and outreach appropriateness, verifies every factual statement about the customer, and owns the wording before sending.', N'Synthesis and drafting', N'A prioritized list that never becomes a message is just a better-sorted backlog.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-LEAD-01-P-SSP-04', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 4, N'Close the loop on what the follow-up produced', N'Review the leads worked this week, record what happened, and decide which signals are worth trusting next time.', N'Extended', N'Both', N'Here are the leads I followed up this week and what happened with each: [paste lead, source signal, action taken, response or silence]. Tell me which signal sources produced a response and which did not, what the responses have in common, and which two signal types I should prioritize next week. Be direct about small sample size; do not overstate a pattern from a handful of leads.', N'1. List the leads worked and the outcome of each.
2. Run the prompt.
3. Record the outcome in the opportunity or lead record.
4. Name the one signal source you will deprioritize.', N'The leads worked this week; the originating signal for each; the action taken; the response or lack of one.', N'A short read on which signal sources are working, and one prioritization change for next week.', N'SSP judges whether the pattern is real or coincidence given the sample size, and owns the decision to change prioritization.', N'Analysis and assessment', N'Lead follow-up improves only if you find out which signals were worth following.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-OPT-01-P-CSA-01', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'PH-CSA-VALUE-1-EXPL', 1, N'Build the optimization evidence base', N'Analyze enabled usage, cost and consumption evidence.', N'Featured', N'Prompt', N'For [Customer] and [period], summarize enabled usage, consumption and cost signals relevant to optimization. Identify material changes and patterns visible in the report and supporting metrics. Separate observations from recommendations and state missing architecture or business context.', NULL, N'Enabled certified report and scope.', N'Optimization evidence summary.', N'CSA confirms KPI meaning, architecture context, priorities and actionability.', N'Synthesis and drafting', N'Most of the effort in the optimization evidence base is assembly, and assembly is exactly what AI removes.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-OPT-01-P-CSA-02', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'PH-CSA-VALUE-1-EXPL', 2, N'Create the FinOps and optimization recommendation', N'Produce a bounded optimization recommendation.', N'Featured', N'Prompt', N'Using approved evidence, create an optimization recommendation for [Customer/workload]. Include current state, outcome, options, supported technical and financial effect, architecture tradeoffs, dependencies, risks, milestones and human-review requirements. Do not invent savings or intent.', NULL, N'Approved evidence; architecture context; outcome; constraints.', N'Optimization recommendation.', N'CSA validates architecture, feasibility, claims, relevance and ownership.', N'Synthesis and drafting', N'You spend your time editing the FinOps and optimization recommendation rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SE-ARCH-01-P-SE-01', N'WF-X-ARCH-01', N'SE-ARCH-1', N'PH-SE-ARCH-1-EXPL', 1, N'Compare architecture options against decision criteria', N'Investigate external technical patterns and authoritative evidence.', N'Featured', N'Prompt', N'Research [architecture decision] using current authoritative Microsoft and approved customer sources. Compare viable options against [decision criteria], identify assumptions, risks, dependencies and evidence gaps, and cite each material claim.', NULL, N'Architecture decision; decision criteria; approved sources.', N'Sourced architecture options assessment.', N'SE and architecture SMEs validate current guidance, applicability and unsupported assumptions.', N'Prioritization', N'Comparing architecture options and evidence surfaces the difference that actually changes the decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-SE-ARCH-01-P-SE-02', N'WF-X-ARCH-01', N'SE-ARCH-1', N'PH-SE-ARCH-1-EXPL', 2, N'Create the architecture decision record', N'Turn approved evidence into a concise decision artifact.', N'Featured', N'Prompt', N'Using the approved discovery brief and architecture evidence, create a decision record with customer outcome, options considered, criteria, selected direction, risks, dependencies, validation steps, unresolved questions and next technical action.', NULL, N'Approved discovery brief and architecture evidence.', N'Architecture decision record.', N'SE validates architecture, security, operations, feasibility and customer commitments.', N'Synthesis and drafting', N'You spend your time editing the architecture decision record rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SE-ASSET-01-P-SE-01', N'WF-X-ASSET-01', N'SE-ASSET', N'PH-SE-ASSET-EXPL', 1, N'Package a reusable technical asset with context', N'Convert successful work into a repeatable, governed asset.', N'Featured', N'Prompt', N'Using the approved [demo, script, architecture, response or checklist], create a reusable asset package with purpose, prerequisites, steps, editable parameters, validation checks, known limitations, owner and example use.', NULL, N'Approved technical asset.', N'Reusable asset package.', N'SE removes sensitive content, validates technical accuracy and confirms reuse permissions.', N'Synthesis and drafting', N'Reuse happens when the asset includes enough context for another SE to trust and adapt it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SE-ASSET-01-P-SE-02', N'WF-X-ASSET-01', N'SE-ASSET', N'PH-SE-ASSET-EXPL', 2, N'Create a technical Skill Blueprint for a repeatable SE workflow', N'Turn a repeatable workflow into a structured personalized skill.', N'Featured', N'Both', N'Create a reusable Skill Blueprint for [SE workflow]. Define trigger, inputs, trusted sources, ordered steps, expected output, rules, exclusions, exception behavior, human review, validation checks, and one representative test case. Do not publish until tested.', N'1. Choose the asset worth reusing.
2. Invoke the skill in Scout or Cowork.
3. Review the generated structure at the checkpoint.
4. Add the context a colleague would need.
5. Publish where the team will actually look.', N'SE workflow; trusted sources; test case.', N'Technical Skill Blueprint with validation checks and test case.', N'SE or skill owner tests representative work and validates access, outputs, safeguards, and repository placement before promotion.', N'Synthesis and drafting', N'A blueprint lets the team test repeatability before pretending the skill is production-ready.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'WF-SE-DEAL-01-P-SE-01', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 1, N'Inspect technical deal health and proof gaps', N'Use available MSX and customer context to identify technical progression gaps.', N'Featured', N'Prompt', N'Review [opportunity] and summarize the intended customer decision, current technical stage, exit criteria, proof completed, open blockers, recent technical engagement, missing roles and next recommended technical action. Show the source signal and flag unavailable context.', NULL, N'Opportunity and available customer context.', N'Technical deal-health brief.', N'SE validates MSX accuracy, customer context, technical risk and the next action.', N'Inspection and review', N'Technical deal health improves when blockers, proof gaps, and next decisions are visible in one place.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-SE-DEAL-01-P-SE-02', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 2, N'Create the technical risk and handoff plan', N'Synthesize approved deal, proof and delivery context into an action plan.', N'Featured', N'Prompt', N'Using approved sources, create a technical risk and handoff plan with blocker, impact, evidence, owner, mitigation, checkpoint, decision needed and delivery handoff requirements.', NULL, N'Approved deal, proof and delivery sources.', N'Technical risk register and handoff plan.', N'SE confirms ownership, feasibility, customer commitments and delivery readiness.', N'Synthesis and drafting', N'Risk plans help only when they assign the owner, evidence, mitigation, checkpoint, and next decision.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SE-DEMO-01-P-SE-01', N'WF-X-ARCH-01', N'SE-ARCH-2', N'PH-SE-ARCH-2-EXPL', 1, N'Build the decision-centered demo or workshop plan', N'Create a bounded multi-part experience package.', N'Featured', N'Prompt', N'Create a demo or workshop package for [customer decision]. Include audience, scenario, decision criteria, agenda, demo flow, sample data needs, roles, likely objections, tenant or permission dependencies, fallback plan and explicit next decision.', NULL, N'Customer decision; audience; approved scenario.', N'Demo or workshop package.', N'SE validates the environment, permissions, technical behavior, evidence and customer appropriateness.', N'Synthesis and drafting', N'A decision-centered plan keeps the demo or workshop from becoming a feature tour.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SE-DEMO-01-P-SE-02', N'WF-X-ARCH-01', N'SE-ARCH-2', N'PH-SE-ARCH-2-EXPL', 2, N'Research supporting proof, limitations, and objections', N'Find authoritative evidence supporting the selected scenario.', N'Featured', N'Prompt', N'Find current authoritative evidence for [scenario or capability]. Return only claims relevant to the customer decision, likely objections, known limitations and SME-needed flags. Cite sources.', NULL, N'Scenario or capability; approved sources.', N'Evidence and objection brief.', N'SE validates freshness and applicability before customer use.', N'Analysis and assessment', N'Authoritative proof and known limitations are what make the demo safe to use in a customer decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-SE-DISC-01-P-SE-01', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 1, N'Build the technical discovery and decision-criteria brief', N'Synthesize approved customer and technical context into a brief that names the customer decision, constraints, evidence gaps, and criteria.', N'Featured', N'Prompt', N'Using the selected approved customer and technical sources, prepare for [meeting]. Summarize known outcomes, decisions, constraints, architecture context, open technical questions and missing evidence. Propose five discovery questions that advance the technical decision. Separate sourced facts from hypotheses.', NULL, N'Selected approved customer and technical sources.', N'Technical discovery brief with questions and evidence gaps.', N'SE validates the sources, technical context and whether each question is appropriate.', N'Synthesis and drafting', N'Discovery becomes useful when it produces decision criteria the customer and team can inspect.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SE-DISC-01-P-SE-02', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 2, N'Rehearse the technical discovery conversation', N'Practice questions, listening, objections and the intended next decision.', N'Featured', N'Prompt', N'Role-play [customer or stakeholder] for the upcoming technical discovery conversation. Use the approved brief only. Simulate realistic questions and objections, coach clarity and listening, and identify statements requiring technical or customer validation. Do not invent customer facts.', NULL, N'Approved discovery brief.', N'Role-play, coaching observations and improvement actions.', N'SE verifies facts, claims and commitments and decides what to change.', N'Conversation preparation', N'Practicing discovery questions reduces the chance that the real meeting ends with ambiguity instead of criteria.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-SE-POC-01-P-SE-01', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 1, N'Scope the smallest useful PoC', N'Build the PoC work package.', N'Featured', N'Prompt', N'Create a PoC plan for [technical decision]. Define hypothesis, in-scope scenario, success and exit criteria, milestones, data and environment needs, roles, risks, dependencies, review gates, final decision and handoff if successful.', NULL, N'Technical decision; constraints; resources.', N'PoC plan and decision gates.', N'SE confirms scope, resources, security, feasibility and that the PoC is necessary.', N'Scoping and design', N'A small, criteria-led PoC reduces waste and makes the exit decision clear before work starts.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SE-POC-01-P-SE-02', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 2, N'Pressure-test PoC readiness', N'Review a proposed PoC plan for gaps and ambiguity.', N'Featured', N'Prompt', N'Review this PoC plan. Identify vague success criteria, unowned dependencies, unrealistic milestones, missing security or data assumptions, weak linkage to the customer decision and unclear exit paths. Return five review questions and the smallest revisions needed.', NULL, N'Proposed PoC plan.', N'Readiness review and revision list.', N'SE owns the go or no-go decision and confirms all required reviewers.', N'Assumption testing', N'Readiness issues should be found in planning, not after the customer expects a proof.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SE-QA-01-P-SE-01', N'WF-X-CONV-01', N'SE-CONV', N'PH-SE-CONV-EXPL', 1, N'Draft the sourced technical answer matrix', N'Answer technical questions with sources, confidence, assumptions, exceptions, and reviewer flags.', N'Featured', N'Prompt', N'Answer the selected technical questions using approved and authoritative sources. For each item provide a grounded answer, source citation, confidence, assumptions and SME-needed flag. Preserve the question order and do not hide unsupported areas.', NULL, N'Selected technical questions; approved sources.', N'Grounded technical answer matrix.', N'SE and relevant SMEs approve technical, security, legal and product claims.', N'Synthesis and drafting', N'A technical answer is safer when confidence, assumptions, and reviewer needs are visible.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-SE-QA-01-P-SE-02', N'WF-X-CONV-01', N'SE-CONV', N'PH-SE-CONV-EXPL', 2, N'Assemble the governed technical response package', N'Produce reviewed answers in the required structure and coordinate gaps.', N'Featured', N'Prompt', N'Using the approved answer matrix, assemble the response in the requested format. Create an exception list for unanswered items, assign suggested reviewers and provide a final quality checklist. Do not submit or send.', NULL, N'Approved answer matrix; required format.', N'Formatted response plus exception list.', N'SE validates completeness and obtains required approvals before distribution.', N'Synthesis and drafting', N'Governance is what keeps fast response work from becoming unsupported customer guidance.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SOLUTION-01-P-SSP-01', N'WF-X-PLAN-01', N'SSP-PLAN', N'PH-SSP-PLAN-EXPL', 1, N'Build the solution-selling plan', N'Shape a solution-specific plan to advance the next customer decision.', N'Featured', N'Prompt', N'Build a solution-selling plan for [solution play] at [account]. Include customer outcomes, maturity, solution vision, stakeholder coverage, value conversation arc, demo or workshop sequence, proof needs, risks, and a 30-day plan to clear the next decision. Flag missing stakeholders and unsupported claims.', NULL, N'Account; solution play; current stage; known stakeholders; approved evidence.', N'Solution-selling plan with decisions, proof needs, owners, and progression actions.', N'SSP validates customer need, stage, solution fit, evidence, stakeholders, and commitments.', N'Synthesis and drafting', N'Most of the solution-selling plan is assembly; the SSP should spend judgment on the pursuit decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-SOLUTION-01-P-SSP-02', N'WF-X-PLAN-01', N'SSP-PLAN', N'PH-SSP-PLAN-EXPL', 2, N'Pressure-test the solution strategy', N'Test the plan against customer priorities, competitive alternatives, stakeholders, and decision criteria.', N'Featured', N'Prompt', N'Review this solution-selling plan against customer priorities, competitive alternatives, stakeholder coverage, proof needs, technical and commercial dependencies, and decision criteria. Return risks, gaps, missing evidence, and the next decisions needed.', NULL, N'Draft solution-selling plan; customer context; stakeholder map; proof and constraints.', N'Pressure-tested strategy with risks, gaps, and next decisions.', N'SSP confirms source accuracy, customer context, role ownership, technical/commercial dependencies, and any system action before use.', N'Assumption testing', N'If the solution strategy will fail, it should fail in review before it fails with the customer.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-SOLUTION-01-P-SSP-03', N'WF-X-PLAN-01', N'SSP-PLAN', N'PH-SSP-PLAN-EXPL', 3, N'Map who actually decides and who is missing', N'Build the real decision map for this solution play, including the people who can stop it, not only the people who like it.', N'Extended', N'Both', N'Here is my solution-selling plan and the stakeholders I have engaged: [paste plan and stakeholder list with roles and engagement level]. The solution play is [paste], the decision type is [paste, for example new workload, renewal, or migration], the customer''s organizational model is [paste, for example centralized IT, business-unit autonomy, or shared services], and their known procurement and technical governance constraints are [paste]. Build a decision map showing who decides, who influences, who implements, and who can block. For each person, state what they need to believe for this to move forward and what evidence would convince them. Then identify missing roles ONLY where the solution play, decision type, organizational model, or governance constraints I gave you imply that role is required. Do not list generic enterprise buying-committee roles. Do not invent names; describe missing roles by function. If my context is too thin to identify missing roles, say so rather than guessing.', N'1. List stakeholders engaged so far with role and engagement level.
2. Gather the solution play, decision type, customer organizational model, and governance constraints.
3. Run the prompt.
4. Identify the highest-risk absence.
5. Decide who introduces you to that person and by when.', N'Solution-selling plan; stakeholders engaged with roles; the solution play and decision type; the customer''s organizational model; known procurement and technical governance constraints; who owns the customer relationship.', N'A decision map with what each stakeholder needs to believe, plus a named list of missing roles and the risk each creates.', N'SSP validates the stakeholder reality against what the account team actually knows, and owns the plan to reach anyone missing.', N'Analysis and assessment', N'Solution plans usually fail on a person nobody engaged, not on a fact nobody knew.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SOLUTION-01-P-SSP-04', N'WF-X-PLAN-01', N'SSP-PLAN', N'PH-SSP-PLAN-EXPL', 4, N'Convert the plan into dated commitments', N'Reduce the plan to the few actions that will actually happen in the next 30 days, each with a named owner and a date.', N'Extended', N'Both', N'From this solution-selling plan [paste], extract only the actions that must happen in the next 30 days to clear the next customer decision. For each: what it is, who owns it by role, the date it must be done by, and what it unblocks. Limit to five actions. If the plan implies more than five critical actions in 30 days, tell me which ones are not realistic and what to cut. Do not assign an action to a person or team I have not named.', N'1. Bring the pressure-tested plan.
2. Run the prompt.
3. Cut to five or fewer.
4. Confirm each owner has agreed.
5. Record the dates where the account team will see them.', N'The pressure-tested solution-selling plan; the account team and their availability; the next customer decision and its timing.', N'Five or fewer dated actions with named owners and what each unblocks.', N'SSP confirms each owner has actually agreed to the action and the date, rather than being assigned it in a document.', N'Planning and drafting', N'A plan without dates and owners is a description of intentions.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-TECH-CONV-01-P-CSA-01', N'WF-X-CONV-01', N'CSA-CONV', N'PH-CSA-CONV-EXPL', 1, N'Prepare the technical advisory conversation', N'Turn approved evidence into a customer-centered plan.', N'Featured', N'Prompt', N'Using approved customer context and technical decision package, prepare for [meeting]. Include outcome, technical state, recommendation and tradeoffs, questions, supporting evidence, likely objections, caveats, next action and ownership. Flag claims requiring review.', NULL, N'Approved context; technical package; desired decision.', N'Technical advisory conversation plan.', N'CSA validates claims, tradeoffs, context, commitments and follow-through.', N'Conversation preparation', N'Preparation for the technical advisory conversation is the step most often skipped and most often decisive.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-TECH-CONV-01-P-CSA-02', N'WF-X-CONV-01', N'CSA-CONV', N'PH-CSA-CONV-EXPL', 2, N'Rehearse the architecture recommendation', N'Role-play and coach a technical advisory conversation.', N'Featured', N'Prompt', N'Use the approved conversation plan to role-play with [customer/stakeholder]. Simulate realistic architecture, readiness, security, operational, cost and implementation questions. Coach clarity, evidence, listening, tradeoffs and next step. Identify claims needing SME review. Do not invent customer facts or commitments.', NULL, N'Approved conversation plan and audience.', N'Role-play transcript and improvement actions.', N'CSA validates facts, guidance, claims and commitments.', N'Conversation preparation', N'Ten minutes rehearsing the architecture recommendation is cheaper than improvising it in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-VALUE-01-P-SSP-01', N'WF-X-VALUE-01', N'SSP-VALUE', N'PH-SSP-VALUE-EXPL', 1, N'Tailor the solution value narrative', N'Translate the solution into customer-specific outcomes, evidence, caveats, and next ask.', N'Featured', N'Prompt', N'Using selected approved sources, build a customer-specific value narrative for [solution play] at [account]. Include top use cases, measurable or directional outcomes, proof points, differentiation, assumptions, caveats, executive talking points, and the next ask. Flag unsupported value claims.', NULL, N'Approved customer priorities, solution evidence, value frameworks, and target audience.', N'Customer-specific value narrative with evidence and review flags.', N'SSP validates value claims, proof, ROI or adoption assumptions, tone, and final ask before customer use.', N'Value translation', N'Generic value decks lose to specific narratives grounded in customer priorities.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VALUE-01-P-SSP-02', N'WF-X-VALUE-01', N'SSP-VALUE', N'PH-SSP-VALUE-EXPL', 2, N'Research evidence for the value story', N'Investigate customer, industry, use-case, and market evidence that strengthens or challenges the value story.', N'Featured', N'Prompt', N'Research [customer/industry/use case] to identify relevant market evidence, customer signals, comparable proof, risks, and counterevidence for [solution play]. Separate sourced facts from recommendations and flag unsupported value or competitor claims.', NULL, N'Customer; industry; use case; solution play; approved source boundaries.', N'Evidence brief for the value narrative.', N'SSP validates source quality, applicability to the customer, and all value or competitor claims.', N'Analysis and assessment', N'Being able to cite value evidence beats remembering a generic claim.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-VALUE-01-P-SSP-03', N'WF-X-VALUE-01', N'SSP-VALUE', N'PH-SSP-VALUE-EXPL', 3, N'Stress-test the assumptions the value claims depend on', N'Expose what each outcome number quietly assumes, and record which assumptions the customer would have to accept.', N'Extended', N'Both', N'Here is our value narrative and the evidence brief behind it: [paste both]. For every outcome claim, produce a row containing: the claim, the assumption it depends on, who has to accept that assumption for the claim to hold, the evidence we currently have, and what happens to the claim if adoption is half as fast as projected. Rank the rows by how much the claim collapses when its assumption fails. Do not add claims that are not in my narrative, and do not supply evidence I have not given you.', N'1. Bring the value narrative and evidence brief.
2. Run the prompt.
3. Find the claim that collapses hardest.
4. Either find proof for its assumption or remove the claim.
5. Bring the assumption table to the huddle.', N'The value narrative; the evidence brief; the customer''s financial context; adoption expectations already discussed with them.', N'An assumption and risk table ranked by how much each claim depends on an unproven assumption.', N'SSP decides which assumptions are defensible with this customer, and owns every outcome figure before it reaches them.', N'Practice and rehearsal', N'The value claim you cannot defend is the one the customer will ask about.', N'https://m365.cloud.microsoft/chat', N'Open Analyst'),
        (N'WF-VALUE-01-P-SSP-04', N'WF-X-VALUE-01', N'SSP-VALUE', N'PH-SSP-VALUE-EXPL', 4, N'Reduce the narrative to something the customer can forward', N'Produce the short version your champion can send to people you will never meet, without you in the room to explain it.', N'Extended', N'Both', N'Reduce this value narrative [paste] to a single page that our champion could forward internally without us present. It must stand alone: state the business problem in the customer''s own terms, the outcome, what it depends on, and what we are asking for next. Remove anything that only makes sense if a seller is explaining it. Remove any claim that is not supported by the evidence brief I gave you. Keep it under 350 words.', N'1. Bring the rehearsed narrative with weak claims removed.
2. Run the prompt.
3. Read it as if you were a stranger receiving it.
4. Cut anything that needs explaining.
5. Confirm the ask is specific.', N'The rehearsed value narrative; the evidence brief; who the champion is and who they would forward it to; the next ask.', N'A one-page, forwardable value summary with a specific next ask.', N'SSP verifies every claim survives without a seller present, and approves the wording before the champion receives it.', N'Value translation', N'Most internal customer decisions happen in rooms the seller is not in.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VALUE-TECH-01-P-CSA-01', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 1, N'Create the technical progress and value narrative', N'Synthesize approved technical evidence.', N'Featured', N'Prompt', N'Using approved architecture, delivery, adoption, consumption, optimization and risk materials for [Customer], create the CSA contribution to the business review. Connect progress to supported outcomes, explain risks and decisions, identify commitments and owners, and propose next technical actions. Separate evidence from interpretation and flag unsupported value claims.', NULL, N'Approved review sources; audience; period.', N'Technical progress and value narrative.', N'CSA validates technical and value claims, linkage, commitments and ownership.', N'Synthesis and drafting', N'You spend your time editing the technical progress and value narrative rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VALUE-TECH-01-P-CSA-02', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 2, N'Assemble the technical review package', N'Create a repeatable customer-review package.', N'Featured', N'Prompt', N'Assemble a technical customer-review package from approved sources: executive technical summary, architecture and delivery progress, consumption or adoption evidence, optimization actions, material risks, open decisions, commitments and follow-through tracker. Preserve source links and flag missing or contradictory evidence.', NULL, N'Approved source package and reviewers.', N'Structured technical-review package.', N'CSA reviews with relevant account, success, technical and commercial contributors.', N'Synthesis and drafting', N'Most of the effort in the technical review package is assembly, and assembly is exactly what AI removes.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-VTEAM-01-P-SSP-01', N'WF-X-ORCH-01', N'SSP-ORCH', N'PH-SSP-ORCH-EXPL', 1, N'Build the specialist, technical, partner, and funding plan', N'Clarify role coverage, dependencies, asks, owners, partner/funding needs, and decision checkpoints.', N'Featured', N'Prompt', N'Create a pursuit orchestration plan for [opportunity] with customer outcome, solution scope, required specialist and technical roles, partner need, funding consideration, dependencies, owner for each action, decision checkpoints, and unresolved risks. Do not represent funding as approved.', NULL, N'Approved opportunity, customer context, roles, partner criteria, funding context, and constraints.', N'Pursuit orchestration plan with owners and checkpoints.', N'SSP validates role need, ownership, partner or funding involvement, and commitments.', N'Coordination and handoff', N'Pursuits stall when handoffs, partner asks, or funding dependencies are assumed rather than owned.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VTEAM-01-P-SSP-03', N'WF-X-ORCH-01', N'SSP-ORCH', N'PH-SSP-ORCH-EXPL', 3, N'Make each ask specific enough to be accepted', N'Turn a role requirement into an ask a busy colleague can say yes to without a meeting to clarify it.', N'Extended', N'Both', N'From this pursuit orchestration plan [paste], write the individual ask for each role involved. Each ask must state: what specifically is needed, why this pursuit needs that role rather than someone else, what the person receives from me to make it easy, the date it is needed by, and how long it should take. Keep each ask under 80 words. Do not represent funding, approvals, or customer commitments as secured if the plan does not show them as secured.', N'1. Bring the orchestration plan.
2. Run the prompt.
3. Check each ask states a realistic time commitment.
4. Send the asks.
5. Record who accepted.', N'The pursuit orchestration plan; the roles required; what you can supply to each; the customer timeline.', N'One short, specific, dated ask per role, ready to send.', N'SSP verifies that no ask overstates funding, approval, or customer commitment status, and owns what is promised in return.', N'Coordination and handoff', N'A vague ask gets a polite yes and no calendar time.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VTEAM-01-P-SSP-04', N'WF-X-ORCH-01', N'SSP-ORCH', N'PH-SSP-ORCH-EXPL', 4, N'Catch the checkpoint that quietly slipped', N'Compare the plan against what has actually happened and surface the dependency nobody has mentioned in two weeks.', N'Extended', N'Both', N'Here is the pursuit orchestration plan with its checkpoints and owners [paste], and here is what has actually happened since [paste updates, meeting notes, or status]. Identify every checkpoint that has passed without evidence of completion, every dependency that has gone quiet, and every owner who has not confirmed. Rank by impact on the customer timeline. For the top item, draft the one message that would restart it. Do not assume something is complete because it was not mentioned.', N'1. Bring the plan and recent activity. If the plan has no dated checkpoints or owners recorded, spend five minutes writing them down first; the activity does not work without them.
2. Run the prompt.
3. Confirm which items are genuinely stalled.
4. Send the restart message for the top one.
5. Reset the checkpoint date.', N'The orchestration plan with checkpoints and owners, written down even if only informally; recent updates, notes, or status; the customer timeline. If checkpoints and owners do not exist yet, create them before running this activity.', N'A ranked list of stalled checkpoints and quiet dependencies, plus one message to restart the highest-impact item.', N'SSP confirms an item is genuinely stalled rather than simply undocumented before escalating to an owner.', N'Inspection and review', N'Pursuits rarely stop. They go quiet, and quiet looks like progress until the date arrives.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'WF-X-ARCH-01-P-ATS-STRAT01', N'WF-X-ARCH-01', N'ATS-TECH', N'PH-ATS-TECH-EXPL', 1, N'Analyze consumption and technical blockers', N'Connect customer and sales context to technical trajectory.', N'Featured', N'Prompt', N'Show consumption versus target for [Account], flag blockers, and recommend architecture, partner, or specialist actions that could improve the technical trajectory. Distinguish source facts from recommendations.', NULL, N'Account; target period; available MSX and customer context.', N'Consumption gap and blocker view with candidate actions.', N'ATS validates consumption interpretation, architecture actions, partner need, and customer context.', N'Inspection and review', N'The technical trajectory should respond to the blockers that are actually slowing value.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-ARCH-01-P-ATS-STRAT02', N'WF-X-ARCH-01', N'ATS-TECH', N'PH-ATS-TECH-EXPL', 2, N'Research technical options and bets', N'Compare technical options and evidence before setting trajectory.', N'Featured', N'Prompt', N'Analyze the main pipeline and consumption drivers for [Account] and recommend the top three technical bets. For each include business outcome, stakeholder, security posture, AI workload readiness, adoption blocker, first conversation, and validation gap. Separate sourced evidence from recommendations.', NULL, N'Account strategy; pipeline or consumption context; authorized sources.', N'Three evidence-backed technical bets with validation gaps.', N'ATS validates evidence, feasibility, strategic fit, and recommended priority.', N'Option analysis', N'Technical bets should be chosen on evidence, not novelty.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-X-ARCH-01-P-ATS-STRAT03', N'WF-X-ARCH-01', N'ATS-TECH', N'PH-ATS-TECH-EXPL', 3, N'Delegate the technical strategy package', N'Build a bounded strategy and validation package.', N'Featured', N'Prompt', N'Using the approved account context, technical bets, and source materials, create a technical strategy package with objectives, current estate, decision criteria, priority bets, proof needs, owners, milestones, risks, and open technical decisions.', NULL, N'Approved account context, technical evidence, and constraints.', N'Technical strategy package with decisions, owners, proof needs, and milestones.', N'ATS validates strategy, architecture, ownership, milestones, and customer relevance.', N'Strategy packaging', N'You should spend time editing the strategy, not staring at a blank version of it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-ARCH-01-P-CSA-01', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 3, N'Build the technical decision path', N'Connect approved account and customer context to the technical decision.', N'Featured', N'Prompt', N'For [Customer/opportunity], summarize outcome, current technical decision, stakeholders, recent interactions available, blockers, commitments and opportunity stage. Propose a decision path with evidence required, gaps, owners, milestones and next customer-facing action. Show source signals and flag unavailable context.', NULL, N'Authorized scope and approved technical context.', N'Grounded technical decision path.', N'CSA validates customer context, technical accuracy, owners, relevance and commitments.', N'Synthesis and drafting', N'Most of the effort in the technical decision path is assembly, and assembly is exactly what AI removes.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-ARCH-01-P-CSA-02', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 4, N'Design the validation and proof plan', N'Create a bounded validation plan.', N'Featured', N'Prompt', N'Using the approved technical decision brief, build the smallest useful validation plan for [decision]. Include criteria, hypothesis, evidence available, proof gaps, activities, success measures, exit criteria, owners, milestones, dependencies, risks and expected decision. Do not expand beyond what is necessary.', NULL, N'Approved decision brief; owner; constraints; evidence.', N'Validation plan.', N'CSA confirms scope, feasibility, criteria, evidence quality and ownership.', N'Scoping and design', N'Settling the validation and proof plan before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-CONV-01-P-ATS-01', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 1, N'Design the executive briefing experience', N'Plan an end-to-end executive briefing experience.', N'Featured', N'Prompt', N'Help me organize an EBC for [Customer]. Choose the right session design and propose a coherent timeline and prep plan. Include desired customer decisions, executive audience, participants, evidence, role contributions, preparation milestones, risks, and follow-through.', NULL, N'Customer; executive audience; desired decisions; approved context.', N'EBC plan with session design, participants, evidence, timeline, and follow-through.', N'ATS validates purpose, participants, technical narrative, evidence, and customer decision.', N'Experience design', N'An EBC only works if the decision, people, evidence, and follow-through line up.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-CONV-01-P-ATS-02', N'WF-X-CONV-01', N'ATS-TALK', N'PH-ATS-TALK-EXPL', 2, N'Adjust the talk track from current signals', N'Adapt approved technical messaging using selected work context.', N'Featured', N'Prompt', N'Using the approved account brief, recent meetings, email, and technical source materials, identify the customer signals that should change the technical talk track. Draft revised opening language, five questions, likely objections, and responses. Separate sourced facts from recommendations.', NULL, N'Selected authorized work sources and approved technical narrative.', N'Revised technical talk track grounded in selected signals.', N'ATS validates signal interpretation, technical accuracy, customer relevance, and claims.', N'Message adaptation', N'The talk track should change when the customer signal changes.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-CONV-01-P-ATS-03', N'WF-X-CONV-01', N'ATS-NARR', N'PH-ATS-NARR-EXPL', 3, N'Translate architecture into business value', N'Create a concise business-value summary from approved architecture content.', N'Featured', N'Prompt', N'Turn this reference architecture into a one-page business value summary. Map technical choices to customer priorities, expected business outcomes, Azure consumption implications, risks, and assumptions requiring review. Quantify only when the source supports it.', NULL, N'Approved reference architecture and supporting evidence.', N'One-page technical-to-value summary with review flags.', N'ATS validates ROI, consumption impact, technical accuracy, and evidence.', N'Technical-to-value translation', N'Architecture matters more when the customer can see the business consequence.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-X-CONV-01-P-ATS-EBC-02', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 2, N'Build the run-of-show and evidence pack', N'Turn the approved briefing plan into the run-of-show the session is actually delivered from.', N'Featured', N'Prompt', N'Using the approved EBC plan, build the run-of-show: each segment in order with its time allocation, the person leading it, the evidence or demonstration used, the questions put to the customer, and the decision the session closes on. Assume the plan, participants and objectives are already agreed.', NULL, N'Approved EBC plan, confirmed participant list, and approved evidence.', N'Run-of-show with segment order, timing, owners, evidence, customer questions, and the closing decision.', N'ATS confirms every piece of evidence is approved for customer use and that each segment owner has agreed to their part.', N'Synthesis and drafting', N'The plan says why the briefing exists. The run-of-show is what the room is actually delivered from.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-CONV-01-P-ATS-JAI', N'WF-X-CONV-01', N'ATS-TALK', N'PH-ATS-TALK-EXPL', 1, N'Rehearse the strategic technical talk track', N'Practice the technical conversation and receive coaching.', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the upcoming strategic technical conversation with [customer or stakeholder]. Use the approved narrative and focus on technical outcomes, open decisions, likely objections, evidence, and the technical ask. Pause for my response before coaching me on clarity, listening, evidence, and next step. Do not invent customer facts or commitments.', NULL, N'Approved narrative; meeting type; customer context; desired decision.', N'Interactive rehearsal, likely questions or objections, coaching, and improvement actions.', N'ATS validates customer facts, technical claims, commitments, evidence, and any response used with the customer.', N'Conversation rehearsal', N'Ten minutes rehearsing the talk track is cheaper than improvising it in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-X-CONV-01-P-ATS-NARR-01', N'WF-X-CONV-01', N'ATS-NARR', N'PH-ATS-NARR-EXPL', 1, N'Prepare the CxO technical briefing', N'Build an account-grounded executive technical briefing.', N'Featured', N'Prompt', N'Prepare a CxO technical briefing for [Account] on [Topic]. Include customer outcomes, architecture direction, risks, proof points, executive talking points, likely questions, and the technical ask. Cite source signals where available and flag unsupported claims.', NULL, N'Account; topic; desired decision; available MSX and customer context.', N'CxO technical briefing with risks, proof points, talking points, and ask.', N'ATS validates architecture, risk, proof, customer context, and technical ask.', N'Executive technical synthesis', N'The executive technical narrative needs enough evidence to be credible and enough focus to drive a decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-CONV-01-P-ATS-NARR-02', N'WF-X-CONV-01', N'ATS-NARR', N'PH-ATS-NARR-EXPL', 2, N'Build the executive technical deck', N'Create a bounded executive-ready presentation package.', N'Featured', N'Prompt', N'Build a concise executive technical deck for [Account] aligned to stated outcomes and the Azure or AI roadmap. Include the story arc, proof, architecture implications, risks, open technical decisions, and review flags.', NULL, N'Approved emails, transcripts, roadmap, and source materials.', N'Executive technical deck with open decisions flagged.', N'ATS reviews all claims, roadmap statements, evidence, and participant-facing content.', N'Artifact creation', N'Deck creation should be assembly work; judgment stays in the story, claims, and ask.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-HEALTH-01-P-CSA-01', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 1, N'Build a technical health evidence brief', N'Synthesize approved technical context.', N'Featured', N'Prompt', N'Using approved sources for [Customer], build a technical health brief. Separate verified evidence from assumptions. Summarize architecture and delivery state, material technical risks, optimization opportunities, open commitments, dependencies and missing evidence. End with the three issues that most deserve CSA attention and why.', NULL, N'Approved customer technical sources; review period; customer outcome.', N'Technical health brief.', N'CSA validates architecture, delivery, support, usage interpretation, priorities and commitments.', N'Synthesis and drafting', N'Most of the effort in a technical health evidence brief is assembly, and assembly is exactly what AI removes.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-X-HEALTH-01-P-CSA-02', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 2, N'Prioritize a technical risk response', N'Analyze enabled certified data relevant to technical health.', N'Featured', N'Prompt', N'For [Customer] and [period], identify the most material enabled consumption, usage or adoption changes visible in this report. Show supporting metrics, distinguish evidence from interpretation, state what the report cannot answer, and suggest which signals warrant deeper technical review. Do not assign a health score or infer customer intent.', NULL, N'Enabled certified report; customer; period.', N'Evidence-backed signals and technical-review priorities.', N'CSA confirms report, filters, KPI meaning, technical significance and action.', N'Prioritization', N'Deciding a technical risk response is really deciding what you will not do. Say it out loud.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-X-ORCH-01-P-ATS-01', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 1, N'Create the technical V-team alignment brief', N'Align technical roles, dependencies, priorities, and owners.', N'Featured', N'Prompt', N'Using the approved account and technical context, create a V-team alignment brief with customer outcome, priority workloads, technical decisions, risks, required roles, dependencies, owner for each action, and next checkpoint. Flag unsupported assumptions.', NULL, N'Approved account and technical context; role list; decision needs.', N'Technical V-team alignment brief with owners and checkpoints.', N'ATS validates role need, ownership, dependencies, risk, and customer relevance.', N'Orchestration', N'Most work stalls in the handoff, not the task.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-X-ORCH-01-P-ATS-ECIF02', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 3, N'Assess ECIF investment opportunities', N'Identify whether ECIF funding could accelerate technical outcomes.', N'Featured', N'Prompt', N'Review Opportunity ID [ID]. Using the customer architecture roadmap, consumption goals, and current deployment blockers: identify where ECIF funding could accelerate time-to-value, recommend relevant funding motions, explain expected customer outcome and directional consumption impact, and highlight risks, dependencies, or reasons ECIF may not be appropriate.', NULL, N'Opportunity ID; architecture roadmap; consumption goals; deployment blockers.', N'Prioritized ECIF funding opportunities with outcomes, impact, risks, and dependencies.', N'ATS and ECIF owner validate eligibility, funding motion, technical feasibility, consumption assumptions, dependencies, and recommendation before action.', N'Investment signal review', N'Investment belongs in the v-team discussion when it removes a blocker to the technical strategy.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-ORCH-01-P-ATS-ECIF03', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 4, N'Monitor ECIF investment performance', N'Evaluate milestone progress, deployment readiness, and consumption path.', N'Extended', N'Prompt', N'Analyze the proposed ECIF-funded engagement for Opportunity ID [ID]. Evaluate scope, milestones, deliverables, technical outcomes, Azure consumption goals, deployment path, risks, dependencies, and priority fixes. Provide a readiness assessment and name the decision owner.', NULL, N'Opportunity ID; proposed engagement; scope; milestones; deliverables; technical outcomes; consumption goals.', N'Engagement-quality assessment, gaps and risks, consumption-readiness assessment, and priority fixes.', N'ATS and ECIF owner validate scope quality, feasibility, consumption path, partner and customer readiness, compliance dependencies, and final funding decision.', N'Investment performance review', N'Realization is judged on evidence someone collected or did not collect.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-PLAN-01-P-ATS-01', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'PH-ATS-WORKLOAD-EXPL', 1, N'Prioritize AI and Azure workloads', N'Convert enabled business insights into a workload action list.', N'Featured', N'Prompt', N'Turn this week’s business and technical signals into a prioritized AI and Azure workload action list. For each workload include readiness, potential impact, ACR or consumption upside if supported, blockers, owner, due date, and validation gap.', NULL, N'Enabled Proactive Insights, MSXI data, account context, and candidate workload list.', N'Prioritized workload action list with rationale, owner, and date.', N'ATS validates readiness, feasibility, upside interpretation, owner, and priority.', N'Prioritization', N'This converts workload interest into a decision list with owners.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-PLAN-01-P-ATS-02', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'PH-ATS-WORKLOAD-EXPL', 2, N'Research workload readiness evidence', N'Investigate technical and external evidence before prioritization.', N'Featured', N'Prompt', N'Investigate [candidate workloads] for [Account]. Compare customer objectives, current estate, security posture, AI readiness, dependencies, adoption blockers, relevant external evidence, and validation gaps. Separate sourced facts from recommendations.', NULL, N'Account context; candidate workloads; authorized internal and public sources.', N'Evidence brief supporting workload prioritization.', N'ATS validates source quality, relevance, architecture implications, and recommendation.', N'Evidence gathering', N'Research is useful when it exposes why a workload is ready, blocked, or not worth chasing yet.', N'https://msxi.microsoft.com/', N'Open MSX Insights'),
        (N'WF-X-PLAN-01-P-ATS-03', N'WF-X-PLAN-01', N'ATS-INTEL', N'PH-ATS-INTEL-EXPL', 3, N'Create the technical risk register', N'Organize technical risks using available account and business data.', N'Featured', N'Prompt', N'Build a weekly technical risk register for my account scope. Include affected accounts, opportunities, workload, MCEM stage, signal source, risk, likely impact, mitigation owner, and 14-day action. Flag unavailable context.', NULL, N'Enabled MSXI or sales data; ATS account scope.', N'Technical risk register with owner and action horizon.', N'ATS validates risk significance, technical context, owner, and mitigation.', N'Risk inspection', N'Unnamed technical risk does not get owned.', N'https://msxi.microsoft.com/', N'Open MSX Insights'),
        (N'WF-X-PLAN-01-P-ATS-INTEL-01', N'WF-X-PLAN-01', N'ATS-INTEL', N'PH-ATS-INTEL-EXPL', 1, N'Build the account intelligence brief', N'Combine work and public context into a meeting-prep brief.', N'Featured', N'Prompt', N'Act as my account intelligence analyst for [Account]. Build a meeting prep brief that summarizes business priorities, current technical strategy, stakeholder context, relevant KPIs, AI and Azure workload signals, open risks, recent customer commitments, and the top actions I should consider. Separate sourced facts from hypotheses and flag missing context.', NULL, N'Account; authorized email, Teams, calendar, files, CRM or sales context, and approved public context.', N'Account intelligence and meeting-prep brief with risks, priorities, and actions.', N'ATS validates current account context, stakeholder interpretation, technical risk, and customer relevance.', N'Synthesis and drafting', N'Account intelligence is useful when it changes the next technical decision, not when it creates a longer dossier.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-PLAN-01-P-ATS-INTEL-02', N'WF-X-PLAN-01', N'ATS-INTEL', N'PH-ATS-INTEL-EXPL', 2, N'Explain the KPI and locate the report', N'Clarify the certified KPI or report behind the business signal.', N'Featured', N'Prompt', N'How is [KPI] calculated? Link me to the relevant report and explain the methodology, filters, and limits I should understand before using it in account technology planning.', NULL, N'Enabled MSXI report or metric context.', N'KPI definition, methodology, relevant report, and caveats.', N'ATS confirms that the KPI, scope, and report match the business question.', N'Certified-data interpretation', N'If the signal is misunderstood, every technical priority built on it is suspect.', N'https://msxi.microsoft.com/', N'Open MSX Insights')
    ) v([ExternalId], [TopicExternalId], [PlacementExternalId], [PhaseExternalId], [DisplayOrder], [Name], [Description], [PracticeTier], [ExecutionMethod], [Prompt], [ActivitySteps], [RequiredContext], [ExpectedOutput], [HumanCheckpoint], [BestFitJob], [WhyThisMatters], [LaunchUrl], [LaunchLabel])
), src AS (
    SELECT raw.*, t.Id AS [HuddleTopicId], p.Id AS [HuddlePlacementId], ph.Id AS [HuddlePhaseId]
    FROM raw
    INNER JOIN dbo.HuddleTopics AS t ON t.[ExternalId] = raw.[TopicExternalId]
    INNER JOIN dbo.HuddlePlacements AS p ON p.[ExternalId] = raw.[PlacementExternalId]
    INNER JOIN dbo.HuddlePhases AS ph ON ph.[ExternalId] = raw.[PhaseExternalId]
)
MERGE dbo.HuddleActivities AS tgt
USING src ON tgt.[ExternalId] = src.[ExternalId]
WHEN MATCHED THEN UPDATE SET
        tgt.[HuddleTopicId] = src.[HuddleTopicId],
        tgt.[HuddlePlacementId] = src.[HuddlePlacementId],
        tgt.[HuddlePhaseId] = src.[HuddlePhaseId],
        tgt.[DisplayOrder] = src.[DisplayOrder],
        tgt.[Name] = src.[Name],
        tgt.[Description] = src.[Description],
        tgt.[PracticeTier] = src.[PracticeTier],
        tgt.[ExecutionMethod] = src.[ExecutionMethod],
        tgt.[Prompt] = src.[Prompt],
        tgt.[ActivitySteps] = src.[ActivitySteps],
        tgt.[RequiredContext] = src.[RequiredContext],
        tgt.[ExpectedOutput] = src.[ExpectedOutput],
        tgt.[HumanCheckpoint] = src.[HumanCheckpoint],
        tgt.[BestFitJob] = src.[BestFitJob],
        tgt.[WhyThisMatters] = src.[WhyThisMatters],
        tgt.[LaunchUrl] = src.[LaunchUrl],
        tgt.[LaunchLabel] = src.[LaunchLabel],
        tgt.[UpdatedAtUtc] = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN INSERT ([ExternalId], [HuddleTopicId], [HuddlePlacementId], [HuddlePhaseId], [DisplayOrder], [Name], [Description], [PracticeTier], [ExecutionMethod], [Prompt], [ActivitySteps], [RequiredContext], [ExpectedOutput], [HumanCheckpoint], [BestFitJob], [WhyThisMatters], [LaunchUrl], [LaunchLabel], [CreatedAtUtc])
    VALUES (src.[ExternalId], src.[HuddleTopicId], src.[HuddlePlacementId], src.[HuddlePhaseId], src.[DisplayOrder], src.[Name], src.[Description], src.[PracticeTier], src.[ExecutionMethod], src.[Prompt], src.[ActivitySteps], src.[RequiredContext], src.[ExpectedOutput], src.[HumanCheckpoint], src.[BestFitJob], src.[WhyThisMatters], src.[LaunchUrl], src.[LaunchLabel], SYSUTCDATETIME());
;WITH raw AS (
    SELECT * FROM (VALUES
        (N'AE-01-P01', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 1, N'Ask what the certified business data says', N'Analyze aggregate pipeline position and gap drivers', N'Featured', N'Prompt', N'For the current quarter, where is pipeline most materially behind plan? Break the gap down by stage, solution area, expected close timing, and account. Identify the largest contributors, distinguish pipeline-volume issues from progression or timing issues, and show the metrics supporting each conclusion. Flag anything the available report cannot answer.', NULL, N'Enabled certified MSXI report; relevant report filters; current quarter scope', N'Pipeline gap analysis by stage, solution area, timing, and account, with metrics and report limitations visible.', N'AE confirms report, filters, KPI definitions, and interpretation before using the output in a forecast or management conversation.', N'Workflow execution', N'Certified data creates a shared starting point for the judgment conversation.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'AE-01-P02', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 2, N'Find the right report and configure a useful view', N'Report discovery, KPI clarification, filters, and bookmarks', N'Featured', N'Both', N'I need the best MSXI report for inspecting current-quarter pipeline gaps by account, stage, and solution area. Provide the report link, explain the relevant KPIs, and help me apply filters for [scope]. If supported, save a bookmark for this view.', N'1. Ask MSXI Assist for the best report for the question.
2. Confirm the KPI definitions match what you meant.
3. Apply filters for your scope.
4. Save a bookmark so the next inspection starts here.', N'Business question; role; scope; desired dimensions', N'Report recommendation, KPI explanation, filtered view guidance, and bookmark or repeatable navigation path where supported.', N'AE confirms report scope, definitions, and filters match the business question.', N'Problem identification', N'The right question in the wrong report creates confident noise.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'AE-01-P04', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 3, N'Review pipeline-hygiene corrections', N'Review eligible automated or assisted pipeline-hygiene changes', N'Featured', N'Activity', NULL, N'1. Open the Auto-Fix Pipeline Agent review queue in MSX.
2. Filter to your opportunities.
3. Review each suggested change against the real customer and deal timeline.
4. Confirm, adjust, revert or opt out on each item.
5. Note anything you reverted and why.', N'Eligible opportunities; current agent rule; seller permissions', N'Reviewed pipeline corrections with accepted, adjusted, reverted, or deferred changes and rationale.', N'AE remains accountable for record accuracy and validates each material correction against real customer and deal context.', N'Inspection and review', N'Automation can propose a fix, but the seller owns whether it represents reality.', NULL, N'Open Auto-Fixes in MSX'),
        (N'AE-01-P05A', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 4, N'Receive pushed business-metric changes', N'Subscribe to a relevant MSXI report or business topic', N'Extended', N'Activity', NULL, N'1. Open Proactive Insights in MSXI.
2. Select the business topic or report you want monitored.
3. Set the scope and the cadence.
4. Save the subscription.
5. Review the first pushed summary and judge whether the signal is useful.', N'Available Proactive Insights topic or report; delivery preferences', N'Proactive insight subscription with scoped signal, cadence, first pushed summary, and usefulness assessment.', N'AE checks that the signal is useful rather than noisy and adjusts scope or cadence if needed.', N'Monitoring and signal', N'Monitoring only helps if the signal is actionable and not another feed to ignore.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'AE-01-P05B', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 5, N'Schedule account or opportunity checks', N'Run a recurring MSX and interaction-grounded check', N'Extended', N'Both', N'Schedule this prompt for [cadence]: Review [scope] for opportunities with material changes, missing next steps, stale customer engagement, or newly surfaced risk. Show the source signal and one seller action for each item.', N'1. Open Sales Agent.
2. Enter the prompt.
3. Set the recurring cadence.
4. Confirm the MSX scope it runs against.
5. Review the first scheduled result before relying on it.', N'Connected MSX scope; cadence; seller access', N'Scheduled MSX-grounded opportunity check with scope, cadence, source signals, and recommended seller actions.', N'AE reviews the first scheduled result, validates source signals, and narrows scope if output is too broad.', N'Monitoring and signal', N'Recurring checks should reduce review burden, not create another inbox.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-02-ALT-01', N'WF-X-PIPE-01', N'AE-PIPE-2', N'PH-AE-PIPE-2-EXPL', 3, N'Pressure-test the forecast narrative', N'Find the movement, risk or commitment in your forecast narrative that you cannot yet evidence.', N'Extended', N'Prompt', N'Review the forecast narrative. For each claim about movement, risk or commitment, state the certified source behind it and whether the judgment is yours or the data''s. Identify the two claims most likely to be challenged in inspection and what evidence would settle them.', NULL, N'The forecast narrative; the certified data behind each claim; the commitments you have made to your manager.', N'A forecast challenge list separating sourced movement from seller judgment, with the evidence needed for the two weakest claims.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Build a Decision-Ready Forecast Narrative is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-02-ALT-02', N'WF-X-PIPE-01', N'AE-PIPE-2', N'PH-AE-PIPE-2-EXPL', 4, N'Create the forecast follow-through plan', N'Turn the forecast inspection into the specific actions and dates that change the position before the next review.', N'Extended', N'Prompt', N'Turn the forecast narrative into a follow-through plan. For each at-risk commit and gap driver, define the action that would change it, the owner, the date it must move by, and the evidence you will check. Set the rhythm you will use to inspect it before the next forecast call.', NULL, N'The reviewed forecast narrative; the at-risk commits and their owners; the date of your next inspection.', N'A forecast follow-through plan with actions, owners, dates, evidence checks, and an inspection rhythm.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Build a Decision-Ready Forecast Narrative rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-02-P01', N'WF-X-PIPE-01', N'AE-PIPE-2', N'PH-AE-PIPE-2-EXPL', 1, N'Analyze certified forecast movement', N'Analyze certified business metrics and drivers.', N'Featured', N'Prompt', N'Give me my weekly forecast narrative for [scope]: qualified versus committed change since last week, the five biggest movers up and down with one-line reasons, committed deals at risk in the next 30 days, and three inspection questions. Use only the enabled certified report and show supporting metrics.', NULL, N'Your forecast scope; access to certified pipeline data; last week''s position for comparison.', N'Forecast narrative with qualified versus committed movement, biggest movers, at-risk deals, inspection questions, and supporting metrics.', N'AE validates source metrics, customer context, and whether the narrative reflects seller judgment.', N'Analysis and assessment', N'A forecast narrative should make risk inspectable, not make uncertainty sound certain.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'AE-02-P02', N'WF-X-PIPE-01', N'AE-PIPE-2', N'PH-AE-PIPE-2-EXPL', 2, N'Create the inspection brief', N'Synthesize approved analysis and work context into an artifact.', N'Featured', N'Prompt', N'Using the approved forecast analysis and my meeting notes, draft a concise forecast-call brief that separates sourced facts, seller judgment, risks, decisions needed, and follow-up actions.', NULL, N'The approved forecast analysis; your own meeting notes; the risks you judge to be real but cannot yet evidence.', N'Forecast-call brief separating sourced facts, seller judgment, risks, decisions needed, and follow-up actions.', N'AE reviews every claim, adds judgment, and decides what is shared with manager or leadership.', N'Synthesis and drafting', N'The brief turns analysis into a review-ready conversation.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-03-ALT-01', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 3, N'Pressure-test the account priority list', N'Challenge whether your account priorities are driven by evidence or by habit and familiarity.', N'Extended', N'Prompt', N'Review my account priority list. For each of the top accounts, state the evidence behind the priority and whether it reflects a current signal or a standing assumption. Identify the account most likely to be wrongly prioritized, the account most likely to be wrongly ignored, and what would confirm either.', NULL, N'The prioritized account list; the source signal behind each priority; the accounts you have not touched recently.', N'A priority challenge showing evidence per account, plus the most likely over-prioritized and under-prioritized account.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Prioritize Accounts and Build an Actionable Account Plan is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-03-ALT-02', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 4, N'Create the account follow-through plan', N'Convert the account priorities into named next actions and the rhythm that keeps them from decaying into a list.', N'Extended', N'Prompt', N'Turn the account priority list into a follow-through plan. For each top account, define the next action, the owner, the date, the signal you will check to know it worked, and the point at which you would drop the account down the list. Set a weekly rhythm for reviewing it.', NULL, N'The prioritized account list; the next action for each top account; your weekly planning rhythm.', N'An account follow-through plan with next actions, owners, dates, verification signals, and a weekly review rhythm.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Prioritize Accounts and Build an Actionable Account Plan rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-03-ECIF-01', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 5, N'Assess ECIF fit and investment momentum', N'Explore eligible investment options for an approved opportunity and identify request or delivery risks to momentum.', N'Featured', N'Prompt', N'Using the approved opportunity ID or TPID, explore eligible investment offers, summarize customer investments, and identify request or delivery risks that could affect opportunity momentum. Separate retrieved facts from assumptions.', NULL, N'Approved opportunity ID or TPID and current opportunity context.', N'Investment-fit summary with supported options, active-request status, risks, evidence gaps, and next human decision.', N'AE confirms opportunity context and does not determine eligibility, approval, or funding. Route to the accountable ECIF owner.', N'Analysis and assessment', N'Investment is useful only when it removes a real account or opportunity barrier.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-03-P01', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 1, N'Prioritize account action for this week', N'Use Sales Agent and available sales context to rank accounts and name one next action for each.', N'Featured', N'Prompt', N'Rank my top 10 accounts for this week. For each, show the priority driver, active opportunity stage, renewal or whitespace signal, partner context, and the single highest-impact seller action. Show the source signal and flag missing context.', NULL, N'Your account list; access to opportunity, renewal and whitespace signals; partner coverage for those accounts.', N'Prioritized account list with priority driver, source signal, active stage, role gaps, and highest-impact action.', N'AE validates the priority logic, relationship nuance, and whether the action is realistic this week.', N'Prioritization', N'Prioritization is a decision about what will not get attention.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-03-P02', N'WF-X-PLAN-01', N'AE-PLAN', N'PH-AE-PLAN-EXPL', 2, N'Build or assess the account plan with approval gates', N'Use a reusable planning skill to propose account-plan updates while keeping every write or commitment AE-approved.', N'Featured', N'Both', N'For [Account] and [TPID], assess the current account plan, research evidence gaps, propose additive updates to priorities, stakeholders, opportunities, and next actions, and require approval before any MSX write.', N'1. Open Scout and start the account plan skill.
2. Supply the account and TPID.
3. Review the proposed additions against your own knowledge.
4. Approve or reject each proposed MSX write.
5. Confirm nothing was written without your approval.', N'The account and its TPID; the current account plan; your authority to approve or reject an MSX write.', N'Account-plan assessment with proposed updates, evidence gaps, and explicit approval/rejection decisions.', N'AE approves or rejects each proposed change and confirms nothing is written or committed without review.', N'Synthesis and drafting', N'Account planning becomes usable when it creates next actions, not just more content.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'AE-04-ALT-01', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 3, N'Pressure-test the opportunity hypotheses', N'Separate the opportunity signals that are genuinely evidenced from the ones that reflect optimism.', N'Extended', N'Prompt', N'Review my opportunity hypotheses. For each, state the trigger event, the evidence it rests on, and whether a customer has actually indicated intent or the intent is inferred. Identify which would create duplicate or unsupported pipeline, and what one piece of evidence would qualify or kill each.', NULL, N'The opportunity hypotheses; the trigger and evidence behind each; your existing pipeline so you can spot duplication.', N'A qualification challenge per hypothesis, with evidence status, duplication risk, and the single test that would qualify or kill it.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Create and Qualify New Opportunities is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-04-ALT-02', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 4, N'Create the opportunity follow-through plan', N'Turn qualified opportunity hypotheses into the first customer action and the date you will know whether it is real.', N'Extended', N'Prompt', N'Turn the qualified opportunity hypotheses into a follow-through plan. For each, define the first customer action, the stakeholder, the date, the response that would confirm it is real, and the point at which you would stop pursuing it. Rank by which is most likely to convert.', NULL, N'The qualified hypotheses; the stakeholder you would approach for each; your outreach capacity this week.', N'A ranked opportunity follow-through plan with first actions, stakeholders, dates, confirming signals, and stop conditions.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Create and Qualify New Opportunities rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-04-P01', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 1, N'Qualify buying signals into opportunity hypotheses', N'Use Sales Agent and available customer context to separate real buying signals from noise or optimism.', N'Featured', N'Prompt', N'Review [Account] across MSX, recent meetings, email, and available content. Summarize buying signals, risks, existing opportunity overlap, and the top three actions to create or progress a qualified opportunity. Flag signals that lack evidence.', NULL, N'The account you are working; access to MSX, recent meetings and email for it; your open opportunities so you can spot overlap.', N'Buying-signal summary with evidence, risks, existing opportunity overlap, top actions, and unsupported signals flagged.', N'AE verifies source access, customer intent, duplication risk, and whether the signal warrants outreach or opportunity creation.', N'Opportunity qualification', N'A qualified opportunity starts with a trigger and evidence, not the need to fill coverage.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-04-P02', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 2, N'Develop whitespace outreach from evidence', N'Turn whitespace and account signals into testable outreach and first-meeting structure.', N'Featured', N'Prompt', N'Analyze whitespace for [scope]. Identify accounts with low solution penetration relative to known priorities, propose the top three opportunity hypotheses, and create an initial outreach plan with a first-meeting agenda. Separate evidence from assumptions.', NULL, N'The territory or account scope; solution penetration data; the customer priorities you already know.', N'Whitespace opportunity hypotheses with evidence, assumptions, first outreach, partner consideration, and meeting agenda.', N'AE validates account fit, customer relevance, partner appropriateness, and whether assumptions are acceptable for outreach.', N'Synthesis and drafting', N'Whitespace only matters when it becomes a customer problem worth testing.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-04-P03', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 5, N'Inspect opportunity-level context before action', N'Review connected MSX opportunities and available customer-conversation context', N'Featured', N'Prompt', N'Review open opportunities closing this quarter for [seller or account scope]. Identify opportunities that need seller attention because the close date, next step, forecast evidence, or recent customer engagement appears incomplete or inconsistent. For each flagged opportunity, show the source signal, explain why attention may be needed, and suggest one seller action. Flag cases where recent customer context is missing.', NULL, N'Connected MSX scope; user access; seller or account scope', N'Flagged opportunity list with close-date, next-step, engagement, and risk signals plus one seller action each.', N'AE verifies the underlying records, customer context, and whether the proposed action is still current.', N'Inspection and review', N'Opportunity inspection is where pipeline noise either becomes action or gets removed.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-ALT-01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 6, N'Pressure-test the deal inspection', N'Find the blocker, approval or stakeholder gap that the deal plan assumes is handled but nobody owns.', N'Extended', N'Prompt', N'Review this deal inspection. Identify the next decision the customer must make, whether the evidence to support it exists, and which blocker has no named owner. Name the assumption that, if wrong, would move the close date most, and what would confirm it.', NULL, N'The deal inspection brief; the exit criteria for the current stage; the account-team roles involved.', N'A deal challenge naming the next customer decision, unowned blockers, and the assumption with the largest close-date impact.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Accelerate a Strategic Deal is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-05-ALT-02', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 7, N'Create the deal follow-through plan', N'Convert the deal inspection into owned actions and checkpoints that move the next customer decision.', N'Extended', N'Prompt', N'Turn the deal inspection into a follow-through plan. For each blocker and open decision, define the action, the owner, the date, the customer-facing step if there is one, and the checkpoint where you will verify movement. Separate what you own from what the account team owns.', NULL, N'The reviewed deal inspection; the account-team owners; the customer decision date you are working toward.', N'A deal follow-through plan separating seller-owned from team-owned actions, with dates and verification checkpoints.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Accelerate a Strategic Deal rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-DEAL-01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 1, N'Inspect deal context before customer action', N'Use the deal making features in Sales Agent to assemble agreement, enrollment, renewal, discount, and consumption context, then shape the deal from real data rather than recollection.', N'Featured', N'Prompt', N'Show me the list of enrollments for [Account name or TPID], then list all agreements with type and status. For the agreement I name, provide license estate details grouped by SKU, list the SKUs whose discount is between 40 and 60 percent, and show the upcoming renewals with expiry dates. Lead with the identifier I give you. Tell me which figures you could not retrieve rather than estimating them, and flag anything that needs licensing or entitlement validation before I use it with the customer.', NULL, N'Approved account, TPID, enrollment, or agreement identifier and current deal context.', N'A deal context brief covering enrollments, agreements, license estate by SKU, discount posture, and upcoming renewals, with retrieval gaps named.', N'AE verifies the figures came from the source systems rather than inference, and routes pricing approval, policy exceptions, and final commercial authority to the accountable owner.', N'Inspection and review', N'Deal making answers depend on the identifier. A named enrollment or agreement returns real deal data; a vague account reference returns a generic summary.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-P01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 2, N'Generate the Deal Book for a renewal and choose your scenario', N'Compile the renewal summary for one agreement, then decide which pricing scenario to lead with and why.', N'Featured', N'Both', N'Create Deal Book for agreement number [agreement number]. If the agreement number does not resolve, try the enrollment number instead. When it returns, summarize the pricing scenarios it produced, what each assumes about the customer, and what evidence in the purchase history and current licensing footprint supports each one. Tell me which scenario you would lead with for [customer context] and what would have to be true for that to be wrong. Flag any upsell or cross-sell recommendation that is not supported by the consumption data. Do not present a scenario as approved or as a commitment.', N'1. Have the agreement number ready; the enrollment number also works.
2. Run the prompt.
3. Review the Agreement Details sheet, including year-over-year revenue, before the scenario tabs.
4. Check the Reason to Believe tooltips on the List Price column for SKUs marked discontinued, new, or replaced.
5. Treat the first output as a draft; re-run if the data looks stale.
6. Decide which scenario to lead with and why.', N'An agreement number or enrollment number for a real renewal. Customer context that would make one scenario more appropriate than another. Sales Agent access with your CRM scope connected.', N'A Deal Book with purchase history, current licensing footprint, pricing scenarios, and upsell or cross-sell recommendations, plus your reasoned choice of which scenario to lead with.', N'AE validates the deal facts against the source data, decides which scenario fits this customer, and routes pricing approval, exceptions, and material amendments to the accountable owner and approval chain rather than acting on the recommendation alone.', N'Synthesis and drafting', N'The Deal Book assembles in minutes what used to take weeks across seven or eight portals. The judgment that matters is which scenario fits this customer.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-P02', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 3, N'Prepare grounded customer follow-up', N'Translate an approved inspection into grounded follow-up.', N'Featured', N'Prompt', N'Using the reviewed deal inspection and latest customer interaction, draft a follow-up that confirms customer outcomes, open decisions, commitments, and the next agreed action. Do not invent commitments.', NULL, N'The reviewed deal inspection; notes from the latest customer interaction; the commitments already made to the customer.', N'Customer follow-up draft confirming outcomes, decisions, commitments, next action, and any open questions.', N'AE validates tone, relationship context, commitments, and whether follow-up should be sent or revised.', N'Conversation preparation', N'A good follow-up turns inspection into customer momentum.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-05-QUOTE-01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 4, N'Turn the chosen scenario into a quote and start the approval', N'Create the EA quote from the scenario you selected, check the pricing fields, and request the approval you know it will need, rather than discovering the approval requirement later.', N'Extended', N'Both', N'Create an EA Quote for [enrollment number] based on the scenario I selected from the Deal Book. Then show me the price settings so I can check them, and tell me which fields you populated from the Deal Book versus which need my input. Identify any discount level in this quote that will require approval, and what the approval path would be. Do not submit anything or represent any discount as approved. If a guardrail or validation issue applies to this deal, including anything multi-year or multi-tenant, surface it now rather than at submission.', N'1. Bring the enrollment number and the scenario you chose from the Deal Book.
2. Run the prompt.
3. Review the price settings and correct anything that came across wrong.
4. Note the approval that will be needed and who owns it.
5. If a discount needs approval, request it: Request approval for a [X percent] discount on this renewal.
6. Keep this in the same chat thread as the rest of this deal.', N'The enrollment number and the Deal Book scenario you selected. Knowledge of your own empowerment level and who owns approval beyond it. Sales Agent access with your CRM scope connected.', N'A draft EA quote with price settings visible, a clear split between populated and required fields, and the approval requirement and path named before submission.', N'AE verifies every pricing field before submission, treats the draft as a draft rather than a final quote, and routes discount approval, exceptions, and any material amendment through the accountable owner and the legal approval chain rather than around it.', N'Execution and drafting', N'Deals stall between a good scenario and a submitted quote. Knowing the approval requirement before you build the quote is what keeps that gap short.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-06-ALT-01', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 4, N'Pressure-test the executive conversation plan', N'Test the conversation plan against the objections and stakeholder dynamics most likely to derail it.', N'Extended', N'Prompt', N'Review my plan for this executive conversation. Identify the claim most likely to be challenged, the stakeholder most likely to resist, the evidence I am missing for my primary ask, and whether my fallback ask is genuinely different or just a smaller version of the same one.', NULL, N'The conversation brief; the stakeholder history and dynamics; the ask you intend to make.', N'A conversation challenge naming the weakest claim, the likely resistor, missing evidence, and fallback-ask quality.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Prepare for a Customer Conversation is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-06-P-AE01', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 1, N'Build the account and conversation brief', N'Use MSX and available customer-interaction context to prepare the AE.', N'Featured', N'Prompt', N'Prepare me for my next conversation with [Account]. Summarize priorities from the last 60 days, sentiment shifts, open commitments, active MSX opportunities, competitive mentions, engaged account-team roles, and missing context. Recommend three talking points and the single ask that best advances the customer decision. Show the source signal for each major claim.', NULL, N'Account; meeting type; desired decision; user access to MSX and available customer context.', N'Grounded AE conversation brief with source signals, gaps, talking points, likely objections, primary ask, and fallback ask.', N'AE verifies customer facts, relationship nuance, opportunity strategy, claims, commitments, and the ask before use.', N'Synthesis and drafting', N'Preparation is the highest-leverage place to improve the customer conversation.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-06-P-AE02', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 5, N'Create the executive value narrative', N'Create a customer-ready narrative from approved evidence and work content.', N'Featured', N'Prompt', N'Using the approved account brief and these source materials, create an executive value narrative for [solution/workload]. Map the solution to the customer’s stated priorities, use only sourced outcomes or quantified evidence, flag claims requiring review, and end with three CXO talking points, one primary ask, and one realistic fallback ask.', NULL, N'Approved account brief; selected files, meetings, or content; solution/workload; desired decision.', N'Executive value narrative with sourced claims, customer priorities, CXO talking points, primary ask, fallback ask, and review flags.', N'AE and relevant technical or commercial roles validate all claims, ROI, customer commitments, and tone before use.', N'Synthesis and drafting', N'Value that is not evidenced is opinion; value that is not connected to an ask does not move the decision.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-06-P-AE03', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 2, N'Research the customer and competitive position with citations', N'Build the sourced research base for the executive conversation, so claims can be traced back to something.', N'Featured', N'Prompt', N'Act as my research analyst for an upcoming executive conversation with [Customer]. Produce a sourced brief covering their stated business priorities, recent public announcements and results, the industry pressures they are under, their current technology direction, and any competitor positioning that is likely to come up. Cite every claim. Separate what you found in published sources from what you found in our own work content, and state clearly where you found nothing rather than filling the gap.', NULL, N'Customer name; the executive and their remit; approved access to work content and public sources.', N'Sourced research brief with citations, separating published sources from internal work content, and naming the gaps.', N'AE verifies each citation actually supports the claim, discards anything unsourced, and decides what is appropriate to reference in front of the customer.', N'Evidence gathering', N'An executive notices the difference between a seller who did the research and one who read the account record. Researcher is also available inside Sales Agent, which draws on it to answer research questions; using it directly gives you the full sourced report and the citations.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'AE-07-ALT-01', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 4, N'Pressure-test the renewal assessment', N'Test whether your renewal risk read is supported by usage and engagement evidence or by the absence of bad news.', N'Extended', N'Prompt', N'Review my renewal assessment. For each at-risk renewal, state the evidence behind the risk rating, when the customer was last genuinely engaged, and whether the value delivered has been demonstrated or assumed. Identify the renewal where I am most likely to be wrong and why.', NULL, N'The renewal view with risk evidence; consumption and usage trends; recency of real customer engagement.', N'A renewal challenge with risk evidence, engagement recency, value-proof status, and the renewal most likely misjudged.', N'AE confirms source accuracy, customer context, role ownership, commitments, and whether the risk changes the plan.', N'Assumption testing', N'If the decision path for Manage Renewal Risk and Expansion Readiness is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-07-ALT-02', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 5, N'Create the renewal follow-through plan', N'Turn the renewal read into the actions and dates that change the outcome while there is still runway.', N'Extended', N'Prompt', N'Turn the renewal assessment into a follow-through plan. For each at-risk renewal, define the action, the owner, the date it must happen by given the renewal date, the value evidence to assemble, and the point at which CE or commercial support must be engaged.', NULL, N'The reviewed renewal view; the renewal dates and their lead times; the account-team and CE owners.', N'A renewal follow-through plan with actions, owners, deadline-aware dates, value evidence, and CE engagement triggers.', N'AE confirms owners, due dates, customer commitments, and which actions require another role.', N'Synthesis and drafting', N'You spend your time editing the follow-through plan for Manage Renewal Risk and Expansion Readiness rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-07-P01', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 1, N'Assess renewal risk and expansion readiness', N'Use Sales Agent and available customer context to prioritize upcoming renewals by risk and supported expansion signals.', N'Featured', N'Prompt', N'Show my accounts with renewals in the next six months. For each, summarize ARR, licensing, consumption trend, usage gaps, recent customer engagement, expansion signals, and risk evidence. Prioritize by potential impact and flag missing data.', NULL, N'Your renewal portfolio for the next six months; licensing, consumption and usage data; recent customer engagement history.', N'Renewal risk view with ARR, licensing, consumption or usage trend, engagement recency, expansion signal, impact priority, and missing data.', N'AE validates renewal facts, customer intent, value evidence, and owner alignment with CSAM, CSA, CE, and SSP.', N'Analysis and assessment', N'Renewal risk found early is still actionable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-07-P02', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 2, N'Draft a renewal outreach package', N'Synthesize reviewed evidence into customer communication.', N'Featured', N'Prompt', N'For [Account] renewing in [Month], use the reviewed renewal assessment and source materials to draft outreach tied to stated goals, value delivered, unresolved consumption gaps, and expansion options. Flag pricing or commercial claims for CE review.', NULL, N'The reviewed renewal assessment; the customer''s stated goals; the value evidence you can support, and your CE contact for pricing claims.', N'Renewal outreach draft with customer goals, value delivered, consumption gaps, expansion options, and CE-review flags.', N'AE validates customer claims, tone, commercial statements, and whether expansion is supported by evidence.', N'Synthesis and drafting', N'Renewal outreach should connect value and next action, not just announce a date.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-07-P03', N'WF-X-RENEW-01', N'AE-RENEW', N'PH-AE-RENEW-EXPL', 3, N'Assemble the renewal and expansion package', N'Pull the renewal position, consumption evidence, value story and expansion options into one package the customer and the account team can both work from.', N'Featured', N'Both', N'Build a renewal and expansion package for [Customer]. Work across the agreement and renewal position, consumption and usage evidence, the value delivered so far, open risks, and the expansion options we believe are supported. Produce a short customer-facing summary, an internal account-team view with the risks stated plainly, and a one-page value story. Show me the plan before you build it, and check in before each document so I can redirect you.', N'1. Bring the customer, the renewal date, and the value evidence you can actually support.
2. Run the prompt.
3. Separate what the package claims as delivered value from what is projected.
4. Flag every pricing or commercial statement for CE review before the package goes near the customer.
5. Confirm the expansion options are grounded in usage evidence rather than aspiration.', N'Approved renewal, consumption, usage and value evidence for the account; the expansion hypotheses already tested.', N'Renewal package with a customer-facing summary, an internal risk view, and a one-page value story.', N'AE validates every claim in the customer-facing material, confirms commercial statements with the Commercial Executive, and decides what is shared externally.', N'Synthesis and drafting', N'The renewal conversation needs a package, not a chat answer. This is multistep work across several sources, with checkpoints, which is what Cowork is for.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'AE-INVEST-01-P01', N'WF-INVEST-01', N'AE-INVEST', N'PH-AE-INVEST-EXPL', 1, N'Identify where customer investment could unlock the next decision', N'Identify where a customer investment could remove a decision, deployment or adoption barrier, without judging eligibility.', N'Featured', N'Prompt', N'Using approved account, opportunity, customer-priority, and adoption context, identify where a customer investment could remove a decision, deployment, or adoption barrier. Separate evidence from assumptions and do not determine eligibility or approval.', NULL, N'Customer priorities, opportunity context, adoption or deployment barrier', N'Investment hypothesis with customer outcome, opportunity linkage, barrier evidence, assumptions, and next human decision.', N'AE confirms the barrier is real, investment is a plausible lever, and eligibility or approval is not implied.', N'Problem identification', N'Naming where customer investment could unlock the next decision is most of the work. Unnamed problems never get an owner.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'AE-INVEST-01-P02', N'WF-INVEST-01', N'AE-INVEST', N'PH-AE-INVEST-EXPL', 2, N'Connect proposed investment to account strategy and outcomes', N'Connect a proposed investment to account priorities and opportunity milestones, naming unsupported claims and dependencies.', N'Featured', N'Prompt', N'Explain how the proposed investment supports account priorities, opportunity milestones, and intended customer outcomes. Identify unsupported claims, dependencies, and the owner of the next decision.', NULL, N'Proposed engagement, scope inputs, intended outcomes', N'Account-level investment rationale with customer outcomes, opportunity milestones, dependencies, unsupported claims, and owner.', N'AE validates account strategy fit, source evidence, and accountable decision owner before routing.', N'Value translation', N'Making proposed investment to account strategy and outcomes explicit is the part almost nobody does, and the part that travels.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'AE-INVEST-01-P03', N'WF-INVEST-01', N'AE-INVEST', N'PH-AE-INVEST-EXPL', 3, N'Confirm account-team sponsorship and handoff', N'Create the handoff showing investment purpose, contributors, unresolved questions and who is accountable next.', N'Featured', N'Prompt', N'Create a concise handoff showing the investment purpose, approved customer context, contributors, unresolved questions, and the person accountable for progressing the request.', NULL, N'Approved context and current investment status', N'Account sponsorship and handoff brief with purpose, contributors, unresolved questions, owner, and next governed action.', N'AE confirms role ownership and does not bypass governed ECIF or investment process steps.', N'Validation and evidence', N'Confirming account-team sponsorship and handoff now costs a conversation. Discovering it late costs a decision.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'AE-INVEST-01-P04', N'WF-INVEST-01', N'AE-INVEST', N'PH-AE-INVEST-EXPL', 4, N'Qualify the investment before anyone builds a request', N'Test whether the investment idea is worth the effort of a request, and decide who owns the next step, before work starts.', N'Featured', N'Both', N'Here is the investment hypothesis for [account and opportunity]: [paste]. Test it. What customer outcome would it unlock that will not happen otherwise? What evidence supports that, and what is assumption? What would need to be true for this to be declined, and is any of that already true? If this is Azure-specific, note that Azure Offer Navigator is the front door rather than a general ECIF request. Recommend proceed, reshape, or stop, and say who owns the next step. Do not assess eligibility or approval likelihood.', N'1. Bring the investment hypothesis from the previous activity.
2. Run the prompt.
3. Be honest about which supporting points are assumption.
4. Decide proceed, reshape, or stop.
5. If proceeding, name who builds the request and who owns the workscope.', N'The investment hypothesis and its account linkage. What the customer has actually said. Who on the account team would build and own the request.', N'A proceed, reshape, or stop decision with the evidence and assumptions separated, and the owner of the next step named.', N'AE owns the judgment about whether the customer outcome is real, and routes eligibility, policy, and funding questions to the accountable owners rather than answering them.', N'Assumption testing', N'The cheapest investment request is the one you decide not to build. Qualifying early costs an hour; qualifying late costs the team weeks.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'AE-INVLINK-01', N'WF-X-DEAL-01', N'AE-DEAL', N'PH-AE-DEAL-EXPL', 5, N'Test whether customer investment would unblock this deal', N'Check the deal for a barrier that customer investment could remove.', N'Extended', N'Prompt', N'Using the approved opportunity, account priorities and current blockers, identify whether a customer investment could remove a decision, deployment or adoption barrier on this deal. Separate evidence from assumption. Do not determine eligibility, funding or approval.', NULL, N'Approved opportunity context, current blockers, account priorities', N'Deal-linked investment hypothesis with barrier, evidence, assumptions, owner, and next human decision.', N'AE confirms the barrier is real, investment is appropriate, and funding or eligibility remains a governed decision.', N'Check the deal for a barrier that customer investment could remove.', N'Investment belongs in the deal conversation only when it changes a real blocker.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-OPP-SCOUT-01', N'WF-X-OPP-01', N'AE-OPP', N'PH-AE-OPP-EXPL', 6, N'Watch your accounts for buying signals worth acting on', N'Set up a standing watch across your account list so external and internal signals reach you while they are still actionable.', N'Extended', N'Both', N'Set up a recurring watch across my named accounts. Each week, surface publicly reported changes - leadership moves, earnings commentary, announced initiatives, regulatory or funding events - alongside internal signals such as new support volume, usage shifts, or newly opened engagements. For each signal, state what it plausibly implies for a Microsoft opportunity and what would have to be true for that to hold. Separate what is evidenced from what is inference, and cite the source for every external claim.', N'1. Bring your named account list and confirm which of those accounts you can see internal activity for.
2. Run the prompt.
3. Check the first digest against one account you know well, and confirm every external claim carries a source.
4. Set the cadence you will actually read; weekly is usually enough.
5. Discard any signal you cannot trace to a source before acting on it.', N'Your named account list; access to internal account activity; the priority solution areas for your territory.', N'A recurring signal digest per account with sourced external events, internal activity changes, and an explicit evidence-versus-inference split.', N'AE validates each signal against what they know about the account before acting, and never repeats an unsourced claim to a customer.', N'Monitoring and signal', N'Opportunity creation is mostly a timing problem. The trigger events that make an account ready are public or visible internally - the constraint is noticing them while there is still time to act.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'AE-ORCH-01-P01', N'WF-X-ORCH-01', N'AE-ORCH', N'PH-AE-ORCH-EXPL', 1, N'Build the account-team role and handoff map', N'Clarify who needs to be involved, what input they owe, and which customer decision the team is supporting.', N'Featured', N'Prompt', N'For [Account or Opportunity], build an account-team role and handoff map. Include customer outcome, current stage, required Microsoft roles, partner role if relevant, missing coverage, owner for each action, input needed, due date, and the next customer decision. Flag unsupported assumptions and stale context.', NULL, N'Account or opportunity context; current stage; known team members; desired customer decision.', N'Account-team role and handoff map with missing roles, owners, inputs, dates, and next customer decision.', N'AE validates role need, relationship nuance, owner accountability, partner fit, and customer commitments before sharing.', N'Coordination and handoff', N'Most account-team friction is hidden until the handoff fails. Naming it early makes it manageable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-ORCH-01-P02', N'WF-X-ORCH-01', N'AE-ORCH', N'PH-AE-ORCH-EXPL', 2, N'Prepare partner co-sell engagement', N'Identify where partner involvement could improve scale, specialization, credibility, or deal velocity.', N'Featured', N'Prompt', N'Recommend whether partner engagement is useful for [Opportunity]. Identify candidate partner roles, evidence of fit from approved sources, dependencies, risks, proposed two-week ask, and a draft internal introduction. Do not imply partner acceptance or incentive eligibility unless confirmed by approved sources.', NULL, N'Opportunity; solution area; customer context; approved partner evidence or criteria.', N'Partner engagement recommendation with role, evidence, risks, dependencies, draft intro, and next ask.', N'AE validates partner evidence, conflicts, ownership, customer fit, and any incentive or co-sell claims before outreach.', N'Workflow execution', N'Partner engagement helps only when the partner role is specific enough to move the customer decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-ORCH-01-P03', N'WF-X-ORCH-01', N'AE-ORCH', N'PH-AE-ORCH-EXPL', 3, N'Create the account-team briefing and follow-through rhythm', N'Turn context, role asks, and open decisions into a reusable team brief and follow-up rhythm.', N'Featured', N'Both', N'Create a briefing for my extended account team ahead of [event or decision]. Include objective, customer context, open commitments, each role’s expected contribution, prep required, questions I need answered, and follow-up cadence. Keep it concise and flag claims needing validation.', N'1. Choose the account or opportunity.
2. Identify the decision or event.
3. Generate the brief.
4. Validate role asks and sensitive claims.
5. Send or store the brief and create follow-up owners.', N'Account context; event or decision; role list; open commitments; approved source materials.', N'Account-team briefing with role-specific asks, prep, open questions, and follow-through owners.', N'AE confirms role asks, relationship sensitivities, source accuracy, and whether the brief should be shared.', N'Synthesis and drafting', N'A team brief reduces repeated context-setting and makes follow-through inspectable.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'AE-PIPE-SCOUT-01', N'WF-X-PIPE-01', N'AE-PIPE-1', N'PH-AE-PIPE-1-EXPL', 6, N'Keep pipeline hygiene current between reviews', N'Stand up a recurring sweep of your owned pipeline so hygiene problems surface on a schedule instead of the night before a review.', N'Extended', N'Both', N'Check my owned pipeline on a recurring basis and report only what has changed since the last run. Flag opportunities with a close date in the past, no activity in the last 30 days, a missing or generic next step, or a stage that has not moved while the close date has. For each one, draft the specific update or question I would need to resolve it. Rank by revenue at risk within the current period. Do not change any record - produce a review list for me to action.', N'1. Confirm your team''s definition of a healthy next step so the check flags the right things.
2. Run the prompt against your owned pipeline.
3. Review the first list and confirm each flagged opportunity is genuinely stale rather than deliberately paused.
4. Set the cadence to land before your pipeline review, not after it.
5. Make every record change yourself; do not let the check write to MSX.', N'Access to your owned pipeline; your current period close dates; your team''s definition of a healthy next step.', N'A recurring change-only hygiene list ranked by revenue at risk, with a drafted resolution for each flagged opportunity.', N'AE confirms each flagged item is genuinely stale before updating, and makes every record change themselves rather than delegating the write.', N'Monitoring and signal', N'Pipeline hygiene fails because it is a periodic scramble rather than a standing habit. A recurring check that reports only what changed turns a two-hour clean-up into a five-minute review.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'AE-VALUE-01-P01', N'WF-X-VALUE-01', N'AE-VALUE', N'PH-AE-VALUE-EXPL', 1, N'Build the QBR and value evidence brief', N'Assemble outcomes, commitments, usage or consumption signals, risks, investments, and expansion plays into a reviewable evidence base.', N'Featured', N'Prompt', N'For [Account] and [period], build a QBR evidence brief. Include outcomes delivered, supporting evidence, open customer and Microsoft commitments, usage or consumption signals, active investments, risks, expansion plays, and missing evidence. Separate sourced facts from interpretation.', NULL, N'Account; period; approved usage, consumption, meeting, opportunity, investment, and commitment sources.', N'QBR evidence brief with supported outcomes, commitments, risks, expansion plays, and evidence gaps.', N'AE validates source evidence, customer-recognized value, unsupported claims, and which roles must review.', N'Synthesis and drafting', N'A QBR should start with evidence the customer would recognize, not slides that sound good internally.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'AE-VALUE-01-P02', N'WF-X-VALUE-01', N'AE-VALUE', N'PH-AE-VALUE-EXPL', 2, N'Create the executive QBR narrative and strategic asks', N'Convert the reviewed evidence brief into an executive-ready narrative with decisions and asks.', N'Featured', N'Both', N'Using the reviewed QBR evidence brief, create an executive QBR narrative for [Account]. Include a concise executive summary, value delivered, commitments, risks, top expansion plays, investment status if relevant, three strategic asks, and claims requiring final review.', N'1. Review the evidence brief.
2. Generate the QBR narrative or deck outline.
3. Remove unsupported claims.
4. Validate with account-team owners.
5. Decide what becomes customer-facing.', N'Reviewed QBR evidence brief; customer audience; desired decisions; approved branding or format constraints.', N'Executive QBR narrative or deck outline with value story, risks, expansion plays, and strategic asks.', N'AE validates tone, customer relevance, commitments, claims, and whether technical or commercial owners must review.', N'Synthesis and drafting', N'The QBR should create the next decision, not just summarize the last quarter.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'AE-VALUE-01-P03', N'WF-X-VALUE-01', N'AE-VALUE', N'PH-AE-VALUE-EXPL', 3, N'Draft the executive value follow-up', N'Turn reviewed value evidence and strategic asks into a concise customer-ready message.', N'Featured', N'Prompt', N'Draft a follow-up email to [Customer Exec] using the reviewed QBR or value brief. Summarize the value supported by evidence, acknowledge open commitments, propose next steps aligned to strategic priorities, and include three talk-track bullets for my follow-up call. Flag any commercial or technical claims for review.', NULL, N'Reviewed value brief; customer executive; desired next step; approved source evidence.', N'Executive follow-up email and talk-track bullets with review flags.', N'AE validates relationship tone, customer facts, commitments, and claims before sending.', N'Conversation preparation', N'Value is only useful if it reaches the right executive with a clear next step.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ALL-DEAL-01', N'WF-X-DEAL-01', N'ALL-DEAL', N'PH-ALL-DEAL-EXPL', 1, N'Find out what this customer actually owns', N'Retrieve the agreements, enrollments, and license estate for one of your own accounts, so you know what the customer already has before you talk to them.', N'Featured', N'Both', N'List all agreements for [Account name or TPID] with type and status, and show me the list of enrollments. For the agreement I name next, provide the license estate details grouped by SKU. Lead with the identifier I gave you. If you cannot retrieve something, say so rather than estimating it, and do not infer entitlements that are not in the data.', N'1. Bring one account you actually work on.
2. Run the prompt with the account name or TPID.
3. Pick one agreement from what comes back and ask for the license estate grouped by SKU.
4. Note anything you did not know.
5. Note anything you had assumed that turned out to be different.', N'An account you work on, and ideally an agreement number, enrollment number, or TPID. Access to Sales Agent with your CRM scope connected.', N'A list of agreements and enrollments for the account, plus license estate grouped by SKU for one agreement.', N'You confirm the retrieved data matches the account you meant, and treat entitlement and licensing detail as information to verify with the deal owner before making any customer-facing commitment.', N'Inspection and review', N'Most roles walk into customer conversations without knowing what the customer already bought. The answer takes about ninety seconds to retrieve.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ALL-DEAL-02', N'WF-X-DEAL-01', N'ALL-DEAL', N'PH-ALL-DEAL-EXPL', 2, N'See what is expiring and what that means for your work', N'Surface upcoming renewals and consumption trend for your account, then work out what it changes for your own role rather than for the deal owner''s.', N'Featured', N'Both', N'What are the upcoming renewals for [Account name or TPID]? Show expiry dates and current agreement details, then give me the ACR trend month over month for this account. Do not recommend a renewal strategy. I want the facts and the timing so I can work out what my own role needs to do before that date.', N'1. Run the prompt for your account.
2. Note the nearest expiry date.
3. Work backwards: what does your role need to have done before that date?
4. Name the one thing you would otherwise have found out too late.', N'The account and identifier from the previous activity. Your own role''s commitments on that account.', N'Upcoming renewals with expiry dates, agreement detail, and consumption trend, plus one action your own role owns ahead of that date.', N'You decide what the timing means for your own work, and leave renewal strategy, pricing, and commercial approach to the account owner and Commercial Executive.', N'Analysis and assessment', N'A renewal date is a deadline for every role touching the account, not only for the person who owns the deal.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ALL-DEAL-03', N'WF-X-DEAL-01', N'ALL-DEAL', N'PH-ALL-DEAL-EXPL', 3, N'Draw the line between what you can answer and what you should hand off', N'Sort the deal questions you get asked into ones you can now answer yourself and ones that belong to the deal owner, so you stop escalating retrievable facts and stop answering commercial questions you should not.', N'Featured', N'Both', N'Here are deal-related questions I have been asked recently by customers or colleagues: [paste the questions]. For each one, tell me whether it can be answered by retrieving facts from agreements, enrollments, licensing, or consumption data, or whether it requires a commercial, pricing, policy, or approval decision. For the retrievable ones, give me the prompt I would use. For the rest, say what kind of decision it is. Do not answer the commercial ones yourself.', N'1. List the deal questions you have been asked in the last month.
2. Run the prompt.
3. Check the split against your own judgment.
4. Pick one question you used to escalate and commit to answering it yourself next time.
5. Pick one you should always route, and confirm who owns it.', N'Real questions you have been asked. Knowledge of who owns commercial decisions on your accounts.', N'Your questions sorted into retrievable and decision-requiring, with a prompt for the first group and an owner for the second.', N'You own the judgment about where the line sits on your accounts, and confirm that anything commercial, pricing, policy, or approval related routes to the accountable owner rather than being answered from retrieved data.', N'Problem identification', N'Two failures cost time: escalating a question you could have answered, and answering one you should have escalated.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ALL-USECASE-01', N'WF-X-USECASE-01', N'ALL-USECASE', N'PH-ALL-USECASE-EXPL', 1, N'Map the workflow the team chose and find where it leaks', N'Make the chosen workflow visible end to end, then locate the specific steps where time, confidence, or quality is lost.', N'Featured', N'Both', N'I run this recurring workflow: [describe the workflow, what triggers it, how often, and who depends on the output]. Here is a recent example of it going badly: [describe what happened]. Break the workflow into its actual steps. For each step, identify what input it needs, what decision it requires, and who owns it. Then tell me which two or three steps most likely cost time or quality, and why you think so. Ask me for anything you need rather than assuming it. Do not propose tools yet.', N'1. Describe the workflow and one recent example.
2. Run the prompt.
3. Correct the step map where the model got your work wrong; that correction is where the learning is.
4. Agree as a group which step leaks the most.', N'A recurring workflow you personally run; a recent concrete example; who owns each step; what inputs the workflow depends on.', N'A step-by-step map of the chosen workflow with the two or three highest-friction steps named.', N'The person who owns the workflow confirms the step map matches how the work is really done, not how it is supposed to be done.', N'Problem identification', N'Most workflow friction is invisible to the person living with it, because they have already adapted to it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ALL-USECASE-02', N'WF-X-USECASE-01', N'ALL-USECASE', N'PH-ALL-USECASE-EXPL', 2, N'Design one bounded experiment you can finish this week', N'Turn the highest-friction step into a test small enough to run before the next huddle and specific enough to judge.', N'Featured', N'Both', N'Here is the workflow step I want to test: [paste the step and why it costs time or quality]. Design a one-week experiment. Specify: the exact input I will supply, the action I will take, the output I expect, who reviews it before it is used, what evidence I will bring back, and the stop condition that tells me to abandon it. Keep it small enough to run in under an hour total. If the step as described is too large to test in a week, tell me how to narrow it rather than proposing a bigger plan.', N'1. Take the step your group identified.
2. Run the prompt.
3. Cut the experiment down until it fits in an hour.
4. Name your reviewer and your stop condition out loud.
5. Put it in your calendar before you leave the huddle.', N'The friction step from the previous activity; what data or systems you can actually access this week; who could review the output.', N'A bounded experiment card with input, action, output, reviewer, evidence, and stop condition.', N'You decide whether the experiment is genuinely small enough to finish, and you own the judgment about what output is safe to use in real work.', N'Planning and drafting', N'An experiment that does not fit in a week does not get run, and an experiment without a stop condition never ends.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-03-ALT-01', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'PH-ATS-WORKLOAD-EXPL', 3, N'Stress-test the workload readiness evidence', N'Test each ranked workload for the readiness evidence that exists, what is still unproven, and who would need to confirm it.', N'Extended', N'Prompt', N'Review this workload prioritization. For each ranked workload, identify the readiness evidence that exists, the impact assumption being made, what is still unproven, the dependency most likely to block it, and the person who would need to confirm it.', NULL, N'Draft workload ranking, readiness signals, and approved account context.', N'Workload readiness challenge list with unproven assumptions and named confirmation owners.', N'ATS confirms which assumptions must be validated before the ranking is allowed to influence technical strategy.', N'Assumption testing', N'A ranking built on unproven readiness sends technical effort to the wrong workload.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-03-ALT-02', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'PH-ATS-WORKLOAD-EXPL', 4, N'Package the workload decision brief', N'Assemble the ranked workloads, rationale, blockers and validation steps into a brief the v-team can decide from.', N'Extended', N'Prompt', N'Using the approved workload prioritization, create a decision brief with ranked workloads, rationale, owner, dependency, blocker, next validation step, and team ask.', NULL, N'Approved workload ranking and evidence.', N'Workload decision brief ready for team review.', N'ATS confirms priority, owner, dependency, and whether the team ask is realistic.', N'Synthesis and handoff', N'The priority is not real until the next action and owner are named.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-04-ALT-01', N'WF-X-ARCH-01', N'ATS-TECH', N'PH-ATS-TECH-EXPL', 4, N'Validate technical and business assumptions', N'Find the unsupported assumptions, unresolved risks and readiness gaps in a technical strategy before it is socialized.', N'Extended', N'Prompt', N'Review this technical strategy package. Identify unsupported assumptions, weak evidence, unresolved technical risks, customer readiness gaps, security or compliance dependencies, and decisions that require SME review.', NULL, N'Draft strategy package and source evidence.', N'Assumption and validation gap register.', N'ATS decides what to revise before sharing or acting.', N'Assumption testing', N'If the strategy is going to fail, it should fail here rather than in front of the customer.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-05-ALT-01', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 3, N'Validate briefing evidence and decisions', N'Check that the briefing is designed to move a specific customer decision and that its claims and participants support that.', N'Extended', N'Prompt', N'Review this EBC plan. Identify the customer decision it is designed to move, evidence gaps, unsupported technical or business claims, missing participants, and follow-through risks.', NULL, N'Draft EBC plan and approved evidence.', N'Briefing validation checklist and fix list.', N'ATS confirms which fixes are required before the briefing plan is used.', N'Validation and evidence', N'A briefing plan without evidence and follow-through becomes calendar management.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-05-ALT-02', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 4, N'Brief the contributors so they arrive ready', N'Give each contributor their objective, the evidence they own, the questions to expect and the time they have.', N'Extended', N'Prompt', N'Using the validated EBC plan, create a per-contributor brief that states the session objective, what each participant must prepare, the evidence they own, the questions they should expect, and the time they have.', NULL, N'Validated EBC plan and confirmed participant list.', N'Per-contributor briefing pack with owned evidence and time allocation.', N'ATS confirms each ask is realistic and that no contributor is asked to present unvalidated evidence.', N'Coordination and handoff', N'An executive briefing fails quietly when contributors arrive unclear about their part.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-05-ALT-03', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 5, N'Define follow-through and inspection rhythm', N'Turn briefing commitments into owners, checkpoint dates and the escalation triggers that keep them alive afterwards.', N'Extended', N'Prompt', N'Using the approved EBC plan, create a follow-through plan with decisions, commitments, owners, evidence required, checkpoint dates, risks, and escalation triggers.', NULL, N'Approved EBC plan and participant list.', N'Follow-through and inspection plan.', N'ATS validates ownership, timing, and escalation boundaries.', N'Follow-through planning', N'The briefing creates value only if the next decision survives after the session.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-06-ALT-01', N'WF-X-CONV-01', N'ATS-TALK', N'PH-ATS-TALK-EXPL', 3, N'Find the weak claims before the customer does', N'Audit the talk track claim by claim, separating what is evidenced from what rests on assumption or unshipped roadmap.', N'Extended', N'Prompt', N'Audit this talk track claim by claim. For each claim, state the evidence that supports it, whether that evidence is approved for customer use, and what a technically informed customer would ask for. Flag any claim that rests on assumption, marketing language, or a roadmap item rather than something available today.', NULL, N'Draft talk track, current customer signals, and approved evidence.', N'Claim-by-claim audit separating supported claims, unsupported claims, and roadmap-dependent claims.', N'ATS decides which challenges are real and validates any technical claim before it is used with the customer.', N'Validation and evidence', N'Executive credibility is lost on one unsupported claim, and roadmap language is the most common source.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-06-ALT-02', N'WF-X-CONV-01', N'ATS-TALK', N'PH-ATS-TALK-EXPL', 4, N'Package the technical conversation brief', N'Assemble the objective, signals, questions, objections and reviewed responses into one brief you can walk in with.', N'Extended', N'Prompt', N'Package the approved talk track into a conversation brief with objective, audience, customer signals, opening, key questions, likely objections, reviewed responses, roles, and follow-up ownership.', NULL, N'Approved talk track and meeting context.', N'Technical conversation brief.', N'ATS confirms claims, roles, and follow-up before sharing.', N'Synthesis and handoff', N'A talk track becomes useful when the team can align around it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-07-P02', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 2, N'Assess role coverage and handoffs', N'Identify missing role coverage and handoff risk.', N'Featured', N'Prompt', N'Review [Account or Opportunity]. Identify current AE, ATS, SSP, SE, CE, CSA, CSAM, partner, and investment coverage for the technical decision in front of the customer. Flag missing roles, unclear owners, dependency risks, and the next handoff that needs confirmation.', NULL, N'Account or opportunity; current team context; decision to move.', N'Role coverage and handoff map.', N'ATS confirms who owns each input, action, and decision.', N'Coverage inspection', N'You cannot orchestrate a team if the coverage gaps are invisible.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ATS-CBR-P01', N'WF-X-VALUE-01', N'ATS-CBR', N'PH-ATS-CBR-EXPL', 1, N'Create the technical CBR contribution', N'Draft the ATS portion of a customer business review.', N'Featured', N'Prompt', N'Using approved account and technical sources, draft the technical contribution for a CBR. Include customer objectives, roadmap, technical progress, proof, risks, open decisions, asks, and follow-through owners.', NULL, N'Approved account, roadmap, proof, risk, and outcome sources.', N'Technical CBR contribution.', N'ATS validates technical accuracy, claims, proof, and customer relevance.', N'Synthesis and drafting', N'The CBR needs the technical story connected to customer outcomes.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-CBR-P02', N'WF-X-VALUE-01', N'ATS-CBR', N'PH-ATS-CBR-EXPL', 2, N'Review technical claims and evidence', N'Check CBR technical content before sharing.', N'Featured', N'Prompt', N'Review this technical CBR contribution. Flag unsupported claims, missing evidence, unclear decisions, weak linkage to customer priorities, and follow-through gaps.', NULL, N'Draft technical CBR contribution and source evidence.', N'Claim and evidence review list.', N'ATS decides which claims to revise, remove, or route to SME review.', N'Validation and evidence', N'Unsupported technical claims weaken the whole customer review.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-CBR-P03', N'WF-X-VALUE-01', N'ATS-CBR', N'PH-ATS-CBR-EXPL', 3, N'Turn the hardest review questions into a readiness edit', N'Find the three questions the content invites, then change the contribution so it answers them before they are asked.', N'Featured', N'Both', N'Here is our technical contribution for a customer business review: [paste]. Identify the three hardest questions this content invites, including about progress that has been slower than planned and any risk we have named. For each question, state what evidence the content currently offers, whether that evidence is sufficient, and the specific edit to the contribution that would answer the question before it is asked. Return the edits as a numbered change list, not as a rewritten document. Do not treat a statement of intent as evidence.', N'1. Bring the reviewed CBR contribution.
2. Run the prompt.
3. Apply the edits where evidence exists.
4. For any question where evidence does not exist, decide whether to name the gap openly in the review or remove the claim.
5. Bring that decision to the huddle.', N'The technical CBR contribution; known risks and slow areas; who attends from the customer side; commitments made in prior reviews.', N'A numbered change list making the contribution answer its three hardest questions, plus any evidence gap named explicitly.', N'ATS decides whether to strengthen the evidence, name the gap openly, or remove the claim, and owns every technical statement made to the customer.', N'Validation and evidence', N'The credibility of a business review is decided by the answer to the uncomfortable question.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'ATS-CBR-P04', N'WF-X-VALUE-01', N'ATS-CBR', N'PH-ATS-CBR-EXPL', 4, N'Convert the review into technical decisions', N'Turn what was discussed into the decisions, owners, and dates that make the next review shorter.', N'Featured', N'Both', N'Here are the notes from the customer business review [paste]. Extract only the technical decisions that were actually made, the decisions that were deferred and why, and the ones that were avoided. For each open decision, state who needs to make it, what they need in order to make it, and by when it must happen to protect the roadmap. Do not record a decision as made if the notes show it was only discussed.', N'1. Capture review notes.
2. Run the prompt.
3. Separate made, deferred, and avoided.
4. Assign the top open decision an owner and date.
5. Confirm it with the customer.', N'Review notes; attendees; the roadmap and its dependencies; commitments made in prior reviews.', N'Separated lists of made, deferred, and avoided decisions, with owners and dates for the open ones.', N'ATS confirms which decisions were genuinely made and owns the follow-up commitments before they are shared.', N'Synthesis and drafting', N'A review that produces no decision guarantees the same conversation next quarter.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-HEALTH-P01', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'PH-ATS-HEALTH-EXPL', 1, N'Prioritize technical health risks', N'Create a ranked technical risk response.', N'Featured', N'Prompt', N'Review available account, usage, deployment, support, and technical context. Identify the top technical health risks, evidence, impact, owner, intervention, and next checkpoint. Flag missing data.', NULL, N'Authorized account, usage, deployment, support, and technical context.', N'Ranked technical risk response.', N'ATS validates risk significance, owner, and intervention.', N'Risk inspection', N'A technical risk only matters when someone decides what to do about it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-HEALTH-P02', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'PH-ATS-HEALTH-EXPL', 2, N'Coordinate the technical risk intervention', N'Turn a reviewed risk into a coordinated action plan.', N'Featured', N'Prompt', N'Using the reviewed technical risk response, create an intervention plan with owners, dependencies, customer communication needs, escalation triggers, and checkpoint dates.', NULL, N'Reviewed technical risk response and role context.', N'Technical risk intervention plan.', N'ATS confirms owners, dependencies, and escalation path.', N'Orchestration', N'Risk response usually fails at the handoff, not the diagnosis.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-HEALTH-P03', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'PH-ATS-HEALTH-EXPL', 3, N'Raise the risk with the customer before it becomes news', N'Draft the message that tells the customer about a technical risk early, in a way that keeps trust rather than spending it.', N'Featured', N'Both', N'We have identified this technical health risk: [paste risk, evidence, impact, and what we are doing]. Draft a short message to the customer technical owner that states the risk plainly, what we know and do not yet know, what we are already doing, what we need from them, and when we will update them next. Do not minimize the risk, do not over-apologize, and do not commit to a resolution date we have not agreed internally. Keep it under 150 words.', N'1. Bring the ranked risk and intervention plan.
2. Confirm internally what can be committed.
3. Run the prompt.
4. Adjust to your relationship with the customer.
5. Send, and diarize the next update.', N'The identified risk and its evidence; the intervention plan; what has been agreed internally; the customer relationship and prior communications.', N'A short, honest customer message with a named next update date.', N'ATS confirms no commitment is made that has not been agreed internally, and owns the decision to communicate and the wording.', N'Synthesis and drafting', N'A risk the customer hears about from us early costs far less than one they discover themselves.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-HEALTH-P04', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'PH-ATS-HEALTH-EXPL', 4, N'Find the risk the data does not show', N'Test the health assessment against what people have said, not only against what the systems report.', N'Featured', N'Both', N'Here is our current technical health assessment based on system data: [paste]. Here are recent notes and conversations with the customer team: [paste]. Identify concerns raised by people that do not appear in the system data, and any system signal that people are not talking about. For each mismatch, say which source is more likely to be right and what would confirm it. Do not treat silence as agreement.', N'1. Bring the data-based assessment.
2. Gather recent conversation notes. If dashboard or transcript access is unavailable, build a lightweight table by hand with source, date, owner, evidence, and your confidence in it, then use that instead.
3. Run the prompt.
4. Pick the mismatch that would hurt most if ignored.
5. Add it to the risk list or record why not.', N'System-derived health assessment, or a hand-built substitute table if system access is unavailable; recent conversation notes with the customer team; who has been quiet and who has been raising concerns.', N'A list of mismatches between reported data and human signals, with what would confirm each.', N'ATS judges which human signal is credible and owns the decision to add or dismiss a risk.', N'Analysis and assessment', N'The risks that damage accounts are usually mentioned in conversation long before they appear in a dashboard.', N'https://m365.cloud.microsoft/chat', N'Open Analyst'),
        (N'ATS-INTEL-SCOUT-01', N'WF-X-PLAN-01', N'ATS-INTEL', N'PH-ATS-INTEL-EXPL', 4, N'Build a standing account intelligence hub the v-team can use', N'Consolidate the scattered sources behind account planning into one maintained hub that refreshes rather than being rebuilt each planning cycle.', N'Extended', N'Both', N'Build me a standing account intelligence hub for this account. Pull together the business context, current opportunities, stakeholder map, installed estate and licensing position, recent engagement history, and open risks into one structured place. Then keep it current on a recurring basis and tell me specifically what changed since the last refresh. Where a source is unavailable to you, list it as a gap rather than filling it with inference.', N'1. Confirm which account planning sources you can reach, and name the ones you cannot.
2. Run the prompt.
3. Review the first hub build against what you already know about the account.
4. Check that nothing customer-confidential has been placed where the wider v-team should not see it.
5. Set the refresh cadence and agree with the v-team who reads the change summary.', N'The account name; access to your account planning sources; the v-team members who need visibility.', N'A maintained account intelligence hub with a change summary each refresh and an explicit list of unavailable sources.', N'ATS reviews the hub for accuracy before sharing with the v-team, and confirms that no customer-confidential material has been placed where it should not sit.', N'Research and synthesis', N'Account planning quality is usually limited by assembly time, not thinking time. When the assembly is standing and self-refreshing, the v-team spends its hour on the judgement instead of the gathering.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'ATS-INVEST-01-P01', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 1, N'Assess strategic and technical investment fit', N'Test whether the investment advances the account technology strategy.', N'Featured', N'Prompt', N'Review this proposed customer investment. Assess fit against account technology strategy, priority workloads, customer readiness, deployment blockers, expected technical outcome, consumption path, dependencies, and risks. Recommend proceed, revise, or pause for review.', NULL, N'Investment idea or request; account technology plan; workload priorities; readiness and blocker context.', N'Strategic and technical investment fit assessment.', N'ATS validates strategy fit, technical feasibility, dependencies, and recommendation. Final funding decisions remain with accountable owners.', N'Investment assessment', N'Testing investment fit early prevents technical time from being spent on low-value work.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ATS-INVEST-01-P02', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 2, N'Validate engagement scope and consumption readiness', N'Assess whether the funded engagement can deliver the intended outcome.', N'Featured', N'Prompt', N'Review the proposed engagement scope, milestones, deliverables, success criteria, deployment path, partner readiness, customer readiness, and consumption drivers. Identify gaps, risks, and fixes needed before request review.', NULL, N'Draft scope; milestones; deliverables; success criteria; readiness context.', N'Scope and consumption-readiness review.', N'ATS confirms technical content and readiness; eligibility, approval, policy, and commercial decisions remain with accountable owners.', N'Validation and evidence', N'Unclear scope becomes rework at approval or delivery.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ATS-INVEST-01-P03', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 3, N'Build the investment review recommendation', N'Package the recommendation for the human decision owner.', N'Featured', N'Prompt', N'Using the reviewed investment assessment, create a concise recommendation package with strategic rationale, technical outcome, scope concerns, dependencies, risks, required reviewers, open questions, and the next governed decision.', NULL, N'Reviewed investment assessment and supporting evidence.', N'Investment review recommendation package.', N'ATS validates claims and routes approval questions to the correct owner before use.', N'Synthesis and drafting', N'The goal is not to approve inside the prompt. The goal is to make the next governed decision easier.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'ATS-INVEST-01-P04', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 4, N'Track investment dependencies and realization evidence', N'Create a lightweight evidence and dependency rhythm.', N'Featured', N'Prompt', N'Create an investment follow-through tracker with dependency, owner, milestone, evidence required, risk, decision needed, checkpoint date, and realization signal.', NULL, N'Approved or draft investment plan; owners; milestones; expected outcomes.', N'Investment dependency and evidence tracker.', N'ATS confirms ownership, evidence quality, and escalation path.', N'Monitoring and follow-through', N'Investment value is proven with evidence gathered along the way, not reconstructed at the end.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-INVEST-01-P05', N'WF-INVEST-01', N'ATS-INVEST', N'PH-ATS-INVEST-EXPL', 5, N'Prove the investment produced the technical outcome', N'Collect the technical evidence that the investment delivered what it was funded to deliver, and name what it did not.', N'Featured', N'Both', N'This investment was funded to achieve [paste the original technical outcome and success measures]. Here is what has happened since: [paste delivery status, milestones from ECIF Central, and any technical results]. Assess each success measure as met, partially met, or not met, with the evidence for each judgment. Where a measure cannot be evidenced, say so rather than inferring it. Identify what would need to be true for this to count as a technical success, and what the customer would say if asked independently.', N'1. Retrieve the original success measures from the approved workscope.
2. Gather delivery status and milestones from ECIF Central.
3. Run the prompt.
4. Be honest about measures that cannot be evidenced.
5. Bring the unmet ones to the account team before the realization review, not during it.', N'The original technical outcome and success measures from the workscope. Delivery status and milestones from ECIF Central. Technical results to date.', N'Each success measure assessed with evidence, and an explicit list of what cannot be evidenced.', N'ATS owns the technical judgment about whether an outcome was genuinely achieved, and does not let an unevidenced measure be reported as met.', N'Validation and evidence', N'Investment that cannot be evidenced makes the next request harder for everyone on the account.', N'https://aka.ms/ECIFCentral', N'Open ECIF Central'),
        (N'ATS-PARTNER-P01', N'WF-X-ORCH-01', N'ATS-PARTNER', N'PH-ATS-PARTNER-EXPL', 1, N'Identify partner and specialist capability gaps', N'Assess what support is needed for the technical priority.', N'Featured', N'Prompt', N'For [Account or Opportunity], summarize the technical priority, current roles involved, missing capability, partner or specialist support needed, timing, risks, and next decision. Recommend the role needed, not a specific partner unless supported by available data.', NULL, N'Account or opportunity context; technical priority; role coverage.', N'Capability gap and support need assessment.', N'ATS validates capability need, timing, and whether partner involvement is appropriate.', N'Coverage inspection', N'Support should be attached to the technical priority, not added by habit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'ATS-PARTNER-P02', N'WF-X-ORCH-01', N'ATS-PARTNER', N'PH-ATS-PARTNER-EXPL', 2, N'Prepare the support alignment note', N'Create an internal alignment note for partner or specialist support.', N'Featured', N'Prompt', N'Using the reviewed support need, draft an internal alignment note with customer outcome, technical priority, expected contribution, required preparation, owner, timing, and next decision.', NULL, N'Reviewed support need and approved account context.', N'Support alignment note.', N'ATS validates claims, owners, timing, and sensitivity before sending.', N'Synthesis and handoff', N'Clear asks make it easier for partners and specialists to contribute at the right time.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-PARTNER-P03', N'WF-X-ORCH-01', N'ATS-PARTNER', N'PH-ATS-PARTNER-EXPL', 3, N'Brief the specialist so they arrive useful', N'Build the short briefing that lets a partner or specialist contribute in their first meeting rather than spending it catching up.', N'Featured', N'Both', N'A [role] is joining to support this technical priority. First tell me: are they an internal Microsoft specialist or an external partner? I will answer, and you will adjust what may be included accordingly. Here is the context: [paste priority, customer context, and what has already been tried]. Write the briefing they need before their first customer meeting. Include: the customer''s outcome in their own words, what has already been attempted and why it did not close the gap, the technical constraints that are fixed, who they will meet and what each person cares about, the specific contribution we need from them, and what they should not commit to. If the recipient is external, generalize or remove customer-identifying detail, internal roadmap references, unannounced product information, and named technical risks, and list separately what I removed so I can decide whether to share it another way. Keep it under 300 words and assume they have no history with this account.', N'1. Bring the capability gap assessment and alignment note.
2. Classify the recipient as internal specialist or external partner before writing anything.
3. Run the prompt.
4. Review the removed-items list and decide what, if anything, to share through an approved channel.
5. Send it before the meeting, not during.
6. Ask them what is still unclear.', N'Whether the recipient is an internal Microsoft specialist or an external partner; the technical priority and customer outcome; what has been tried; fixed constraints; the stakeholders they will meet; the sensitivity classification of any account detail.', N'A short standalone briefing appropriate to the recipient type, plus a separate list of anything withheld because the recipient is external.', N'ATS classifies the recipient as internal or external before drafting, then confirms that no customer-identifying detail, roadmap reference, or named technical risk reaches an external partner without approval, and confirms what the recipient may and may not commit to.', N'Coordination and handoff', N'An unbriefed specialist spends their first customer meeting learning what you already knew.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'ATS-PARTNER-P04', N'WF-X-ORCH-01', N'ATS-PARTNER', N'PH-ATS-PARTNER-EXPL', 4, N'Check whether the support actually moved the priority', N'Review what changed after partner or specialist involvement, so the next request is based on evidence rather than habit.', N'Featured', N'Both', N'Gather what has happened on this account since [date] from my recent meetings, notes, chats, and files, and summarize it against this original capability gap and ask: [paste original gap and what we asked for]. Then assess whether the gap is now closed, partially closed, or unchanged, and what evidence supports that judgment. If it is unchanged, identify whether the problem was the brief, the fit, the timing, or the gap itself being misdiagnosed. If you cannot find enough recent activity to judge, say so rather than inferring. Be direct.', N'1. Restate the original gap and ask.
2. Let the agent gather recent activity, or supply it manually if the agent cannot reach the sources.
3. Run the prompt.
4. Decide whether to continue, change the ask, or stop.
5. Record the lesson for the next request.', N'The original capability gap and the ask made; the date support began; access to recent meetings, notes, and files, or a manual summary if access is unavailable; the current state of the technical priority.', N'A judgment on whether the gap closed, with evidence, and a diagnosis if it did not.', N'ATS owns the assessment of a colleague''s or partner''s contribution and decides how, or whether, it is shared.', N'Inspection and review', N'Support gets added by habit unless someone checks whether the last one worked.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'ATS-TEAM-P05', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 5, N'Keep the v-team commitments moving between huddles', N'Set up a recurring check that watches the technical v-team commitments and tells you what has slipped, without you having to go looking.', N'Extended', N'Both', N'Set up a recurring check on the technical v-team commitments for [Account or opportunity]. Each week, look across our meetings, mail and the account record for the commitments made, and tell me which ones have no activity since they were made, which have passed their date, and which have gone quiet on the customer side. Give me the specific chase for each one and who should make it. Keep a memory of what you already flagged so you are not repeating the same item back to me every week.', N'1. Bring the current v-team commitments with owners and dates.
2. Run the prompt.
3. Confirm each flagged commitment is genuinely stalled rather than progressing somewhere you cannot see.
4. Set the cadence to run before your v-team call.
5. Raise slipped items with the owner directly rather than in the group thread.', N'The v-team commitments and owners from the alignment brief; approved access to your own mail, meetings and account record.', N'A recurring commitment check that reports slipped, stalled and quiet items with a named chase for each.', N'ATS decides whether silence actually means a stall, and owns the judgment about which chases are appropriate given the relationships involved.', N'Monitoring and follow-through', N'Technical commitments do not fail loudly. They go quiet, and by the time anyone notices the customer has moved on. This is exactly the persistent, between-sessions work that Scout is built for.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CE-01-ALT-01', N'WF-X-HEALTH-01', N'CE-HEALTH', N'PH-CE-HEALTH-EXPL', 3, N'Stress-test assumptions behind the commercial risk view', N'Find the unsupported assumptions, stale sources and missing owners that would change your commercial risk recommendation.', N'Extended', N'Prompt', N'Review the commercial risk view for unsupported assumptions, stale sources, missing owners, policy dependencies, approval needs, and customer constraints. Identify what would change the intervention recommendation.', NULL, N'The prioritized commercial risk view; the source and date behind each item; the customer constraints you know of.', N'Commercial assumption and risk register with evidence gaps, owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the commercial risk view will fail, it should fail in review rather than at approval or with the customer.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-01-ALT-02', N'WF-X-HEALTH-01', N'CE-HEALTH', N'PH-CE-HEALTH-EXPL', 4, N'Create the intervention and escalation plan', N'Turn prioritized commercial risks into owned actions, keeping internal steps separate from anything the customer is asked to do.', N'Extended', N'Prompt', N'Translate the prioritized commercial risks into owners, next actions, approval steps, customer actions, escalation route, and inspection points. Separate internal actions from customer actions.', NULL, N'The validated commercial risk view; the approval owners; the escalation route your team actually uses.', N'Commercial intervention plan with owners, actions, escalation route, and inspection points.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Risk without owner, action, and route is just a warning label.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-02-ALT-01', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 4, N'Stress-test commercial structure assumptions', N'Find the precedent risk, customer constraints and approval dependencies a proposed commercial structure is quietly assuming away.', N'Extended', N'Prompt', N'Review the proposed commercial structure for unsupported assumptions, customer constraints, policy dependencies, approval needs, precedent risk, and unresolved decisions.', NULL, N'The proposed commercial structure; the approval requirements it triggers; known customer constraints and precedent concerns.', N'Commercial structure assumption register with risks, evidence gaps, and decision owners.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the structure will fail, it should fail while options still exist.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-02-ALT-02', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 5, N'Build the commercial structure execution plan', N'Turn the selected commercial direction into owners, approval steps and inspection points that survive contact with the deal timeline.', N'Extended', N'Prompt', N'Translate the selected commercial direction into owners, approval steps, dependencies, customer actions, internal actions, and inspection points.', NULL, N'The selected commercial structure; the approval path and its lead times; internal and customer action owners.', N'Commercial structure execution plan with owners and approval path.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'The structure is not real until the approval path and owners are real.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-02-BYOD-01', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 2, N'Build an MCA-E proposal from a validated product list you already have', N'Bring your own product data into proposal creation for an MCA-E or EA to MCA-E transition, and resolve what does not map before it reaches the customer.', N'Featured', N'Both', N'I have product and quantity data for an MCA-E proposal in a spreadsheet. Walk me through bringing it in: what format you need, how you will validate the SKUs and products against the agreement, and what happens to anything that does not match. Then generate the draft proposal in MSX from the validated inputs. List every unmatched product separately so I can resolve it, and tell me if the upload has to be split across multiple proposals to stay within platform limits. Do not drop unmatched items silently.', N'1. Prepare the product and quantity data as Excel or CSV.
2. Run the prompt and follow the validation guidance.
3. Review the unmatched product list; those are the ones that will cause problems later.
4. Resolve or consciously defer each one.
5. Generate the draft proposal in MSX.
6. Check the proposal against the customer''s actual commercial expectation before it goes anywhere.', N'Product and quantity data in Excel or CSV. The MCA-E agreement or the EA being transitioned. The opportunity the proposal attaches to.', N'A validated input set, a named list of unmatched products for follow-up, and a draft proposal in MSX ready for commercial review.', N'CE confirms the SKU mapping is commercially correct rather than merely valid, resolves unmatched products rather than accepting the gap, and owns the pricing and structure before the proposal reaches the customer.', N'Execution and validation', N'Unmatched products found before proposal creation are a cleanup task. Found after, they are a customer conversation.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-02-DEAL-01', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 1, N'Create and validate the deal path', N'Role-relevant Deal Making capabilities practice within the recommended Role Path.', N'Featured', N'Prompt', N'Using the approved agreement or enrollment context, review deal assumptions and create or revise the appropriate deal-book or proposal path. Include options, dependencies, validation issues, authority boundaries, and required approvals. Do not submit or approve deal artifacts.', NULL, N'Approved agreement or enrollment identifier, deal strategy, pricing context, and approval constraints.', N'Reviewable deal path with options, proposal or deal-book artifact, validation findings, and approval requirements.', N'CE validates commercial accuracy, pricing, exception handling, approval path, and any customer-facing use before progressing the deal.', N'Synthesis and drafting', N'You spend your time editing the deal path rather than staring at a blank version of it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-03-ALT-01', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 3, N'Stress-test policy and licensing assumptions', N'Identify where a policy or licensing conclusion rests on stale guidance or an assumption no authoritative owner has confirmed.', N'Extended', N'Prompt', N'Review the policy and licensing check for unsupported assumptions, stale guidance, missing evidence, unresolved exceptions, and questions that require authoritative review.', NULL, N'The policy and licensing check; the guidance sources used and their dates; the authoritative owners for each open question.', N'Policy assumption register with evidence gaps, authoritative owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the policy interpretation is uncertain, that uncertainty should be explicit before the deal advances.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-03-ALT-02', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 4, N'Create the policy routing and execution plan', N'Route each open policy question to its authoritative owner with the evidence they need, without implying an approval that has not happened.', N'Extended', N'Prompt', N'Translate the policy and licensing findings into routed questions, owners, evidence needed, approval steps, and execution checkpoints. Do not infer approval or exception status.', NULL, N'The policy and licensing findings; the authoritative owner for each question; the deal timeline the answers must meet.', N'Policy routing and execution plan with owners, evidence, and checkpoints.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Policy work moves when the question, owner, and evidence are explicit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-04-ALT-01', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 5, N'Stress-test negotiation assumptions', N'Test the concession logic and authority boundaries in a negotiation plan before customer pressure exposes them.', N'Extended', N'Prompt', N'Review the negotiation plan for unsupported commercial assumptions, customer constraints, policy dependencies, approval needs, concession risks, and unresolved authority boundaries.', NULL, N'The negotiation plan with its concession logic; your confirmed authority limits; known customer constraints and alternatives.', N'Negotiation assumption register with authority gaps, concession risks, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the negotiation position will fail, it should fail in rehearsal rather than across the table.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-04-ALT-02', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 6, N'Build the negotiation follow-through plan', N'Define who does what after the negotiation, including concession checkpoints and the triggers that force an escalation.', N'Extended', N'Prompt', N'Translate the negotiation position into owners, customer actions, internal approval steps, concession checkpoints, escalation triggers, and follow-through dates.', NULL, N'The agreed negotiation position; the approval owners; the customer commitments and dates already made.', N'Negotiation follow-through plan with owners, checkpoints, and escalation triggers.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Negotiation discipline survives only when follow-through is explicit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-05-ALT-01', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 5, N'Stress-test approval and execution assumptions', N'Find where an approval path assumes an owner, an evidence item or an exception that nobody has actually confirmed.', N'Extended', N'Prompt', N'Review the approval and commercial execution path for unsupported assumptions, missing evidence, unclear owners, policy dependencies, exception triggers, and unresolved decisions.', NULL, N'The commercial execution path; the approval record as it stands; the exception triggers your team must respect.', N'Approval and execution assumption register with evidence gaps, owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If approval will fail, it should fail before the package reaches the approver.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-05-ALT-02', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 3, N'Build the approval and execution plan', N'Turn a commercial direction into a governed execution plan that never represents approval as granted unless the record confirms it.', N'Extended', N'Prompt', N'Translate the commercial direction into owners, approval steps, evidence needed, dependencies, customer actions, internal actions, escalation route, and inspection points. Do not represent approval as granted unless the authoritative record confirms it.', NULL, N'The commercial recommendation; the authoritative approval record; the owners for each approval step and customer action.', N'Governed commercial execution plan with owners, approval path, blockers, and next decision.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Commercial execution stalls when the route, owner, and evidence are implied.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-05-ECIF-01', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 1, N'Clarify ECIF commercial and approval dependencies', N'Role-relevant ECIF practice within the recommended Role Path.', N'Featured', N'Prompt', N'Using approved deal and ECIF context, summarize commercial dependencies, approval touchpoints, communication constraints, evidence needs, and unresolved questions that require ECIF, finance, Deal Desk, or policy-owner review. Do not imply funding, policy, or approval authority without explicit evidence.', NULL, N'Approved deal context, current ECIF status, and authoritative guidance.', N'Commercial dependency and escalation brief with owners, evidence needs, and next decisions.', N'CE confirms whether the scenario is within CE accountability and does not imply funding, policy, or approval authority without explicit evidence.', N'Scoping and design', N'ECIF dependencies move faster when the commercial question, owner, and evidence are visible early.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-05-ORCH-01', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 2, N'Map the approval path and the evidence each approver needs', N'Build the approval sequence for the commercial structure, with owners, evidence, and timing. Assumes policy and licensing questions have already been routed.', N'Featured', N'Prompt', N'Using approved deal context, map the approval path for this commercial structure: each approval required, the accountable owner, the evidence or justification that approver expects, the sequence and dependencies, the rework risk, and a realistic timeline. Do not interpret pricing, discount, or policy rules; route those to the authoritative owner.', NULL, N'Approved deal context, proposed commercial structure, and current approval guidance.', N'Approval path with owners, required evidence, sequence, dependencies, and timeline risk.', N'CE verifies approval requirements against authoritative guidance and routes pricing, discount, and policy interpretation to the accountable owner rather than answering them.', N'Scoping and design', N'Approvals discovered one at a time cost weeks. Approvals mapped up front cost a conversation.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-06-ALT-01', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 4, N'Stress-test renewal strategy assumptions', N'Challenge the value evidence, expansion claims and approval assumptions in a renewal strategy before they reach the customer.', N'Extended', N'Prompt', N'Review the renewal strategy for unsupported commercial assumptions, value evidence gaps, customer constraints, policy dependencies, approval needs, expansion claims, and unresolved decisions.', NULL, N'The renewal strategy; the value evidence behind each claim; the approval requirements and customer constraints.', N'Renewal assumption and risk register with evidence gaps, owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'If the renewal strategy will fail, it should fail while there is still time to change it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-06-ALT-02', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 5, N'Build the renewal execution plan', N'Convert the renewal strategy into owners, approval steps and timing checkpoints that hold against the renewal date.', N'Extended', N'Prompt', N'Translate the renewal strategy into owners, approval steps, customer actions, internal actions, dependencies, inspection points, and timing checkpoints.', NULL, N'The validated renewal strategy; the renewal date and approval lead times; the internal and customer owners.', N'Renewal execution plan with owners, approval path, actions, and checkpoints.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A renewal strategy becomes executable only when owners and checkpoints are explicit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-06-SCOUT-01', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 3, N'Watch the renewal portfolio for commercial trigger dates', N'Set up a standing check across your renewal portfolio so commercial trigger dates surface with enough runway to act on them.', N'Featured', N'Both', N'Set up a recurring check across my renewal portfolio. Each week, tell me which agreements are approaching a commercial trigger date, which have consumption or usage moving in a direction that changes the commercial position, and which have an approval dependency that has not started yet. Rank by how much runway is left rather than by value. Do not interpret pricing or policy; where a question needs an authoritative answer, name the owner instead.', N'1. Bring your renewal portfolio with dates and the current approval requirements.
2. Run the prompt.
3. Confirm the runway ranking matches your own read on which renewals are genuinely tight.
4. Set the cadence far enough ahead of approval lead times to be useful.
5. Route pricing, discount and policy questions to the accountable owner rather than answering them yourself.', N'Your renewal portfolio with dates; approved consumption and usage data; the current approval requirements.', N'A recurring portfolio check ranked by remaining runway, with approval dependencies and the owner for each open question.', N'CE confirms the commercial reading of every flagged item and routes pricing, discount and policy interpretation to the accountable owner rather than acting on the output.', N'Monitoring and signal', N'Commercial leverage is a function of how early you saw it coming. A renewal found with three weeks left is a different negotiation from the same renewal found with three months.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CE-07-ALT-01', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 4, N'Stress-test agreement transition assumptions', N'Surface the timing risk, customer constraints and policy dependencies hiding in a proposed agreement or commerce transition.', N'Extended', N'Prompt', N'Review the proposed agreement or commerce transition for commercial assumptions, customer constraints, policy dependencies, approval needs, timing risk, and unresolved questions.', NULL, N'The proposed transition; the current agreement terms and dates; the policy dependencies and approval needs.', N'Agreement transition assumption register with risks, owners, and required decisions.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Assumption testing', N'Agreement transitions fail when unstated assumptions become customer-facing commitments.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CE-07-ALT-02', N'WF-X-ORCH-01', N'CE-ORCH', N'PH-CE-ORCH-EXPL', 6, N'Build the agreement transition execution plan', N'Sequence the agreement transition into owners, approval steps and decision gates tied to the dates that cannot move.', N'Extended', N'Prompt', N'Translate the agreement or commerce transition direction into owners, approval steps, customer actions, internal actions, dependencies, checkpoints, and decision gates.', NULL, N'The validated transition approach; the agreement dates that constrain it; internal and customer owners for each step.', N'Agreement transition execution plan with owners, approval path, dependencies, and checkpoints.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A transition plan holds only when the owners, checkpoints, and decision gates are explicit.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-INVEST-01-P01', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 1, N'Identify commercial and policy dependencies for the investment', N'Surface the commercial, agreement, exception and approval questions an investment path will encounter, using authoritative guidance only.', N'Featured', N'Prompt', N'Using current approved guidance, identify commercial, policy, agreement, exception, or approval questions that may affect the investment path. Do not interpret policy beyond authoritative sources or approve exceptions.', NULL, N'Proposed investment, customer and agreement context', N'Commercial and policy dependency brief with authoritative questions and owners.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Problem identification', N'Naming commercial and policy dependencies early prevents investment rework later.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CE-INVEST-01-P02', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 2, N'Clarify approval and exception handoffs', N'Map the approvals, exception triggers and evidence needs for an investment without assigning authority that policy has not confirmed.', N'Featured', N'Prompt', N'Map the known approvals, exception triggers, evidence needs, owners, and escalation questions for the investment without assigning authority not confirmed by policy.', NULL, N'Request stage, known policy constraints, unresolved exceptions', N'Approval and exception handoff map with evidence needs, owners, and open questions.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Scoping and design', N'Approval and exception handoffs hold only when authority and evidence are explicit.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CE-INVEST-01-P03', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 3, N'Assess the commercial shape of the investment', N'Test whether the proposed investment structure holds up commercially before it reaches approval.', N'Featured', N'Prompt', N'Review the proposed investment against the customer agreement, term, commercial structure, exception risk, precedent risk, and current approved guidance. Cite authoritative guidance and flag anything you cannot confirm.', NULL, N'Proposed investment, agreement and term context, current approved guidance', N'Commercial structure assessment with precedent risks, exception questions, and cited guidance.', N'Confirm the grounding sources, separate evidence from assumption, and validate the named owner and next decision before this reaches a customer or an approver.', N'Analysis and assessment', N'Working through the commercial shape of the investment forces a position, and a position is what the decision needs.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-INVEST-01-P04', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 4, N'Track the approval path and unblock the next decision', N'Follow an in-flight investment request through approval and identify what is actually holding it.', N'Featured', N'Both', N'For the in-flight investment request, summarize the approval stage, evidence supplied, outstanding items, known owner, and next decision. Do not represent any approval as granted unless confirmed by the authoritative record.', N'1. Ask ECIF Agent via Sales Agent for the current approval stage and outstanding items.
2. Review against your own record of what was submitted.
3. Open ECIF Central where approval detail is not answerable from the summary.
4. Identify the single blocking item and its owner.
5. Route the missing evidence request.', N'Approved request status, policy constraints, approval stage', N'Approval-path status with blocking item, owner, evidence needed, and next decision.', N'Confirm status and milestone data against the authoritative record before acting or reporting. Do not infer financial yield or approval state from a summary.', N'Monitoring and signal', N'With approval-path tracking, the blocker finds you instead of you remembering to go look.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CE-INVEST-01-P05', N'WF-INVEST-01', N'CE-INVEST', N'PH-CE-INVEST-EXPL', 5, N'Find where the approval is actually stuck', N'Work out which approval a request is waiting on, who holds it, and what would move it, rather than waiting for it to surface.', N'Featured', N'Both', N'For investment request [request ID or opportunity], I need to work out what is blocking approval. Here is the current status from the tracker: [paste]. Identify which approval it is waiting on, what evidence that approver typically needs, what in our submission is likely to be the sticking point, and what the fastest legitimate way to unblock it is. Distinguish between a request that is genuinely progressing and one that has stalled. Do not represent anything as approved, and do not suggest routing around an approver.', N'1. Open the request in MSX Deal Assistance and read the tracker view for stage, owner, and blockers.
2. Run the prompt with that status.
3. Decide whether it is progressing or stalled.
4. If stalled, contact the named owner with the specific evidence gap rather than a status request.
5. If blocked on access or tooling, use MCAPS Help.', N'The request ID and its current tracker status. The submitted package. Knowledge of the approval path for this request type.', N'A clear read on whether the request is progressing or stalled, the specific blocker, its owner, and one action to unblock it.', N'CE owns the judgment about whether a delay is normal or a genuine block, and never routes around an approver or represents an approval that has not been given.', N'Inspection and review', N'Requests rarely get rejected. They go quiet, and quiet looks like progress until the customer asks.', N'https://microsoftsales.crm.dynamics.com/main.aspx?appid=fe0c3504-3700-e911-a849-000d3a10b7cc&forceUCI=1&pagetype=entitylist&etn=opportunity&viewid=00000000-0000-0000-00aa-000010003000&viewType=1039', N'Open MSX Opportunities'),
        (N'CE-INVLINK-01', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 5, N'Check the investment path against policy and approval requirements', N'Surface the commercial and policy dependencies that an investment request will meet.', N'Featured', N'Prompt', N'Using current approved guidance, identify the policy, licensing, agreement, exception, or approval questions that a proposed customer investment would raise, the approval path it would follow, and the authoritative owner of each question. Cite the guidance used and flag anything you cannot confirm. Do not infer eligibility, exception, funding, or approval status.', NULL, N'Proposed investment, customer agreement context, current approved guidance', N'Dependency and approval map for the investment with cited guidance, named owners, and unresolved questions.', N'CE confirms every interpretation against an authoritative source and approves no exception here.', N'Surface the commercial and policy dependencies that an investment request will meet.', N'Clearing the investment path early prevents approval rework without overstating authority.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CE-POLICY-SCOUT-01', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 6, N'Track commercial policy and licensing changes that affect your accounts', N'Set up a monitored, source-locked watch on the commercial policy and licensing guidance you rely on, so changes reach you before a customer raises them.', N'Extended', N'Both', N'Set up a recurring check against a fixed list of authoritative Microsoft commercial policy and licensing sources that I will confirm with you first. Each time, report only what has changed, quote the change, cite the source, and state plainly which of my accounts it plausibly affects and why. Do not interpret the change into commercial advice and do not draw on any source outside the confirmed list. Where the implication is unclear, say so and name the owner who can rule on it.', N'1. Agree the fixed list of authoritative policy and licensing sources with your team before you enable anything.
2. Run the prompt with that confirmed list.
3. Check the first digest quotes and cites each change rather than paraphrasing it.
4. Set the cadence and confirm the watch is not drawing on sources outside the agreed list.
5. Route every interpretation to the accountable policy owner rather than acting on the summary.', N'The authoritative policy and licensing sources your team treats as canonical; your account list; your escalation owners.', N'A recurring change-only digest quoting and citing each change, with plausible account impact and the named owner for anything requiring a ruling.', N'CE confirms the source list before the watch is enabled, and routes every interpretation to the accountable policy owner rather than acting on the summary.', N'Monitoring and signal', N'Commercial policy changes are only a problem when the customer knows before you do. A locked source list is what separates a reliable watch from confident invention.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSA-01-ALT-01', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 4, N'Validate the technical health evidence', N'Separate what the health signals actually evidence from what the team has been assuming, before a risk is escalated.', N'Extended', N'Prompt', N'Review the technical health assessment. For each risk, state the signal that evidences it, how current that signal is, and what is inference rather than observation. Identify the risks whose evidence would not survive a customer challenge, and name what would be needed to confirm them.', NULL, N'The technical health and risk view; the telemetry and support signals behind it; the customer constraints that limit your options.', N'A technical health evidence map separating observed signal from inference, with the confirmation needed for each weak item.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Assess Customer Technical Health and Prioritize Risk now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-01-ALT-02', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 5, N'Design the technical risk intervention plan', N'Turn the prioritized technical risks into sequenced interventions with owners and checkpoints that show whether they worked.', N'Extended', N'Prompt', N'Turn the prioritized technical risks into a sequenced intervention plan. For each risk, define the specific technical action, the owner, the dependency that could block it, the checkpoint date, and the evidence that will show the intervention worked. Sequence by which risk becomes customer-visible soonest.', NULL, N'The validated technical risk list; the delivery and customer owners available; the checkpoints already in the engagement rhythm.', N'A sequenced technical intervention plan with owners, dependencies, checkpoint dates, and success evidence per risk.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Assess Customer Technical Health and Prioritize Risk before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-02-ALT-01', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 5, N'Validate the architecture evidence before the design is shared', N'Find the unsupported assumptions and unresolved dependencies in a production design before it reaches the customer.', N'Extended', N'Prompt', N'Review the production architecture package. Identify assumptions presented as requirements, dependencies with no named owner, non-functional requirements with no validation step, and any option comparison that does not map to the customer decision criteria. Name what must be proven before this design is committed.', NULL, N'The production architecture package; the constraints and non-functional requirements it assumes; the validation steps already planned.', N'An architecture assumption and dependency review naming what must be proven before commitment.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Design a Production-Ready Customer Architecture now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-02-ALT-02', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 1, N'Design the architecture intervention plan', N'Sequence the work needed to close the gaps a design review exposed, with owners and the evidence that closes each one.', N'Extended', N'Prompt', N'Turn the architecture review findings into a sequenced remediation plan. For each gap, define the action, the owner, the dependency, the date it must be closed by to protect the delivery milestone, and the evidence that will close it. Flag any gap that cannot be closed in time.', NULL, N'The architecture review findings; the delivery owners available; the milestone dates the design must support.', N'A sequenced architecture remediation plan with owners, dates tied to delivery milestones, and closure evidence.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Design a Production-Ready Customer Architecture before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-02-ECIF-01', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 2, N'Review ECIF delivery readiness and technical outcomes', N'Review delivery readiness, milestones and success measures for funded engagement work before execution starts.', N'Featured', N'Prompt', N'Review the funded-engagement context, technical dependencies, delivery milestones, success measures, and evidence needed to support execution and outcome tracking.', NULL, N'Approved case or workscope context, milestones, architecture dependencies, and intended outcomes.', N'Delivery-readiness review with technical risks, checkpoints, and evidence needs.', N'CSA verifies technical and delivery assumptions and confirms ownership boundaries with CSAM, delivery, and the ECIF process owner.', N'Inspection and review', N'Reviewing eCIF delivery readiness and technical outcomes is judgment work. The agent proposes; you stay accountable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSA-03-ALT-01', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 3, N'Validate the evidence behind the technical decision path', N'Check whether the sequence of technical decisions rests on confirmed evidence or on decisions nobody has actually made yet.', N'Extended', N'Prompt', N'Review the technical decision path. For each decision, state whether the evidence to make it exists today, who owns the decision, and what happens to the sequence if that decision slips. Identify decisions that are being assumed rather than scheduled.', NULL, N'The technical decision path; the evidence behind each decision point; the owner who must confirm each one.', N'A decision-path review naming evidence status, decision owner, and slip impact for each point in the sequence.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Build the Technical Decision and Validation Path now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-03-ALT-02', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 4, N'Design the validation-path intervention plan', N'Define how each unproven part of the design gets validated, by whom, and by when.', N'Extended', N'Prompt', N'Turn the open validation items into a proof plan. For each, define the smallest test that would settle it, the environment and data needed, the owner, the date, and what the result changes. Order by which unproven item carries the most delivery risk.', NULL, N'The validation path and its open items; the environments and data available for proof; the owners of each validation step.', N'A validation proof plan ordered by delivery risk, with the smallest settling test, environment needs, owner, and date per item.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Build the Technical Decision and Validation Path before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-04-ALT-01', N'WF-X-CONV-01', N'CSA-CONV', N'PH-CSA-CONV-EXPL', 3, N'Validate the evidence behind the advisory recommendation', N'Check that every claim in your advisory recommendation is backed by evidence the customer will accept before you put it in front of them.', N'Extended', N'Prompt', N'Review the advisory recommendation you intend to give. For each claim, state the supporting evidence, whether that evidence is approved for customer use, and what a technically informed customer would push back on. Flag anything resting on assumption or on a roadmap item that has not shipped.', NULL, N'The draft advisory recommendation; the telemetry, architecture and cost evidence behind it; the customer''s stated constraints.', N'A claim-by-claim evidence review of the advisory recommendation with customer-safe status and likely pushback per claim.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Prepare a Technical Advisory Customer Conversation now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-04-ALT-02', N'WF-X-CONV-01', N'CSA-CONV', N'PH-CSA-CONV-EXPL', 4, N'Design the advisory adoption plan', N'Convert the advisory recommendation into the actions, owners and checkpoints the customer would need to actually adopt it.', N'Extended', N'Prompt', N'Turn the advisory recommendation into an adoption plan the customer can act on. Define the sequenced actions, the customer owner and Microsoft owner for each, the dependency most likely to stall it, the checkpoint dates, and the evidence that will show progress.', NULL, N'The agreed advisory recommendation; the customer roles who would own each step; the delivery dependencies involved.', N'An adoption plan for the advisory recommendation with paired customer and Microsoft owners, dependencies, and checkpoints.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Prepare a Technical Advisory Customer Conversation before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-05-ALT-01', N'WF-X-PIPE-01', N'CSA-PIPE', N'PH-CSA-PIPE-EXPL', 3, N'Validate the consumption gap analysis', N'Test whether the consumption gap has been traced to a real technical cause or to a plausible-sounding assumption.', N'Extended', N'Prompt', N'Review the consumption analysis. For each shortfall, state the technical cause proposed, the signal that evidences that cause, and the alternative explanations that have not been ruled out. Identify which gaps are technically caused, which are commercial or customer-driven, and which are still unexplained.', NULL, N'The consumption position against plan; the telemetry and deployment signals behind it; known customer events that affect usage.', N'A consumption gap analysis separating evidenced technical causes from unruled-out alternatives and non-technical drivers.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Forecast Consumption and Intervene on Shortfall Risk now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-05-ALT-02', N'WF-X-PIPE-01', N'CSA-PIPE', N'PH-CSA-PIPE-EXPL', 4, N'Design the consumption intervention plan', N'Build the intervention that changes the consumption trajectory, with the owner and the checkpoint that will show whether it moved.', N'Extended', N'Prompt', N'Turn the evidenced consumption causes into an intervention plan. For each, define the technical action, who owns it on both sides, the dependency that could block it, the date you would expect to see movement, and the telemetry that would confirm it. Rank by the size of the gap each one closes.', NULL, N'The validated consumption causes; the deployment and architecture levers available; the customer owners for each dependency.', N'A ranked consumption intervention plan with owners, blocking dependencies, expected movement dates, and confirming telemetry.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Forecast Consumption and Intervene on Shortfall Risk before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-05-SCOUT-01', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 3, N'Watch consumption and health signals between reviews', N'Set up a standing check on the accounts you carry, so a health or consumption change reaches you when it happens rather than at the next review.', N'Featured', N'Both', N'Set up a recurring check on technical health across the accounts I carry. Each week, tell me where consumption has moved against plan, where a deployment or adoption blocker has appeared, and where a previously flagged risk has not changed. For each one, state what the data shows, what it does not tell us, and the single technical question I should ask next. Remember what you flagged before so you can tell me what is new and what is unchanged.', N'1. Confirm which telemetry, support and consumption sources the check can reach.
2. Run the prompt.
3. Review the first output and separate genuinely new movement from risk you already knew about.
4. Set the cadence to land before your delivery review.
5. Validate each technical hypothesis yourself before raising it with the customer or the account team.', N'The accounts you carry; approved consumption, usage and support data; the risks currently on your register.', N'A recurring health check separating new movement from unchanged risk, with the next technical question for each.', N'CSA confirms the technical reading of each signal and decides which movement is significant enough to act on.', N'Monitoring and signal', N'Risk found early is a conversation and the same risk found late is an escalation. Between reviews is exactly where that gap opens, and it is where an always-on agent earns its place.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSA-06-ALT-01', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'PH-CSA-VALUE-1-EXPL', 3, N'Validate the cost and optimization evidence', N'Test the cost baseline and savings estimates before an optimization recommendation goes to the customer.', N'Extended', N'Prompt', N'Review the cost and optimization analysis. For each recommendation, state the baseline it is measured against, the assumptions behind the projected saving, whether the saving is modelled or observed, and the customer constraint that could prevent it. Flag any figure that would not survive review by the customer finance function.', NULL, N'The cost and consumption evidence base; the baseline period and its assumptions; the customer commitments that constrain change.', N'A cost evidence review separating modelled from observed savings, with baseline assumptions and blocking constraints per recommendation.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Build a FinOps and Optimization Recommendation now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-06-ALT-02', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'PH-CSA-VALUE-1-EXPL', 4, N'Design the FinOps intervention plan', N'Turn the validated cost findings into changes someone owns, with the measurement that will prove the saving landed.', N'Extended', N'Prompt', N'Turn the validated cost findings into an implementation plan. For each optimization, define the technical change, the owner, the customer approval needed, the date, and the specific billing or telemetry measure that will confirm the saving. Rank by net saving against effort.', NULL, N'The validated optimization recommendations; the technical owners for each change; the billing or telemetry view that will show the effect.', N'A ranked FinOps implementation plan with owners, required approvals, and the measure that will confirm each saving.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Build a FinOps and Optimization Recommendation before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-07-ALT-01', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 3, N'Validate the evidence behind the customer value story', N'Check that the value story is built on measured outcomes rather than activity, before the customer''s finance function does it for you.', N'Extended', N'Prompt', N'Review the technical value narrative. For each claimed outcome, state whether it is measured or projected, the baseline it is compared against, and whether the measurement basis has changed since the commitment was made. Separate delivered value from activity completed, and flag any claim a finance reviewer would reject.', NULL, N'The draft value narrative; the outcomes committed in the business case; the measurement basis and baseline used.', N'A value-claim review separating measured from projected outcomes, with baseline integrity and finance-review risk per claim.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Confirming the technical health evidence for Translate Technical Progress into Customer Value now costs a conversation. Discovering it late costs a decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSA-07-ALT-02', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 4, N'Design the value-translation intervention plan', N'Close the gap between the value you have delivered and the value the customer can see, with named owners and evidence.', N'Extended', N'Prompt', N'Where the value story has gaps, define what would close them. For each gap, state the evidence still needed, who can produce it, the date it is needed by, and the customer stakeholder it is intended to convince. Identify which gaps can be closed before the next review and which cannot.', NULL, N'The validated value narrative and its gaps; the customer stakeholders who need to see it; the upcoming review that will carry it.', N'A value evidence plan naming the missing proof, its producer, the date, and the stakeholder it must convince.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Scoping and design', N'Settling the technical intervention plan for Translate Technical Progress into Customer Value before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSA-INVEST-01-P01', N'WF-INVEST-01', N'CSA-INVEST', N'PH-CSA-INVEST-EXPL', 1, N'Validate delivery readiness and technical dependencies', N'Test whether investment-funded scope can be executed as written, against dependencies, prerequisites and ownership.', N'Featured', N'Prompt', N'Review the approved or proposed investment scope for execution readiness, technical dependencies, customer prerequisites, ownership, and measurable technical outcomes.', NULL, N'Proposed scope, technical evidence, customer prerequisites', N'Delivery-readiness assessment with dependencies, risks, and required actions.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Validation and evidence', N'Confirming delivery readiness and technical dependencies now costs a conversation. Discovering it late costs a decision.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSA-INVEST-01-P02', N'WF-INVEST-01', N'CSA-INVEST', N'PH-CSA-INVEST-EXPL', 2, N'Define technical checkpoints and outcome evidence', N'Define the technical checkpoints and evidence that will support the later value-realization review.', N'Featured', N'Prompt', N'Translate the investment scope into technical checkpoints, evidence requirements, and signals that support later value-realization review.', NULL, N'Scope, milestones, technical success measures', N'Technical checkpoint and evidence plan.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Scoping and design', N'Settling technical checkpoints and outcome evidence before the work starts is the only version of that decision that holds.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSA-INVEST-01-P03', N'WF-INVEST-01', N'CSA-INVEST', N'PH-CSA-INVEST-EXPL', 3, N'Surface delivery risk before it reaches the customer', N'Review in-flight investment delivery for the technical risks that would become customer-visible.', N'Featured', N'Both', N'Using approved delivery status and milestone evidence, identify technical risks, unmet prerequisites and dependency slippage that could become customer-visible. State evidence, owner and the intervention available now.', N'1. Ask ECIF Agent via Sales Agent for delivery status across in-flight engagements.
2. Review for dependency slippage and unmet prerequisites.
3. Open ECIF Central for milestone detail where needed.
4. Name evidence, owner and intervention for each risk.
5. Raise what cannot wait.', N'Approved delivery status, milestone evidence, customer prerequisites', N'Technical delivery-risk brief with evidence, owners and interventions.', N'Confirm status and milestone data against the authoritative record before acting or reporting. Do not infer financial yield or approval state from a summary.', N'Problem identification', N'Naming delivery risk before it reaches the customer is most of the work. Unnamed problems never get an owner.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSA-INVEST-01-P04', N'WF-INVEST-01', N'CSA-INVEST', N'PH-CSA-INVEST-EXPL', 4, N'Translate technical outcomes into the customer value story', N'Connect the technical evidence from the investment to the outcomes the customer agreed to.', N'Featured', N'Prompt', N'Using approved milestone, adoption and consumption evidence, connect what was delivered to the intended customer outcomes. Separate evidenced from expected. Do not claim causality the data does not support.', NULL, N'Approved milestone, adoption and consumption evidence, agreed outcomes', N'Evidence-based technical value story with confirmed outcomes and gaps.', N'Confirm the grounding sources, separate evidence from assumption, and validate the named owner and next decision before this reaches a customer or an approver.', N'Value translation', N'Making technical outcomes into the customer value story explicit is the part almost nobody does, and the part that travels.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSA-INVLINK-01', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'PH-CSA-ARCH-2-EXPL', 5, N'Validate delivery readiness for investment-funded scope', N'Test whether investment-funded technical scope can actually be delivered as designed.', N'Featured', N'Prompt', N'Review the proposed investment-funded scope for execution readiness, technical dependencies, customer prerequisites, ownership and measurable technical outcomes. Identify what would block delivery and who owns each item.', NULL, N'Proposed scope, technical evidence, customer prerequisites', N'A delivery-readiness view with dependencies, prerequisites and named owners.', N'CSA confirms the prerequisites are real and that the outcome measures are technically observable.', N'Test whether investment-funded technical scope can actually be delivered as designed.', N'Avoid inheriting an undeliverable scope', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSAM-ESCALATE-ALT01', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 3, N'Build the recovery action register', N'Capture each recovery action with owner, customer impact, dependency, due date and escalation threshold.', N'Extended', N'Both', N'Create a recovery action register with action, owner, customer impact, dependency, due date, escalation threshold and evidence source.', N'1. Open the Customer Success Agent app in Teams; there is no published direct link.
2. Start from the validated escalation brief.
6. Extract actions.
6. Confirm owner and date.
6. Add escalation threshold.
6. Track follow-through in the appropriate system.', N'Validated escalation brief and owner context.', N'Recovery action register.', N'CSAM validates owners, dates and where actions should be tracked.', N'Operational governance', N'Escalations repeat when recovery actions do not become governed follow-through.', NULL, N'Open Customer Success Agent'),
        (N'CSAM-ESCALATE-ALT02', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 4, N'Prepare the post-incident value and prevention summary', N'Document impact, completed recovery, prevention actions and how the fix will be reviewed once things stabilize.', N'Extended', N'Prompt', N'After the issue stabilizes, draft a prevention summary. Include root-cause status if approved, customer impact, recovery actions completed, prevention actions, owners, dates and how this will be reviewed in the next CSDR.', NULL, N'Closed or stabilized issue, approved RCA or status, recovery actions and CSDR cadence.', N'Post-incident prevention summary.', N'CSAM validates approved RCA language, customer sensitivity and follow-through ownership.', N'Continuous improvement', N'Trust is repaired when the customer sees what changed after the issue.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSAM-ESCALATE-P01', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 1, N'Create the escalation and recovery brief', N'Consolidate incident, support, delivery and customer communication context into a grounded brief.', N'Featured', N'Prompt', N'Create an escalation and recovery brief for [issue]. Include customer impact, current status, timeline, owners, decisions needed, risks, next action, next update cadence and what is unknown. Use only approved sources and separate facts from assumptions.', NULL, N'Incident or support notes, delivery updates, customer communications, owners, timelines and current risks.', N'Escalation and recovery brief.', N'CSAM validates accuracy, sensitivity, owner commitments and customer-safe language before distribution.', N'Escalation leadership', N'In escalation moments, clarity protects trust and reduces duplicated status chasing.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-ESCALATE-P02', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'PH-CSAM-ESCALATE-EXPL', 2, N'Draft the customer-safe status update', N'Prepare a concise status update that protects trust and avoids unsupported commitments.', N'Featured', N'Prompt', N'Draft a customer-safe status update for [stakeholder] on [issue]. Include what happened, current impact, what Microsoft is doing, what we need from the customer, next update timing and what remains under investigation. Avoid blame and unsupported commitments.', NULL, N'Validated escalation brief, customer stakeholder and approved communication position.', N'Customer-safe escalation update.', N'CSAM confirms accuracy, support alignment and approval path before sending.', N'Stakeholder communication', N'The wrong update can create more risk than the issue itself.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-EXEC-ALT01', N'WF-X-CONV-01', N'CSAM-EXEC', N'PH-CSAM-EXEC-EXPL', 3, N'Rehearse the executive conversation', N'Role-play the executive stakeholder against your approved brief to expose weak evidence, vague asks and unowned risk.', N'Extended', N'Prompt', N'Role-play [executive stakeholder] for the upcoming alignment conversation. Use the approved brief only. Challenge weak evidence, unclear value, vague asks and unowned risks. End with coaching notes and changes to make before the meeting.', NULL, N'Approved executive alignment brief.', N'Role-play output with likely questions, objections and coaching notes.', N'CSAM decides what to change and confirms no unsupported customer facts were introduced.', N'Conversation preparation', N'A ten-minute rehearsal is cheaper than discovering the weak ask in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'CSAM-EXEC-ALT02', N'WF-X-CONV-01', N'CSAM-EXEC', N'PH-CSAM-EXEC-EXPL', 4, N'Draft executive follow-up with decisions and asks', N'Capture the decisions, open asks, owners and next review point in a follow-up the executive can act on.', N'Extended', N'Prompt', N'Draft a concise executive follow-up for [meeting]. Summarize decisions, open asks, owners, dates, risks and next review point. Keep the tone advisory and customer-safe.', NULL, N'Meeting notes, executive brief and confirmed decisions.', N'Executive follow-up draft.', N'CSAM validates decisions, owner commitments and customer-facing language before sending.', N'Stakeholder communication', N'Follow-up is where alignment becomes accountability.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-EXEC-P01', N'WF-X-CONV-01', N'CSAM-EXEC', N'PH-CSAM-EXEC-EXPL', 1, N'Build the stakeholder and influence map', N'Map stakeholders, decision rights, sponsor health, relationship gaps and next engagement actions.', N'Featured', N'Prompt', N'Using approved meetings, emails, CRM notes and account context for [Account], build a stakeholder and influence map. Include executive sponsor, BDMs, workload owners, blockers, champions, relationship health, last interaction, open asks and recommended next engagement action. Flag inferred items separately.', NULL, N'Approved customer relationship context, recent interactions, CRM notes and known account team inputs.', N'Stakeholder and influence map with relationship risks and next actions.', N'CSAM validates relationship interpretation and removes unsupported inferences.', N'Customer intelligence', N'Stakeholder changes can break adoption, value proof and renewal confidence before metrics show it.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSAM-EXEC-P02', N'WF-X-CONV-01', N'CSAM-EXEC', N'PH-CSAM-EXEC-EXPL', 2, N'Prepare the executive alignment brief', N'Create a brief with priorities, value evidence, risk, decision needed and the executive ask.', N'Featured', N'Prompt', N'Prepare an executive alignment brief for [stakeholder or meeting]. Include customer priorities, progress since last touch, value evidence, top risk, decision needed, recommended ask and questions to confirm alignment. Use only approved sources and flag gaps.', NULL, N'Stakeholder map, success plan, value evidence, health risks and meeting context.', N'Executive alignment brief and talk track.', N'CSAM validates executive relevance, tone, evidence and the ask.', N'Executive storytelling', N'Executive alignment is where CSAMs convert activity into trust and decisions.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-HEALTH-ALT01', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'PH-CSAM-HEALTH-EXPL', 3, N'Prepare the customer-safe health message', N'Write the health concern in customer language, with the proposed action and the support you need from them.', N'Extended', N'Prompt', N'Draft a customer-safe message for [stakeholder] about this health risk. State the concern, why it matters, the proposed action and the support needed from the customer. Avoid internal terminology and unsupported conclusions.', NULL, N'Validated health risk, customer stakeholder and proposed action.', N'Customer-safe health message.', N'CSAM approves tone, accuracy and whether the message should be sent.', N'Stakeholder communication', N'Risk communication can build trust or create noise. The CSAM owns that judgment.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-HEALTH-ALT02', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'PH-CSAM-HEALTH-EXPL', 4, N'Update RAID and CSDR follow-through', N'Turn a health risk into RAID and review entries with owner, dependency, decision, due date and evidence source.', N'Extended', N'Both', N'Create RAID and CSDR follow-through entries for this health risk. Include risk, action, owner, dependency, decision, due date and evidence source.', N'1. Select the validated health risk.
2. Draft RAID entries.
3. Confirm owners and dates.
4. Prepare the CSDR follow-up line.
5. Update the system only after review.', N'Validated health risk and account governance cadence.', N'RAID-ready and CSDR-ready follow-through entries.', N'CSAM verifies system updates and confirms accountable owners.', N'Operational governance', N'Health work fails when findings do not become tracked actions.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-HEALTH-P01', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'PH-CSAM-HEALTH-EXPL', 1, N'Rank customer health risks and drivers', N'Create a ranked view of health risk across usage, support, sentiment, delivery and stakeholder signals.', N'Featured', N'Prompt', N'Using approved customer health, usage, support, delivery, sentiment and stakeholder signals for [Account or portfolio], rank the top risks. For each risk show driver, evidence, likely customer impact, owner, mitigation, due date and escalation threshold. Flag unavailable data.', NULL, N'Customer health signals, usage or consumption data, support trends, delivery milestones, sentiment and stakeholder notes.', N'Ranked customer health risk view with mitigations.', N'CSAM validates source freshness, customer impact and the intervention before acting.', N'Problem identification', N'Health scores rarely tell you what to do. This turns signals into action.', N'https://msxi.microsoft.com/', N'Open MSX Insights'),
        (N'CSAM-HEALTH-P02', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'PH-CSAM-HEALTH-EXPL', 2, N'Create the proactive intervention plan', N'Translate the top risk into a customer-safe intervention with owner and cadence.', N'Featured', N'Prompt', N'For the top validated health risk, create a proactive intervention plan. Include customer-facing framing, Microsoft owner, customer owner, required evidence, next meeting, mitigation action, escalation condition and follow-up cadence.', NULL, N'Validated top health risk, owner context, customer relationship context and available mitigation options.', N'Proactive intervention plan.', N'CSAM confirms the plan is appropriate for the customer relationship and does not overstate risk.', N'Action planning', N'Early intervention is where customer health work creates trust.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-INVEST-ALT01', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 3, N'Track investment delivery risks and handoffs', N'Find the overdue milestones, unclear owners and delivery dependencies in active investment work.', N'Extended', N'Prompt', N'Review active investment milestones for [Account]. Identify overdue actions, unclear owners, missing evidence, delivery dependencies, customer impact and recommended next action.', NULL, N'Active investment milestones, workscope status, delivery updates and success-plan context.', N'Investment risk and handoff review.', N'CSAM confirms status with ECIF or delivery owners before escalating or updating the customer.', N'Risk tracking', N'Investment value is lost when handoffs drift without visibility.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSAM-INVEST-ALT02', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 4, N'Prepare the investment realization review', N'Assemble objective, work completed, value evidence, remaining gaps and the recommendation for the next review.', N'Extended', N'Prompt', N'Prepare an investment realization review for [Account]. Include original objective, work completed, customer value evidence, remaining gaps, risks, next actions and recommendation for the next CSDR or QBR.', NULL, N'Completed or in-flight investment data, value evidence, success plan and review audience.', N'Investment realization review brief.', N'CSAM validates value claims, approved sources and next-step ownership.', N'Value storytelling', N'Investment only proves value when the evidence is captured and reviewed.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-INVEST-P01', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 1, N'Connect the investment to the success plan', N'Ensure the investment supports a documented customer outcome and success-plan milestone.', N'Featured', N'Prompt', N'Review this customer investment against the success plan for [Account]. Identify the customer outcome it supports, related milestone, owner, dependency, risk, success evidence and next governed action. Flag gaps before execution continues.', NULL, N'Investment request or workscope, success plan, customer priority, milestones and stakeholder context.', N'Investment-to-success-plan alignment view.', N'CSAM validates outcome alignment and confirms policy or approval questions remain with accountable owners.', N'Governance and evidence', N'Investment should accelerate a customer outcome, not become a disconnected activity.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'CSAM-INVEST-P02', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 2, N'Establish the investment operating rhythm', N'Create the owners, checkpoints and evidence plan for investment execution.', N'Featured', N'Both', N'Create an investment operating rhythm with milestones, owner, checkpoint date, delivery dependency, risk, evidence needed and realization review timing.', N'1. Select the investment.
2. Identify milestones and owners.
3. Add checkpoints.
4. Define value evidence.
5. Review with the v-team before customer use.', N'Investment scope, milestones, delivery plan and success-plan context.', N'Investment operating rhythm with checkpoints and evidence plan.', N'CSAM validates owners, dates, handoffs and customer-facing commitments.', N'Operational governance', N'A governed rhythm is what keeps investment execution from drifting.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-INVEST-P05', N'WF-INVEST-01', N'CSAM-INVEST', N'PH-CSAM-INVEST-EXPL', 5, N'Turn investment delivery into evidence the customer recognizes', N'Convert what the investment delivered into value the customer would describe the same way, and identify what is still unproven.', N'Featured', N'Both', N'This investment was intended to deliver [paste the outcome and the success plan linkage]. Here is what was delivered and what the usage and adoption data shows: [paste]. Produce a realization view that separates what we can evidence, what we are inferring, and what has not materialized. For each evidenced outcome, phrase it the way the customer would describe it rather than the way we would. Flag anything a customer stakeholder would dispute if they read it.', N'1. Bring the investment outcome and its success plan linkage.
2. Gather delivery evidence from ECIF Central and adoption data.
3. Run the prompt.
4. Read the evidenced list as if you were the customer.
5. Take the unproven items to the account team before the realization review.', N'The investment outcome and success plan linkage. Delivery evidence and milestones. Adoption and usage data. What the customer has said about value.', N'A realization view separating evidenced, inferred, and unmaterialized outcomes, phrased in the customer''s terms.', N'CSAM confirms the customer would recognize the value as described, and removes any claim the customer would dispute before it reaches a review.', N'Value translation', N'Value the customer would not describe the same way is not realized value, whatever the internal record says.', N'https://aka.ms/ECIFCentral', N'Open ECIF Central'),
        (N'CSAM-ORCH-ALT01', N'WF-X-ORCH-01', N'CSAM-ORCH', N'PH-CSAM-ORCH-EXPL', 3, N'Build the weekly customer-success action plan', N'Rank this week''s top five customer actions by impact, urgency and dependency risk, including what to leave alone.', N'Extended', N'Prompt', N'Create my weekly customer-success action plan for [Account]. Prioritize the top five actions by customer impact, urgency and dependency risk. Include owner, source signal, next step and what not to spend time on this week.', NULL, N'Current account signals, meetings, notes, support, delivery and success-plan context.', N'Weekly customer-success action plan.', N'CSAM confirms priority logic and adjusts based on customer relationship context.', N'Prioritization', N'The highest-value CSAM week starts with deciding what not to chase.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-ORCH-ALT02', N'WF-X-ORCH-01', N'CSAM-ORCH', N'PH-CSAM-ORCH-EXPL', 4, N'Prepare the internal alignment message', N'Give the v-team the customer outcome, current state, open risks and the decisions you need from them.', N'Extended', N'Prompt', N'Draft an internal alignment message for the v-team. Include customer outcome, current state, open risks, needed decisions, owner asks and date. Keep it concise and specific.', NULL, N'V-team orchestration brief and desired decision or action.', N'Internal alignment message.', N'CSAM validates ownership, tone and whether any customer-sensitive content should be removed.', N'Stakeholder communication', N'Internal alignment should reduce meetings, not create more of them.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-ORCH-P01', N'WF-X-ORCH-01', N'CSAM-ORCH', N'PH-CSAM-ORCH-EXPL', 1, N'Create the v-team orchestration brief', N'Synthesize current workstreams, owners, handoffs, decisions and blockers.', N'Featured', N'Prompt', N'Analyze approved customer-success sources for [Account] across meetings, emails, notes, CRM, support and delivery context. List active workstreams, owner, input needed, due date, dependency, blocker, decision needed and recommended next action. Flag missing owners and stale dates.', NULL, N'Approved account context, workstream notes, meetings, delivery updates, support context and CRM records.', N'V-team orchestration brief with workstreams and handoffs.', N'CSAM validates owners, dates, escalation path and whether each action is still relevant.', N'Orchestration', N'CSAMs create leverage by making the system visible instead of carrying every detail personally.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-ORCH-P02', N'WF-X-ORCH-01', N'CSAM-ORCH', N'PH-CSAM-ORCH-EXPL', 2, N'Make one stalled handoff explicit', N'Turn a vague or stalled handoff into an owner, input, date and decision.', N'Featured', N'Both', N'For this stalled handoff, identify the missing input, accountable owner, decision needed, customer impact, due date and escalation route. Draft the internal message that asks for exactly what is needed.', N'1. Pick one stalled handoff.
2. Name the needed input.
3. Confirm owner.
4. Draft the ask.
5. Send or route only after validation.', N'One stalled handoff or vague dependency.', N'Handoff clarification message and action record.', N'CSAM confirms the ask is accurate, respectful and routed to the right owner.', N'Workflow coordination', N'Most stalled work gets unstuck when the missing input and owner are explicit.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-RENEW-ALT01', N'WF-X-RENEW-01', N'CSAM-RENEW', N'PH-CSAM-RENEW-EXPL', 3, N'Stress-test the expansion hypothesis', N'Test an expansion hypothesis against usage, stakeholder and timing evidence, and name the likely objections.', N'Extended', N'Prompt', N'Stress-test this expansion hypothesis. Identify supporting usage, stakeholder, business-outcome and timing evidence. Flag missing evidence, likely objections and the next validation action.', NULL, N'Expansion hypothesis, adoption and usage evidence, customer priorities and stakeholder context.', N'Expansion evidence and objection review.', N'CSAM and AE validate whether this is ready for pursuit or needs more discovery.', N'Assumption testing', N'Expansion tied to realized value is stronger than expansion tied only to whitespace.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'CSAM-RENEW-ALT02', N'WF-X-RENEW-01', N'CSAM-RENEW', N'PH-CSAM-RENEW-EXPL', 4, N'Draft the renewal value narrative', N'Connect realized outcomes, adoption progress and remaining risk into a customer-safe renewal narrative.', N'Extended', N'Prompt', N'Draft a renewal value narrative for [Account] that connects realized outcomes, adoption progress, remaining risks and the next value milestone. Keep it customer-safe and avoid pricing or commercial commitments.', NULL, N'Validated value evidence, renewal readiness view and customer audience.', N'Renewal value narrative draft.', N'CSAM validates with AE or account owner before using in customer-facing renewal context.', N'Value storytelling', N'The strongest renewal support is credible evidence that Microsoft value is ongoing.', N'https://m365.cloud.microsoft/chat', N'Open Analyst'),
        (N'CSAM-RENEW-P01', N'WF-X-RENEW-01', N'CSAM-RENEW', N'PH-CSAM-RENEW-EXPL', 1, N'Build the renewal and growth readiness view', N'Connect health, consumption, adoption, value and stakeholder signals into a renewal readiness view.', N'Featured', N'Prompt', N'Build a renewal and growth readiness view for [Account]. Include renewal context, consumption or usage trajectory, MACC or commitment risk if applicable, adoption gaps, value evidence, support or health risks, stakeholder health, expansion hypothesis and recommended v-team next action. Flag unavailable data.', NULL, N'Renewal context, agreements, consumption or usage signals, adoption data, value proof, health risks and stakeholder context.', N'Renewal and growth readiness view.', N'CSAM aligns with AE and validates which signals are appropriate to share or escalate.', N'Renewal readiness', N'Renewal risk is easier to change when it is seen through health and value before the renewal date.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSAM-RENEW-P02', N'WF-X-RENEW-01', N'CSAM-RENEW', N'PH-CSAM-RENEW-EXPL', 2, N'Prepare the AE and v-team alignment brief', N'Create a brief that helps AE, CSA, SSP and CE align on renewal risk and growth actions.', N'Featured', N'Prompt', N'Prepare a v-team alignment brief for [Account] renewal or growth readiness. Include the customer value proof, top risk, consumption or adoption gap, expansion hypothesis, roles needed, decision owner and 30-day action plan.', NULL, N'Renewal readiness view, v-team roles and next review context.', N'V-team renewal and growth alignment brief.', N'CSAM confirms ownership boundaries and aligns with AE before external use.', N'Cross-role alignment', N'CSAMs influence renewal outcomes by making value, risk and next actions visible to the account team.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-SPLAN-ALT01', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 3, N'Validate the success-plan evidence', N'Label every statement in the success plan as sourced fact, assumption or recommendation, and flag what is not customer-ready.', N'Featured', N'Prompt', N'Review the success-plan update and label each statement as sourced fact, assumption, recommendation or missing evidence. Flag anything that should not be shared with the customer yet.', NULL, N'Draft success-plan update and source material.', N'Evidence validation matrix for the success-plan update.', N'CSAM removes unsupported claims and confirms customer-safe language.', N'Validation and evidence', N'Validation prevents the plan from sounding confident where the evidence is thin.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'CSAM-SPLAN-ALT02', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 4, N'Create the CSDR-ready success-plan narrative', N'Turn the validated success plan into a short review narrative covering progress, value, risk and the decision needed.', N'Extended', N'Prompt', N'Turn this validated success-plan update into a concise CSDR narrative. Include progress, value, risk, decision needed and next action. Keep it customer-safe and avoid unsupported claims.', NULL, N'Validated success-plan update and CSDR audience context.', N'CSDR-ready success-plan narrative.', N'CSAM validates tone, customer context and decision ask before use.', N'Executive storytelling', N'A plan matters more when the customer can understand the progress and decision needed.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSAM-SPLAN-P01', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 1, N'Draft the outcome-anchored success-plan view', N'Draft or refresh the CSP around customer outcomes, milestones, owners, risks and review points.', N'Featured', N'Prompt', N'Using approved customer priorities, recent meetings, CSP notes and delivery updates for [Account], draft a Customer Success Plan view. Include outcome, success measure, milestone, owner, dependency, risk, next customer review point and evidence source. Separate sourced facts from suggested updates.', NULL, N'Customer priorities, existing CSP or notes, recent customer meetings, delivery milestones and known risks.', N'Outcome-anchored success-plan view with gaps and suggested updates.', N'CSAM validates customer priority, owner, commitment, measure and source before updating any system of record.', N'Synthesis and drafting', N'Most success-plan toil is assembling scattered signals. The CSAM should spend judgment on the outcome and commitment.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'CSAM-SPLAN-P02', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 2, N'Inspect the plan for drift and missing accountability', N'Find stale milestones, missing owners and risks that are not tied to action.', N'Featured', N'Prompt', N'Review this success plan for drift. Identify stale milestones, missing owners, unsupported outcomes, risks without mitigation, dependencies without dates and actions that no longer map to the customer priority. Recommend the smallest set of updates needed before the next CSDR.', NULL, N'Current success plan, action log, CSDR notes, milestone status and RAID items.', N'Plan-drift inspection with recommended updates.', N'CSAM confirms what should be changed, retired, escalated or kept as-is.', N'Inspection and review', N'A stale plan creates false confidence. Drift detection keeps the plan governable.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-SPLAN-SCOUT-01', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'PH-CSAM-SPLAN-EXPL', 5, N'Keep success plan commitments visible between check-ins', N'Turn the success plan from a document reviewed monthly into a tracked set of commitments with standing visibility on what is slipping.', N'Extended', N'Both', N'Track the commitments in this account''s success plan on a recurring basis. For each milestone, tell me whether there is recent evidence of progress, whether the named owner has been active on it, and whether the date is still credible given what has happened since it was set. Flag anything with no evidence of movement and draft the specific question I should ask the owner. Report only changes and exceptions - do not restate the whole plan each time.', N'1. Bring the current success plan with milestones, owners and dates.
2. Run the prompt.
3. Review the exceptions list, remembering that no evidence of movement is not proof that nothing moved.
4. Set the cadence to run before your customer check-in.
5. Ask the named owner the drafted question directly rather than escalating first.', N'The current success plan with milestones, owners and dates; access to the engagement activity behind it.', N'A recurring exceptions-only commitment tracker with an evidence check per milestone and a drafted question for each stalled item.', N'CSAM confirms the credibility judgement on each date personally before raising it, since absence of visible evidence is not proof of absence of progress.', N'Follow-through and orchestration', N'Success plans decay quietly. The milestone that slipped is rarely announced - it is simply never mentioned again until the review.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'CSAM-VALUE-ALT01', N'WF-X-VALUE-01', N'CSAM-VALUE', N'PH-CSAM-VALUE-EXPL', 3, N'Draft the sponsor value update', N'Summarize adoption progress and value evidence for a sponsor in their language, not in internal metrics.', N'Extended', N'Prompt', N'Draft a sponsor update for [stakeholder] that summarizes adoption progress, value evidence, remaining gap and the next action needed. Use customer language and avoid internal metrics unless they support the outcome.', NULL, N'Validated value realization brief and sponsor context.', N'Sponsor value update draft.', N'CSAM validates evidence, tone, sensitivity and next ask before sending.', N'Stakeholder communication', N'Sponsors need a clear value narrative, not a dashboard dump.', N'https://m365.cloud.microsoft/chat', N'Open Analyst'),
        (N'CSAM-VALUE-ALT02', N'WF-X-VALUE-01', N'CSAM-VALUE', N'PH-CSAM-VALUE-EXPL', 4, N'Convert value gaps into next-best actions', N'Turn adoption and value gaps into next-best actions with paired customer and Microsoft owners and a review date.', N'Extended', N'Prompt', N'Review the adoption and value gaps for [Account]. Recommend next-best actions, including customer owner, Microsoft owner, Success Program or delivery resource if relevant, expected outcome and review date.', NULL, N'Adoption gaps, value evidence, success plan and available delivery or program options.', N'Next-best-action list for value acceleration.', N'CSAM validates fit, ownership and whether recommendations should enter the success plan.', N'Action planning', N'The value story should lead to action, not just a better deck.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'CSAM-VALUE-P01', N'WF-X-VALUE-01', N'CSAM-VALUE', N'PH-CSAM-VALUE-EXPL', 1, N'Identify adoption friction and next activation actions', N'Map usage gaps to customer priorities and build a short activation plan.', N'Featured', N'Prompt', N'For [Account and workload], compare current adoption or usage signals with customer priorities and licensed or committed scope. Identify the top adoption friction points, likely root cause, stakeholder owner and a 4-week activation plan with measurable milestones.', NULL, N'Usage or adoption data, customer priorities, workload scope, stakeholder context and prior adoption actions.', N'Adoption friction analysis and 4-week activation plan.', N'CSAM validates whether the adoption action is relevant to the customer priority and achievable with available owners.', N'Adoption acceleration', N'Adoption work matters when it changes customer behavior tied to a business outcome.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'CSAM-VALUE-P02', N'WF-X-VALUE-01', N'CSAM-VALUE', N'PH-CSAM-VALUE-EXPL', 2, N'Build the value realization brief', N'Translate adoption, usage, delivery and outcome evidence into a customer-recognized value story.', N'Featured', N'Prompt', N'Build a value realization brief for [Account]. Show what changed, what evidence supports it, how it maps to the customer outcome, remaining gaps and the recommended next action. Separate measured evidence from narrative interpretation.', NULL, N'Adoption data, usage signals, customer outcome, delivery milestones, support or health improvements and prior review notes.', N'Value realization brief with evidence and gaps.', N'CSAM validates customer-recognized value, removes unsupported claims and aligns tone to the audience.', N'Value storytelling', N'Value that is not evidenced is an opinion. Value that is not communicated is invisible.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'CSA-VALUE-SCOUT-01', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 5, N'Track delivered value against what was promised', N'Keep a running comparison between the outcomes committed in the business case and what consumption and usage data actually show.', N'Extended', N'Both', N'Set up a recurring comparison between the outcomes we committed to in this account''s business case and what the consumption and usage data now shows. Report the direction of travel for each committed outcome, flag any where the trend will not reach the commitment on the current trajectory, and state what evidence would be needed to make the value claim defensible to the customer''s finance function. Distinguish measured results from projected results everywhere.', N'1. Bring the agreed business case, its committed outcomes, and the baseline used at commitment.
2. Run the prompt.
3. Confirm the tracker distinguishes measured results from projected ones on every outcome.
4. Check that the measurement basis has not changed since the commitment was made.
5. Verify any figure yourself before it is shown to the customer as delivered value.', N'The agreed business case and its committed outcomes; current consumption and usage data; the baseline used at commitment.', N'A recurring value tracker per committed outcome, showing measured versus projected, trajectory against commitment, and the evidence gap.', N'CSA verifies the measurement basis has not changed and confirms every figure before it is shown to the customer as a delivered result.', N'Analysis and measurement', N'Value claims lose credibility the moment a customer''s finance function finds the number is projected rather than measured. Tracking continuously is what makes the claim survive scrutiny.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SE-01-ALT-01', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 3, N'Map evidence gaps against decision criteria', N'Test each decision criterion in the discovery brief against the evidence you actually hold, so the gaps are visible before the customer finds them.', N'Extended', N'Prompt', N'Using the discovery brief, map each proposed decision criterion to supporting evidence, missing evidence, assumptions, and required reviewer input.', NULL, N'The discovery brief with its proposed decision criteria; the evidence you currently hold for each; the reviewers who could close a gap.', N'Evidence-gap map tied to customer decision criteria.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'The gap map shows what must be proven before architecture, demo, or PoC work proceeds.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-01-ALT-02', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 4, N'Create the discovery handoff package', N'Package the bounded problem, agreed criteria, evidence gaps and owners so the next technical stage starts without repeating discovery.', N'Extended', N'Prompt', N'Package the bounded problem, agreed criteria, evidence gaps, assumptions, owners, and next technical action for the account team.', NULL, N'The completed discovery brief; the agreed decision criteria; the named owner for each open item.', N'Discovery handoff package for the next technical stage.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A clear handoff prevents discovery findings from being lost before design or proof work begins.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-01-ECIF-01', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 5, N'Validate the technical scope for ECIF', N'Review a proposed investment-funded technical scope for missing evidence and corrections before it reaches request review.', N'Featured', N'Prompt', N'Review the proposed ECIF technical scope, milestones, deliverables, dependencies, and acceptance criteria. Identify missing technical evidence and corrections needed before request review.', NULL, N'Draft workscope, architecture context, technical dependencies, and acceptance criteria.', N'Technical-scope review with issues, proposed corrections, and handoff notes.', N'SE validates technical content only and confirms that eligibility, policy, commercial, and approval decisions remain with accountable owners.', N'Validation and evidence', N'Confirming the technical scope for ECIF now costs a conversation. Discovering it late costs a decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-02-ALT-01', N'WF-X-ARCH-01', N'SE-ARCH-1', N'PH-SE-ARCH-1-EXPL', 3, N'Validate architecture evidence and assumptions', N'Find the unsupported claims and open security or operations questions in an architecture decision record before it is shared.', N'Extended', N'Prompt', N'Review the architecture decision record and source evidence. Identify unsupported claims, assumptions, security or operations questions, and reviewer needs.', NULL, N'The architecture decision record; the source evidence behind each option; the security and operations reviewers available to you.', N'Architecture evidence and assumption review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Architecture confidence improves when unsupported claims are visible before customer use.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-02-ALT-02', N'WF-X-ARCH-01', N'SE-ARCH-1', N'PH-SE-ARCH-1-EXPL', 4, N'Package the architecture handoff', N'Assemble the recommendation, criteria, dependencies and unresolved questions so the next technical stage can act on the decision.', N'Extended', N'Prompt', N'Package the architecture recommendation, decision criteria, dependencies, validation steps, risks, owners, and unresolved questions for the next technical stage.', NULL, N'The validated architecture decision record; the named owner for each dependency; the next technical stage and who leads it.', N'Architecture handoff package.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A clean handoff prevents design intent from changing silently during demo, PoC, or delivery.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-03-ALT-01', N'WF-X-ARCH-01', N'SE-ARCH-2', N'PH-SE-ARCH-2-EXPL', 3, N'Validate demo evidence and known limitations', N'Check what the demo actually proves, what it cannot, and which environment or permission constraints could break it on the day.', N'Extended', N'Prompt', N'Review the demo or workshop plan for evidence, known limitations, environment needs, permission constraints, and unsupported claims.', NULL, N'The demo or workshop plan; the environment and tenant it will run in; the claims you intend to make live.', N'Demo evidence and limitation review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'The strongest demo is honest about what it proves and what still needs validation.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-03-ALT-02', N'WF-X-ARCH-01', N'SE-ARCH-2', N'PH-SE-ARCH-2-EXPL', 4, N'Create the demo follow-up and decision package', N'Capture what the customer reacted to, what stayed unresolved, and the technical decision the demo was meant to move.', N'Extended', N'Prompt', N'Package the demo outcome, customer reactions, unresolved questions, evidence shown, follow-up owners, and next technical decision.', NULL, N'The demo plan as delivered; your notes on customer reactions and questions; the decision the demo was designed to advance.', N'Demo follow-up and decision package.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Follow-up turns the demo from an event into a decision step.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-04-ALT-01', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 3, N'Validate PoC success and exit criteria', N'Test whether the PoC has measurable success criteria and a real exit condition, or whether it will quietly become a project.', N'Extended', N'Prompt', N'Review the PoC plan for measurable success criteria, exit conditions, dependencies, security or data assumptions, milestones, and owner clarity.', NULL, N'The PoC plan with its stated criteria; the data and environment assumptions; the owner of the exit decision.', N'PoC criteria and readiness review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Measurable success and exit criteria prevent the PoC from becoming open-ended work.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-04-ALT-02', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 4, N'Create the PoC decision and handoff package', N'Package the hypothesis, criteria, exit decision and dependencies so the PoC result can be acted on rather than debated.', N'Extended', N'Prompt', N'Package the PoC hypothesis, scope, success criteria, exit decision, milestones, dependencies, owners, and handoff requirements.', NULL, N'The reviewed PoC plan; the milestone owners; the team receiving the result if it succeeds.', N'PoC decision and handoff package.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A PoC handoff makes the final decision and next stage inspectable.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-05-ALT-01', N'WF-X-CONV-01', N'SE-CONV', N'PH-SE-CONV-EXPL', 3, N'Route unsupported technical answers for review', N'Separate the answers that are supported from those needing an SME, policy owner or security reviewer, and name who decides each one.', N'Extended', N'Prompt', N'Review the answer matrix and create an exception list for unsupported, low-confidence, policy-sensitive, security-sensitive, or SME-needed items. Assign suggested reviewers and required decisions.', NULL, N'The completed answer matrix with confidence levels; your reviewer and SME contacts; the response deadline.', N'Exception and reviewer-routing list.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Showing uncertainty early is better than discovering it after the response is distributed.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-05-ALT-02', N'WF-X-CONV-01', N'SE-CONV', N'PH-SE-CONV-EXPL', 4, N'Prepare the response quality checklist', N'Build the final pass that catches unsourced claims, unapproved commitments and unresolved items before a technical response leaves the building.', N'Extended', N'Prompt', N'Create a final response quality checklist covering source completeness, claim review, assumptions, approvals, unresolved items, customer commitments, and distribution readiness.', NULL, N'The near-final response package; the approvals already obtained; the customer commitments it implies.', N'Technical response quality checklist.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'The checklist protects the SE from sending a fluent answer that still lacks approval or evidence.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-06-ALT-01', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 3, N'Validate the blocker evidence and mitigation path', N'Check that every blocker in the technical risk plan has evidence, an owner, a mitigation and a next decision rather than just a name.', N'Extended', N'Prompt', N'Review the technical risk plan and identify whether each blocker has evidence, impact, owner, mitigation, checkpoint, and a clear next decision.', NULL, N'The technical risk plan with its listed blockers; the evidence behind each; the owners you can realistically assign.', N'Blocker evidence and mitigation review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'A blocker without evidence and owner remains an observation, not a plan.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-06-ALT-02', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 4, N'Prepare the delivery or account-team handoff for technical risk', N'Package the technical risk, mitigation and re-engagement triggers so the account or delivery team can carry it without you in the room.', N'Extended', N'Prompt', N'Package the technical risk, evidence, mitigation, owners, dependencies, re-engagement triggers, and handoff requirements for the account team or delivery roles.', NULL, N'The reviewed technical risk plan; the mitigation owners; the delivery or account-team roles receiving the handoff.', N'Technical risk handoff package.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'A clear handoff prevents technical risk from being rediscovered after the deal progresses.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-07-ALT-01', N'WF-X-ASSET-01', N'SE-ASSET', N'PH-SE-ASSET-EXPL', 3, N'Sanitize and validate the reusable asset', N'Check a technical asset for sensitive content, accuracy and missing prerequisites before anyone else reuses it.', N'Extended', N'Prompt', N'Review the asset for sensitive content, technical accuracy, prerequisites, limitations, permissions, owner, and validation checks before reuse.', NULL, N'The draft asset; the customer context it was built from; your team''s rules on what may be shared internally.', N'Asset readiness and sanitization review.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Validation and evidence', N'Reusable assets create risk when sensitive content or unvalidated assumptions travel with them.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'SE-07-ALT-02', N'WF-X-ASSET-01', N'SE-ASSET', N'PH-SE-ASSET-EXPL', 4, N'Create the reuse note and repository metadata', N'Write the tags, purpose, prerequisites and limitations another SE needs to find the asset and know whether it fits their situation.', N'Extended', N'Prompt', N'Create the reuse note, tags, owner, purpose, prerequisites, example use, limitations, and repository metadata needed for another SE to find and adapt the asset.', NULL, N'The sanitized asset; where it will be stored; the owner who will maintain it.', N'Reuse note and repository metadata.', N'Confirm source accuracy, role ownership, customer context, policy or technical constraints, commitments, and any system action before use.', N'Synthesis and drafting', N'Findability and context are what turn a useful file into a reusable asset.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'SE-HEALTH-SCOUT-01', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 5, N'Monitor technical blockers across your accounts between reviews', N'Set up a standing watch on the technical signals that predict a stalled deployment, so intervention happens before the review rather than at it.', N'Extended', N'Both', N'Set up a recurring check across the accounts I support. Surface where deployment or consumption has flattened or declined, where a technical blocker has been open longer than expected, where a support pattern suggests an unresolved architectural issue, and where a planned milestone has slipped without a new date. For each, state the technical hypothesis and the evidence behind it, and name what you would need to confirm it. Do not diagnose root cause with confidence you do not have.', N'1. Confirm which deployment, consumption and support signals you can reach for the accounts you support.
2. Run the prompt.
3. Review each technical hypothesis and check the evidence actually supports it.
4. Set the cadence to land before your account or delivery review.
5. Confirm any blocker technically yourself before raising it with the customer.', N'The accounts you support; access to deployment, consumption and support signals; the committed technical milestones.', N'A recurring technical risk list with a stated hypothesis, supporting evidence, and the confirmation step for each item.', N'SE validates each hypothesis technically before raising it with the customer or the account team, and corrects any signal that reflects a known planned change.', N'Monitoring and signal', N'Technical blockers are cheapest to fix early and most expensive to fix at a review. The signal is usually present weeks before anyone names the problem.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SE-INVEST-01-P01', N'WF-INVEST-01', N'SE-INVEST', N'PH-SE-INVEST-EXPL', 1, N'Define the investment-funded technical scope and decision criteria', N'Bound what the investment is technically meant to prove, including the assumptions, dependencies and explicit out-of-scope items.', N'Featured', N'Prompt', N'Clarify the technical problem, bounded scope, architecture assumptions, decision criteria, dependencies, risks, and out-of-scope items that the proposed investment should address. Do not infer eligibility or approval.', NULL, N'Customer problem, opportunity context, proposed investment', N'Bounded technical scope and decision-criteria brief.', N'SE validates technical content and confirms that eligibility, policy, commercial, funding, and approval decisions remain with accountable owners.', N'Scoping and design', N'Clear technical scope prevents investment-funded work from expanding beyond the proof it was meant to produce.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-INVEST-01-P02', N'WF-INVEST-01', N'SE-INVEST', N'PH-SE-INVEST-EXPL', 2, N'Create the technical evidence and success-measure package', N'Define the proof, milestones and observable success measures that let a reviewer judge whether the funded work delivered.', N'Featured', N'Prompt', N'Identify the technical proof, readiness evidence, milestones, observable success measures, failure indicators, and review gates needed to evaluate the investment-funded work.', NULL, N'Draft scope and technical context', N'Technical evidence and success-measure package.', N'Confirm source accuracy, current policy and process, role ownership, decision authority, customer context, and any system action before use.', N'Synthesis and drafting', N'Observable success measures make the investment reviewable instead of anecdotal.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-INVEST-01-P03', N'WF-INVEST-01', N'SE-INVEST', N'PH-SE-INVEST-EXPL', 3, N'Pressure-test investment scope against failure modes', N'Stress the proposed technical scope for the assumptions and failure modes that would undermine the investment.', N'Featured', N'Prompt', N'Using the draft technical scope and architecture assumptions, identify the assumptions that would most damage the outcome if wrong, the failure modes that would surface during delivery, and the evidence that would confirm or rule out each one.', NULL, N'Draft technical scope, architecture assumptions, known constraints', N'Ranked assumption and failure-mode register with the evidence needed to close each one.', N'Confirm the grounding sources, separate evidence from assumption, and validate the named owner and next decision before this reaches a customer or an approver.', N'Assumption testing', N'Failure modes found during scoping are cheaper than failure modes found during delivery.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-INVEST-01-P04', N'WF-INVEST-01', N'SE-INVEST', N'PH-SE-INVEST-EXPL', 4, N'Prepare the technical handoff to delivery', N'Package the technical scope, evidence and success measures for the roles who will deliver against them.', N'Featured', N'Prompt', N'Using the approved technical scope, evidence package and success measures, prepare a handoff for the delivery roles. State what is decided, what remains open, and which technical decisions must not change without returning to you.', NULL, N'Approved scope, technical evidence package, success measures', N'Delivery handoff with decided items, open questions and re-engagement triggers.', N'Confirm the grounding sources, separate evidence from assumption, and validate the named owner and next decision before this reaches a customer or an approver.', N'Conversation preparation', N'A handoff protects the technical decisions that should not change without re-engaging the SE.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SE-INVLINK-01', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 5, N'Define what an investment-funded proof must demonstrate', N'Set the success criteria for technical work that customer investment would fund.', N'Featured', N'Prompt', N'For the proposed proof of concept or workshop, define what an investment-funded engagement would need to demonstrate, the observable success measures, the exit criteria and the evidence that would satisfy a reviewer. Do not assume the investment is approved.', NULL, N'Draft proof or workshop scope, customer decision criteria', N'Success and exit criteria specific enough to justify and later evaluate an investment.', N'SE validates that the criteria are observable and that scope is bounded.', N'Set the success criteria for technical work that customer investment would fund.', N'This links PoC scope to investment readiness without implying the investment is approved.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SSP-COMP-SCOUT-01', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 6, N'Build a reusable objection and language library from real calls', N'Mine your own customer conversations for the objections and language that keep recurring, and turn them into something the team can reuse.', N'Featured', N'Both', N'Work across my customer meeting transcripts and mail from the last quarter for [solution area]. Identify the objections that keep recurring, the language customers actually use to describe the problem we solve, the competitor claims that come up, and the points where conversations stall. Group them by how often they appear. For each recurring objection, show me the customer''s own words rather than a paraphrase, and note which conversations it came from so I can go back to the source.', N'1. Confirm you can reach your own meeting transcripts and mail for this solution area.
2. Run the prompt.
3. Check the recurring objections against your own memory of those calls before treating them as a pattern.
4. Keep the customer language the customer actually used rather than rewriting it into product language.
5. Share the library with your solution area only after removing customer-identifying detail.', N'Approved access to your own meeting transcripts and mail; the solution area in scope; a quarter or more of conversations.', N'An objection and customer-language library grouped by frequency, quoted in the customer''s own words, traceable back to source conversations.', N'SSP verifies the quotes against the source conversation, removes anything customer-identifying before sharing, and decides what is safe to circulate beyond the account team.', N'Analysis and assessment', N'The most useful competitive content is already sitting in conversations you have had. Reading a quarter of transcripts by hand is not realistic, which is why this pattern only became available recently.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'SSP-INVEST-01-P01', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 1, N'Assess investment fit and request readiness', N'Assemble an investment readiness assessment without determining eligibility or approval.', N'Featured', N'Prompt', N'Using approved customer, opportunity, workload, partner, and engagement context, assemble an investment readiness assessment. Identify confirmed inputs, gaps, dependencies, and questions requiring a process owner. Do not determine final eligibility or approval.', NULL, N'Customer outcome; opportunity context; engagement intent; partner context.', N'Readiness assessment with confirmed inputs, gaps, owners, and next decision.', N'SSP confirms source accuracy, current policy/process boundaries, role ownership, decision authority, and customer context.', N'Analysis and assessment', N'Working through readiness forces a position without overstating authority.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-01-P02', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 2, N'Build the request preparation package', N'Organize approved investment inputs into a preparation package.', N'Featured', N'Prompt', N'Organize approved investment inputs into a preparation package. Separate facts from assumptions, identify role contributions, and show unresolved dependencies. Do not submit, approve, or invent missing information.', NULL, N'Approved account, technical, delivery, partner, and outcome inputs.', N'Request preparation package with confirmed facts, open questions, contributions, and human decisions.', N'SSP confirms source accuracy, current policy/process boundaries, role ownership, decision authority, and customer context.', N'Synthesis and drafting', N'Most request delay is missing inputs and unclear ownership.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-01-P03', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 3, N'Coordinate contributors, suppliers, and handoffs', N'Map contributors, partner/supplier inputs, dependencies, and handoff points.', N'Featured', N'Prompt', N'Map the contributors, partner or supplier inputs, dependencies, and handoff points for the proposed investment. Identify stalled items and owners. Do not imply funding or approval status.', NULL, N'Current request context and contributor information.', N'Contributor and handoff map with inputs, owners, dependencies, and escalation questions.', N'SSP confirms source accuracy, ownership, decision authority, and status before use.', N'Coordination and handoff', N'Contributor handoffs are invisible when they work and obvious when they fail.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-01-P04', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 4, N'Connect investment to the opportunity decision path', N'Explain how investment supports the customer decision, milestones, readiness, and outcomes.', N'Featured', N'Prompt', N'Explain how the proposed investment supports the customer decision, engagement milestones, implementation readiness, and intended outcomes. Separate evidence from assumptions and do not represent funding as approved.', NULL, N'Opportunity strategy; proposed investment; supported outcomes.', N'Investment-to-opportunity rationale with evidence, milestones, dependencies, and next decision.', N'SSP confirms the barrier is real, investment is an appropriate lever, and no approval or funding status is overstated.', N'Value translation', N'Investment should connect to a customer decision, not sit beside the pursuit.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-01-P05', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 5, N'Track request status and identify the next supported action', N'Summarize current request stage, owner, blockers, and next supported action.', N'Featured', N'Prompt', N'Summarize the current investment request stage, known owner, blockers, pending information, and next supported action using approved status sources. Do not claim unsupported editing, automation, eligibility, funding, or approval status.', NULL, N'Approved request status and notifications.', N'Status and next-action brief with owner, blockers, and questions.', N'SSP verifies current status against authoritative records before acting or reporting.', N'Monitoring and signal', N'With request status, the change finds you instead of you remembering to look.', N'https://aka.ms/SalesM365', N'Open ECIF Agent'),
        (N'SSP-INVEST-P06', N'WF-INVEST-01', N'SSP-INVEST', N'PH-SSP-INVEST-EXPL', 6, N'Submit the request and know where it went', N'Move the prepared request into MSX Deal Assistance, confirm what is required before submission, and know how to check its status afterwards.', N'Featured', N'Both', N'I have a prepared investment request for [opportunity]. Before I submit it in MSX Deal Assistance, check my package against what a complete submission needs: opportunity linkage, business justification, ROI rationale, workscope reference, supplier detail if applicable, and the consumption plan if this is a Global ECIF or ACO request. Tell me what is missing or thin, and what an approver is most likely to send back. Do not tell me it is eligible or approvable; that is not your call.', N'1. Run the prompt against your prepared package.
2. Close whatever it flags as missing.
3. Open the opportunity in MSX, go to the Deal Assistance tab, select New Request, and choose the request type.
4. Attach the workscope from ECIF Central if the request needs one.
5. Submit, then note where the tracker view shows it sitting and who holds it.
6. If you are blocked on access or process rather than a decision, go to MCAPS Help rather than waiting.', N'The prepared request package. The MSX opportunity. The workscope from ECIF Central if applicable. Access to MSX Deal Assistance.', N'A submitted request with a known status, a named current owner, and a completeness check done before submission rather than after a rejection.', N'SSP confirms the business justification is genuine rather than assembled to pass a check, and accepts that eligibility, policy, and funding decisions belong to the accountable owners rather than to the seller or the tool.', N'Execution and validation', N'A request that comes back for missing information costs a cycle. Most of what gets sent back is knowable before submission.', N'https://microsoftsales.crm.dynamics.com/main.aspx?appid=fe0c3504-3700-e911-a849-000d3a10b7cc&forceUCI=1&pagetype=entitylist&etn=opportunity&viewid=00000000-0000-0000-00aa-000010003000&viewType=1039', N'Open MSX Opportunities'),
        (N'SSP-INVLINK-01', N'WF-X-ORCH-01', N'SSP-ORCH', N'PH-SSP-ORCH-EXPL', 2, N'Bring funding into the pursuit orchestration plan', N'Add investment and funding path to the specialist and partner plan.', N'Featured', N'Prompt', N'Using the current pursuit plan, identify where funding or customer investment is a dependency, who owns the request, what inputs are still missing, and the next governed action. Do not represent funding as approved.', NULL, N'Current pursuit plan; contributor list; known funding dependencies.', N'Pursuit plan with funding dependency, owner, and next action made explicit.', N'SSP confirms ownership of the request and that no funding status is overstated.', N'Coordination and handoff', N'Funding is part of orchestration when it changes the pursuit path.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'SSP-LEAD-SCOUT-01', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 5, N'Close the loop on outreach that never got an answer', N'Track the outreach you have sent so the follow-ups that matter are surfaced and drafted rather than remembered.', N'Extended', N'Both', N'Review the outreach I have sent over the last 30 days and identify every message where I asked for something - a meeting, an introduction, a decision, or information - and did not receive a substantive reply. For each one, tell me how long it has been waiting, how important it looks based on the opportunity involved, and draft a short follow-up in my own voice that adds a new reason to respond rather than simply repeating the ask. Do not send anything.', N'1. Confirm the check can see your sent messages for the last 30 days.
2. Run the prompt.
3. Review the ranked list and remove any thread where the silence is itself the answer.
4. Edit every drafted follow-up so it adds a new reason to reply rather than repeating the ask.
5. Send them yourself; do not let the check send on your behalf.', N'Access to your sent messages; your current lead and opportunity list; your team''s follow-up cadence norms.', N'A ranked list of unanswered asks with elapsed time and a drafted follow-up for each that adds new value rather than repeating.', N'SSP reviews and edits every draft before sending, and removes any follow-up where the silence is itself the answer.', N'Follow-through and orchestration', N'Most lost specialist opportunities are not rejected - they are dropped. The follow-up that would have converted was never sent because it was never surfaced.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'WF-ARCH-01-P-CSA-01', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 1, N'Compare production architecture options', N'Investigate current architecture patterns and evidence.', N'Featured', N'Prompt', N'Research architecture options for [workload/customer scenario] using approved Microsoft and authoritative public sources. Compare security, resilience, governance, scale, operational complexity, cost considerations, dependencies and maturity. Cite claims, identify conflicting guidance or missing evidence, and do not recommend until decision criteria are explicit.', NULL, N'Outcome; workload; constraints; decision criteria; allowed sources.', N'Sourced option comparison.', N'CSA validates source authority, applicability, security, compliance and recommendation boundaries.', N'Prioritization', N'Comparing production architecture options surfaces the difference that actually changes the decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-ARCH-01-P-CSA-02', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 2, N'Create the production-ready architecture package', N'Produce a bounded architecture decision package.', N'Featured', N'Prompt', N'Create a production-ready architecture decision package for [Customer/workload] using approved context and option analysis. Include desired outcome, current state, recommended architecture, alternative, tradeoffs, controls, governance, dependencies, sequence, readiness criteria, open decisions, and a human-review checklist. Stop and ask when evidence conflicts or a material decision lacks an owner.', NULL, N'Approved architecture context and reviewers.', N'Architecture decision package.', N'CSA owns the recommendation and obtains required reviews.', N'Synthesis and drafting', N'You spend your time editing the production-ready architecture package rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-CE-APPROVAL-01-P-CE-01', N'WF-X-DEAL-01', N'CE-DEAL-1', N'PH-CE-DEAL-1-EXPL', 2, N'Map approvals and fastest governed path', N'Identify approval, policy and escalation dependencies.', N'Featured', N'Prompt', N'Review opportunity [ID] and map all known approvals, policy checks, reviewers, dependencies and escalation paths. Highlight blockers, missing evidence and the next action for each. Draft a Deal Desk justification, but do not submit it.', NULL, N'Opportunity ID and approved materials.', N'Approval map and draft justification.', N'CE validates approval requirements, evidence, routing, precedent and final submission.', N'Problem identification', N'Naming approvals and fastest governed path is most of the work. Unnamed problems never get an owner.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-APPROVAL-01-P-CE-02', N'WF-X-DEAL-01', N'CE-DEAL-1', N'PH-CE-DEAL-1-EXPL', 3, N'Create the commercial execution tracker', N'Coordinate approvals, amendments and close actions.', N'Featured', N'Prompt', N'Using approved deal materials, create an execution tracker with action, owner, evidence, dependency, due checkpoint, status, blocker, escalation and decision required. Separate customer actions from internal actions.', NULL, N'Approved deal materials.', N'Commercial execution tracker.', N'CE confirms owners, dates, approvals, customer commitments and system-of-record updates.', N'Synthesis and drafting', N'You spend your time editing the commercial execution tracker rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-CE-NEG-01-P-CE-01', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 3, N'Build the negotiation strategy and concession plan', N'Prepare positions and value trades before negotiation.', N'Featured', N'Prompt', N'Build a negotiation plan for [deal]. Include customer objectives, Microsoft objectives, opening position, must-have terms, tradable items, concession ladder, give/get logic, likely objections, walk-away or escalation triggers and next decision.', NULL, N'Approved deal and authority context.', N'Negotiation and concession plan.', N'CE validates authority, customer context, policy, value trades and escalation triggers.', N'Synthesis and drafting', N'Most of the effort in the negotiation strategy and concession plan is assembly, and assembly is exactly what AI removes.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-NEG-01-P-CE-02', N'WF-X-DEAL-01', N'CE-DEAL-3', N'PH-CE-DEAL-3-EXPL', 4, N'Rehearse the commercial negotiation', N'Practice objections, value trades and decision control.', N'Featured', N'Prompt', N'Role-play the upcoming commercial negotiation using the approved plan. Simulate realistic customer objections and requests. Pause for my response, then coach clarity, value trading, concession discipline, policy boundaries and the next decision. Do not invent terms or authority.', NULL, N'Approved negotiation plan.', N'Negotiation rehearsal and coaching actions.', N'CE validates all positions, concessions, authority and customer commitments before use.', N'Conversation preparation', N'Ten minutes rehearsing the commercial negotiation is cheaper than improvising it in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-CE-POLICY-01-P-CE-01', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 1, N'Map eligibility, policy, and execution requirements', N'Apply current authoritative guidance to a proposed structure and route open questions.', N'Featured', N'Prompt', N'Using current approved guidance and the proposed segment, products, SKUs, terms, agreement context, and exception questions, identify eligibility considerations, required amendments, execution steps, approval needs, side-agreement risk, and authoritative owners. Cite the exact guidance used and flag uncertainty. Do not approve exceptions.', NULL, N'Current approved guidance and proposed offer.', N'Policy, eligibility, and execution map with cited guidance, open questions, and owners.', N'CE validates source version, interpretation, required legal, finance, policy, or Deal Desk review, and any customer-facing use.', N'Validation and evidence', N'The useful AI output is not a guessed policy answer. It is the right question, evidence, and owner.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-CE-POLICY-01-P-CE-02', N'WF-X-POLICY-01', N'CE-POLICY', N'PH-CE-POLICY-EXPL', 2, N'Inspect licensing, discount, and compliance risk', N'Review the proposed structure for commercial risk.', N'Featured', N'Prompt', N'Review the proposed licensing, discount, and compliance structure for [account/opportunity]. Identify unused or mismatched licensing, discount exceptions, compliance concerns, policy questions, approval requirements, renewal risk, and evidence gaps. Cite sources where available.', NULL, N'Proposed licensing and discount structure.', N'Licensing, discount, and compliance risk review with evidence gaps and approval questions.', N'CE validates licensing, eligibility, discount authority, policy and recommended action.', N'Inspection and review', N'Reviewing licensing and discount risk is judgment work. The agent proposes; the CE remains accountable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-RENEW-01-P-CE-01', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 1, N'Build the CE-led renewal strategy view', N'Surface renewal economics, risk and expansion early.', N'Featured', N'Prompt', N'For [account name or TPID], show the upcoming renewals with expiry dates and current agreement details, then for the agreement I name provide the license estate grouped by SKU, the SKUs whose discount is between 40 and 60 percent, and ACR trends month over month. Build a CE-led renewal strategy view covering structure, MACC trajectory, consumption signals, current discounts and concessions, risk, expansion potential, and amendments in play. Separate what the source systems returned from what you inferred, and do not represent any concession or discount as approved.', NULL, N'Account and approved renewal context.', N'Renewal strategy brief with commercial structure, risk, expansion potential, approval path, and evidence gaps.', N'CE validates contract, revenue, usage, structure, risk, authority and ownership.', N'Synthesis and drafting', N'Most of the effort in the renewal strategy view is assembly. The strategy decision stays human-led.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-RENEW-01-P-CE-02', N'WF-X-RENEW-01', N'CE-RENEW', N'PH-CE-RENEW-EXPL', 2, N'Inspect upcoming renewal portfolio for CE intervention', N'Prioritize renewals requiring CE intervention.', N'Featured', N'Prompt', N'Show upcoming renewals in the selected period for my scope. Prioritize by revenue, discount exposure, consumption or MACC risk, execution complexity, expansion potential, approval requirements, and evidence quality. Explain the certified signal behind each priority.', NULL, N'Approved renewal report and scope.', N'Prioritized renewal radar with intervention rationale, evidence quality, and missing data.', N'CE validates report scope, signals, ownership and recommended intervention.', N'Inspection and review', N'Reviewing the renewal portfolio is judgment work. The agent proposes; the CE stays accountable.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-CE-RISK-01-P-CE-01', N'WF-X-HEALTH-01', N'CE-HEALTH', N'PH-CE-HEALTH-EXPL', 1, N'Identify commercial risk and escalation priorities', N'Use approved signals to prioritize commercial risk, source evidence, and escalation needs.', N'Featured', N'Prompt', N'Review the approved commercial, renewal, agreement, and deal signals for [scope]. Identify the top commercial risks, the supporting source signal, likely impact, recommended intervention, owner, escalation need, and any unavailable or stale data. Separate evidence from interpretation.', NULL, N'Approved scope, current commercial signals, renewal or agreement context, and known ownership.', N'Prioritized commercial risk view with evidence, intervention, owner, escalation need, and source gaps.', N'CE validates data scope, source freshness, business context, risk interpretation, mitigation, owner, and escalation route.', N'Problem identification', N'Commercial risk found early is a conversation. The same risk found at approval becomes delay.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-CE-RISK-01-P-CE-02', N'WF-X-HEALTH-01', N'CE-HEALTH', N'PH-CE-HEALTH-EXPL', 2, N'Build the commercial decision brief', N'Prepare commercial talking points, decision needs, and authority boundaries for a live customer or deal review.', N'Featured', N'Prompt', N'Prepare the CE commercial decision brief for [account/opportunity]. Include contract context, proposed structure, concessions or terms requiring review, current approvals, renewal or consumption risk, likely customer questions, authority boundaries, and the next commercial decision. Flag any customer-facing claim requiring review.', NULL, N'Account or opportunity context.', N'Commercial decision brief with authority boundaries, risks, questions, and next decision.', N'CE validates terms, authority, source freshness, customer-facing positions, and required reviewers.', N'Synthesis and drafting', N'Most of the effort in the commercial decision brief is assembly. The judgment stays with the CE.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-STRUCT-01-P-CE-01', N'WF-X-DEAL-01', N'CE-DEAL-1', N'PH-CE-DEAL-1-EXPL', 1, N'Compare viable commercial structures', N'Develop decision-ready commercial options.', N'Featured', N'Prompt', N'For [opportunity], compare three viable commercial structures using available approved context. For each show products or SKUs, term, pricing logic, customer value, Microsoft trade-offs, risks, approvals and assumptions. Do not create or submit an offer.', NULL, N'Approved opportunity context.', N'Commercial options matrix.', N'CE validates pricing, products, licensing, authority, policy and feasibility.', N'Prioritization', N'Comparing viable commercial structures surfaces the difference that actually changes the decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CE-STRUCT-01-P-CE-02', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 1, N'Create the commercial decision narrative', N'Turn approved context into a concise internal recommendation.', N'Featured', N'Prompt', N'Using the approved deal context and options, draft a commercial decision narrative with customer outcome, options considered, recommended structure, value trades, assumptions, risks, required reviewers and next decision.', NULL, N'Approved deal context and options.', N'Internal commercial recommendation.', N'CE approves the recommendation and routes required review.', N'Synthesis and drafting', N'You spend your time editing the commercial decision narrative rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-CE-TRANS-01-P-CE-01', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 2, N'Research agreement and commerce changes', N'Ground migration advice in current authoritative sources.', N'Featured', N'Prompt', N'Research current differences between [legacy agreement] and [new commerce model] using authoritative Microsoft sources. Summarize commercial, administrative and customer-impact differences, risks, unresolved questions and citations.', NULL, N'Agreement models and authoritative sources.', N'Sourced transition evidence brief.', N'CE and policy, licensing or legal SMEs validate applicability and current guidance.', N'Analysis and assessment', N'Being able to cite agreement and commerce changes beats being able to remember it.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-CE-TRANS-01-P-CE-02', N'WF-X-DEAL-01', N'CE-DEAL-2', N'PH-CE-DEAL-2-EXPL', 3, N'Build the customer migration brief', N'Translate approved guidance into customer-specific decision support.', N'Featured', N'Prompt', N'Using approved customer contract context and validated transition guidance, create a migration brief with current state, contractual differences, administrative shift, amendment needs, red-line risks, choices, timeline, responsibilities and customer talk track.', NULL, N'Approved contract context and validated guidance.', N'Customer-specific migration brief.', N'CE validates contract interpretation, policy, dates, commitments and required reviewers.', N'Synthesis and drafting', N'Most of the effort in the customer migration brief is assembly, and assembly is exactly what AI removes.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-COMP-01-P-SSP-01', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 1, N'Build the competitive differentiation brief', N'Use approved win/loss and market context for a proof-backed competitive position.', N'Featured', N'Prompt', N'Produce a competitive differentiation brief for [solution area] and [customer context]. Include relevant win/loss drivers, three strongest differentiators with proof, common objections with handlers, risks, and a concise talk track. Flag where data or proof is weak.', NULL, N'Solution area; customer context; approved competitive and win/loss sources.', N'Competitive brief with differentiators, proof, objections, and talk track.', N'SSP validates freshness, source grounding, customer applicability, and claims before external use.', N'Synthesis and drafting', N'Competitive conversations are lost by improvisation.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-COMP-01-P-SSP-02', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 2, N'Research competitive and industry context', N'Investigate current evidence before positioning.', N'Featured', N'Prompt', N'Research [competitor], [solution area], and [customer industry]. Compare publicly supportable positions, proof, recent developments, common objections, and uncertainty. Do not infer confidential competitor information.', NULL, N'Competitor; solution area; industry; approved source boundaries.', N'Sourced competitive context brief.', N'SSP validates source quality, timeliness, relevance, and customer-facing claims.', N'Analysis and assessment', N'Being able to cite competitive context beats remembering it.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-COMP-01-P-SSP-03', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 3, N'Test the differentiator against the customer''s real decision criteria', N'Pressure-test each claimed differentiator against what this customer actually said they will decide on, and drop the ones that do not connect.', N'Extended', N'Both', N'You are helping a specialist seller sharpen a competitive position. Here is the customer''s stated decision criteria and evaluation process: [paste criteria, evaluation team, timeline]. Here are the differentiators we plan to lead with: [paste differentiators and proof]. For each differentiator, state which specific decision criterion it addresses, how directly it addresses it, and what proof the customer would need to accept it. Identify any differentiator that does not map to a stated criterion and recommend dropping or reframing it. Flag any criterion we currently have no answer for. Do not add differentiators that are not in my list.', N'1. Gather the customer''s stated decision criteria from meeting notes or MSX.
2. List current differentiators and their proof.
3. Run the prompt.
4. Cut differentiators that do not map to a criterion.
5. Name the gaps you cannot yet answer.', N'Customer decision criteria and evaluation process; current differentiators and supporting proof; who is on the evaluation team.', N'A shortened differentiator list mapped to decision criteria, plus a named list of criteria with no current answer.', N'SSP confirms the decision criteria are what the customer actually said rather than what the team assumes, and owns the decision to drop a differentiator.', N'Analysis and assessment', N'A differentiator the customer is not deciding on is noise, however true it is.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-COMP-01-P-SSP-04', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 4, N'Rehearse the competitive conversation and build the objection handler', N'Practice the response out loud, then convert what broke into a written objection handler tied to approved proof.', N'Extended', N'Both', N'Play the role of a technical evaluator at [customer] who currently favors [competitor]. I will present our competitive position. Challenge me the way that evaluator would, including on price, migration effort, and lock-in. After three exchanges, stop the role-play and produce an objection handler table: each objection you raised, my response, the approved proof that supports it, and a note where no approved proof exists. Do not soften the objections and do not supply proof I have not given you.', N'1. Bring the differentiator list from the previous activity and the approved competitive proof.
2. Run a short rehearsal with the agent as the skeptical evaluator.
3. Have it produce the objection handler table.
4. Fill or remove any row where proof is missing.
5. Bring the table to the huddle.', N'Competitive position and differentiators; the competitor in play; approved competitive proof sources; known evaluator concerns; customer role you will be speaking to.', N'An objection handler table mapping each objection to a response and the approved proof behind it, with proof gaps named.', N'SSP judges whether the rehearsed language is accurate, appropriate for this customer, and consistent with approved competitive guidance before using it externally.', N'Practice and rehearsal', N'Competitive conversations are lost in the moment, not in the brief.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-COMP-01-P-SSP-05', N'WF-X-DEAL-01', N'SSP-COMP', N'PH-SSP-COMP-EXPL', 5, N'Convert the competitive position into the next customer step', N'Turn the position into a concrete next action in the opportunity rather than a document that stops at the brief.', N'Extended', N'Both', N'Using this competitive position and the customer''s decision criteria [paste], propose the single next step that would most reduce competitive risk in this opportunity. Give me three options ranked by impact, each with: what it is, who from our side needs to be involved, what the customer gets out of it, and what evidence it would generate for the decision. Then draft the short note I would send to the customer to set it up. Keep the note under 120 words and do not overstate what we have proven.', N'1. Bring the tested differentiator list and the open gaps.
2. Run the prompt.
3. Pick one next step.
4. Adjust the draft note in your own voice.
5. Record the next step in the opportunity.', N'Tested differentiators and open gaps; opportunity stage and close plan; who owns the customer relationship.', N'One chosen next step with owner and purpose, and a short customer-ready note to set it up.', N'SSP owns the choice of next step and the customer-facing wording, and confirms it fits the account team''s plan before sending.', N'Planning and drafting', N'A competitive brief that does not change the next customer interaction has not changed the deal.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CONSUME-01-P-CSA-01', N'WF-X-PIPE-01', N'CSA-PIPE', N'PH-CSA-PIPE-EXPL', 1, N'Analyze consumption trajectory and shortfall drivers', N'Ask what certified consumption data says.', N'Featured', N'Prompt', N'For [Customer] and [period], analyze enabled consumption trajectory and compare it with the relevant plan or milestone view. Break down largest changes by available dimension, identify data-supported contributors to potential shortfall, show supporting metrics and state what the report cannot answer.', NULL, N'Enabled certified report; customer; period.', N'Consumption trajectory analysis.', N'CSA confirms scope, KPI definitions, technical significance and credibility.', N'Analysis and assessment', N'Working through consumption trajectory and shortfall drivers forces a position, and a position is what the decision needs.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-CONSUME-01-P-CSA-02', N'WF-X-PIPE-01', N'CSA-PIPE', N'PH-CSA-PIPE-EXPL', 2, N'Design a technical shortfall intervention', N'Connect customer context to intervention planning.', N'Featured', N'Prompt', N'Using approved consumption analysis and available context for [Customer], identify technical blockers, workload milestones, stakeholders, commitments and dependencies relevant to the potential shortfall. Propose intervention options, owner candidates, customer touchpoints and evidence needed. Do not assume cause or make commitments.', NULL, N'Approved analysis and authorized context.', N'Intervention options with evidence, owners and gaps.', N'CSA selects intervention and validates cause, context, ownership and commitments.', N'Scoping and design', N'Settling a technical shortfall intervention before the work starts is the only version of that decision that holds.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CONV-01-P-AE-JAI', N'WF-X-CONV-01', N'AE-CONV', N'PH-AE-CONV-EXPL', 3, N'Rehearse the executive customer conversation', N'Rehearse the executive customer conversation', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the upcoming [meeting type] with [customer or stakeholder]. Use the approved conversation plan and focus on the AE contribution: executive narrative, customer outcome, primary ask, fallback ask, likely questions, and relationship-sensitive responses. Simulate realistic questions or objections, pause for the team member response, then provide coaching on clarity, evidence, listening, and the proposed next step. Identify claims, commitments, technical guidance, or commercial positions that require human or SME review. Do not invent customer facts or make commitments.', NULL, N'Approved conversation plan; meeting type; customer or stakeholder context; role contribution; desired decision or outcome; known boundaries.', N'Role-play output with likely questions, coaching observations, improvement actions, and claims requiring review.', N'AE validates customer facts, commitments, technical or commercial guidance, and final wording before customer use.', N'Conversation preparation', N'Rehearsal lets weak claims fail safely before the customer hears them.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-CONV-01-P-SSP-01', N'WF-X-CONV-01', N'SSP-CONV', N'PH-SSP-CONV-EXPL', 1, N'Prepare the solution-specific customer conversation', N'Build grounded discovery, proof, objection, role contribution, and ask structure.', N'Featured', N'Prompt', N'Prepare me for the upcoming [meeting] with [account]. Summarize priorities, stakeholders, open risks, competitive mentions, and solution context. Draft five discovery questions, proof points, likely objections with responses, role contributions, primary ask, and fallback ask. Flag uncertainty.', NULL, N'Account; meeting; solution play; current stage; approved sales context.', N'Conversation plan with discovery questions, proof, objections, role contributions, and ask.', N'SSP validates customer facts, evidence, competitive claims, commitments, and the final ask.', N'Conversation preparation', N'Preparation is where the solution conversation is decided.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CONV-01-P-SSP-03', N'WF-X-CONV-01', N'SSP-CONV', N'PH-SSP-CONV-EXPL', 3, N'Find the discovery gap before the meeting, not after', N'Check what you still do not know that would change your recommendation, and build the question that closes it.', N'Extended', N'Both', N'Here is what we currently know about [account] for [solution play]: [paste priorities, environment, stakeholders, constraints, prior conversations]. Identify what we do not know that would materially change our recommendation, ranked by how much it would change it. For the top three unknowns, write one open question each that could be asked naturally in the upcoming conversation without sounding like a survey. Distinguish what we actually know from what we have assumed.', N'1. Assemble what is known about the account.
2. Run the prompt.
3. Separate known from assumed.
4. Choose one question to definitely ask.
5. Add it to the conversation plan.', N'Everything currently known about the account and solution context; prior conversation notes; the recommendation you intend to make.', N'A ranked list of decision-changing unknowns and three natural questions to close the top ones.', N'SSP verifies which items are genuinely known versus assumed by the account team, and chooses which question is worth the meeting time.', N'Problem identification', N'The most expensive assumptions are the ones nobody noticed they were making.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-CONV-01-P-SSP-04', N'WF-X-CONV-01', N'SSP-CONV', N'PH-SSP-CONV-EXPL', 4, N'Turn the conversation into decisions and commitments', N'Convert meeting notes into what changed, what was agreed, and what the customer actually committed to.', N'Extended', N'Both', N'Here are my notes from the customer conversation: [paste notes or transcript summary]. Produce three separate lists: what we learned that changes our understanding, what was explicitly agreed and by whom, and what remains open. Then draft a short follow-up note to the customer confirming only what was actually agreed. Do not record something as agreed if the notes only show it was discussed. Flag anything ambiguous rather than resolving it.', N'1. Capture notes immediately after the meeting.
2. Run the prompt.
3. Check the agreed list against your memory.
4. Send the follow-up note.
5. Update the opportunity with what changed.', N'Meeting notes or transcript summary; who attended; what was asked for; the conversation plan you went in with.', N'Separated lists of learnings, agreements, and open items, plus a short confirming follow-up note.', N'SSP confirms that anything recorded as agreed was actually agreed, and owns the follow-up wording before sending.', N'Synthesis and drafting', N'Deals slip on the gap between what was discussed and what was agreed.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-CONV-01-P-SSP-JAI', N'WF-X-CONV-01', N'SSP-CONV', N'PH-SSP-CONV-EXPL', 2, N'Rehearse solution discovery and objection handling', N'Rehearse the solution conversation and receive coaching before customer use.', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the upcoming [meeting type] with [customer or stakeholder]. Use the approved conversation plan and focus on solution discovery, differentiation, proof points, likely objections, next solution decision, and primary ask. Pause for the team member response, then coach clarity, evidence, listening, and next step. Do not invent customer facts or commitments.', NULL, N'Approved conversation plan; meeting type; customer context; desired outcome.', N'Interactive role-play, targeted coaching, objections, and improvement list.', N'SSP validates facts, claims, commitments, guidance, and decides what to change before customer use.', N'Conversation preparation', N'Ten minutes rehearsing is cheaper than improvising in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-DEAL-01-P-SSP-01', N'WF-X-DEAL-01', N'SSP-DEAL', N'PH-SSP-DEAL-EXPL', 1, N'Inspect solution opportunity readiness', N'Identify the decision or blocker preventing progression.', N'Featured', N'Prompt', N'Review opportunity [ID] for [solution play]. Summarize current stage, customer outcome, stakeholder coverage, proof or demo status, technical and commercial dependencies, partner or funding needs, blockers, and the single next decision required. Recommend actions with owners.', NULL, N'Opportunity ID; solution play; current sales context.', N'Readiness view with blockers, next decision, actions, and owners.', N'SSP validates stage, blockers, owners, dependencies, and commitments.', N'Inspection and review', N'Readiness inspection is judgment work. The agent proposes; the SSP stays accountable.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-DEAL-01-P-SSP-02', N'WF-X-DEAL-01', N'SSP-DEAL', N'PH-SSP-DEAL-EXPL', 2, N'Create the solution acceleration action plan', N'Turn enabled opportunity data into prioritized actions.', N'Featured', N'Prompt', N'For my active [solution area] opportunities, identify stalled milestones, missing customer evidence, stakeholder gaps, and next actions. Prioritize the opportunities requiring SSP intervention this week.', NULL, N'Enabled MSXI report or opportunity context.', N'Prioritized solution-opportunity action plan.', N'SSP validates report scope, stage, risk, intervention, and ownership.', N'Synthesis and drafting', N'The path advances when blockers, owners, and next decisions are explicit.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-DEAL-01-P-SSP-03', N'WF-X-DEAL-01', N'SSP-DEAL', N'PH-SSP-DEAL-EXPL', 3, N'Prepare the conversation that clears the next decision', N'Design the single conversation that would unblock the opportunity, and decide who needs to be in it.', N'Extended', N'Both', N'For opportunity [ID], the next decision required is [paste decision] and the current blocker is [paste blocker]. Design the one conversation that would most likely clear it: who needs to be in the room from both sides, what each person needs to hear, what we must bring as evidence, what we are asking them to decide by the end, and what we do if they say not yet. Keep it to one conversation; do not propose a sequence of three meetings.', N'1. Bring the readiness view and the named blocker.
2. Run the prompt.
3. Confirm the attendee list is realistic.
4. Prepare the evidence.
5. Schedule it.', N'The readiness view; the next decision required; the current blocker; stakeholder coverage; available evidence and proof.', N'A single conversation design with attendees, evidence needed, the decision being asked for, and a fallback.', N'SSP validates that the named blocker is the real one, confirms attendees with the account team, and owns what is asked of the customer.', N'Conversation preparation', N'Most stalled opportunities need one specific conversation, not more activity.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-DEAL-01-P-SSP-04', N'WF-X-DEAL-01', N'SSP-DEAL', N'PH-SSP-DEAL-EXPL', 4, N'State the close plan in the customer''s terms', N'Rewrite the close plan as the customer''s path to their outcome, so it can be shared with them rather than kept internal.', N'Extended', N'Both', N'Rewrite this internal close plan [paste] as a shared plan from the customer''s point of view. Replace our sales stages with their decision milestones, name what they need from us at each step and what we need from them, and end with the outcome they said they wanted. Remove internal language, forecast terms, and anything we would not want a customer to read. Flag any step that depends on something we have not confirmed with them.', N'1. Bring the internal close plan.
2. Run the prompt.
3. Remove anything still internal.
4. Check every date is one the customer has agreed to.
5. Share it and ask them to correct it.', N'The internal close plan; the customer''s stated outcome and decision process; confirmed dates versus assumed dates.', N'A customer-facing shared plan organized around their decision milestones, with unconfirmed dependencies flagged.', N'SSP verifies no internal forecast language survives, confirms which dates the customer actually agreed to, and approves before sharing externally.', N'Value translation', N'A close plan the customer has never seen is a forecast, not a plan.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-LEAD-01-P-SSP-01', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 1, N'Build a prioritized lead follow-up plan', N'Combine scattered lead, event, account, and interaction signals into a structured SSP follow-up plan.', N'Featured', N'Prompt', N'Using approved lead, attendee, account, email, meeting, and public context, create a prioritized follow-up plan for [solution area]. For each lead include source, account, likely interest, solution relevance, suggested message, owner, and next action. Flag missing evidence and do not send outreach.', NULL, N'Approved lead or attendee lists; account context; solution area; recent interactions.', N'Prioritized lead follow-up plan with source, fit, message, owner, and next action.', N'SSP validates consent, customer context, solution relevance, ownership, and outreach language before use.', N'Synthesis and drafting', N'Most of the effort in lead follow-up is assembly. AI can assemble; the SSP decides where to focus.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-LEAD-01-P-SSP-02', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 2, N'Identify missed solution-area opportunities', N'Use sales signals to identify solution-area opportunities the SSP may be missing.', N'Featured', N'Prompt', N'For [solution area] across my active accounts, identify opportunity signals I may be missing. Show the source signal, likely customer need, relevant solution play, uncertainty, and the next discovery action. Separate facts from recommendations.', NULL, N'SSP scope; solution area; available MSX and approved customer signals.', N'Ranked opportunity hypotheses with next discovery actions.', N'SSP validates signal quality, customer need, ownership, and whether an opportunity should be created or advanced.', N'Problem identification', N'Unnamed solution opportunities never get an owner.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-LEAD-01-P-SSP-03', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 3, N'Draft the first contact for the top-priority lead', N'Turn the top-ranked lead into a specific, short first message that connects the signal to a reason for the customer to respond.', N'Extended', N'Both', N'Here is the top lead from my follow-up plan: [paste source signal, account, role, likely interest, and any prior interaction]. Draft a first contact message under 100 words that references the specific signal, states one reason this is relevant to their business now, and asks for one small next step. Give me two versions: one for a business decision maker and one for a technical decision maker. Do not claim knowledge of their environment we do not have, and do not assert a product feature I have not given you.', N'1. Take the top lead from the prioritized plan.
2. Confirm consent and context are appropriate for outreach.
3. Run the prompt.
4. Edit into your own voice.
5. Send one, and note the date.', N'The prioritized lead plan; the source signal; the contact''s role; prior interaction history; consent and outreach appropriateness.', N'Two short first-contact drafts, one business and one technical, tied to the originating signal.', N'SSP confirms consent and outreach appropriateness, verifies every factual statement about the customer, and owns the wording before sending.', N'Synthesis and drafting', N'A prioritized list that never becomes a message is just a better-sorted backlog.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-LEAD-01-P-SSP-04', N'WF-X-OPP-01', N'SSP-LEAD', N'PH-SSP-LEAD-EXPL', 4, N'Close the loop on what the follow-up produced', N'Review the leads worked this week, record what happened, and decide which signals are worth trusting next time.', N'Extended', N'Both', N'Here are the leads I followed up this week and what happened with each: [paste lead, source signal, action taken, response or silence]. Tell me which signal sources produced a response and which did not, what the responses have in common, and which two signal types I should prioritize next week. Be direct about small sample size; do not overstate a pattern from a handful of leads.', N'1. List the leads worked and the outcome of each.
2. Run the prompt.
3. Record the outcome in the opportunity or lead record.
4. Name the one signal source you will deprioritize.', N'The leads worked this week; the originating signal for each; the action taken; the response or lack of one.', N'A short read on which signal sources are working, and one prioritization change for next week.', N'SSP judges whether the pattern is real or coincidence given the sample size, and owns the decision to change prioritization.', N'Analysis and assessment', N'Lead follow-up improves only if you find out which signals were worth following.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-OPT-01-P-CSA-01', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'PH-CSA-VALUE-1-EXPL', 1, N'Build the optimization evidence base', N'Analyze enabled usage, cost and consumption evidence.', N'Featured', N'Prompt', N'For [Customer] and [period], summarize enabled usage, consumption and cost signals relevant to optimization. Identify material changes and patterns visible in the report and supporting metrics. Separate observations from recommendations and state missing architecture or business context.', NULL, N'Enabled certified report and scope.', N'Optimization evidence summary.', N'CSA confirms KPI meaning, architecture context, priorities and actionability.', N'Synthesis and drafting', N'Most of the effort in the optimization evidence base is assembly, and assembly is exactly what AI removes.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-OPT-01-P-CSA-02', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'PH-CSA-VALUE-1-EXPL', 2, N'Create the FinOps and optimization recommendation', N'Produce a bounded optimization recommendation.', N'Featured', N'Prompt', N'Using approved evidence, create an optimization recommendation for [Customer/workload]. Include current state, outcome, options, supported technical and financial effect, architecture tradeoffs, dependencies, risks, milestones and human-review requirements. Do not invent savings or intent.', NULL, N'Approved evidence; architecture context; outcome; constraints.', N'Optimization recommendation.', N'CSA validates architecture, feasibility, claims, relevance and ownership.', N'Synthesis and drafting', N'You spend your time editing the FinOps and optimization recommendation rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SE-ARCH-01-P-SE-01', N'WF-X-ARCH-01', N'SE-ARCH-1', N'PH-SE-ARCH-1-EXPL', 1, N'Compare architecture options against decision criteria', N'Investigate external technical patterns and authoritative evidence.', N'Featured', N'Prompt', N'Research [architecture decision] using current authoritative Microsoft and approved customer sources. Compare viable options against [decision criteria], identify assumptions, risks, dependencies and evidence gaps, and cite each material claim.', NULL, N'Architecture decision; decision criteria; approved sources.', N'Sourced architecture options assessment.', N'SE and architecture SMEs validate current guidance, applicability and unsupported assumptions.', N'Prioritization', N'Comparing architecture options and evidence surfaces the difference that actually changes the decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-SE-ARCH-01-P-SE-02', N'WF-X-ARCH-01', N'SE-ARCH-1', N'PH-SE-ARCH-1-EXPL', 2, N'Create the architecture decision record', N'Turn approved evidence into a concise decision artifact.', N'Featured', N'Prompt', N'Using the approved discovery brief and architecture evidence, create a decision record with customer outcome, options considered, criteria, selected direction, risks, dependencies, validation steps, unresolved questions and next technical action.', NULL, N'Approved discovery brief and architecture evidence.', N'Architecture decision record.', N'SE validates architecture, security, operations, feasibility and customer commitments.', N'Synthesis and drafting', N'You spend your time editing the architecture decision record rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SE-ASSET-01-P-SE-01', N'WF-X-ASSET-01', N'SE-ASSET', N'PH-SE-ASSET-EXPL', 1, N'Package a reusable technical asset with context', N'Convert successful work into a repeatable, governed asset.', N'Featured', N'Prompt', N'Using the approved [demo, script, architecture, response or checklist], create a reusable asset package with purpose, prerequisites, steps, editable parameters, validation checks, known limitations, owner and example use.', NULL, N'Approved technical asset.', N'Reusable asset package.', N'SE removes sensitive content, validates technical accuracy and confirms reuse permissions.', N'Synthesis and drafting', N'Reuse happens when the asset includes enough context for another SE to trust and adapt it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SE-ASSET-01-P-SE-02', N'WF-X-ASSET-01', N'SE-ASSET', N'PH-SE-ASSET-EXPL', 2, N'Create a technical Skill Blueprint for a repeatable SE workflow', N'Turn a repeatable workflow into a structured personalized skill.', N'Featured', N'Both', N'Create a reusable Skill Blueprint for [SE workflow]. Define trigger, inputs, trusted sources, ordered steps, expected output, rules, exclusions, exception behavior, human review, validation checks, and one representative test case. Do not publish until tested.', N'1. Choose the asset worth reusing.
2. Invoke the skill in Scout or Cowork.
3. Review the generated structure at the checkpoint.
4. Add the context a colleague would need.
5. Publish where the team will actually look.', N'SE workflow; trusted sources; test case.', N'Technical Skill Blueprint with validation checks and test case.', N'SE or skill owner tests representative work and validates access, outputs, safeguards, and repository placement before promotion.', N'Synthesis and drafting', N'A blueprint lets the team test repeatability before pretending the skill is production-ready.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'WF-SE-DEAL-01-P-SE-01', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 1, N'Inspect technical deal health and proof gaps', N'Use available MSX and customer context to identify technical progression gaps.', N'Featured', N'Prompt', N'Review [opportunity] and summarize the intended customer decision, current technical stage, exit criteria, proof completed, open blockers, recent technical engagement, missing roles and next recommended technical action. Show the source signal and flag unavailable context.', NULL, N'Opportunity and available customer context.', N'Technical deal-health brief.', N'SE validates MSX accuracy, customer context, technical risk and the next action.', N'Inspection and review', N'Technical deal health improves when blockers, proof gaps, and next decisions are visible in one place.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-SE-DEAL-01-P-SE-02', N'WF-X-HEALTH-01', N'SE-HEALTH', N'PH-SE-HEALTH-EXPL', 2, N'Create the technical risk and handoff plan', N'Synthesize approved deal, proof and delivery context into an action plan.', N'Featured', N'Prompt', N'Using approved sources, create a technical risk and handoff plan with blocker, impact, evidence, owner, mitigation, checkpoint, decision needed and delivery handoff requirements.', NULL, N'Approved deal, proof and delivery sources.', N'Technical risk register and handoff plan.', N'SE confirms ownership, feasibility, customer commitments and delivery readiness.', N'Synthesis and drafting', N'Risk plans help only when they assign the owner, evidence, mitigation, checkpoint, and next decision.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SE-DEMO-01-P-SE-01', N'WF-X-ARCH-01', N'SE-ARCH-2', N'PH-SE-ARCH-2-EXPL', 1, N'Build the decision-centered demo or workshop plan', N'Create a bounded multi-part experience package.', N'Featured', N'Prompt', N'Create a demo or workshop package for [customer decision]. Include audience, scenario, decision criteria, agenda, demo flow, sample data needs, roles, likely objections, tenant or permission dependencies, fallback plan and explicit next decision.', NULL, N'Customer decision; audience; approved scenario.', N'Demo or workshop package.', N'SE validates the environment, permissions, technical behavior, evidence and customer appropriateness.', N'Synthesis and drafting', N'A decision-centered plan keeps the demo or workshop from becoming a feature tour.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SE-DEMO-01-P-SE-02', N'WF-X-ARCH-01', N'SE-ARCH-2', N'PH-SE-ARCH-2-EXPL', 2, N'Research supporting proof, limitations, and objections', N'Find authoritative evidence supporting the selected scenario.', N'Featured', N'Prompt', N'Find current authoritative evidence for [scenario or capability]. Return only claims relevant to the customer decision, likely objections, known limitations and SME-needed flags. Cite sources.', NULL, N'Scenario or capability; approved sources.', N'Evidence and objection brief.', N'SE validates freshness and applicability before customer use.', N'Analysis and assessment', N'Authoritative proof and known limitations are what make the demo safe to use in a customer decision.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-SE-DISC-01-P-SE-01', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 1, N'Build the technical discovery and decision-criteria brief', N'Synthesize approved customer and technical context into a brief that names the customer decision, constraints, evidence gaps, and criteria.', N'Featured', N'Prompt', N'Using the selected approved customer and technical sources, prepare for [meeting]. Summarize known outcomes, decisions, constraints, architecture context, open technical questions and missing evidence. Propose five discovery questions that advance the technical decision. Separate sourced facts from hypotheses.', NULL, N'Selected approved customer and technical sources.', N'Technical discovery brief with questions and evidence gaps.', N'SE validates the sources, technical context and whether each question is appropriate.', N'Synthesis and drafting', N'Discovery becomes useful when it produces decision criteria the customer and team can inspect.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SE-DISC-01-P-SE-02', N'WF-X-DISC-01', N'SE-DISC', N'PH-SE-DISC-EXPL', 2, N'Rehearse the technical discovery conversation', N'Practice questions, listening, objections and the intended next decision.', N'Featured', N'Prompt', N'Role-play [customer or stakeholder] for the upcoming technical discovery conversation. Use the approved brief only. Simulate realistic questions and objections, coach clarity and listening, and identify statements requiring technical or customer validation. Do not invent customer facts.', NULL, N'Approved discovery brief.', N'Role-play, coaching observations and improvement actions.', N'SE verifies facts, claims and commitments and decides what to change.', N'Conversation preparation', N'Practicing discovery questions reduces the chance that the real meeting ends with ambiguity instead of criteria.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-SE-POC-01-P-SE-01', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 1, N'Scope the smallest useful PoC', N'Build the PoC work package.', N'Featured', N'Prompt', N'Create a PoC plan for [technical decision]. Define hypothesis, in-scope scenario, success and exit criteria, milestones, data and environment needs, roles, risks, dependencies, review gates, final decision and handoff if successful.', NULL, N'Technical decision; constraints; resources.', N'PoC plan and decision gates.', N'SE confirms scope, resources, security, feasibility and that the PoC is necessary.', N'Scoping and design', N'A small, criteria-led PoC reduces waste and makes the exit decision clear before work starts.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SE-POC-01-P-SE-02', N'WF-X-ARCH-01', N'SE-ARCH-3', N'PH-SE-ARCH-3-EXPL', 2, N'Pressure-test PoC readiness', N'Review a proposed PoC plan for gaps and ambiguity.', N'Featured', N'Prompt', N'Review this PoC plan. Identify vague success criteria, unowned dependencies, unrealistic milestones, missing security or data assumptions, weak linkage to the customer decision and unclear exit paths. Return five review questions and the smallest revisions needed.', NULL, N'Proposed PoC plan.', N'Readiness review and revision list.', N'SE owns the go or no-go decision and confirms all required reviewers.', N'Assumption testing', N'Readiness issues should be found in planning, not after the customer expects a proof.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SE-QA-01-P-SE-01', N'WF-X-CONV-01', N'SE-CONV', N'PH-SE-CONV-EXPL', 1, N'Draft the sourced technical answer matrix', N'Answer technical questions with sources, confidence, assumptions, exceptions, and reviewer flags.', N'Featured', N'Prompt', N'Answer the selected technical questions using approved and authoritative sources. For each item provide a grounded answer, source citation, confidence, assumptions and SME-needed flag. Preserve the question order and do not hide unsupported areas.', NULL, N'Selected technical questions; approved sources.', N'Grounded technical answer matrix.', N'SE and relevant SMEs approve technical, security, legal and product claims.', N'Synthesis and drafting', N'A technical answer is safer when confidence, assumptions, and reviewer needs are visible.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-SE-QA-01-P-SE-02', N'WF-X-CONV-01', N'SE-CONV', N'PH-SE-CONV-EXPL', 2, N'Assemble the governed technical response package', N'Produce reviewed answers in the required structure and coordinate gaps.', N'Featured', N'Prompt', N'Using the approved answer matrix, assemble the response in the requested format. Create an exception list for unanswered items, assign suggested reviewers and provide a final quality checklist. Do not submit or send.', NULL, N'Approved answer matrix; required format.', N'Formatted response plus exception list.', N'SE validates completeness and obtains required approvals before distribution.', N'Synthesis and drafting', N'Governance is what keeps fast response work from becoming unsupported customer guidance.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-SOLUTION-01-P-SSP-01', N'WF-X-PLAN-01', N'SSP-PLAN', N'PH-SSP-PLAN-EXPL', 1, N'Build the solution-selling plan', N'Shape a solution-specific plan to advance the next customer decision.', N'Featured', N'Prompt', N'Build a solution-selling plan for [solution play] at [account]. Include customer outcomes, maturity, solution vision, stakeholder coverage, value conversation arc, demo or workshop sequence, proof needs, risks, and a 30-day plan to clear the next decision. Flag missing stakeholders and unsupported claims.', NULL, N'Account; solution play; current stage; known stakeholders; approved evidence.', N'Solution-selling plan with decisions, proof needs, owners, and progression actions.', N'SSP validates customer need, stage, solution fit, evidence, stakeholders, and commitments.', N'Synthesis and drafting', N'Most of the solution-selling plan is assembly; the SSP should spend judgment on the pursuit decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-SOLUTION-01-P-SSP-02', N'WF-X-PLAN-01', N'SSP-PLAN', N'PH-SSP-PLAN-EXPL', 2, N'Pressure-test the solution strategy', N'Test the plan against customer priorities, competitive alternatives, stakeholders, and decision criteria.', N'Featured', N'Prompt', N'Review this solution-selling plan against customer priorities, competitive alternatives, stakeholder coverage, proof needs, technical and commercial dependencies, and decision criteria. Return risks, gaps, missing evidence, and the next decisions needed.', NULL, N'Draft solution-selling plan; customer context; stakeholder map; proof and constraints.', N'Pressure-tested strategy with risks, gaps, and next decisions.', N'SSP confirms source accuracy, customer context, role ownership, technical/commercial dependencies, and any system action before use.', N'Assumption testing', N'If the solution strategy will fail, it should fail in review before it fails with the customer.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-SOLUTION-01-P-SSP-03', N'WF-X-PLAN-01', N'SSP-PLAN', N'PH-SSP-PLAN-EXPL', 3, N'Map who actually decides and who is missing', N'Build the real decision map for this solution play, including the people who can stop it, not only the people who like it.', N'Extended', N'Both', N'Here is my solution-selling plan and the stakeholders I have engaged: [paste plan and stakeholder list with roles and engagement level]. The solution play is [paste], the decision type is [paste, for example new workload, renewal, or migration], the customer''s organizational model is [paste, for example centralized IT, business-unit autonomy, or shared services], and their known procurement and technical governance constraints are [paste]. Build a decision map showing who decides, who influences, who implements, and who can block. For each person, state what they need to believe for this to move forward and what evidence would convince them. Then identify missing roles ONLY where the solution play, decision type, organizational model, or governance constraints I gave you imply that role is required. Do not list generic enterprise buying-committee roles. Do not invent names; describe missing roles by function. If my context is too thin to identify missing roles, say so rather than guessing.', N'1. List stakeholders engaged so far with role and engagement level.
2. Gather the solution play, decision type, customer organizational model, and governance constraints.
3. Run the prompt.
4. Identify the highest-risk absence.
5. Decide who introduces you to that person and by when.', N'Solution-selling plan; stakeholders engaged with roles; the solution play and decision type; the customer''s organizational model; known procurement and technical governance constraints; who owns the customer relationship.', N'A decision map with what each stakeholder needs to believe, plus a named list of missing roles and the risk each creates.', N'SSP validates the stakeholder reality against what the account team actually knows, and owns the plan to reach anyone missing.', N'Analysis and assessment', N'Solution plans usually fail on a person nobody engaged, not on a fact nobody knew.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-SOLUTION-01-P-SSP-04', N'WF-X-PLAN-01', N'SSP-PLAN', N'PH-SSP-PLAN-EXPL', 4, N'Convert the plan into dated commitments', N'Reduce the plan to the few actions that will actually happen in the next 30 days, each with a named owner and a date.', N'Extended', N'Both', N'From this solution-selling plan [paste], extract only the actions that must happen in the next 30 days to clear the next customer decision. For each: what it is, who owns it by role, the date it must be done by, and what it unblocks. Limit to five actions. If the plan implies more than five critical actions in 30 days, tell me which ones are not realistic and what to cut. Do not assign an action to a person or team I have not named.', N'1. Bring the pressure-tested plan.
2. Run the prompt.
3. Cut to five or fewer.
4. Confirm each owner has agreed.
5. Record the dates where the account team will see them.', N'The pressure-tested solution-selling plan; the account team and their availability; the next customer decision and its timing.', N'Five or fewer dated actions with named owners and what each unblocks.', N'SSP confirms each owner has actually agreed to the action and the date, rather than being assigned it in a document.', N'Planning and drafting', N'A plan without dates and owners is a description of intentions.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-TECH-CONV-01-P-CSA-01', N'WF-X-CONV-01', N'CSA-CONV', N'PH-CSA-CONV-EXPL', 1, N'Prepare the technical advisory conversation', N'Turn approved evidence into a customer-centered plan.', N'Featured', N'Prompt', N'Using approved customer context and technical decision package, prepare for [meeting]. Include outcome, technical state, recommendation and tradeoffs, questions, supporting evidence, likely objections, caveats, next action and ownership. Flag claims requiring review.', NULL, N'Approved context; technical package; desired decision.', N'Technical advisory conversation plan.', N'CSA validates claims, tradeoffs, context, commitments and follow-through.', N'Conversation preparation', N'Preparation for the technical advisory conversation is the step most often skipped and most often decisive.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-TECH-CONV-01-P-CSA-02', N'WF-X-CONV-01', N'CSA-CONV', N'PH-CSA-CONV-EXPL', 2, N'Rehearse the architecture recommendation', N'Role-play and coach a technical advisory conversation.', N'Featured', N'Prompt', N'Use the approved conversation plan to role-play with [customer/stakeholder]. Simulate realistic architecture, readiness, security, operational, cost and implementation questions. Coach clarity, evidence, listening, tradeoffs and next step. Identify claims needing SME review. Do not invent customer facts or commitments.', NULL, N'Approved conversation plan and audience.', N'Role-play transcript and improvement actions.', N'CSA validates facts, guidance, claims and commitments.', N'Conversation preparation', N'Ten minutes rehearsing the architecture recommendation is cheaper than improvising it in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-VALUE-01-P-SSP-01', N'WF-X-VALUE-01', N'SSP-VALUE', N'PH-SSP-VALUE-EXPL', 1, N'Tailor the solution value narrative', N'Translate the solution into customer-specific outcomes, evidence, caveats, and next ask.', N'Featured', N'Prompt', N'Using selected approved sources, build a customer-specific value narrative for [solution play] at [account]. Include top use cases, measurable or directional outcomes, proof points, differentiation, assumptions, caveats, executive talking points, and the next ask. Flag unsupported value claims.', NULL, N'Approved customer priorities, solution evidence, value frameworks, and target audience.', N'Customer-specific value narrative with evidence and review flags.', N'SSP validates value claims, proof, ROI or adoption assumptions, tone, and final ask before customer use.', N'Value translation', N'Generic value decks lose to specific narratives grounded in customer priorities.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VALUE-01-P-SSP-02', N'WF-X-VALUE-01', N'SSP-VALUE', N'PH-SSP-VALUE-EXPL', 2, N'Research evidence for the value story', N'Investigate customer, industry, use-case, and market evidence that strengthens or challenges the value story.', N'Featured', N'Prompt', N'Research [customer/industry/use case] to identify relevant market evidence, customer signals, comparable proof, risks, and counterevidence for [solution play]. Separate sourced facts from recommendations and flag unsupported value or competitor claims.', NULL, N'Customer; industry; use case; solution play; approved source boundaries.', N'Evidence brief for the value narrative.', N'SSP validates source quality, applicability to the customer, and all value or competitor claims.', N'Analysis and assessment', N'Being able to cite value evidence beats remembering a generic claim.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-VALUE-01-P-SSP-03', N'WF-X-VALUE-01', N'SSP-VALUE', N'PH-SSP-VALUE-EXPL', 3, N'Stress-test the assumptions the value claims depend on', N'Expose what each outcome number quietly assumes, and record which assumptions the customer would have to accept.', N'Extended', N'Both', N'Here is our value narrative and the evidence brief behind it: [paste both]. For every outcome claim, produce a row containing: the claim, the assumption it depends on, who has to accept that assumption for the claim to hold, the evidence we currently have, and what happens to the claim if adoption is half as fast as projected. Rank the rows by how much the claim collapses when its assumption fails. Do not add claims that are not in my narrative, and do not supply evidence I have not given you.', N'1. Bring the value narrative and evidence brief.
2. Run the prompt.
3. Find the claim that collapses hardest.
4. Either find proof for its assumption or remove the claim.
5. Bring the assumption table to the huddle.', N'The value narrative; the evidence brief; the customer''s financial context; adoption expectations already discussed with them.', N'An assumption and risk table ranked by how much each claim depends on an unproven assumption.', N'SSP decides which assumptions are defensible with this customer, and owns every outcome figure before it reaches them.', N'Practice and rehearsal', N'The value claim you cannot defend is the one the customer will ask about.', N'https://m365.cloud.microsoft/chat', N'Open Analyst'),
        (N'WF-VALUE-01-P-SSP-04', N'WF-X-VALUE-01', N'SSP-VALUE', N'PH-SSP-VALUE-EXPL', 4, N'Reduce the narrative to something the customer can forward', N'Produce the short version your champion can send to people you will never meet, without you in the room to explain it.', N'Extended', N'Both', N'Reduce this value narrative [paste] to a single page that our champion could forward internally without us present. It must stand alone: state the business problem in the customer''s own terms, the outcome, what it depends on, and what we are asking for next. Remove anything that only makes sense if a seller is explaining it. Remove any claim that is not supported by the evidence brief I gave you. Keep it under 350 words.', N'1. Bring the rehearsed narrative with weak claims removed.
2. Run the prompt.
3. Read it as if you were a stranger receiving it.
4. Cut anything that needs explaining.
5. Confirm the ask is specific.', N'The rehearsed value narrative; the evidence brief; who the champion is and who they would forward it to; the next ask.', N'A one-page, forwardable value summary with a specific next ask.', N'SSP verifies every claim survives without a seller present, and approves the wording before the champion receives it.', N'Value translation', N'Most internal customer decisions happen in rooms the seller is not in.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VALUE-TECH-01-P-CSA-01', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 1, N'Create the technical progress and value narrative', N'Synthesize approved technical evidence.', N'Featured', N'Prompt', N'Using approved architecture, delivery, adoption, consumption, optimization and risk materials for [Customer], create the CSA contribution to the business review. Connect progress to supported outcomes, explain risks and decisions, identify commitments and owners, and propose next technical actions. Separate evidence from interpretation and flag unsupported value claims.', NULL, N'Approved review sources; audience; period.', N'Technical progress and value narrative.', N'CSA validates technical and value claims, linkage, commitments and ownership.', N'Synthesis and drafting', N'You spend your time editing the technical progress and value narrative rather than staring at a blank version of it.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VALUE-TECH-01-P-CSA-02', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'PH-CSA-VALUE-2-EXPL', 2, N'Assemble the technical review package', N'Create a repeatable customer-review package.', N'Featured', N'Prompt', N'Assemble a technical customer-review package from approved sources: executive technical summary, architecture and delivery progress, consumption or adoption evidence, optimization actions, material risks, open decisions, commitments and follow-through tracker. Preserve source links and flag missing or contradictory evidence.', NULL, N'Approved source package and reviewers.', N'Structured technical-review package.', N'CSA reviews with relevant account, success, technical and commercial contributors.', N'Synthesis and drafting', N'Most of the effort in the technical review package is assembly, and assembly is exactly what AI removes.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-VTEAM-01-P-SSP-01', N'WF-X-ORCH-01', N'SSP-ORCH', N'PH-SSP-ORCH-EXPL', 1, N'Build the specialist, technical, partner, and funding plan', N'Clarify role coverage, dependencies, asks, owners, partner/funding needs, and decision checkpoints.', N'Featured', N'Prompt', N'Create a pursuit orchestration plan for [opportunity] with customer outcome, solution scope, required specialist and technical roles, partner need, funding consideration, dependencies, owner for each action, decision checkpoints, and unresolved risks. Do not represent funding as approved.', NULL, N'Approved opportunity, customer context, roles, partner criteria, funding context, and constraints.', N'Pursuit orchestration plan with owners and checkpoints.', N'SSP validates role need, ownership, partner or funding involvement, and commitments.', N'Coordination and handoff', N'Pursuits stall when handoffs, partner asks, or funding dependencies are assumed rather than owned.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VTEAM-01-P-SSP-03', N'WF-X-ORCH-01', N'SSP-ORCH', N'PH-SSP-ORCH-EXPL', 3, N'Make each ask specific enough to be accepted', N'Turn a role requirement into an ask a busy colleague can say yes to without a meeting to clarify it.', N'Extended', N'Both', N'From this pursuit orchestration plan [paste], write the individual ask for each role involved. Each ask must state: what specifically is needed, why this pursuit needs that role rather than someone else, what the person receives from me to make it easy, the date it is needed by, and how long it should take. Keep each ask under 80 words. Do not represent funding, approvals, or customer commitments as secured if the plan does not show them as secured.', N'1. Bring the orchestration plan.
2. Run the prompt.
3. Check each ask states a realistic time commitment.
4. Send the asks.
5. Record who accepted.', N'The pursuit orchestration plan; the roles required; what you can supply to each; the customer timeline.', N'One short, specific, dated ask per role, ready to send.', N'SSP verifies that no ask overstates funding, approval, or customer commitment status, and owns what is promised in return.', N'Coordination and handoff', N'A vague ask gets a polite yes and no calendar time.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-VTEAM-01-P-SSP-04', N'WF-X-ORCH-01', N'SSP-ORCH', N'PH-SSP-ORCH-EXPL', 4, N'Catch the checkpoint that quietly slipped', N'Compare the plan against what has actually happened and surface the dependency nobody has mentioned in two weeks.', N'Extended', N'Both', N'Here is the pursuit orchestration plan with its checkpoints and owners [paste], and here is what has actually happened since [paste updates, meeting notes, or status]. Identify every checkpoint that has passed without evidence of completion, every dependency that has gone quiet, and every owner who has not confirmed. Rank by impact on the customer timeline. For the top item, draft the one message that would restart it. Do not assume something is complete because it was not mentioned.', N'1. Bring the plan and recent activity. If the plan has no dated checkpoints or owners recorded, spend five minutes writing them down first; the activity does not work without them.
2. Run the prompt.
3. Confirm which items are genuinely stalled.
4. Send the restart message for the top one.
5. Reset the checkpoint date.', N'The orchestration plan with checkpoints and owners, written down even if only informally; recent updates, notes, or status; the customer timeline. If checkpoints and owners do not exist yet, create them before running this activity.', N'A ranked list of stalled checkpoints and quiet dependencies, plus one message to restart the highest-impact item.', N'SSP confirms an item is genuinely stalled rather than simply undocumented before escalating to an owner.', N'Inspection and review', N'Pursuits rarely stop. They go quiet, and quiet looks like progress until the date arrives.', N'https://aka.ms/m', N'Get started with Scout'),
        (N'WF-X-ARCH-01-P-ATS-STRAT01', N'WF-X-ARCH-01', N'ATS-TECH', N'PH-ATS-TECH-EXPL', 1, N'Analyze consumption and technical blockers', N'Connect customer and sales context to technical trajectory.', N'Featured', N'Prompt', N'Show consumption versus target for [Account], flag blockers, and recommend architecture, partner, or specialist actions that could improve the technical trajectory. Distinguish source facts from recommendations.', NULL, N'Account; target period; available MSX and customer context.', N'Consumption gap and blocker view with candidate actions.', N'ATS validates consumption interpretation, architecture actions, partner need, and customer context.', N'Inspection and review', N'The technical trajectory should respond to the blockers that are actually slowing value.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-ARCH-01-P-ATS-STRAT02', N'WF-X-ARCH-01', N'ATS-TECH', N'PH-ATS-TECH-EXPL', 2, N'Research technical options and bets', N'Compare technical options and evidence before setting trajectory.', N'Featured', N'Prompt', N'Analyze the main pipeline and consumption drivers for [Account] and recommend the top three technical bets. For each include business outcome, stakeholder, security posture, AI workload readiness, adoption blocker, first conversation, and validation gap. Separate sourced evidence from recommendations.', NULL, N'Account strategy; pipeline or consumption context; authorized sources.', N'Three evidence-backed technical bets with validation gaps.', N'ATS validates evidence, feasibility, strategic fit, and recommended priority.', N'Option analysis', N'Technical bets should be chosen on evidence, not novelty.', N'https://m365.cloud.microsoft/chat', N'Open Researcher'),
        (N'WF-X-ARCH-01-P-ATS-STRAT03', N'WF-X-ARCH-01', N'ATS-TECH', N'PH-ATS-TECH-EXPL', 3, N'Delegate the technical strategy package', N'Build a bounded strategy and validation package.', N'Featured', N'Prompt', N'Using the approved account context, technical bets, and source materials, create a technical strategy package with objectives, current estate, decision criteria, priority bets, proof needs, owners, milestones, risks, and open technical decisions.', NULL, N'Approved account context, technical evidence, and constraints.', N'Technical strategy package with decisions, owners, proof needs, and milestones.', N'ATS validates strategy, architecture, ownership, milestones, and customer relevance.', N'Strategy packaging', N'You should spend time editing the strategy, not staring at a blank version of it.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-ARCH-01-P-CSA-01', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 3, N'Build the technical decision path', N'Connect approved account and customer context to the technical decision.', N'Featured', N'Prompt', N'For [Customer/opportunity], summarize outcome, current technical decision, stakeholders, recent interactions available, blockers, commitments and opportunity stage. Propose a decision path with evidence required, gaps, owners, milestones and next customer-facing action. Show source signals and flag unavailable context.', NULL, N'Authorized scope and approved technical context.', N'Grounded technical decision path.', N'CSA validates customer context, technical accuracy, owners, relevance and commitments.', N'Synthesis and drafting', N'Most of the effort in the technical decision path is assembly, and assembly is exactly what AI removes.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-ARCH-01-P-CSA-02', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'PH-CSA-ARCH-1-EXPL', 4, N'Design the validation and proof plan', N'Create a bounded validation plan.', N'Featured', N'Prompt', N'Using the approved technical decision brief, build the smallest useful validation plan for [decision]. Include criteria, hypothesis, evidence available, proof gaps, activities, success measures, exit criteria, owners, milestones, dependencies, risks and expected decision. Do not expand beyond what is necessary.', NULL, N'Approved decision brief; owner; constraints; evidence.', N'Validation plan.', N'CSA confirms scope, feasibility, criteria, evidence quality and ownership.', N'Scoping and design', N'Settling the validation and proof plan before the work starts is the only version of that decision that holds.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-CONV-01-P-ATS-01', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 1, N'Design the executive briefing experience', N'Plan an end-to-end executive briefing experience.', N'Featured', N'Prompt', N'Help me organize an EBC for [Customer]. Choose the right session design and propose a coherent timeline and prep plan. Include desired customer decisions, executive audience, participants, evidence, role contributions, preparation milestones, risks, and follow-through.', NULL, N'Customer; executive audience; desired decisions; approved context.', N'EBC plan with session design, participants, evidence, timeline, and follow-through.', N'ATS validates purpose, participants, technical narrative, evidence, and customer decision.', N'Experience design', N'An EBC only works if the decision, people, evidence, and follow-through line up.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-CONV-01-P-ATS-02', N'WF-X-CONV-01', N'ATS-TALK', N'PH-ATS-TALK-EXPL', 2, N'Adjust the talk track from current signals', N'Adapt approved technical messaging using selected work context.', N'Featured', N'Prompt', N'Using the approved account brief, recent meetings, email, and technical source materials, identify the customer signals that should change the technical talk track. Draft revised opening language, five questions, likely objections, and responses. Separate sourced facts from recommendations.', NULL, N'Selected authorized work sources and approved technical narrative.', N'Revised technical talk track grounded in selected signals.', N'ATS validates signal interpretation, technical accuracy, customer relevance, and claims.', N'Message adaptation', N'The talk track should change when the customer signal changes.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-CONV-01-P-ATS-03', N'WF-X-CONV-01', N'ATS-NARR', N'PH-ATS-NARR-EXPL', 3, N'Translate architecture into business value', N'Create a concise business-value summary from approved architecture content.', N'Featured', N'Prompt', N'Turn this reference architecture into a one-page business value summary. Map technical choices to customer priorities, expected business outcomes, Azure consumption implications, risks, and assumptions requiring review. Quantify only when the source supports it.', NULL, N'Approved reference architecture and supporting evidence.', N'One-page technical-to-value summary with review flags.', N'ATS validates ROI, consumption impact, technical accuracy, and evidence.', N'Technical-to-value translation', N'Architecture matters more when the customer can see the business consequence.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-X-CONV-01-P-ATS-EBC-02', N'WF-X-CONV-01', N'ATS-EBC', N'PH-ATS-EBC-EXPL', 2, N'Build the run-of-show and evidence pack', N'Turn the approved briefing plan into the run-of-show the session is actually delivered from.', N'Featured', N'Prompt', N'Using the approved EBC plan, build the run-of-show: each segment in order with its time allocation, the person leading it, the evidence or demonstration used, the questions put to the customer, and the decision the session closes on. Assume the plan, participants and objectives are already agreed.', NULL, N'Approved EBC plan, confirmed participant list, and approved evidence.', N'Run-of-show with segment order, timing, owners, evidence, customer questions, and the closing decision.', N'ATS confirms every piece of evidence is approved for customer use and that each segment owner has agreed to their part.', N'Synthesis and drafting', N'The plan says why the briefing exists. The run-of-show is what the room is actually delivered from.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-CONV-01-P-ATS-JAI', N'WF-X-CONV-01', N'ATS-TALK', N'PH-ATS-TALK-EXPL', 1, N'Rehearse the strategic technical talk track', N'Practice the technical conversation and receive coaching.', N'Featured', N'Prompt', N'Use Agent J.ai to role-play the upcoming strategic technical conversation with [customer or stakeholder]. Use the approved narrative and focus on technical outcomes, open decisions, likely objections, evidence, and the technical ask. Pause for my response before coaching me on clarity, listening, evidence, and next step. Do not invent customer facts or commitments.', NULL, N'Approved narrative; meeting type; customer context; desired decision.', N'Interactive rehearsal, likely questions or objections, coaching, and improvement actions.', N'ATS validates customer facts, technical claims, commitments, evidence, and any response used with the customer.', N'Conversation rehearsal', N'Ten minutes rehearsing the talk track is cheaper than improvising it in the room.', N'https://aka.ms/AgentJCopilot', N'Open Agent J.ai'),
        (N'WF-X-CONV-01-P-ATS-NARR-01', N'WF-X-CONV-01', N'ATS-NARR', N'PH-ATS-NARR-EXPL', 1, N'Prepare the CxO technical briefing', N'Build an account-grounded executive technical briefing.', N'Featured', N'Prompt', N'Prepare a CxO technical briefing for [Account] on [Topic]. Include customer outcomes, architecture direction, risks, proof points, executive talking points, likely questions, and the technical ask. Cite source signals where available and flag unsupported claims.', NULL, N'Account; topic; desired decision; available MSX and customer context.', N'CxO technical briefing with risks, proof points, talking points, and ask.', N'ATS validates architecture, risk, proof, customer context, and technical ask.', N'Executive technical synthesis', N'The executive technical narrative needs enough evidence to be credible and enough focus to drive a decision.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-CONV-01-P-ATS-NARR-02', N'WF-X-CONV-01', N'ATS-NARR', N'PH-ATS-NARR-EXPL', 2, N'Build the executive technical deck', N'Create a bounded executive-ready presentation package.', N'Featured', N'Prompt', N'Build a concise executive technical deck for [Account] aligned to stated outcomes and the Azure or AI roadmap. Include the story arc, proof, architecture implications, risks, open technical decisions, and review flags.', NULL, N'Approved emails, transcripts, roadmap, and source materials.', N'Executive technical deck with open decisions flagged.', N'ATS reviews all claims, roadmap statements, evidence, and participant-facing content.', N'Artifact creation', N'Deck creation should be assembly work; judgment stays in the story, claims, and ask.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-HEALTH-01-P-CSA-01', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 1, N'Build a technical health evidence brief', N'Synthesize approved technical context.', N'Featured', N'Prompt', N'Using approved sources for [Customer], build a technical health brief. Separate verified evidence from assumptions. Summarize architecture and delivery state, material technical risks, optimization opportunities, open commitments, dependencies and missing evidence. End with the three issues that most deserve CSA attention and why.', NULL, N'Approved customer technical sources; review period; customer outcome.', N'Technical health brief.', N'CSA validates architecture, delivery, support, usage interpretation, priorities and commitments.', N'Synthesis and drafting', N'Most of the effort in a technical health evidence brief is assembly, and assembly is exactly what AI removes.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-X-HEALTH-01-P-CSA-02', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'PH-CSA-HEALTH-EXPL', 2, N'Prioritize a technical risk response', N'Analyze enabled certified data relevant to technical health.', N'Featured', N'Prompt', N'For [Customer] and [period], identify the most material enabled consumption, usage or adoption changes visible in this report. Show supporting metrics, distinguish evidence from interpretation, state what the report cannot answer, and suggest which signals warrant deeper technical review. Do not assign a health score or infer customer intent.', NULL, N'Enabled certified report; customer; period.', N'Evidence-backed signals and technical-review priorities.', N'CSA confirms report, filters, KPI meaning, technical significance and action.', N'Prioritization', N'Deciding a technical risk response is really deciding what you will not do. Say it out loud.', N'https://aka.ms/MSXIAssistV2', N'Open MSXI Assist V2'),
        (N'WF-X-ORCH-01-P-ATS-01', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 1, N'Create the technical V-team alignment brief', N'Align technical roles, dependencies, priorities, and owners.', N'Featured', N'Prompt', N'Using the approved account and technical context, create a V-team alignment brief with customer outcome, priority workloads, technical decisions, risks, required roles, dependencies, owner for each action, and next checkpoint. Flag unsupported assumptions.', NULL, N'Approved account and technical context; role list; decision needs.', N'Technical V-team alignment brief with owners and checkpoints.', N'ATS validates role need, ownership, dependencies, risk, and customer relevance.', N'Orchestration', N'Most work stalls in the handoff, not the task.', N'https://m365.cloud.microsoft/chat', N'Open Microsoft 365 Copilot'),
        (N'WF-X-ORCH-01-P-ATS-ECIF02', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 3, N'Assess ECIF investment opportunities', N'Identify whether ECIF funding could accelerate technical outcomes.', N'Featured', N'Prompt', N'Review Opportunity ID [ID]. Using the customer architecture roadmap, consumption goals, and current deployment blockers: identify where ECIF funding could accelerate time-to-value, recommend relevant funding motions, explain expected customer outcome and directional consumption impact, and highlight risks, dependencies, or reasons ECIF may not be appropriate.', NULL, N'Opportunity ID; architecture roadmap; consumption goals; deployment blockers.', N'Prioritized ECIF funding opportunities with outcomes, impact, risks, and dependencies.', N'ATS and ECIF owner validate eligibility, funding motion, technical feasibility, consumption assumptions, dependencies, and recommendation before action.', N'Investment signal review', N'Investment belongs in the v-team discussion when it removes a blocker to the technical strategy.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-ORCH-01-P-ATS-ECIF03', N'WF-X-ORCH-01', N'ATS-TEAM', N'PH-ATS-TEAM-EXPL', 4, N'Monitor ECIF investment performance', N'Evaluate milestone progress, deployment readiness, and consumption path.', N'Extended', N'Prompt', N'Analyze the proposed ECIF-funded engagement for Opportunity ID [ID]. Evaluate scope, milestones, deliverables, technical outcomes, Azure consumption goals, deployment path, risks, dependencies, and priority fixes. Provide a readiness assessment and name the decision owner.', NULL, N'Opportunity ID; proposed engagement; scope; milestones; deliverables; technical outcomes; consumption goals.', N'Engagement-quality assessment, gaps and risks, consumption-readiness assessment, and priority fixes.', N'ATS and ECIF owner validate scope quality, feasibility, consumption path, partner and customer readiness, compliance dependencies, and final funding decision.', N'Investment performance review', N'Realization is judged on evidence someone collected or did not collect.', N'https://aka.ms/SalesM365', N'Open Sales Agent'),
        (N'WF-X-PLAN-01-P-ATS-01', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'PH-ATS-WORKLOAD-EXPL', 1, N'Prioritize AI and Azure workloads', N'Convert enabled business insights into a workload action list.', N'Featured', N'Prompt', N'Turn this week’s business and technical signals into a prioritized AI and Azure workload action list. For each workload include readiness, potential impact, ACR or consumption upside if supported, blockers, owner, due date, and validation gap.', NULL, N'Enabled Proactive Insights, MSXI data, account context, and candidate workload list.', N'Prioritized workload action list with rationale, owner, and date.', N'ATS validates readiness, feasibility, upside interpretation, owner, and priority.', N'Prioritization', N'This converts workload interest into a decision list with owners.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-PLAN-01-P-ATS-02', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'PH-ATS-WORKLOAD-EXPL', 2, N'Research workload readiness evidence', N'Investigate technical and external evidence before prioritization.', N'Featured', N'Prompt', N'Investigate [candidate workloads] for [Account]. Compare customer objectives, current estate, security posture, AI readiness, dependencies, adoption blockers, relevant external evidence, and validation gaps. Separate sourced facts from recommendations.', NULL, N'Account context; candidate workloads; authorized internal and public sources.', N'Evidence brief supporting workload prioritization.', N'ATS validates source quality, relevance, architecture implications, and recommendation.', N'Evidence gathering', N'Research is useful when it exposes why a workload is ready, blocked, or not worth chasing yet.', N'https://msxi.microsoft.com/', N'Open MSX Insights'),
        (N'WF-X-PLAN-01-P-ATS-03', N'WF-X-PLAN-01', N'ATS-INTEL', N'PH-ATS-INTEL-EXPL', 3, N'Create the technical risk register', N'Organize technical risks using available account and business data.', N'Featured', N'Prompt', N'Build a weekly technical risk register for my account scope. Include affected accounts, opportunities, workload, MCEM stage, signal source, risk, likely impact, mitigation owner, and 14-day action. Flag unavailable context.', NULL, N'Enabled MSXI or sales data; ATS account scope.', N'Technical risk register with owner and action horizon.', N'ATS validates risk significance, technical context, owner, and mitigation.', N'Risk inspection', N'Unnamed technical risk does not get owned.', N'https://msxi.microsoft.com/', N'Open MSX Insights'),
        (N'WF-X-PLAN-01-P-ATS-INTEL-01', N'WF-X-PLAN-01', N'ATS-INTEL', N'PH-ATS-INTEL-EXPL', 1, N'Build the account intelligence brief', N'Combine work and public context into a meeting-prep brief.', N'Featured', N'Prompt', N'Act as my account intelligence analyst for [Account]. Build a meeting prep brief that summarizes business priorities, current technical strategy, stakeholder context, relevant KPIs, AI and Azure workload signals, open risks, recent customer commitments, and the top actions I should consider. Separate sourced facts from hypotheses and flag missing context.', NULL, N'Account; authorized email, Teams, calendar, files, CRM or sales context, and approved public context.', N'Account intelligence and meeting-prep brief with risks, priorities, and actions.', N'ATS validates current account context, stakeholder interpretation, technical risk, and customer relevance.', N'Synthesis and drafting', N'Account intelligence is useful when it changes the next technical decision, not when it creates a longer dossier.', N'https://m365.cloud.microsoft/', N'Open Cowork'),
        (N'WF-X-PLAN-01-P-ATS-INTEL-02', N'WF-X-PLAN-01', N'ATS-INTEL', N'PH-ATS-INTEL-EXPL', 2, N'Explain the KPI and locate the report', N'Clarify the certified KPI or report behind the business signal.', N'Featured', N'Prompt', N'How is [KPI] calculated? Link me to the relevant report and explain the methodology, filters, and limits I should understand before using it in account technology planning.', NULL, N'Enabled MSXI report or metric context.', N'KPI definition, methodology, relevant report, and caveats.', N'ATS confirms that the KPI, scope, and report match the business question.', N'Certified-data interpretation', N'If the signal is misunderstood, every technical priority built on it is suspect.', N'https://msxi.microsoft.com/', N'Open MSX Insights')
    ) v([ExternalId], [TopicExternalId], [PlacementExternalId], [PhaseExternalId], [DisplayOrder], [Name], [Description], [PracticeTier], [ExecutionMethod], [Prompt], [ActivitySteps], [RequiredContext], [ExpectedOutput], [HumanCheckpoint], [BestFitJob], [WhyThisMatters], [LaunchUrl], [LaunchLabel])
)
SELECT @unresolved = 281 - COUNT(*) FROM raw
    INNER JOIN dbo.HuddleTopics AS t ON t.[ExternalId] = raw.[TopicExternalId]
    INNER JOIN dbo.HuddlePlacements AS p ON p.[ExternalId] = raw.[PlacementExternalId]
    INNER JOIN dbo.HuddlePhases AS ph ON ph.[ExternalId] = raw.[PhaseExternalId];
IF @unresolved <> 0
    THROW 51000, 'HuddleActivities: 281 source rows were expected to resolve their foreign keys but some did not. Run the earlier scripts in order and re-check the workbook.', 1;

COMMIT TRANSACTION;
GO
